from xml.dom import minidom

def connect_to_db():
    try:
        # Replace these with your actual database credentials
        conn = psycopg2.connect(
            dbname="your_database",
            user="your_user",
            password="REDACTED_CREDENTIAL",
            host="your_host",
            port="your_port"
        )
        return conn
    except Exception as e:
        print(f"Error connecting to the database: {e}")
        return None

def execute_query(conn, query):
    try:
        cur = conn.cursor()
        cur.execute(query)
        rows = cur.fetchall()
        cur.close()
        return rows
    except Exception as e:
        print(f"Error executing the query: {e}")
        return None

def create_xml(rows):
    root = ET.Element("Customers")
    for row in rows:
        customer = ET.SubElement(root, "Customer")
        for i, column in enumerate(row):
            ET.SubElement(customer, f"column_{i}").text = str(column)

    # Convert to a pretty-printed XML string
    xml_str = ET.tostring(root, encoding="utf-8")
    return minidom.parseString(xml_str).toprettyxml(indent="  ")

def main():
    query = """
    SELECT * FROM customers 
    WHERE customer_city ILIKE '%New York%' 
    AND signup_date BETWEEN '2020-01-01' AND '2020-03-01';
    """

    conn = connect_to_db()
    if conn:
        rows = execute_query(conn, query)
        if rows:
            xml_result = create_xml(rows)
            print(xml_result)
        conn.close()

if __name__ == "__main__":
    main()

