import os

def print_lines(file_path, num_lines, from_end=False):
    with open(file_path, "r") as f:
        lines = f.readlines()
        if from_end:
            lines_to_print = lines[-num_lines:]
        else:
            lines_to_print = lines[:num_lines]
        print(f"---{file_path}---")
        print(''.join(lines_to_print))

def main(log_dir, file_patterns, num_lines, from_end=False):
    for root, dirs, files in os.walk(log_dir):
        for file in files:
            if any(pattern in file for pattern in file_patterns):
                file_path = os.path.join(root, file)
                print_lines(file_path, num_lines, from_end)

