import time
import math

def factorial_iterative(x):
    if x < 0:
        raise ValueError("Factorial is not defined for negative numbers")
    result = 1
    for i in range(2, x + 1):
        result *= i
    return result

def factorial_recursive(x):
    if x < 0:
        raise ValueError("Factorial is not defined for negative numbers")
    if x == 0 or x == 1:
        return 1
    return x * factorial_recursive(x - 1)

def measure_time(func, x):
    start_time = time.time()
    result = func(x)
    end_time = time.time()
    return result, end_time - start_time

def main():
    x = int(input("Enter a non-negative integer: "))

    # Calculate factorial iteratively
    result_iterative, time_iterative = measure_time(factorial_iterative, x)

    # Calculate factorial recursively
    result_recursive, time_recursive = measure_time(factorial_recursive, x)

    print(f"Factorial of {x} (Iterative): {result_iterative}")
    print(f"Time taken (Iterative): {time_iterative:.6f} seconds")

    print(f"Factorial of {x} (Recursive): {result_recursive}")
    print(f"Time taken (Recursive): {time_recursive:.6f} seconds")

    if result_iterative == result_recursive:
        print("Both methods produced the same result.")
    else:
        print("The methods produced different results.")

