    main()

import xml.etree.ElementTree as ET
import json

def xml_to_dict(element):
    """Recursively converts an XML element to a dictionary."""
    elem_dict = {element.tag: {} if element.attrib else None}
    children = list(element)

    if children:
        dd = {}
        for dc in map(xml_to_dict, children):
            for k, v in dc.items():
                try:
                    dd[k].append(v)
                except KeyError:
                    dd[k] = [v]
        elem_dict = {element.tag: {k: v[0] if len(v) == 1 else v for k, v in dd.items()}}

    if element.attrib:
        elem_dict[element.tag].update((k, v) for k, v in element.attrib.items())

    if element.text:
        text = element.text.strip()
        if children or element.attrib:
            if text:
                elem_dict[element.tag]['#text'] = text
        else:
            elem_dict[element.tag] = text
    return elem_dict

def parse_xml_to_json(xml_string):
    """Parses an XML string and converts it to a JSON string."""
    root = ET.fromstring(xml_string)
    xml_dict = xml_to_dict(root)
    json_str = json.dumps(xml_dict, indent=4)
    return json_str

