import csv
from sympy import isprime

def find_primes(n):
    """Find all prime numbers less than or equal to n."""
    return [i for i in range(2, n + 1) if isprime(i)]

def convert_to_binary(num):
    """Convert a number to its binary representation as a string."""
    return bin(num)[2:]

def generate_multiplication_table(primes, format_type='decimal'):
    """Generate the multiplication table for the given prime numbers in the specified format."""
    if format_type not in ['decimal', 'binary']:
        raise ValueError("Format type must be 'decimal' or 'binary'")

    table = []
    header = [''] + [str(p) if format_type == 'decimal' else convert_to_binary(p) for p in primes]
    table.append(header)

    for prime in primes:
        row = [str(prime) if format_type == 'decimal' else convert_to_binary(prime)]
        for other_prime in primes:
            product = prime * other_prime
            row.append(str(product) if format_type == 'decimal' else convert_to_binary(product))
        table.append(row)

    return table

def save_to_csv(filename, tables, format_type='decimal'):
    """Save the multiplication tables to a CSV file."""
    with open(filename, 'w', newline='') as csvfile:
        writer = csv.writer(csvfile)
        for table in tables:
            for row in table:
                writer.writerow(row)
            writer.writerow([])  # Add an empty row between tables

def main():
    # Example inputs
    numbers = [5, 7]  # You can add more numbers here
    formats = ['decimal', 'binary']

    tables = []
    for number in numbers:
        primes = find_primes(number)
        for format_type in formats:
            table = generate_multiplication_table(primes, format_type)
            tables.append(table)

    save_to_csv("multiplication_table.csv", tables)

if __name__ == "__main__":
    main()

import os

def get_directory_size(path):
    total_size = 0
    for dirpath, dirnames, filenames in os.walk(path):
        for f in filenames:
            fp = os.path.join(dirpath, f)
            if not os.path.islink(fp):
                total_size += os.path.getsize(fp)
    return total_size

def convert_size(size_bytes):
    kb = size_bytes / 1024
    mb = kb / 1024
    gb = mb / 1024
    return kb, mb, gb

