from abc import ABC, abstractmethod
from typing import List

class Node(ABC):
    @abstractmethod
    def evaluate(self) -> int:
        pass

    @abstractmethod
    def print(self) -> str:
        pass

class OperandNode(Node):
    def __init__(self, value: int):
        self.value = value

    def evaluate(self) -> int:
        return self.value

    def print(self) -> str:
        return str(self.value)

class OperatorNode(Node):
    def __init__(self, operator: str, left: Node, right: Node):
        self.operator = operator
        self.left = left
        self.right = right

    def evaluate(self) -> int:
        if self.operator == '+':
            return self.left.evaluate() + self.right.evaluate()
        elif self.operator == '-':
            return self.left.evaluate() - self.right.evaluate()
        elif self.operator == '*':
            return self.left.evaluate() * self.right.evaluate()
        elif self.operator == '/':
            return self.left.evaluate() // self.right.evaluate()

    def print(self) -> str:
        left_str = self.left.print()
        right_str = self.right.print()
        return f"({left_str} {self.operator} {right_str})"

def build_expression_tree(postfix: List[str]) -> Node:
    stack = []
    for token in postfix:
        if token.isdigit():
            stack.append(OperandNode(int(token)))
        else:
            right = stack.pop()
            left = stack.pop()
            stack.append(OperatorNode(token, left, right))
    return stack[0]

def solve(postfix: List[str]) -> (int, str):
    tree = build_expression_tree(postfix)
    result = tree.evaluate()
    expression = tree.print()
    return result, expression

# Example usage:
postfix1 = ["3", "4", "+", "2", "*", "7", "/"]
print(solve(postfix1))  # Output: (2, "(3 + 4) * 2 / 7")

postfix2 = ["4", "5", "7", "2", "+", "-", "*"]
print(solve(postfix2))  # Output: (-16, "4 * (5 - (7 + 2))")

postfix3 = ["4", "2", "+", "3", "5", "1", "-", "*", "+"]
print(solve(postfix3))  # Output: (18, "4 + 2 * (3 - (5 - 1))")

postfix4 = ["100", "200", "+", "2", "/", "5", "*", "7", "+"]
print(solve(postfix4))  # Output: (757, "((100 + 200) / 2) * 5 + 7")

def shortest_unique_substring(strings):
    def build_suffix_array(s):
        n = len(s)
        suffixes = [(s[i:], i) for i in range(n)]
        suffixes.sort()
        return [index for _, index in suffixes]

    def is_unique(substring, strings, exclude_index):
        for i, s in enumerate(strings):
            if i == exclude_index:
                continue
            if substring in s:
                return False
        return True

    def find_shortest_unique_substring(s, strings, exclude_index):
        n = len(s)
        suffix_array = build_suffix_array(s)
        for length in range(1, n + 1):
            seen = {}
            for i in suffix_array:
                if i + length > n:
                    break
                sub = s[i:i + length]
                if sub in seen:
                    seen[sub] += 1
                else:
                    seen[sub] = 1
            for sub, count in seen.items():
                if count == 1 and is_unique(sub, strings, exclude_index):
                    return sub
        return None

    shortest_unique = None
    for i, s in enumerate(strings):
        if not s.strip():
            continue
        sub = find_shortest_unique_substring(s, strings, i)
        if sub and (shortest_unique is None or len(sub) < len(shortest_unique)):
            shortest_unique = sub

    if shortest_unique:
        return shortest_unique
    else:
        return "No unique sub-string found"

