def is_prime(num):
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def lcm(a, b):
    return a * b // gcd(a, b)

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def process_input(input_value):
    if isinstance(input_value, str):
        try:
            input_value = int(input_value)
        except ValueError:
            try:
                input_value = float(input_value)
            except ValueError:
                return "Error: Invalid input type, unable to convert to number."

    if isinstance(input_value, complex):
        real_part = input_value.real
        imag_part = input_value.imag
        factors_real = [i for i in range(1, int(real_part) + 1) if real_part % i == 0]
        factors_imag = [i for i in range(1, int(imag_part) + 1) if imag_part % i == 0]
        is_even_real = len(factors_real) % 2 == 0
        is_even_imag = len(factors_imag) % 2 == 0
        sum_factors_real = sum(factors_real)
        sum_factors_imag = sum(factors_imag)
        max_prime_real = max([i for i in factors_real if is_prime(i)], default=None)
        max_prime_imag = max([i for i in factors_imag if is_prime(i)], default=None)
        lcm_real = lcm(factors_real[0], factors_real[-1]) if factors_real else None
        lcm_imag = lcm(factors_imag[0], factors_imag[-1]) if factors_imag else None
        gcd_real = gcd(factors_real[0], factors_real[-1]) if factors_real else None
        gcd_imag = gcd(factors_imag[0], factors_imag[-1]) if factors_imag else None
        return {
            'real': (is_even_real, factors_real, sum_factors_real, max_prime_real, (lcm_real, gcd_real)),
            'imag': (is_even_imag, factors_imag, sum_factors_imag, max_prime_imag, (lcm_imag, gcd_imag))
        }

    if not isinstance(input_value, (int, float, complex)):
        return "Error: Invalid input type."

    if isinstance(input_value, float):
        input_value = round(input_value)

    if input_value <= 0:
        return "Error: Input must be a positive integer or float."

    factors = [i for i in range(1, int(input_value) + 1) if input_value % i == 0]
    is_even = len(factors) % 2 == 0
    sum_factors = sum(factors)
    max_prime = max([i for i in factors if is_prime(i)], default=None)
    lcm_factors = lcm(factors[0], factors[-1]) if factors else None
    gcd_factors = gcd(factors[0], factors[-1]) if factors else None
    return (is_even, factors, sum_factors, max_prime, (lcm_factors, gcd_factors))

def process_matrix(matrix):
    if not all(isinstance(row, list) for row in matrix):
        return "Error: Input must be a matrix (list of lists)."

    result = []
    for row in matrix:
        row_result = []
        for element in row:
            processed = process_input(element)
            row_result.append(processed)
        result.append(row_result)
    return result

