def is_account_locked(username):
    user = users.get(username)
    if not user:
        return False
    if user['failed_attempts'] >= MAX_FAILED_ATTEMPTS:
        last_failed_time = user['last_failed_attempt_time']
        if last_failed_time and datetime.now() - last_failed_time < LOCKOUT_DURATION:
            return True
    return False

def login(username, password):
    if is_account_locked(username):
        print(f"Account for {username} is locked. Please try again later.")
        return False

    user = users.get(username)
    if not user:
        print("User not found.")
        return False

    if hash_password(password) == user['password_hash']:
        user['failed_attempts'] = 0
        user['last_failed_attempt_time'] = None
        print(f"Login successful for {username}.")
        return True
    else:
        user['failed_attempts'] += 1
        user['last_failed_attempt_time'] = datetime.now()
        print(f"Login failed for {username}. {MAX_FAILED_ATTEMPTS - user['failed_attempts']} attempts remaining.")
        return False

