def read_corpus(file_path):
    """Reads a corpus file and returns a list of (word, tag) tuples."""
    corpus = []
    with open(file_path, 'r', encoding='utf-8') as file:
        for line in file:
            if line.strip():  # Skip empty lines
                sentence = []
                parts = line.strip().split()
                for part in parts:
                    word, tag = part.rsplit('/', 1)  # Assuming tags are separated by '/'
                    sentence.append((word, tag))
                corpus.append(sentence)
    return corpus

def calculate_metrics(gold_corpus, test_corpus):
    """Calculates precision and recall for each tag."""
    tag_metrics = {}

    for sentence_gold, sentence_test in zip(gold_corpus, test_corpus):
        for (word_gold, tag_gold), (word_test, tag_test) in zip(sentence_gold, sentence_test):
            if word_gold != word_test:
                raise ValueError(f"Words do not match: {word_gold} != {word_test}")

            if tag_gold not in tag_metrics:
                tag_metrics[tag_gold] = {'TP': 0, 'FP': 0, 'FN': 0}

            if tag_test not in tag_metrics:
                tag_metrics[tag_test] = {'TP': 0, 'FP': 0, 'FN': 0}

            if tag_gold == tag_test:
                tag_metrics[tag_gold]['TP'] += 1
            else:
                tag_metrics[tag_gold]['FN'] += 1
                tag_metrics[tag_test]['FP'] += 1

    # Calculate precision and recall
    for tag, metrics in tag_metrics.items():
        TP = metrics['TP']
        FP = metrics['FP']
        FN = metrics['FN']

        precision = TP / (TP + FP) if (TP + FP) > 0 else 0
        recall = TP / (TP + FN) if (TP + FN) > 0 else 0

        tag_metrics[tag]['precision'] = precision
        tag_metrics[tag]['recall'] = recall

    return tag_metrics

# Example usage
