def convert_frame_to_ascii(frame, charset, scale):
    frame_gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    frame_resized = cv2.resize(frame_gray, (int(frame_gray.shape[1] // scale), int(frame_gray.shape[0] // scale)), interpolation=cv2.INTER_LINEAR)

    ascii_frame = ''
    for row in frame_resized:
        for pixel in row:
            ascii_frame += charset[int(pixel // (256 / len(charset)))]
        ascii_frame += '\n'

    return ascii_frame

