import math

def is_prime(num):
    """Check if a number is prime."""
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(num)) + 1, 2):
        if num % i == 0:
            return False
    return True

def digit_sum(num):
    """Calculate the sum of digits of a number."""
    return sum(int(digit) for digit in str(num))

def has_recurring_digits(num):
    """Check if a number has recurring digits."""
    digits = str(num)
    return len(set(digits)) != len(digits)

def generate_n_digit_primes(n):
    """Generate all n-digit prime numbers."""
    start = 10**(n-1)
    end = 10**n
    primes = []
    for num in range(start, end, 2):
        if is_prime(num):
            primes.append(num)
    return primes

def advanced_prime_sum(n, m):
    """
    Accepting two positive integers n and m as parameters, this function should output the aggregate of all n-digit prime numbers whose digit sum equates to a prime number, are not factors of 5 and whose cubed value falls below m. Further, it shall disregard prime numbers with an even digit count or those showcasing recurring digits. The function needs to demonstrate efficacy when dealing with high values of n and m.
    """
    primes = generate_n_digit_primes(n)
    valid_primes = []

    for prime in primes:
        if prime % 5 != 0 and is_prime(digit_sum(prime)) and prime**3 < m and n % 2 != 0 and not has_recurring_digits(prime):
            valid_primes.append(prime)

    return sum(valid_primes)

