from typing import List, Optional

def common_substring(strings: List[str], k: int) -> Optional[str]:
    if not strings or k <= 0:
        return None

    # Helper function to find all substrings of a given string
    def find_substrings(s: str) -> List[str]:
        n = len(s)
        return [s[i:j] for i in range(n) for j in range(i + 1, n + 1)]

    # Dictionary to count occurrences of substrings
    substring_count = {}

    # Iterate through each string and find all substrings
    for s in strings:
        substrings = find_substrings(s)
        for sub in substrings:
            if sub in substring_count:
                substring_count[sub] += 1
            else:
                substring_count[sub] = 1

    # Find the longest substring that appears at least k times
    longest_substring = None
    max_length = -1

    for sub, count in substring_count.items():
        if count >= k and len(sub) > max_length:
            longest_substring = sub
            max_length = len(sub)

    return longest_substring

# Examples
print(common_substring([], 2))  # Should return None
print(common_substring(['a', 'b', 'c'], 2))  # Should return None
print(common_substring(['abc', 'def', 'efc'], 2))  # Should return None
print(common_substring(['abc', 'abcabc', 'abcabcabc'], 3))  # Should return 'abc'

