import json

def parse_json(json_str):
    try:
        return json.loads(json_str)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON format: {e}")

def validate_json_structure(json_obj):
    if not isinstance(json_obj, dict):
        raise ValueError("JSON object must be a dictionary")

def check_keys(json_obj, required_keys):
    for key in required_keys:
        if key not in json_obj:
            raise KeyError(f"Key '{key}' is missing in the JSON object")

def modify_value(json_obj, target_key, key1, key2):
    try:
        json_obj[target_key] = json_obj[key1] + json_obj[key2]
    except TypeError:
        raise ValueError(f"Values of keys '{key1}' and '{key2}' must be integers")

def process_json(json_str, target_key, key1, key2):
    try:
        json_obj = parse_json(json_str)
        validate_json_structure(json_obj)
        check_keys(json_obj, [target_key, key1, key2])
        modify_value(json_obj, target_key, key1, key2)
        return json.dumps(json_obj, indent=2)
    except (ValueError, KeyError) as e:
        return str(e)

# Example usage
json_str = '''
{
  "key1": 10,
  "key2": 20,
  "key3": 0
}
'''

# Correct JSON
print(process_json(json_str, "key3", "key1", "key2"))

# Faulty JSON with incorrect closing brackets
faulty_json_str = '''
{
  "key1": 10,
  "key2": 20,
  "key3": 0,
}
'''
print(process_json(faulty_json_str, "key3", "key1", "key2"))

# JSON with missing key
missing_key_json_str = '''
{
  "key1": 10,
  "key2": 20
}
'''
print(process_json(missing_key_json_str, "key3", "key1", "key2"))

# JSON with non-integer values
non_integer_json_str = '''
{
  "key1": 10,
  "key2": "20",
  "key3": 0
}
'''
print(process_json(non_integer_json_str, "key3", "key1", "key2"))

import re
import random
from typing import Tuple

# Simulated user's previous banking history
MIN_BALANCE = 1000
MAX_BALANCE = 100000

# List of common dictionary words (for simplicity, using a small list)
COMMON_WORDS = ["password", "123456", "qwerty", "letmein", "admin"]

def is_strong_password(password: str) -> bool:
    """Check if the password is strong."""
    if len(password) < 10:
        return False
    if not re.search(r"[a-z]", password):
        return False
    if not re.search(r"[A-Z]", password):
        return False
    if not re.search(r"\d", password):
        return False
    if not re.search(r"[!@#$%^&*(),.?\":{}|<>]", password):
        return False
    return True

def is_similar(username: str, password: str) -> bool:
    """Check if the username and password are similar."""
    return username.lower() in password.lower() or password.lower() in username.lower()

def contains_common_word(password: str) -> bool:
    """Check if the password contains common words."""
    return any(word in password.lower() for word in COMMON_WORDS)

def is_valid_balance(balance: float) -> bool:
    """Check if the balance is within the allowed range."""
    return MIN_BALANCE <= balance <= MAX_BALANCE

class BankAccount:
    def __init__(self, username: str, password: str, balance: float):
        self.username = username
        self.password = password
        self.balance = balance

    def __str__(self):
        return f"Account for {self.username} created with a balance of ${self.balance:.2f}"

def create_bank_account() -> Tuple[bool, str]:
    """Function to create a new bank account after validating the inputs."""
    username = input("Enter a unique username: ")
    password = input("Enter a strong password: ")
    balance = float(input("Enter your desired account balance: "))

    if not is_strong_password(password):
        return False, "Password is not strong enough. It must be at least 10 characters long and include uppercase, lowercase, numbers, and special characters."

    if is_similar(username, password):
        return False, "Username and password are too similar."

    if contains_common_word(password):
        return False, "Password contains common words or patterns."

    if not is_valid_balance(balance):
        return False, f"Balance must be between ${MIN_BALANCE} and ${MAX_BALANCE}."

    account = BankAccount(username, password, balance)
    return True, str(account)

# Example usage
success, message = create_bank_account()
if success:
    print(message)
else:
    print("Failed to create account:", message)

def calculate_mean(arr, index=0, total=0):
    if index == len(arr):
        return total / len(arr)
    return calculate_mean(arr, index + 1, total + arr[index])

def calculate_std(arr, mean, index=0, squared_diff_sum=0):
    if index == len(arr):
        return (squared_diff_sum / len(arr)) ** 0.5
    return calculate_std(arr, mean, index + 1, squared_diff_sum + (arr[index] - mean) ** 2)

def normalize_array(arr, mean=None, std=None, index=0):
    if not isinstance(arr, list) or not all(isinstance(x, (int, float)) for x in arr):
        raise TypeError("Input must be a list of numbers")

    if mean is None:
        mean = calculate_mean(arr)
    if std is None:
        std = calculate_std(arr, mean)

    if index == len(arr):
        return [(x - mean) / std for x in arr]

    normalized_arr = normalize_array(arr, mean, std, index + 1)
    normalized_arr[index] = (arr[index] - mean) / std
    return normalized_arr

def denormalize_array(normalized_arr, original_arr, mean=None, std=None, index=0):
    if not isinstance(normalized_arr, list) or not all(isinstance(x, (int, float)) for x in normalized_arr):
        raise TypeError("Input must be a list of numbers")

    if mean is None:
        mean = calculate_mean(original_arr)
    if std is None:
        std = calculate_std(original_arr, mean)

    if index == len(normalized_arr):
        return [x * std + mean for x in normalized_arr]

    denormalized_arr = denormalize_array(normalized_arr, original_arr, mean, std, index + 1)
    denormalized_arr[index] = normalized_arr[index] * std + mean
    return denormalized_arr

# Example usage
array = [4, 8, 15, 23, 42]

try:
    normalized_array = normalize_array(array)
    print("Normalized Array:", normalized_array)

    denormalized_array = denormalize_array(normalized_array, array)
    print("Denormalized Array:", denormalized_array)
except TypeError as e:
    print(e)

import re
from datetime import datetime, timedelta
import pytz

class DateTimeParser:
    def __init__(self, date_str, time_str, timezone_str):
        self.date_str = date_str
        self.time_str = time_str
        self.timezone_str = timezone_str
        self.parsed_date = None
        self.parsed_time = None
        self.timezone = None

    def parse_date(self):
        date_patterns = [
            r'(\d{4})-(\d{2})-(\d{2})',  # YYYY-MM-DD
            r'(\d{2})/(\d{2})/(\d{4})',  # MM/DD/YYYY
            r'(\d{4})/(\d{2})/(\d{2})'   # YYYY/MM/DD
        ]
        for pattern in date_patterns:
            match = re.match(pattern, self.date_str)
            if match:
                year, month, day = match.groups()
                self.parsed_date = datetime(int(year), int(month), int(day))
                return True
        return False

    def parse_time(self):
        time_patterns = [
            r'(\d{2}):(\d{2})',  # HH:MM
            r'(\d{2}):(\d{2}):(\d{2})'  # HH:MM:SS
        ]
        for pattern in time_patterns:
            match = re.match(pattern, self.time_str)
            if match:
                hour, minute, second = match.groups() if len(match.groups()) == 3 else (match.group(1), match.group(2), '00')
                self.parsed_time = datetime(1, 1, 1, int(hour), int(minute), int(second))
                return True
        return False

    def parse_timezone(self):
        try:
            if self.timezone_str.upper() in pytz.all_timezones:
                self.timezone = pytz.timezone(self.timezone_str)
            elif re.match(r'UTC[+-]\d{2}:\d{2}', self.timezone_str.upper()):
                offset = timedelta(hours=int(self.timezone_str[3:6]), minutes=int(self.timezone_str[7:9]))
                self.timezone = pytz.FixedOffset(offset.total_seconds() / 60)
            else:
                raise ValueError("Invalid time zone")
        except Exception as e:
            return False
        return True

    def validate(self):
        if not self.parse_date():
            return "Invalid date format"
        if not self.parse_time():
            return "Invalid time format"
        if not self.parse_timezone():
            return "Invalid time zone format"
        return None

    def to_iso8601(self):
        dt = datetime.combine(self.parsed_date, self.parsed_time.time())
        dt = self.timezone.localize(dt)
        dt = dt.astimezone(pytz.utc)
        return dt.isoformat()

def convert_to_iso8601(date_str, time_str, timezone_str):
    parser = DateTimeParser(date_str, time_str, timezone_str)
    error = parser.validate()
    if error:
        return error
    return parser.to_iso8601()

# Example usage:
date_str = "2023-10-05"
time_str = "14:30"
timezone_str = "America/New_York"
print(convert_to_iso8601(date_str, time_str, timezone_str))  # Output: 2023-10-05T18:30:00Z

