            if len(session) != 5:
                raise ValueError("Each session must be a tuple of (date, start_time, end_time, location, max_students).")
            if not isinstance(session[0], str) or not isinstance(session[1], str) or not isinstance(session[2], str) or not isinstance(session[3], str) or not isinstance(session[4], int):
                raise ValueError("Session format is incorrect.")

        self.courses[course_id] = {
            'name': name,
            'description': description,
            'instructor': instructor,
            'schedule': schedule,
            'registered_students': [0] * len(schedule)
        }

    def get_courses_at_capacity(self):
        return [course_id for course_id, course in self.courses.items() if all(registered == max_students for registered, (_, _, _, _, max_students) in zip(course['registered_students'], course['schedule']))]

    def get_available_seats(self, course_id, session_index):
        if course_id not in self.courses:
            raise KeyError(f"Course ID {course_id} not found.")
        if session_index < 0 or session_index >= len(self.courses[course_id]['schedule']):
            raise IndexError("Session index out of range.")

        max_students = self.courses[course_id]['schedule'][session_index][4]
        registered_students = self.courses[course_id]['registered_students'][session_index]
        return max_students - registered_students

    def get_total_registered_students(self, course_id):
        if course_id not in self.courses:
            raise KeyError(f"Course ID {course_id} not found.")

        return sum(self.courses[course_id]['registered_students'])

    def get_average_registered_students(self):
        total_registered = sum(sum(course['registered_students']) for course in self.courses.values())
        total_sessions = sum(len(course['schedule']) for course in self.courses.values())
        if total_sessions == 0:
            return 0
        return total_registered / total_sessions

    def get_most_popular_course(self):
        if not self.courses:
            return None

        max_registration_rate = -1
        popular_course_id = None

        for course_id, course in self.courses.items():
            total_registered = sum(course['registered_students'])
            total_capacity = sum(session[4] for session in course['schedule'])
            if total_capacity == 0:
                continue
            registration_rate = total_registered / total_capacity
            if registration_rate > max_registration_rate:
                max_registration_rate = registration_rate
                popular_course_id = course_id

        return popular_course_id

    def register_student(self, course_id, session_index):
        if course_id not in self.courses:
            raise KeyError(f"Course ID {course_id} not found.")
        if session_index < 0 or session_index >= len(self.courses[course_id]['schedule']):
            raise IndexError("Session index out of range.")

        max_students = self.courses[course_id]['schedule'][session_index][4]
        if self.courses[course_id]['registered_students'][session_index] >= max_students:
            raise ValueError("Session is at capacity.")

        self.courses[course_id]['registered_students'][session_index] += 1

