import math
import unittest

# Dictionary comprehension with error handling
def create_sqrt_dict(start, end):
    try:
        # Ensure start and end are integers
        start = int(start)
        end = int(end)

        # Ensure start is less than or equal to end
        if start > end:
            raise ValueError("Start value must be less than or equal to end value.")

        # Create the dictionary
        return {i: math.sqrt(i) for i in range(start, end + 1)}

    except ValueError as e:
        print(f"Error: {e}")
        return {}
    except TypeError:
        print("Error: Both start and end values must be numeric.")
        return {}

# Unit tests
class TestCreateSqrtDict(unittest.TestCase):
    def test_valid_range(self):
        result = create_sqrt_dict(1, 25)
        expected = {i: math.sqrt(i) for i in range(1, 26)}
        self.assertEqual(result, expected)

    def test_invalid_range(self):
        result = create_sqrt_dict(25, 1)
        self.assertEqual(result, {})

    def test_non_numeric_input(self):
        result = create_sqrt_dict('a', 25)
        self.assertEqual(result, {})

    def test_float_input(self):
        result = create_sqrt_dict(1.0, 25.0)
        expected = {i: math.sqrt(i) for i in range(1, 26)}
        self.assertEqual(result, expected)

if __name__ == '__main__':
    unittest.main()

from collections import defaultdict

def canAssignTasks(people_skills, task_requirements):
    n = len(people_skills)
    m = len(task_requirements)

    # Create a bipartite graph
    graph = defaultdict(list)
    for i in range(n):
        for j in range(m):
            if all(people_skills[i][k] >= task_requirements[j][k] for k in range(len(people_skills[i]))):
                graph[i].append(j + n)  # People are indexed from 0 to n-1, tasks from n to n+m-1

    # Hopcroft-Karp algorithm for maximum matching
    match = [-1] * (n + m)
    visited = [False] * (n + m)

    def bfs():
        queue = []
        for i in range(n):
            if match[i] == -1:
                visited[i] = True
                queue.append(i)

        while queue:
            u = queue.pop(0)
            for v in graph[u]:
                if visited[v]:
                    continue
                visited[v] = True
                if match[v] == -1 or bfs():
                    match[u] = v
                    match[v] = u
                    return True
        return False

    for _ in range(m):
        visited = [False] * (n + m)
        if not bfs():
            return False

    return True

