    [0, 1, 1],
    [1, 1, 0]
]

task_requirements = [
    [1, 0, 1],
    [0, 1, 0]
]

print(canAssignTasks(people_skills, task_requirements))  # Output: True

import sqlparse

sql = "SELECT d_year, s_nation, p_category, sum(lo_revenue - lo_supplycost) as profit FROM DATES, CUSTOMER, SUPPLIER, PART, LINEORDER WHERE lo_custkey = c_custkey AND lo_suppkey = s_suppkey AND lo_partkey = p_partkey AND lo_orderdate = d_datekey AND c_region = 'AFRICA' AND s_region = 'AFRICA' AND (d_year = 1996 OR d_year = 1997) AND (p_mfgr = 'MFGR#2' OR p_mfgr = 'MFGR#4') GROUP BY d_year, s_nation, p_category ORDER BY d_year, s_nation, p_category"

parsed = sqlparse.parse(sql)[0]

def extract_from_part(parsed):
    from_seen = False
    tables = []
    for token in parsed.tokens:
        if from_seen:
            if token.ttype is sqlparse.tokens.Keyword:
                break
            if isinstance(token, sqlparse.sql.IdentifierList):
                for identifier in token.get_identifiers():
                    tables.append(identifier.get_name())
            elif isinstance(token, sqlparse.sql.Identifier):
                tables.append(token.get_name())
        if token.ttype is sqlparse.tokens.Keyword and token.value.upper() == 'FROM':
            from_seen = True
    return tables

def extract_where_part(parsed):
    where_seen = False
    where_conditions = []
    for token in parsed.tokens:
        if where_seen:
            where_conditions.append(str(token))
        if token.ttype is sqlparse.tokens.Keyword and token.value.upper() == 'WHERE':
            where_seen = True
    return ' '.join(where_conditions)

def extract_group_by_part(parsed):
    group_by_seen = False
    group_by_columns = []
    for token in parsed.tokens:
        if group_by_seen:
            if token.ttype is sqlparse.tokens.Keyword:
                break
            if isinstance(token, sqlparse.sql.IdentifierList):
                for identifier in token.get_identifiers():
                    group_by_columns.append(identifier.get_name())
            elif isinstance(token, sqlparse.sql.Identifier):
                group_by_columns.append(token.get_name())
        if token.ttype is sqlparse.tokens.Keyword and token.value.upper() == 'GROUP BY':
            group_by_seen = True
    return group_by_columns

def extract_order_by_part(parsed):
    order_by_seen = False
    order_by_columns = []
    for token in parsed.tokens:
        if order_by_seen:
            if token.ttype is sqlparse.tokens.Keyword:
                break
            if isinstance(token, sqlparse.sql.IdentifierList):
                for identifier in token.get_identifiers():
                    order_by_columns.append(identifier.get_name())
            elif isinstance(token, sqlparse.sql.Identifier):
                order_by_columns.append(token.get_name())
        if token.ttype is sqlparse.tokens.Keyword and token.value.upper() == 'ORDER BY':
            order_by_seen = True
    return order_by_columns

# Extract information
tables = extract_from_part(parsed)
where_conditions = extract_where_part(parsed)
group_by_columns = extract_group_by_part(parsed)
order_by_columns = extract_order_by_part(parsed)

# Print extracted information
print("Tables:", tables)
print("Where Conditions:", where_conditions)
print("Group By Columns:", group_by_columns)
print("Order By Columns:", order_by_columns)

import json
import boto3
import os

def lambda_handler(event, context):
    # Parse the S3 event
    s3_event = event['Records'][0]['s3']
    bucket_name = s3_event['bucket']['name']
    object_key = s3_event['object']['key']

    # Create an SES client
    ses_client = boto3.client('ses')

    # Email parameters
    sender_email = os.environ['SENDER_EMAIL']
    recipient_email = os.environ['RECIPIENT_EMAIL']
    subject = f"New file uploaded to S3: {object_key}"
    body = f"A new file has been uploaded to the S3 bucket {bucket_name}.\nFile name: {object_key}"

    # Send the email
    response = ses_client.send_email(
        Source=sender_email,
        Destination={
            'ToAddresses': [recipient_email]
        },
        Message={
            'Subject': {
                'Data': subject
            },
            'Body': {
                'Text': {
                    'Data': body
                }
            }
        }
    )

    return {
        'statusCode': 200,
        'body': json.dumps('Email sent successfully!')
    }

import re

def is_independent_clause(clause):
    # A simple heuristic to check if a clause is independent
    # This can be improved with more sophisticated NLP techniques
    return any(word in clause for word in ["is", "are", "was", "were", "am", "be", "been", "being"])

def is_dependent_clause(clause):
    # A simple heuristic to check if a clause is dependent
    # This can be improved with more sophisticated NLP techniques
    subordinating_conjunctions = ["although", "as", "because", "since", "unless", "until", "while", "who", "whom", "whose", "which", "that", "even though", "provided that", "in order", "as if", "if"]
    return any(clause.startswith(conj) for conj in subordinating_conjunctions)

def classify_sentence(sentence):
    clauses = re.split(r'(\band\b|\bor\b|\bbut\b|\bso\b|\byet\b|\balthough\b|\bas\b|\bbecause\b|\bsince\b|\bunless\b|\buntil\b|\bwhile\b|\bwho\b|\bwhom\b|\bwhose\b|\bwhich\b|\bthat\b|\beven though\b|\bprovided that\b|\bin order\b|\bas if\b|\bif\b)', sentence)
    independent_clauses = [clause for clause in clauses if is_independent_clause(clause)]
    dependent_clauses = [clause for clause in clauses if is_dependent_clause(clause)]

    if len(independent_clauses) == 1 and len(dependent_clauses) == 0:
        return "simple"
    elif len(independent_clauses) >= 2 and len(dependent_clauses) == 0:
        return "compound"
    else:
        return "complex"

text = "The quick brown fox jumped over the lazy dog. She jumped happily. Consider compound and complex sentences as separate types. Although it was raining, she went out. She went out, and she was happy."

sentences = re.split(r'(?<=[.!?])\s+', text)
sentences = [s.strip() for s in sentences if s.strip()]

simple_count = 0
compound_count = 0
complex_count = 0

for sentence in sentences:
    sentence_type = classify_sentence(sentence)
    if sentence_type == "simple":
        simple_count += 1
    elif sentence_type == "compound":
        compound_count += 1
    elif sentence_type == "complex":
        complex_count += 1

print(f"Simple sentences: {simple_count}")
print(f"Compound sentences: {compound_count}")
print(f"Complex sentences: {complex_count}")

