   # User class
   class User(UserMixin):
       def __init__(self, id, email, password):
           self.id = id
           self.email = email
           self.password = password

       def __repr__(self):
           return f'<User: {self.email}>'

   # In-memory user store (for demonstration purposes)
   users = {
       1: User(1, 'redacted@example.invalid', 'password123')
   }

   # User loader
   @login_manager.user_loader
   def load_user(user_id):
       return users.get(int(user_id))

   # Forms
   class RegistrationForm(FlaskForm):
       email = StringField('Email', validators=[DataRequired(), Email()])
       password = PasswordField('Password', validators=[DataRequired()])
       confirm_password = PasswordField('Confirm Password', validators=[DataRequired(), EqualTo('password')])
       submit = SubmitField('Register')

   class LoginForm(FlaskForm):
       email = StringField('Email', validators=[DataRequired(), Email()])
       password = PasswordField('Password', validators=[DataRequired()])
       submit = SubmitField('Login')

   # Routes
   @app.route('/')
   def home():
       return render_template('home.html')

   @app.route('/register', methods=['GET', 'POST'])
   def register():
       form = RegistrationForm()
       if form.validate_on_submit():
           # Check if the user already exists
           if not any(user.email == form.email.data for user in users.values()):
               # Create a new user
               user_id = len(users) + 1
               new_user = User(user_id, form.email.data, form.password.data)
               users[user_id] = new_user
               flash('Registration successful! You can now log in.', 'success')
               return redirect(url_for('login'))
           else:
               flash('Email already exists. Please log in.', 'danger')
       return render_template('register.html', form=form)

   @app.route('/login', methods=['GET', 'POST'])
   def login():
       form = LoginForm()
       if form.validate_on_submit():
           # Check if the user exists and the password is correct
           user = next((user for user in users.values() if user.email == form.email.data), None)
           if user and user.password == form.password.data:
               login_user(user)
               flash('Login successful!', 'success')
               return redirect(url_for('dashboard'))
           else:
               flash('Invalid email or password.', 'danger')
       return render_template('login.html', form=form)

