def flatten_list(two_d_list):
    return [item for sublist in two_d_list for item in sublist]

def calculate_median(sorted_list):
    n = len(sorted_list)
    if n == 0:
        return None  # Handle empty list
    if n % 2 == 1:
        return sorted_list[n // 2]
    else:
        return (sorted_list[n // 2 - 1] + sorted_list[n // 2]) / 2

def print_median(two_d_list):
    flat_list = flatten_list(two_d_list)
    if not flat_list:
        print("The list is empty, no median to calculate.")
        return
    sorted_list = sorted(flat_list)
    median = calculate_median(sorted_list)
    print(f"The median of the list is: {median}")

