def lcs(X, Y, m, n, dp):
    if m == 0 or n == 0:
        return 0
    if dp[m][n] != -1:
        return dp[m][n]
    if X[m-1] == Y[n-1]:
        dp[m][n] = 1 + lcs(X, Y, m-1, n-1, dp)
    else:
        dp[m][n] = max(lcs(X, Y, m, n-1, dp), lcs(X, Y, m-1, n, dp))
    return dp[m][n]

def find_lcs(strings):
    if not strings:
        return ""
    n = len(strings)
    lcs_str = strings[0]
    for i in range(1, n):
        m = len(lcs_str)
        n = len(strings[i])
        dp = [[-1] * (n+1) for _ in range(m+1)]
        lcs_length = lcs(lcs_str, strings[i], m, n, dp)
        lcs_str = build_lcs(lcs_str, strings[i], dp)
    return lcs_str

def build_lcs(X, Y, dp):
    m = len(X)
    n = len(Y)
    lcs_str = []
    i, j = m, n
    while i > 0 and j > 0:
        if X[i-1] == Y[j-1]:
            lcs_str.append(X[i-1])
            i -= 1
            j -= 1
        elif dp[i-1][j] > dp[i][j-1]:
            i -= 1
        else:
            j -= 1
    return ''.join(reversed(lcs_str))

def find_sus(strings):
    if not strings:
        return ""
    sus = None
    for string in strings:
        for i in range(len(string)):
            for j in range(i + 1, len(string) + 1):
                subseq = string[i:j]
                if all(subseq not in s for s in strings if s != string):
                    if sus is None or len(subseq) < len(sus):
                        sus = subseq
    return sus

def process_inputs(input1, input2):
    all_strings = input1 + input2
    lcs_result = find_lcs(all_strings)
    sus_result = find_sus(all_strings)
    return sus_result, len(lcs_result)

