def encode_string(text):
    encoded = []
    for c in text:
        if c.islower():
            # Shift lowercase letters by 2 and handle overflow
            encoded.append(chr((ord(c) - ord('a') + 2) % 26 + ord('a')))
        elif c.isupper():
            # Shift uppercase letters by 2 and handle overflow
            encoded.append(chr((ord(c) - ord('A') + 2) % 26 + ord('A')))
        else:
            # Non-alphabetic characters remain unchanged
            encoded.append(c)
    return ''.join(encoded)

def decode_string(text):
    decoded = []
    for c in text:
        if c.islower():
            # Shift lowercase letters by -2 and handle overflow
            decoded.append(chr((ord(c) - ord('a') - 2) % 26 + ord('a')))
        elif c.isupper():
            # Shift uppercase letters by -2 and handle overflow
            decoded.append(chr((ord(c) - ord('A') - 2) % 26 + ord('A')))
        else:
            # Non-alphabetic characters remain unchanged
            decoded.append(c)
    return ''.join(decoded)

def check_encoding_decoding(text):
    encoded = encode_string(text)
    decoded = decode_string(encoded)
    if text == decoded:
        print(f"Original: {text}")
        print(f"Encoded: {encoded}")
        print(f"Decoded: {decoded}")
        print("Encoding and decoding are correct.")
    else:
        print("There was an error in encoding or decoding.")

