import math

def is_perfect_square(n):
    if not isinstance(n, int):
        return False
    root = int(math.isqrt(n))
    return root * root == n

def find_perfect_squares(num_array):
    perfect_squares = {}

    for sublist in num_array:
        for item in sublist:
            if isinstance(item, int) and is_perfect_square(item):
                root = int(math.isqrt(item))
                perfect_squares[item] = root

    return perfect_squares

# Given multidimensional array
num_array = [[16, "23a", 45], [False, 36, 49, 81], [100, "e", None, 121]]

# Find perfect squares and their square roots
result = find_perfect_squares(num_array)

# Print the result
print(result)

import random

# Define cooking methods and their probabilities
beef_cooking_methods = {
    'grill': 0.4,
    'fry': 0.3,
    'bake': 0.2,
    'boil': 0.1
}

potato_cooking_methods = {
    'bake': 0.5,
    'boil': 0.3,
    'fry': 0.2
}

# Define nutritional content and health requirements
nutritional_content = {
    'grill': {'calories': 200, 'fat': 10},
    'fry': {'calories': 400, 'fat': 30},
    'bake': {'calories': 250, 'fat': 15},
    'boil': {'calories': 150, 'fat': 5}
}

health_requirements = {
    'max_calories': 300,
    'max_fat': 20
}

# Function to filter cooking methods based on health requirements
def filter_cooking_methods(cooking_methods, nutritional_content, health_requirements):
    filtered_methods = {}
    for method, prob in cooking_methods.items():
        if (nutritional_content[method]['calories'] <= health_requirements['max_calories'] and
            nutritional_content[method]['fat'] <= health_requirements['max_fat']):
            filtered_methods[method] = prob
    return filtered_methods

# Function to sample from a probability distribution
def sample_from_distribution(distribution):
    total_prob = sum(distribution.values())
    rand_val = random.uniform(0, total_prob)
    cumulative_prob = 0
    for method, prob in distribution.items():
        cumulative_prob += prob
        if rand_val <= cumulative_prob:
            return method
    return None  # Fallback in case of rounding errors

# Function to cook beef
def cook_beef():
    filtered_methods = filter_cooking_methods(beef_cooking_methods, nutritional_content, health_requirements)
    if not filtered_methods:
        return "No healthy cooking methods available for beef."
    selected_method = sample_from_distribution(filtered_methods)
    return f"Beef is cooked by {selected_method}."

# Function to cook potatoes
def cook_potatoes():
    filtered_methods = filter_cooking_methods(potato_cooking_methods, nutritional_content, health_requirements)
    if not filtered_methods:
        return "No healthy cooking methods available for potatoes."
    selected_method = sample_from_distribution(filtered_methods)
    return f"Potatoes are cooked by {selected_method}."

# Example usage
