print(cook_potatoes())

def calculate_bmi(weight, height):
    """Calculate Body Mass Index (BMI)."""
    bmi = weight / (height ** 2)
    return round(bmi, 2)

def calculate_whr(waist, hip):
    """Calculate Waist-to-Hip Ratio (WHR)."""
    whr = waist / hip
    return round(whr, 2)

def calculate_bmr(weight, body_fat_percentage):
    """Calculate Basal Metabolic Rate (BMR) using the Katch-McArdle formula."""
    lbm = weight * (1 - (body_fat_percentage / 100))
    bmr = 370 + (21.6 * lbm)
    return round(bmr, 2)

def calculate_mhr(age, sex):
    """Calculate Maximum Heart Rate (MHR) using the Tanaka equation."""
    if sex.lower() == 'male':
        mhr = 208 - (0.7 * age)
    elif sex.lower() == 'female':
        mhr = 206 - (0.88 * age)
    else:
        raise ValueError("Sex must be 'male' or 'female'.")
    return round(mhr)

def main():
    # User input
    weight = float(input("Enter your weight in kg: "))
    height = float(input("Enter your height in meters: "))
    waist = float(input("Enter your waist circumference in cm: "))
    hip = float(input("Enter your hip circumference in cm: "))
    body_fat_percentage = float(input("Enter your body fat percentage: "))
