def factorial(n):
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers")
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

class Student:
    def __init__(self, student_id, full_name, age, grades, activities):
        self.student_id = student_id
        self.full_name = full_name
        self.age = age
        self.grades = grades
        self.activities = activities

class StudentSystem:
    def __init__(self):
        self.students = []
        self.age_index = {}
        self.grade_range_index = {}
        self.activity_index = {}

    def add_student(self, student_id, full_name, age, grades, activities):
        student = Student(student_id, full_name, age, grades, activities)
        self.students.append(student)
        self._update_indices(student, add=True)

    def update_student(self, student_id, full_name=None, age=None, grades=None, activities=None):
        for student in self.students:
            if student.student_id == student_id:
                if full_name is not None:
                    student.full_name = full_name
                if age is not None:
                    student.age = age
                if grades is not None:
                    student.grades = grades
                if activities is not None:
                    student.activities = activities
                self._update_indices(student, add=True)
                return
        raise ValueError(f"Student with ID {student_id} not found")

    def get_students_by_age(self, age):
        return [student for student in self.students if student.student_id in self.age_index.get(age, [])]

    def get_students_by_grade_range(self, min_grade, max_grade):
        grade_range = (min_grade, max_grade)
        return [student for student in self.students if student.student_id in self.grade_range_index.get(grade_range, [])]

    def get_students_by_activity(self, activity):
        return [student for student in self.students if student.student_id in self.activity_index.get(activity, [])]

    def _update_indices(self, student, add=False):
        if add:
            self.age_index.setdefault(student.age, []).append(student.student_id)
            for grade in student.grades:
                grade_range = (min(grade), max(grade))
                self.grade_range_index.setdefault(grade_range, []).append(student.student_id)
            for activity in student.activities:
                self.activity_index.setdefault(activity, []).append(student.student_id)
        else:
            self.age_index[student.age].remove(student.student_id)
            for grade in student.grades:
                grade_range = (min(grade), max(grade))
                self.grade_range_index[grade_range].remove(student.student_id)
            for activity in student.activities:
                self.activity_index[activity].remove(student.student_id)

# Example usage
if __name__ == "__main__":
    system = StudentSystem()

    system.add_student(1, "Alice Smith", 18, [85, 90, 92], ["Chess Club", "Debate Team"])
    system.add_student(2, "Bob Johnson", 19, [78, 80, 85], ["Chess Club", "Robotics Club"])
    system.add_student(3, "Charlie Brown", 20, [95, 98, 99], ["Drama Club"])

    print("Students of age 18:")
    for student in system.get_students_by_age(18):
        print(student.full_name)

    print("Students with grades between 80 and 90:")
    for student in system.get_students_by_grade_range(80, 90):
        print(student.full_name)

    print("Students in Chess Club:")
    for student in system.get_students_by_activity("Chess Club"):
        print(student.full_name)

    system.update_student(1, full_name="Alice Doe")
    print("Updated student with ID 1:")
    for student in system.get_students_by_age(18):
        print(student.full_name)

import numpy as np
from scipy.integrate import quad

def validate_input(r1, r2, a, b, h, f, g):
    if r1 < 0 or r2 < 0 or a < 0 or b < 0 or h < 0:
        raise ValueError("Invalid input: negative values are not allowed")
    if f is not None and not callable(f):
        raise ValueError("Invalid input: f must be a callable function")
    if g is not None and not callable(g):
        raise ValueError("Invalid input: g must be a callable function")

def cone_surface_area_and_volume(r1, r2, h):
    A = np.pi * (r1 + r2) * np.sqrt((r1 - r2)**2 + h**2)
    V = (1/3) * np.pi * h * (r1**2 + r1*r2 + r2**2)
    return A, V

def elliptical_cone_surface_area_and_volume(a1, b1, a2, b2, h):
    A = quad(lambda h: 2 * np.pi * np.sqrt(a1**2 + b1**2) * np.sqrt(1 + (a1 - a2)**2 / h**2), 0, h)[0]
    V = (1/3) * np.pi * h * (a1 * b1 + a1 * b2 + a2 * b2)
    return A, V

def non_uniform_cone_surface_area_and_volume(f, h):
    A = quad(lambda h: 2 * np.pi * f(h) * np.sqrt(1 + (f(h + 1e-6) - f(h))**2 / 1e-6), 0, h)[0]
    V = quad(lambda h: np.pi * f(h)**2, 0, h)[0]
    return A, V

def process_cone(r1, r2, a, b, h, f, g, time_points=None):
    validate_input(r1, r2, a, b, h, f, g)

    if g is not None:
        results = []
        for t in time_points:
            r1_t, r2_t, a_t, b_t, h_t = g(t)
            A, V = process_cone(r1_t, r2_t, a_t, b_t, h_t, f, None)
            results.append((A, V))
        return results

    if f is not None:
        return non_uniform_cone_surface_area_and_volume(f, h)

    if a > 0 and b > 0:
        return elliptical_cone_surface_area_and_volume(r1, r1, r2, r2, h)

    return cone_surface_area_and_volume(r1, r2, h)

def main(cones, time_points=None):
    results = []
    for cone in cones:
        r1, r2, a, b, h, f, g = cone
        result = process_cone(r1, r2, a, b, h, f, g, time_points)
        results.append(result)
    return results

# Example usage
cones = [
    (3, 2, 0, 0, 5, None, None),
    (4, 3, 5, 3, 6, None, None),
    (5, 4, 0, 0, 7, lambda h: 5 - h/2, None),
    (6, 5, 7, 4, 8, None, lambda t: (6 + t, 5 + t, 7 + t, 4 + t, 8 + t))
]

time_points = np.linspace(0, 10, 100)
results = main(cones, time_points)
print(results)

def hanoi(n, source, auxiliary, target, step=1):
    if n == 1:
        print(f"Step {step}: Move disk 1 from {source} to {target}")
        return 1
    else:
        step = hanoi(n - 1, source, target, auxiliary, step)
        print(f"Step {step + 1}: Move disk {n} from {source} to {target}")
        step += 1
        step = hanoi(n - 1, auxiliary, source, target, step + 1)
        return step

def solve_tower_of_hanoi(n):
    if not isinstance(n, int) or n < 1:
        raise ValueError("Number of disks must be a positive integer.")

    print(f"Solving Tower of Hanoi for {n} disks:")
    total_steps = hanoi(n, 'A', 'B', 'C')
    print(f"Total steps: {total_steps}")

if __name__ == "__main__":
    try:
        n = int(input("Enter the number of disks: "))
        solve_tower_of_hanoi(n)
    except ValueError as e:
        print(f"Error: {e}")

def second_smallest_odd_element(l: list):
    min1, min2 = None, None
    for x in l:
        if x % 2 != 0:
            if min1 is None:
                min1 = x
            elif x < min1:
                min2 = min1
                min1 = x
            elif min2 is None or x < min2:
                min2 = x
    return min2

# Test Cases:
print(second_smallest_odd_element([1, 2, 3, 4]))  # Expected output: 3
print(second_smallest_odd_element([5, -2, -7, 0, -1, 3, 8, -8, -9, 2, -11]))  # Expected output: -7
print(second_smallest_odd_element([2, 4, 6, 8]))  # Expected output: None
print(second_smallest_odd_element([-1, -3, -5, -7]))  # Expected output: -5

from rest_framework import serializers
from .models import Book, Page

class PageSerializer(serializers.ModelSerializer):
    class Meta:
        model = Page
        fields = ['id', 'text']

class RequestSerializer(serializers.Serializer):
    book_id = serializers.IntegerField()
    pages = PageSerializer(many=True)

    def create(self, validated_data):
        book_id = validated_data['book_id']
        pages_data = validated_data['pages']

        # Get or create the book
        book, created = Book.objects.get_or_create(id=book_id)

        # Create or update pages
        for page_data in pages_data:
            page_id = page_data.get('id')
            if page_id:
                # Update existing page
                Page.objects.update_or_create(id=page_id, book=book, defaults=page_data)
            else:
                # Create new page
                Page.objects.create(book=book, **page_data)

        return {'book_id': book_id, 'pages': pages_data}

    def update(self, instance, validated_data):
        book_id = validated_data['book_id']
        pages_data = validated_data['pages']

        # Get the book
        book = Book.objects.get(id=book_id)

        # Update pages
        for page_data in pages_data:
            page_id = page_data.get('id')
            if page_id:
                # Update existing page
                Page.objects.update_or_create(id=page_id, book=book, defaults=page_data)
            else:
                # Create new page
                Page.objects.create(book=book, **page_data)

        return {'book_id': book_id, 'pages': pages_data}

