# Function to get information about an artifact
def get_artifact_info(artifact_name):
    try:
        info = ancient_artifacts[artifact_name]
        return f"Artifact: {artifact_name}\nPeriod: {info['period']}\nDescription: {info['description']}"
    except KeyError:
        return f"Artifact '{artifact_name}' not found."

# Function to add a new artifact
def add_artifact(artifact_name, period, description):
    if artifact_name in ancient_artifacts:
        return f"Artifact '{artifact_name}' already exists."
    ancient_artifacts[artifact_name] = {"period": period, "description": description}
    return f"Artifact '{artifact_name}' added successfully."

# Function to update an existing artifact
def update_artifact(artifact_name, period=None, description=None):
    if artifact_name not in ancient_artifacts:
        return f"Artifact '{artifact_name}' not found."
    if period:
        ancient_artifacts[artifact_name]["period"] = period
    if description:
        ancient_artifacts[artifact_name]["description"] = description
    return f"Artifact '{artifact_name}' updated successfully."

# Function to delete an artifact
def delete_artifact(artifact_name):
    if artifact_name not in ancient_artifacts:
        return f"Artifact '{artifact_name}' not found."
    del ancient_artifacts[artifact_name]
    return f"Artifact '{artifact_name}' deleted successfully."

