def print_board(board):
    for row in board:
        print(' '.join(str(cell) for cell in row))
    print('---')

def is_valid(board, row, col):
    n = len(board)
    if row < 0 or row >= n or col < 0 or col >= n:
        return False
    if board[row][col] != 0:
        return False
    return True

def place_block(board, row, col, block_type):
    if block_type == '1x1':
        board[row][col] = 1
    elif block_type == '2x1':
        board[row][col] = 2
        board[row][col + 1] = 2

def remove_block(board, row, col, block_type):
    if block_type == '1x1':
        board[row][col] = 0
    elif block_type == '2x1':
        board[row][col] = 0
        board[row][col + 1] = 0

def solve(board, row, col, solutions):
    n = len(board)
    if row == n:
        solutions.append([row[:] for row in board])
        return

    if col == n:
        solve(board, row + 1, 0, solutions)
        return

    if board[row][col] != 0:
        solve(board, row, col + 1, solutions)
        return

    # Try placing a 1x1 block
    place_block(board, row, col, '1x1')
    solve(board, row, col + 1, solutions)
    remove_block(board, row, col, '1x1')

    # Try placing a 2x1 block
    if col + 1 < n and board[row][col + 1] == 0:
        place_block(board, row, col, '2x1')
        solve(board, row, col + 2, solutions)
        remove_block(board, row, col, '2x1')

def find_all_tilings():
    n = 3
    board = [[0] * n for _ in range(n)]
    solutions = []
    solve(board, 0, 0, solutions)
    for solution in solutions:
        print_board(solution)

find_all_tilings()

from flask_sqlalchemy import SQLAlchemy
from flask_migrate import Migrate

db = SQLAlchemy()
migrate = Migrate()

class User(db.Model):
    __tablename__ = 'users'

    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(64), index=True, unique=True)
    password_hash = db.Column(db.String(128))
    tasks = db.relationship('Task', backref='user', lazy='dynamic')

    def __repr__(self):
        return '<User {}>'.format(self.username)

class Task(db.Model):
    __tablename__ = 'tasks'

    id = db.Column(db.Integer, primary_key=True)
    title = db.Column(db.String(128))
    completed = db.Column(db.Boolean, default=False)
    user_id = db.Column(db.Integer, db.ForeignKey('users.id'))

    def __repr__(self):
        return '<Task {}>'.format(self.title)

import os
from os.path import join, getsize

def GetFolderSize(path):
    TotalSize = 0
    for entry in os.scandir(path):
        if entry.is_file():
            try:
                TotalSize += entry.stat().st_size
            except OSError:
                print("error with file: " + entry.path)
        elif entry.is_dir():
            TotalSize += GetFolderSize(entry.path)
    return TotalSize

