class Room:
    def __init__(self, name, description, items=None, exits=None, puzzle=None, puzzle_solution=None):
        self.name = name
        self.description = description
        self.items = items if items is not None else []
        self.exits = exits if exits is not None else {}
        self.puzzle = puzzle
        self.puzzle_solution = puzzle_solution

    def add_item(self, item):
        self.items.append(item)

    def remove_item(self, item):
        if item in self.items:
            self.items.remove(item)

    def solve_puzzle(self, solution):
        if self.puzzle and solution == self.puzzle_solution:
            print("Puzzle solved!")
            self.puzzle = None
            self.puzzle_solution = None
            return True
        else:
            print("That doesn't seem to solve the puzzle.")
            return False

    def describe(self):
        print(f"--- {self.name} ---")
        print(self.description)
        if self.items:
            print("Items in the room:", ", ".join(self.items))
        if self.puzzle:
            print("There is a puzzle to solve here.")
        print("Exits:", ", ".join(self.exits.keys()))

def main():
    # Define rooms
    kitchen = Room(
        name="Kitchen",
        description="You are in a dimly lit kitchen. There is a table with some utensils and a door leading to the hallway.",
        items=["knife", "spoon"],
        exits={"east": "hallway"}
    )

    hallway = Room(
        name="Hallway",
        description="You are in a long hallway. There are doors to the north, south, and east.",
        exits={"north": "bedroom", "south": "kitchen", "east": "living room"}
    )

    bedroom = Room(
        name="Bedroom",
        description="You are in a cozy bedroom. There is a bed and a small desk with a locked drawer.",
        items=["book"],
        puzzle="What is the combination to the drawer?",
        puzzle_solution="1234"
    )

    living_room = Room(
        name="Living Room",
        description="You are in a spacious living room. There is a couch, a TV, and a door to the outside.",
        items=["remote", "key"],
        exits={"west": "hallway", "east": "outside"}
    )

    outside = Room(
        name="Outside",
        description="You are outside the house. You have escaped! Congratulations!",
        exits={}
    )

    # Set up room connections
    kitchen.exits["east"] = hallway
    hallway.exits["north"] = bedroom
    hallway.exits["south"] = kitchen
    hallway.exits["east"] = living_room
    living_room.exits["west"] = hallway
    living_room.exits["east"] = outside

    # Player's inventory
    inventory = []

    # Starting room
    current_room = kitchen

    while True:
        current_room.describe()
        command = input("What do you want to do? ").lower().split()

        if not command:
            continue

        action = command[0]

        if action == "go":
            if len(command) > 1:
                direction = command[1]
                if direction in current_room.exits:
                    current_room = current_room.exits[direction]
                else:
                    print("You can't go that way.")
            else:
                print("Go where?")

        elif action == "take":
            if len(command) > 1:
                item = command[1]
                if item in current_room.items:
