class ListNode:
    def __init__(self, value=0, next=None):
        self.value = value
        self.next = next

def get_length_and_tail(head):
    length = 0
    while head:
        length += 1
        if not head.next:
            return length, head
        head = head.next
    return length, None

def get_intersection_node(head1, head2):
    length1, tail1 = get_length_and_tail(head1)
    length2, tail2 = get_length_and_tail(head2)

    # If the tails are different, the lists do not intersect
    if tail1 != tail2:
        return None

    # Equalize the lengths
    if length1 > length2:
        for _ in range(length1 - length2):
            head1 = head1.next
    else:
        for _ in range(length2 - length1):
            head2 = head2.next

    # Find the intersection node
    while head1 != head2:
        head1 = head1.next
        head2 = head2.next

    return head1

