from datetime import datetime

def number_to_words(n):
    words = {
        0: 'Zero', 1: 'One', 2: 'Two', 3: 'Three', 4: 'Four', 5: 'Five',
        6: 'Six', 7: 'Seven', 8: 'Eight', 9: 'Nine', 10: 'Ten',
        11: 'Eleven', 12: 'Twelve', 13: 'Thirteen', 14: 'Fourteen',
        15: 'Fifteen', 16: 'Sixteen', 17: 'Seventeen', 18: 'Eighteen',
        19: 'Nineteen', 20: 'Twenty', 30: 'Thirty', 40: 'Forty',
        50: 'Fifty', 60: 'Sixty', 70: 'Seventy', 80: 'Eighty', 90: 'Ninety'
    }

    if n in words:
        return words[n]
    elif n < 100:
        return words[n - n % 10] + '-' + words[n % 10].lower()
    elif n < 1000:
        if n % 100 == 0:
            return words[n // 100] + ' Hundred'
        else:
            return words[n // 100] + ' Hundred and ' + number_to_words(n % 100)
    else:
        raise ValueError("Number out of supported range")

def month_to_words(month):
    months = {
        1: 'January', 2: 'February', 3: 'March', 4: 'April', 5: 'May', 6: 'June',
        7: 'July', 8: 'August', 9: 'September', 10: 'October', 11: 'November', 12: 'December'
    }
    return months[month]

def convert_iso_to_words(iso_timestamp):
    dt = datetime.fromisoformat(iso_timestamp.replace('Z', '+00:00'))

    # Extract components
    year = dt.year
    month = dt.month
    day = dt.day
    hour = dt.hour
    minute = dt.minute
    second = dt.second

    # Convert to words
    year_words = number_to_words(year)
    month_words = month_to_words(month)
    day_words = number_to_words(day)

    if hour == 0:
        hour_words = 'Twelve'
    else:
        hour_words = number_to_words(hour % 12)

    minute_words = number_to_words(minute)
    am_pm = 'AM' if hour < 12 else 'PM'

    # Combine into final string
    time_words = f"{hour_words} {minute_words} {am_pm}, {day_words} of {month_words} {year_words}"

    return time_words

