import math
from random import randint

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def pollards_rho(n):
    if n % 2 == 0:
        return 2
    if is_prime(n):
        return n

    def f(x):
        return (x * x + 1) % n

    x, y, d = 2, 2, 1
    while d == 1:
        x = f(x)
        y = f(f(y))
        d = math.gcd(abs(x - y), n)
    return d

def prime_factorization(n):
    if n == 1:
        return []
    factors = set()
    # Check for divisibility by 2
    while n % 2 == 0:
        factors.add(2)
        n //= 2
    # Check for divisibility by odd numbers up to a limit
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        while n % i == 0:
            factors.add(i)
            n //= i
    # If n is a prime number greater than 2
    if n > 2:
        factors.add(n)
    # Use Pollard's Rho for large numbers
    while not is_prime(n) and n > 1:
        factor = pollards_rho(n)
        factors.add(factor)
        n //= factor
    return sorted(factors)

# Test Cases
def test_prime_factorization():
    assert prime_factorization(8) == [2]
    assert prime_factorization(25) == [5]
    assert prime_factorization(70) == [2, 5, 7]
    assert prime_factorization(100) == [2, 5]
    assert prime_factorization(1000003) == [1000003]
    assert prime_factorization(1000000007) == [1000000007]
    assert prime_factorization(1234567890123456789) == [3, 7, 11, 13, 37, 101, 9901, 99990001]

