import numpy as np

class TicTacToe:
    def __init__(self):
        self.board = np.zeros((3, 3))
        self.current_player = 1  # 1 for player 1, -1 for player 2
        self.done = False
        self.winner = None

    def reset(self):
        self.board = np.zeros((3, 3))
        self.current_player = 1
        self.done = False
        self.winner = None
        return self.board

    def available_actions(self):
        return [(i, j) for i in range(3) for j in range(3) if self.board[i, j] == 0]

    def step(self, action):
        if self.board[action] != 0:
            return self.board, -1, True, "Invalid move"

        self.board[action] = self.current_player
        if self.check_winner():
            self.done = True
            self.winner = self.current_player
            reward = 1
        elif len(self.available_actions()) == 0:
            self.done = True
            reward = 0
        else:
            self.current_player = -self.current_player
            reward = 0

        return self.board, reward, self.done, {}

    def check_winner(self):
        for i in range(3):
            if np.all(self.board[i, :] == self.current_player) or np.all(self.board[:, i] == self.current_player):
                return True
        if np.all(np.diag(self.board) == self.current_player) or np.all(np.diag(np.fliplr(self.board)) == self.current_player):
            return True
        return False

    def render(self):
        print(self.board)

