import concurrent.futures
import random

def prime_factor(value):
    factors = []
    for divisor in range(2, value):
        quotient, remainder = divmod(value, divisor)
        if not remainder:
            factors.extend(prime_factor(divisor))
            factors.extend(prime_factor(quotient))
            break
    else:
        factors = [value]
    return factors

