}

bool yet_another_function() {
    detect_signif(bstartg(end-4));
}
"""

# Regular expression to match the function definition with return type bool
function_pattern = re.compile(r"""
    bool\s+            # Match 'bool' return type
    \w+\s*             # Match function name and optional whitespace
    \([^)]*\)\s*       # Match function parameters
    \{                 # Match opening brace
    (.*?)              # Match function body (non-greedy)
    \}                 # Match closing brace
""", re.VERBOSE | re.DOTALL)

# Regular expression to match the specific code snippet
code_snippet_pattern = re.compile(r"(\bdetect_signif\(bstartg\(end-4\)\))")

# Function to replace the code snippet within the function body
def replace_code_snippet(match):
    function_body = match.group(1)
    replaced_body = code_snippet_pattern.sub(r"\1, se_bstartg(end-4)", function_body)
    return f"bool {match.group(2)}({match.group(3)}) {{ {replaced_body} }}"

# Substitute the matched function definitions with the replaced code
result = function_pattern.sub(replace_code_snippet, code)

print(result)

class Student:
    def __init__(self, name, age, grade_level):
        self.name = name
        self.age = age
        self.grade_level = grade_level
        self.subjects = []  # List to store subjects
        self.grades = {}    # Dictionary to store grades for each subject

    def add_subject(self, subject):
        if subject not in self.subjects:
            self.subjects.append(subject)
            self.grades[subject] = None  # Initialize grade for the subject as None

    def remove_subject(self, subject):
        if subject in self.subjects:
            self.subjects.remove(subject)
            del self.grades[subject]

    def get_subjects(self):
        return self.subjects

    def set_grade(self, subject, grade):
        if subject in self.subjects:
            if 0 <= grade <= 100:
                self.grades[subject] = grade
            else:
                raise ValueError("Grade must be between 0 and 100")
        else:
            raise ValueError(f"Subject {subject} is not enrolled")

    def get_average_grade(self):
        total_grades = 0
        count = 0
        for subject, grade in self.grades.items():
            if grade is not None:
                total_grades += grade
                count += 1
        if count == 0:
            return None  # No grades available
        return total_grades / count

