def fetch_effective_tax_rules(current_date):
    return TaxRule.query.filter(
        (TaxRule.effective_date <= current_date) &
        (or_(TaxRule.expiration_date.is_(None), TaxRule.expiration_date > current_date))
    ).all()

def evaluate_criteria(tax_rule, data):
    criteria = TaxCriterion.query.filter_by(tax_rule_id=tax_rule.tax_rule_id).all()
    combination = TaxCriterionCombination.query.filter_by(tax_rule_id=tax_rule.tax_rule_id).first()

    results = []
    for criterion in criteria:
        field_value = data.get(criterion.criterion_field)
        if criterion.criterion_type == 'boolean':
            result = field_value == (criterion.value == 'true')
        elif criterion.criterion_type == 'numeric':
            result = eval(f"{field_value} {criterion.operator} {criterion.value}")
        elif criterion.criterion_type == 'categorical':
            result = field_value == criterion.value
        results.append(result)

    if combination.combination_type == 'AND':
        return all(results)
    elif combination.combination_type == 'OR':
        return any(results)

def apply_tax(data, current_date):
    tax_rules = fetch_effective_tax_rules(current_date)
    for tax_rule in tax_rules:
        if evaluate_criteria(tax_rule, data):
            data['tax_amount'] += data['taxable_amount'] * tax_rule.tax_rate
    return data

from typing import List, Tuple, Dict

class InsufficientBalanceException(Exception):
    pass

def below_zero(operations: Dict[int, List[Tuple[str, int]]], case_insensitive: bool = False) -> Dict[str, List[int]]:
    """
    Starting with zero balance, implement a system to track deposit and withdrawal operations on different bank accounts. Recognize when a balance turns negative and invoke an "InsufficientBalanceException" at such instances. End the operation by returning a dictionary presenting a list of account numbers that stayed above zero. If a case_insensitive flag is true, interpret 'Deposit' and 'deposit', 'Withdrawal' and 'withdrawal' as identical, and consider the balance at zero as well.

    Input dictionary presents tuples in the structure (Operation_type, Operation_value) as the value and Account_number as the key.

    Examples:
    >>> below_zero({1: [('Deposit', 1), ('Deposit', 2), ('Deposit', 3)]})
    {1: ['No negative balance']}
    >>> below_zero({1: [('Deposit', 1), ('Deposit', 2), ('Withdrawal', 4), ('Deposit', 5)]})
    InsufficientBalanceException: 'Account 1 has insufficient balance.'
    >>> below_zero({1: [('Deposit', 1), ('Deposit', 2), ('withdrawal', 3)]}, True)
    InsufficientBalanceException: 'Account 1 has insufficient balance.'
    """

    positive_balance_accounts = {}

    for account_number, ops in operations.items():
        balance = 0
        for op_type, op_value in ops:
            if case_insensitive:
                op_type = op_type.lower()

            if op_type == 'deposit':
                balance += op_value
            elif op_type == 'withdrawal':
                balance -= op_value
            else:
                raise ValueError(f"Unknown operation type: {op_type}")

            if balance < 0:
                raise InsufficientBalanceException(f'Account {account_number} has insufficient balance.')
            if case_insensitive and balance == 0:
                raise InsufficientBalanceException(f'Account {account_number} has insufficient balance.')

        positive_balance_accounts[account_number] = ['No negative balance']

    return positive_balance_accounts

# Example usage:
if __name__ == "__main__":
    try:
        print(below_zero({1: [('Deposit', 1), ('Deposit', 2), ('Deposit', 3)]}))
        print(below_zero({1: [('Deposit', 1), ('Deposit', 2), ('Withdrawal', 4), ('Deposit', 5)]}))
        print(below_zero({1: [('Deposit', 1), ('Deposit', 2), ('withdrawal', 3)]}, True))
    except InsufficientBalanceException as e:
        print(e)

class Class:
    def __init__(self, classname, teacher):
        self.classname = classname
        self.teacher = teacher

    def __repr__(self):
        return f"Class(classname='{self.classname}', teacher='{self.teacher}')"

class StudentData:
    def __init__(self):
        self.students = {}

    def add_student(self, name, age):
        if name in self.students:
            raise ValueError(f"Student with name '{name}' already exists.")
        self.students[name] = {"age": age, "classes": []}

    def remove_student(self, name):
        if name not in self.students:
            raise ValueError(f"Student with name '{name}' does not exist.")
        del self.students[name]

    def update_student_age(self, name, age):
        if name not in self.students:
            raise ValueError(f"Student with name '{name}' does not exist.")
        self.students[name]["age"] = age

    def enroll_student(self, name, classname, teacher):
        if name not in self.students:
            raise ValueError(f"Student with name '{name}' does not exist.")
        class_obj = Class(classname, teacher)
        if class_obj not in self.students[name]["classes"]:
            self.students[name]["classes"].append(class_obj)

    def unenroll_student(self, name, classname):
        if name not in self.students:
            raise ValueError(f"Student with name '{name}' does not exist.")
        self.students[name]["classes"] = [cls for cls in self.students[name]["classes"] if cls.classname != classname]

    def get_student_data(self, name):
        if name not in self.students:
            raise ValueError(f"Student with name '{name}' does not exist.")
        return self.students[name]

    def __repr__(self):
        return f"StudentData(students={self.students})"

