def process_files(file1, file2):
    import re

    def read_file(file_path):
        with open(file_path, 'r') as file:
            return [line.strip().split() for line in file]

    def is_valid_id(id):
        return re.match(r'^[a-zA-Z0-9]+$', id) is not None

    def filter_rows(rows):
        return {row[0].lower(): row[1] for row in rows if is_valid_id(row[0])}

    # Read and filter rows from both files
    rows1 = filter_rows(read_file(file1))
    rows2 = filter_rows(read_file(file2))

    # Find common ids and check for "foo"
    common_ids = set(rows1.keys()) & set(rows2.keys())
    result = {id: (rows1[id], rows2[id]) for id in common_ids if rows1[id] == 'foo' and rows2[id] == 'foo'}

    return result

# Example usage
