def compile_and_run(i):
    filename = f"test{i}.c"
    with open(filename, "w") as f:
        f.write(f"const main={i};")

    try:
        subprocess.run(["gcc", filename, "-o", f"test{i}"], check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except subprocess.CalledProcessError as e:
        return f"const main={hex(i)} : Compilation failed: {e.stderr.decode().strip()}"

    process = subprocess.Popen(f"./test{i}", shell=True)
    result = process.wait()

    if result == -11:
        result = "segfault"
    elif result == -10:
        result = "bus error"
    elif result == -4:
        result = "illegal instruction"
    elif result == -5:
        result = "trap"
    else:
        result = f"exit code {result}"

    return f"const main={hex(i)} : {result}"

with concurrent.futures.ThreadPoolExecutor(max_workers=8) as executor:
    futures = [executor.submit(compile_and_run, i) for i in range(65536)]
    for future in concurrent.futures.as_completed(futures):
        print(future.result())

import sqlparse
import json

def sql_to_es(sql_query):
    try:
        parsed = sqlparse.parse(sql_query)
        if not parsed:
            raise ValueError("Invalid SQL query")

        statement = parsed[0]
        es_query = {}

        # Extract SELECT clause
        select_clause = [token for token in statement.tokens if isinstance(token, sqlparse.sql.IdentifierList) or isinstance(token, sqlparse.sql.Identifier)]
        select_fields = [field.value for field in select_clause[0].tokens if isinstance(field, sqlparse.sql.Identifier)]

        es_query['_source'] = select_fields

        # Extract FROM clause
        from_clause = [token for token in statement.tokens if isinstance(token, sqlparse.sql.Identifier) and token.value.lower() != 'from']
        index_name = from_clause[0].value
        es_query['index'] = index_name

        # Extract WHERE clause
        where_clause = [token for token in statement.tokens if isinstance(token, sqlparse.sql.Where)]
        if where_clause:
            es_query['query'] = {'bool': {'must': []}}
            where_conditions = parse_where_clause(where_clause[0])
            es_query['query']['bool']['must'].extend(where_conditions)

        # Extract GROUP BY clause
        group_by_clause = [token for token in statement.tokens if isinstance(token, sqlparse.sql.Token) and token.value.lower() == 'group by']
        if group_by_clause:
            group_by_conditions = parse_group_by_clause(statement)
            es_query['aggs'] = group_by_conditions

        # Extract HAVING clause
        having_clause = [token for token in statement.tokens if isinstance(token, sqlparse.sql.Token) and token.value.lower() == 'having']
        if having_clause:
            having_conditions = parse_having_clause(statement)
            es_query['query']['bool']['filter'] = having_conditions

        return json.dumps(es_query, indent=4)
    except Exception as e:
        return f"Error: {str(e)}"

def parse_where_clause(where_clause):
    conditions = []
    for token in where_clause.tokens:
        if isinstance(token, sqlparse.sql.Comparison):
            conditions.append(parse_comparison(token))
        elif isinstance(token, sqlparse.sql.Token) and token.value.lower() in ('and', 'or'):
            conditions.append(token.value.lower())
    return conditions

def parse_comparison(comparison):
    left = comparison.left.value
    right = comparison.right.value
    operator = comparison.token_next(0, skip_cm=True).value

    if operator == '=':
        return {'term': {left: right}}
    elif operator == '!=':
        return {'bool': {'must_not': {'term': {left: right}}}}
    elif operator in ('>', '<', '>=', '<='):
        return {'range': {left: {operator: right}}}
    elif operator == 'like':
        return {'wildcard': {left: right}}
    elif operator == 'in':
        values = [val.value for val in comparison.right.get_identifiers()]
        return {'terms': {left: values}}
    else:
        raise ValueError(f"Unsupported operator: {operator}")

def parse_group_by_clause(statement):
    group_by_conditions = {}
    for token in statement.tokens:
        if isinstance(token, sqlparse.sql.Token) and token.value.lower() == 'group by':
            group_by_fields = [field.value for field in statement.tokens[token.pos + 1].get_identifiers()]
            group_by_conditions = {'group_by': {}}
            for field in group_by_fields:
                group_by_conditions['group_by'][field] = {'terms': {'field': field}}
            break
    return group_by_conditions

def parse_having_clause(statement):
    having_conditions = []
    for token in statement.tokens:
        if isinstance(token, sqlparse.sql.Token) and token.value.lower() == 'having':
            having_conditions = parse_where_clause(token)
            break
    return having_conditions

# Example usage
sql_query = """
SELECT name, age
FROM users
WHERE age > 25 AND name LIKE 'J%'
GROUP BY name
HAVING COUNT(name) > 1
"""

es_query = sql_to_es(sql_query)
print(es_query)

import json
import os

class CostCenterManager:
    def __init__(self, file_path='data/cost_centers.json'):
        self.file_path = file_path
        self.cost_centers = self._load_cost_centers()
        if not self.cost_centers:
            self.next_id = 1
        else:
            self.next_id = max(int(cc['id']) for cc in self.cost_centers) + 1

    def _load_cost_centers(self):
        if os.path.exists(self.file_path):
            with open(self.file_path, 'r') as file:
                return json.load(file)
        return []

    def _save_cost_centers(self):
        with open(self.file_path, 'w') as file:
            json.dump(self.cost_centers, file, indent=4)

    def _validate_cost_center(self, project_name, tags, status):
        if len(project_name) > 50 or len(tags) > 50:
            raise ValueError("Project name and tags must not exceed 50 characters.")
        if status not in ['active', 'inactive']:
            raise ValueError("Status must be either 'active' or 'inactive'.")

    def _check_admin_privilege(self, user, tag):
        if tag == 'admin_only' and user != 'admin':
            raise PermissionError("Only users with admin privileges can modify cost centers with the 'admin_only' tag.")

    def add_cost_center(self, user, project_name, tags, status):
        self._validate_cost_center(project_name, tags, status)
        self._check_admin_privilege(user, tags)

        new_cost_center = {
            'id': self.next_id,
            'project_name': project_name,
            'tags': tags,
            'status': status
        }
        self.cost_centers.append(new_cost_center)
        self._save_cost_centers()
        self.next_id += 1
        return new_cost_center

    def update_cost_center(self, user, cost_center_id, project_name=None, tags=None, status=None):
        cost_center = next((cc for cc in self.cost_centers if cc['id'] == cost_center_id), None)
        if not cost_center:
            raise ValueError(f"Cost center with ID {cost_center_id} does not exist.")

        if tags:
            self._check_admin_privilege(user, tags)

        if project_name:
            self._validate_cost_center(project_name, cost_center['tags'], cost_center['status'])
            cost_center['project_name'] = project_name

        if tags:
            self._validate_cost_center(cost_center['project_name'], tags, cost_center['status'])
            cost_center['tags'] = tags

        if status:
            self._validate_cost_center(cost_center['project_name'], cost_center['tags'], status)
            cost_center['status'] = status

        self._save_cost_centers()
        return cost_center

    def delete_cost_center(self, user, cost_center_id):
        cost_center = next((cc for cc in self.cost_centers if cc['id'] == cost_center_id), None)
        if not cost_center:
            raise ValueError(f"Cost center with ID {cost_center_id} does not exist.")

        self._check_admin_privilege(user, cost_center['tags'])

        self.cost_centers.remove(cost_center)
        self._save_cost_centers()
        return cost_center

# Example usage:
if __name__ == "__main__":
    manager = CostCenterManager()

    # Add a new cost center
    new_cc = manager.add_cost_center('admin', 'Project A', 'admin_only', 'active')
    print("Added Cost Center:", new_cc)

    # Update an existing cost center
    updated_cc = manager.update_cost_center('admin', new_cc['id'], project_name='Project B', tags='public', status='inactive')
    print("Updated Cost Center:", updated_cc)

    # Delete a cost center
    deleted_cc = manager.delete_cost_center('admin', new_cc['id'])
    print("Deleted Cost Center:", deleted_cc)

