        keys = []
    if values is None:
        values = []

    # Ensure keys and values are unique
    unique_keys = list(dict.fromkeys(keys))
    unique_values = list(dict.fromkeys(values))

    # Initialize the result list
    result = []

    # Generate dictionaries for the provided keys
    for key in unique_keys:
        if len(result) >= N:
            break
        nested_dict = {str(uuid.uuid4()): None} if populate_nested else {}
        result.append({key: nested_dict})

    # Generate dictionaries for the provided values
    for i, value in enumerate(unique_values):
        if len(result) >= N:
            break
        nested_dict = {i: value} if value is not None else {str(uuid.uuid4()): None}
        if populate_nested and not nested_dict:
            nested_dict = {str(uuid.uuid4()): None}
        result.append({str(uuid.uuid4()): nested_dict})

    # Generate dictionaries with unique identifiers until N dictionaries are created
    while len(result) < N:
        key = str(uuid.uuid4())
        nested_dict = {str(uuid.uuid4()): None} if populate_nested else {}
        result.append({key: nested_dict})

    return result

