import time
import math

def is_pythagorean_quadruplet(a1, a2, a3, a4):
    """
    Check if the given numbers form a Pythagorean quadruplet.
    """
    return a1**2 + a2**2 + a3**2 == a4**2

def find_pythagorean_quadruplet(y):
    """
    Find the smallest Pythagorean quadruplet with sum y.

    :param y: The target sum for the quadruplet.
    :return: A tuple (a1, a2, a3, a4) if found, otherwise None.
    """
    for a1 in range(1, y):
        for a2 in range(a1, y - a1):
            for a3 in range(a2, y - a1 - a2):
                a4 = y - a1 - a2 - a3
                if a4 > a3 and is_pythagorean_quadruplet(a1, a2, a3, a4):
                    return (a1, a2, a3, a4)
    return None

def main(y):
    """
    Main function to find and validate the Pythagorean quadruplet and measure execution time.

    :param y: The target sum for the quadruplet.
    """
    if not isinstance(y, int):
        raise ValueError("Input must be an integer.")

    start_time = time.time()

    quadruplet = find_pythagorean_quadruplet(y)

    end_time = time.time()
    execution_time = end_time - start_time

    if quadruplet:
        a1, a2, a3, a4 = quadruplet
        print(f"Found Pythagorean quadruplet: {quadruplet}")
        print(f"Verification: {a1}^2 + {a2}^2 + {a3}^2 = {a4}^2")
        print(f"Sum: {a1} + {a2} + {a3} + {a4} = {y}")
    else:
        print("No Pythagorean quadruplet found for the given sum.")

    print(f"Execution time: {execution_time:.6f} seconds")

if __name__ == "__main__":
    y = 30
    try:
        main(y)
    except ValueError as e:
        print(e)

import itertools
import math
from typing import List, Tuple

def generate_expression(numbers: List[int], target: int, allow_duplicates: bool) -> Tuple[str, int]:
    def evaluate_expression(expr: str) -> float:
        try:
            return eval(expr)
        except ZeroDivisionError:
            return float('inf')
        except Exception:
            return float('nan')

    def is_valid_expression(expr: str) -> bool:
        try:
            eval(expr)
            return True
        except:
            return False

    def generate_expressions(nums: List[int], target: int, max_steps: int) -> Tuple[str, int]:
        if not nums:
            return "", -1

        # Generate all permutations of the numbers
        permutations = list(itertools.permutations(nums))
        if not allow_duplicates:
            permutations = list(set(permutations))

        # Generate all possible combinations of operations
        operations = ['+', '-', '*', '/', '**', 'math.log']

        for perm in permutations:
            for steps in range(1, max_steps + 1):
                for ops in itertools.product(operations, repeat=steps):
                    expr = str(perm[0])
                    used_numbers = 1
                    for i, op in enumerate(ops):
                        if used_numbers < len(perm):
                            if op == 'math.log':
                                if perm[used_numbers] > 0 and perm[used_numbers] != 1:
                                    expr += f" {op}({perm[used_numbers]})"
                                    used_numbers += 1
                                else:
                                    break
                            else:
                                expr += f" {op} {perm[used_numbers]}"
                                used_numbers += 1
                        else:
                            break

                    if is_valid_expression(expr):
                        result = evaluate_expression(expr)
                        if math.isclose(result, target, rel_tol=1e-9):
                            return expr, steps

        return "", -1

    # Set a reasonable maximum number of steps
    max_steps = 5
    expression, steps = generate_expressions(numbers, target, max_steps)
    return expression, steps

