FILES = [r"\.env", r"\.ssh", r"/etc/", r"credentials", r"token", r"apikey", r"private"]
SHELL = [r"curl .*\| bash", r"chmod \+x", r"sudo", r"rm -rf"]
rules = [("EXFIL", EXFIL), ("FILES", FILES), ("SHELL", SHELL)]
risk_score = 0
findings = []
