import bisect
from collections.abc import Iterable
from typing import NamedTuple
from torch.utils.data import ConcatDataset
# can't be a local class as it is required to be pickleable
class _InterleavedConcatDataset(ConcatDataset):
    """`torch.utils.data.ConcatDataset` but it returns the dataset index."""
    def __getitem__(self, idx):
        if idx < 0:
            if -idx > len(self):
                raise ValueError("absolute value of index should not exceed dataset length")
            idx = len(self) + idx
        dataset_idx = bisect.bisect_right(self.cumulative_sizes, idx)
        if dataset_idx == 0:
            sample_idx = idx
        else:
            sample_idx = idx - self.cumulative_sizes[dataset_idx - 1]
        return dataset_idx, self.datasets[dataset_idx][sample_idx]
# can't be a local class as it is required to be pickleable
class _InterleavedCollator:
    """Holds a list of collators and calls a single one of them based on the dataset_idx that was returned."""
    def __init__(self, collators):
        self.collators = collators
    def __call__(self, data):
        dataset_idxs, data = zip(*data, strict=True)
        if not all(dataset_idxs[0] == idx for idx in dataset_idxs):
            raise ValueError("All samples in a batch must come from the same dataset.")
        return self.collators[dataset_idxs[0]](data)
class SamplerOutput(NamedTuple):  #  lint-ignore: NoNamedTuple
    """Output of the InterleavedSampler. Contains the sample index and the dataset index."""
    is_full_batch: bool
    idx: int
# can't be a local class as it is required to be pickleable
class _InterleavedBatchSampler:
    """Creates batches of indices from an iterable of indices."""
    def __init__(self, sampler: Iterable[SamplerOutput]):
        super().__init__()
        self.sampler = sampler
    def __iter__(self):
        idxs = []
        for is_full_batch, idx in self.sampler:
            idxs.append(idx)
            if is_full_batch:
                yield idxs
                idxs = []
        assert len(idxs) == 0
    def __len__(self):
        raise NotImplementedError

import torch.nn as nn
try:
    import torch_npu
except ImportError:
    tmo = None
class NpuQuantLinearInt8(nn.Module):
    def __init__(self, in_features, out_features, bias=True, dtype=torch.bfloat16):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.register_buffer("weight", torch.empty((out_features, in_features), dtype=torch.int8))
        self.register_buffer("weight_scale", torch.empty((out_features, 1), dtype=torch.float32))
        if bias:
            self.register_buffer("bias", torch.empty(out_features, dtype=dtype))
        else:
            self.register_buffer("bias", None)
    def act_quant_func(self, x):
        input_tensor_quant, input_tensor_scale = torch_npu.npu_dynamic_quant(x)
        return input_tensor_quant, input_tensor_scale
    def forward(self, input_tensor):
        dtype = input_tensor.dtype
        input_tensor_quant, input_tensor_scale = self.act_quant_func(input_tensor)
        output_tensor = torch_npu.npu_quant_matmul(
            input_tensor_quant, self.weight.t(), self.weight_scale.reshape(-1), offset=None, bias=self.bias, pertoken_scale=input_tensor_scale.reshape(-1), output_dtype=dtype
        )
        if len(output_tensor.shape) == 2:
            return output_tensor.unsqueeze(0)
        elif len(output_tensor.shape) == 3:
            return output_tensor
    def _apply(self, fn):
        for module in self.children():
            module._apply(fn)
        def maybe_cast(t):
            if t is not None and t.device != fn(t).device:
                return fn(t)
            return t
        self.weight = maybe_cast(self.weight)
        self.weight_scale = maybe_cast(self.weight_scale)
        self.bias = maybe_cast(self.bias)
        return self

