class VQAEvalDataset(BaseEvalDataset):
    def __init__(self, text_path, image_path):
        super().__init__(text_path, image_path)
    def build_prompt(self, line):
        msgs = super().build_prompt(line)
        if msgs[-1]['type'] != 'text':
