import gym
import numpy as np
from gym.spaces import Box, Dict
class SinglePrecision(gym.ObservationWrapper):
    def __init__(self, env):
        super().__init__(env)
        if isinstance(self.observation_space, Box):
            obs_space = self.observation_space
            self.observation_space = Box(obs_space.low, obs_space.high,
                                         obs_space.shape)
        elif isinstance(self.observation_space, Dict):
            obs_spaces = copy.copy(self.observation_space.spaces)
            for k, v in obs_spaces.items():
                obs_spaces[k] = Box(v.low, v.high, v.shape)
            self.observation_space = Dict(obs_spaces)
        else:
            raise NotImplementedError
    def observation(self, observation) -> np.ndarray:
        if isinstance(observation, np.ndarray):
            return observation.astype(np.float32)
        elif isinstance(observation, dict):
            observation = copy.copy(observation)
            for k, v in observation.items():
                observation[k] = v.astype(np.float32)
            return observation

import json
import click
from .helpers import extract_tree, sum_tree, convert_balance, convert_tree, filter_by_date, period_boundaries
@click.command("income-statement")
@click.pass_context
def income_statement(ctx):
    """Print income statement as JSON for a beancount file."""
    from beancount.core import realization
    obj = ctx.obj
    entries, options = obj["entries"], obj["options"]
    price_map, convert = obj["price_map"], obj["convert"]
    start_date, end_date = obj["start_date"], obj["end_date"]
    if not obj["history"]:
        filtered = filter_by_date(entries, start_date, end_date)
        real = realization.realize(filtered)
        result = {
            "income": extract_tree(realization, real, options["name_income"]),
            "expenses": extract_tree(realization, real, options["name_expenses"]),
        }
        if convert:
            date = end_date - datetime.timedelta(days=1) if end_date else None
            result = {k: convert_tree(v, price_map, convert, date) for k, v in result.items()}
        click.echo(json.dumps(result))
        return
    periods = period_boundaries(start_date, end_date, obj["granularity"])
    result = []
    for p_start, p_end, label in periods:
        filtered = filter_by_date(entries, p_start, p_end)
        real = realization.realize(filtered)
        row = {
            "period": label,
            "income": sum_tree(realization, real, options["name_income"]),
            "expenses": sum_tree(realization, real, options["name_expenses"]),
        }
        if convert:
            date = p_end - datetime.timedelta(days=1)
            for key in ("income", "expenses"):
                row[key] = convert_balance(row[key], price_map, convert, date)
        result.append(row)
    click.echo(json.dumps(result))

from copy import deepcopy
import yaml
# TO CHECK these args when used, the default type for these args are not right.
# _BOOL_TYPE_ARGS = ['lora-mixed-training', 'lazy-mpu-init', 'onnx-safe']
def get_sys_args_from_yaml():
    def flatten_config(d):
        """
        Recursively expand nested dictionaries, retaining only the key-value pairs at the lowest level.
        Underscores `_` in key names will be converted to hyphens `-`.
        """
        items = []
        def _flatten(obj):
            if isinstance(obj, dict):
                for k, v in obj.items():
                    if isinstance(v, dict):
                        _flatten(v)
                    else:
                        key_flat = k.replace('_', '-')
                        items.append((key_flat, v))
            else:
                pass
        _flatten(d)
        return dict(items)
    first_arg = sys.argv[1]
    if not first_arg.endswith('.yaml'):
        return
    config_path = first_arg
    try:
        with open(config_path, 'r') as f:
            config = yaml.safe_load(f)
    except FileNotFoundError as e:
        print(f"Warning: Config file not found: {config_path} - {e}")
    except PermissionError as e:
        print(f"Error: Permission denied when reading: {config_path} - {e}")
    except yaml.YAMLError as e:
        print(f"Error: Invalid YAML format in {config_path} - {e}")
    except Exception as e:
        print(f"Error: Unexpected error loading {config_path} - {e}")
    original_argv = deepcopy(sys.argv)
    new_argv = [original_argv[0]]  # script name
    flat_args = flatten_config(config['gpt_args'])
    if 'gpt_args' not in config:
        raise KeyError("The required keyword 'gpt_args' is missing from the configuration file.")
    if 'lora_args' in config:
        flat_args.update(flatten_config(config['lora_args']))
    for key, value in flat_args.items():
        if isinstance(value, bool) and value:
            new_argv.append(f'--{key}')
        elif isinstance(value, list):
            for v in value:
                new_argv.append(f'--{key}')
                new_argv.append(str(v))
        else:
            new_argv.append(f'--{key}')
