from datetime import datetime, timedelta
from typing import List, Optional


class Transaction:
    def __init__(self, transaction_type: str, amount: float, description: Optional[str] = None):
        self.transaction_type = transaction_type
        self.amount = amount
        self.description = description
        self.timestamp = datetime.now()

    def __repr__(self):
        return (f"Transaction(type={self.transaction_type}, amount={self.amount}, "
                f"description={self.description}, timestamp={self.timestamp})")


class AdvancedBankAccount:
    def __init__(self, name: str, email: str, initial_balance: float = 0.0):
        self.name = name
        self.email = email
        self.balance = initial_balance
        self.transaction_history: List[Transaction] = []

    def deposit(self, amount: float, description: Optional[str] = None) -> None:
        if amount <= 0:
            raise ValueError("Deposit amount must be positive.")
        self.balance += amount
        self.transaction_history.append(Transaction("deposit", amount, description))

    def withdraw(self, amount: float, description: Optional[str] = None) -> None:
        if amount <= 0:
            raise ValueError("Withdrawal amount must be positive.")
        if amount > self.balance:
            raise ValueError("Insufficient funds.")
        self.balance -= amount
        self.transaction_history.append(Transaction("withdrawal", amount, description))

    def transfer(self, to_account: 'AdvancedBankAccount', amount: float, description: Optional[str] = None) -> None:
        if amount <= 0:
            raise ValueError("Transfer amount must be positive.")
        if amount > self.balance:
            raise ValueError("Insufficient funds.")

        self.balance -= amount
        self.transaction_history.append(Transaction("transfer", amount, description))

        to_account.deposit(amount, description=f"Transfer from {self.name}")

    def get_transaction_history(self, start_date: Optional[datetime] = None, end_date: Optional[datetime] = None) -> List[Transaction]:
        if start_date is None:
            start_date = datetime.min
        if end_date is None:
            end_date = datetime.max

        return [transaction for transaction in self.transaction_history 
                if start_date <= transaction.timestamp <= end_date]

    def get_balance_on_date(self, date: datetime) -> float:
        balance = 0.0
        for transaction in self.transaction_history:
            if transaction.timestamp <= date:
                if transaction.transaction_type == "deposit":
                    balance += transaction.amount
                elif transaction.transaction_type == "withdrawal" or transaction.transaction_type == "transfer":
                    balance -= transaction.amount
        return balance


