# Type checker implementation for SimpleLanguage
from antlr4 import *
from SimpleLanguageLexer import SimpleLanguageLexer
from SimpleLanguageParser import SimpleLanguageParser
from SimpleLanguageVisitor import SimpleLanguageVisitor


class SymbolTable:
    def __init__(self):
        self.table = {}

    def add_variable(self, name, type):
        self.table[name] = type

    def get_type(self, name):
        return self.table.get(name)


class TypeChecker(SimpleLanguageVisitor):
    def __init__(self):
        self.symbol_table = SymbolTable()

    def visitVarDecl(self, ctx):
        name = ctx.ID().getText()
        type = ctx.type().getText()
        self.symbol_table.add_variable(name, type)
        return self.visitChildren(ctx)

    def visitAssignment(self, ctx):
        name = ctx.ID().getText()

        # Check if variable is defined
        if name not in self.symbol_table.table:
            raise ValueError(f"Undefined variable: {name}")

        # Get types and compare
        expr_type = self.visit(ctx.expr())
        var_type = self.symbol_table.get_type(name)

        if expr_type != var_type:
            raise ValueError(f"Type mismatch: {expr_type} != {var_type}")

        return var_type

    def visitExpr(self, ctx):
        if ctx.INT():
            return 'int'
        name = ctx.ID().getText()
        return self.symbol_table.get_type(name)


def main():
    input = FileStream('input.txt')
    lexer = SimpleLanguageLexer(input)
    stream = CommonTokenStream(lexer)
    parser = SimpleLanguageParser(stream)
    tree = parser.prog()

    checker = TypeChecker()
    checker.visit(tree)


if __name__ == '__main__':
    main()

