import math
from typing import List, Tuple

def validate_spherical_coordinates(r: float, theta: float, phi: float) -> bool:
    # Check if radius is non-negative
    if r < 0:
        return False

    # Check if azimuthal angle is in valid range [0, 2π]
    if not (0 <= theta <= 2 * math.pi):
        return False

    # Check if polar angle is in valid range [0, π]
    if not (0 <= phi <= math.pi):
        return False

    return True

def spherical_to_cylindrical(r: float, theta: float, phi: float) -> Tuple[float, float, float]:
    # Validate input coordinates first
    if not validate_spherical_coordinates(r, theta, phi):
        raise ValueError("Invalid spherical coordinates")

    # Calculate cylindrical coordinates
    rho = r * math.sin(phi)
    z = r * math.cos(phi)

    return (rho, theta, z)

def batch_convert_spherical_to_cylindrical(spherical_coords: List[Tuple[float, float, float]]) -> List[Tuple[float, float, float]]:
    cylindrical_coords = []

    for r, theta, phi in spherical_coords:
        try:
            cylindrical_coords.append(spherical_to_cylindrical(r, theta, phi))
        except ValueError as e:
            print(f"Warning: {e} for coordinates ({r}, {theta}, {phi})")
            continue

    return cylindrical_coords

# Example usage
if __name__ == "__main__":
    # Example spherical coordinates
    spherical_coords = [
        (5.0, math.pi / 4, math.pi / 6),
        (3.0, 0.0, math.pi / 2),
        (-1.0, 0.0, 0.0),  # Invalid: negative radius
        (2.0, 3 * math.pi, math.pi / 4),  # Invalid: azimuthal angle out of range
        (4.0, math.pi / 2, 2 * math.pi),  # Invalid: polar angle out of range
    ]

    cylindrical_coords = batch_convert_spherical_to_cylindrical(spherical_coords)

    for spherical, cylindrical in zip(spherical_coords, cylindrical_coords):
        print(f"Spherical: {spherical} -> Cylindrical: {cylindrical}")

