# Binary Search Tree implementation with various operations

from typing import List, Optional


class TreeNode:
    def __init__(self, value: int):
        self.value = value
        self.left = None
        self.right = None


class BinarySearchTree:
    def __init__(self):
        self.root = None

    def add_node(self, value: int) -> None:
        if self.root is None:
            self.root = TreeNode(value)
        else:
            self._add_node(self.root, value)

    def _add_node(self, node: TreeNode, value: int) -> None:
        if value < node.value:
            if node.left is None:
                node.left = TreeNode(value)
            else:
                self._add_node(node.left, value)
        elif value > node.value:
            if node.right is None:
                node.right = TreeNode(value)
            else:
                self._add_node(node.right, value)

    def remove_node(self, value: int) -> bool:
        self.root, removed = self._remove_node(self.root, value)
        return removed

    def _remove_node(
        self, node: Optional[TreeNode], value: int
    ) -> (Optional[TreeNode], bool):
        if node is None:
            return None, False

        if value < node.value:
            node.left, removed = self._remove_node(node.left, value)
        elif value > node.value:
            node.right, removed = self._remove_node(node.right, value)
        else:
            # Node to be deleted found
            if node.left is None and node.right is None:
                return None, True
            elif node.left is None:
                return node.right, True
            elif node.right is None:
                return node.left, True
            else:
                # Two children: get inorder successor (smallest in right subtree)
                min_larger_node = self._get_min_value_node(node.right)
                node.value = min_larger_node.value
                node.right, _ = self._remove_node(
                    node.right, min_larger_node.value
                )
                removed = True

        return node, removed

    def search(self, value: int) -> bool:
        return self._search(self.root, value)

    def _search(self, node: Optional[TreeNode], value: int) -> bool:
        if node is None:
            return False
        if value == node.value:
            return True
        elif value < node.value:
            return self._search(node.left, value)
        else:
            return self._search(node.right, value)

    def get_in_order_traversal(self) -> List[int]:
        return self._in_order_traversal(self.root, [])

    def _in_order_traversal(
        self, node: Optional[TreeNode], result: List[int]
    ) -> List[int]:
        if node:
            self._in_order_traversal(node.left, result)
            result.append(node.value)
            self._in_order_traversal(node.right, result)
        return result

    def get_pre_order_traversal(self) -> List[int]:
        return self._pre_order_traversal(self.root, [])

    def _pre_order_traversal(
        self, node: Optional[TreeNode], result: List[int]
    ) -> List[int]:
        if node:
            result.append(node.value)
            self._pre_order_traversal(node.left, result)
            self._pre_order_traversal(node.right, result)
        return result

    def get_post_order_traversal(self) -> List[int]:
        return self._post_order_traversal(self.root, [])

    def _post_order_traversal(
        self, node: Optional[TreeNode], result: List[int]
    ) -> List[int]:
        if node:
            self._post_order_traversal(node.left, result)
            self._post_order_traversal(node.right, result)
            result.append(node.value)
        return result

    def get_level_order_traversal(self) -> List[int]:
        if not self.root:
            return []
        result = []
        queue = [self.root]
        while queue:
            node = queue.pop(0)
            result.append(node.value)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        return result

    def get_min_value(self) -> int:
        if self.root is None:
            raise ValueError("The tree is empty")
        return self._get_min_value_node(self.root).value

    def _get_min_value_node(self, node: TreeNode) -> TreeNode:
        while node.left:
            node = node.left
        return node

    def get_max_value(self) -> int:
        if self.root is None:
            raise ValueError("The tree is empty")
        return self._get_max_value_node(self.root).value

    def _get_max_value_node(self, node: TreeNode) -> TreeNode:
        while node.right:
            node = node.right
        return node

    def get_height(self) -> int:
        return self._get_height(self.root)

    def _get_height(self, node: Optional[TreeNode]) -> int:
        if node is None:
            return 0
        left_height = self._get_height(node.left)
        right_height = self._get_height(node.right)
        return max(left_height, right_height) + 1


