# Function to remove non-even elements from a nested structure
def remove_non_even_elements(t):

    # Helper function to check if a string represents an even numeric value
    def is_even_numeric(s):
        """Check if a string represents an even numeric value."""
        try:
            num = float(s)
            return num.is_integer() and num % 2 == 0
        except ValueError:
            return False

    # Process element: convert lists and dicts to tuples
    def process_element(e):
        """Process an individual element, converting lists and dictionaries to tuples."""
        if isinstance(e, list) or isinstance(e, dict):
            return tuple(e)
        return e

    # Filter element: determine if it should be kept based on being even
    def filter_element(e):
        """Filter out non-even elements based on their type and value."""
        if isinstance(e, int) and e % 2 == 0:
            return True
        elif isinstance(e, float) and e.is_integer() and e % 2 == 0:
            return True
        elif isinstance(e, str) and is_even_numeric(e):
            return True
        elif isinstance(e, tuple):
            return True
        return False

    # Recursive filtering function for nested tuples
    def recursive_filter(t):
        """Recursively filter out non-even elements from the tuple."""
        result = ()
        for element in t:
            processed_element = process_element(element)
            if isinstance(processed_element, tuple):
                result += (recursive_filter(processed_element),)
            elif filter_element(processed_element):
                result += (processed_element,)
        return result

    # Start recursive filtering
    return recursive_filter(t)


