# Abstract base class for expression tree nodes
from abc import ABC, abstractmethod
from typing import List

class Node(ABC):
    @abstractmethod
    def evaluate(self) -> int:
        pass

    @abstractmethod
    def print(self) -> str:
        pass

# Leaf node representing an operand (number)
class OperandNode(Node):
    def __init__(self, value: int):
        self.value = value

    def evaluate(self) -> int:
        return self.value

    def print(self) -> str:
        return str(self.value)

# Internal node representing an operator with left and right children
class OperatorNode(Node):
    def __init__(self, operator: str, left: Node, right: Node):
        self.operator = operator
        self.left = left
        self.right = right

    def evaluate(self) -> int:
        if self.operator == '+':
            return self.left.evaluate() + self.right.evaluate()
        elif self.operator == '-':
            return self.left.evaluate() - self.right.evaluate()
        elif self.operator == '*':
            return self.left.evaluate() * self.right.evaluate()
        elif self.operator == '/':
            return self.left.evaluate() // self.right.evaluate()

    def print(self) -> str:
        left_str = self.left.print()
        right_str = self.right.print()
        return f"({left_str} {self.operator} {right_str})"

# Build expression tree from postfix notation
def build_expression_tree(postfix: List[str]) -> Node:
    stack = []
    for token in postfix:
        if token.isdigit():
            stack.append(OperandNode(int(token)))
        else:
            right = stack.pop()
            left = stack.pop()
            stack.append(OperatorNode(token, left, right))
    return stack[0]

# Evaluate the expression tree and generate string representation
def solve(postfix: List[str]) -> (int, str):
    tree = build_expression_tree(postfix)
    result = tree.evaluate()
    expression = tree.print()
    return result, expression

