# Import necessary modules
import ast
import graphviz


class AlgorithmVisualizer:
    def __init__(self, code):
        self.code = code
        self.ast_tree = None
        # Initialize the graph with a comment
        self.dot = graphviz.Digraph(comment='Algorithm Execution Flow')

    def parse_code(self):
        try:
            # Parse the code into an AST tree
            self.ast_tree = ast.parse(self.code)
        except SyntaxError as e:
            print(f"Syntax Error: {e}")
            return False
        return True

    def visualize(self):
        if not self.ast_tree:
            print("No AST tree to visualize.")
            return

        # Start traversal from the top-level body
        self._traverse_ast(self.ast_tree.body, "Start")

        # Render and view the graph
        self.dot.render('algorithm_flow', view=True)

    def _traverse_ast(self, nodes, parent_name):
        for node in nodes:
            # Create a unique node name based on the node type and position
            node_name = str(node)
            self.dot.node(node_name, node_name)
            self.dot.edge(parent_name, node_name)

            # Recursively traverse nested structures
            if isinstance(node, ast.FunctionDef):
                self._traverse_ast(node.body, node_name)
            elif isinstance(node, ast.For) or isinstance(node, ast.While):
                self._traverse_ast(node.body, node_name)
            elif isinstance(node, ast.If):
                self._traverse_ast(node.body, node_name)
                # Handle else branch separately if present
                if node.orelse:
                    self._traverse_ast(node.orelse, node_name + "_else")


