# Initialize Flask app
app = Flask(__name__)
app.config['UPLOAD_FOLDER'] = 'uploads/'
app.config['OUTPUT_FOLDER'] = 'outputs/'
app.config['ALLOWED_EXTENSIONS'] = {'mp4', 'avi', 'mov'}

def allowed_file(filename):
    # Check if file has an extension and if it's in the allowed list
    return '.' in filename and filename.rsplit('.', 1)[1] in app.config['ALLOWED_EXTENSIONS']

def convert_frame_to_ascii(frame, charset, scale):
    # Convert frame to grayscale
    frame_gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)

    # Resize frame for ASCII conversion
    frame_resized = cv2.resize(
        frame_gray, 
        (int(frame_gray.shape[1] // scale), int(frame_gray.shape[0] // scale)), 
        interpolation=cv2.INTER_LINEAR
    )

    # Build ASCII representation
    ascii_frame = ''
    for row in frame_resized:
        for pixel in row:
            ascii_frame += charset[int(pixel // (256 / len(charset)))]
        ascii_frame += '\n'

    return ascii_frame

@app.route('/', methods=['GET', 'POST'])
def index():
    if request.method == 'POST':
        file = request.files.get('file')
        charset = request.form.get('charset') or '@%#*+=-:. '
        scale = float(request.form.get('scale') or 2.5)

        if file and allowed_file(file.filename):
            input_path = os.path.join(app.config['UPLOAD_FOLDER'], file.filename)
            output_path = os.path.join(
                app.config['OUTPUT_FOLDER'], 
                f"{file.filename.rsplit('.', 1)[0]}_ascii.txt"
            )

            file.save(input_path)

            video = VideoFileClip(input_path)
            fps = video.fps

            cap = cv2.VideoCapture(input_path)

            with open(output_path, 'w') as output_file:
                frame_number = 1
                while cap.isOpened():
                    ret, frame = cap.read()
                    if ret:
                        # Process every half-second frame
                        if frame_number % (round(fps) // 2) == 0:
                            ascii_frame = convert_frame_to_ascii(frame, charset, scale)
                            output_file.write(ascii_frame)
                            output_file.write('\n')
                        frame_number += 1
                    else:
                        break

            cap.release()
            return redirect(url_for('output', filename=f"{file.filename.rsplit('.', 1)[0]}_ascii.txt"))

    return render_template('index.html')

@app.route('/outputs/<filename>')
