# Import necessary modules
import os
import hashlib

def calculate_md5(file_path):
    """
    Calculate the MD5 hash of a file.
    Reads the file in chunks to handle large files efficiently.
    """
    hash_md5 = hashlib.md5()

    with open(file_path, "rb") as f:
        # Read file in 4KB chunks
        for chunk in iter(lambda: f.read(4096), b""):
            hash_md5.update(chunk)

    return hash_md5.hexdigest()

def list_files_with_md5():
    """
    List all files in the current directory 
    along with their MD5 hash values.
    """
    file_hashes = {}

    # Iterate through all items in current directory
    for file_name in os.listdir():
        # Check if it's a regular file (not a directory)
        if os.path.isfile(file_name):
            # Get full file path
            file_path = os.path.join(os.getcwd(), file_name)

            # Calculate and store MD5 hash
            file_hashes[file_name] = calculate_md5(file_path)

            # Print filename and its hash
            print(f"{file_name}: {file_hashes[file_name]}")

    return file_hashes

def check_for_duplicates(file_hashes):
    """
    Check for duplicate files based on their MD5 hash values.
    Groups files by their hash and identifies duplicates.
    """
    hash_to_files = {}

    # Group files by their hash
    for file_name, file_hash in file_hashes.items():
        if file_hash in hash_to_files:
            hash_to_files[file_hash].append(file_name)
        else:
            hash_to_files[file_hash] = [file_name]

    # Filter only groups with more than one file (duplicates)
    duplicates = {
        hash_value: file_names 
        for hash_value, file_names in hash_to_files.items() 
        if len(file_names) > 1
    }

    # Output results
    if duplicates:
        print("Duplicate files found:")
        for hash_value, file_names in duplicates.items():
            print(f"MD5 Hash: {hash_value}")
            for file_name in file_names:
                print(f"  - {file_name}")
    else:
        print("No duplicate files found.")

# Main execution block
if __name__ == "__main__":
    # Get file hashes from current directory
    file_hashes = list_files_with_md5()

    # Check for duplicates among the files
    check_for_duplicates(file_hashes)

