def compare_dicts(dict1, dict2):
    # Find keys in dict1 that are not in dict2 or have different values
    diff1 = {k: dict1[k] for k in dict1 if k not in dict2 or dict1[k] != dict2[k]}

    # Find keys in dict2 that are not in dict1 or have different values
    diff2 = {k: dict2[k] for k in dict2 if k not in dict1 or dict2[k] != dict1[k]}

    return diff1, diff2

