# Simple Sentiment Analyzer class
class SimpleSentimentAnalyzer:
    def __init__(self):
        # Define positive and negative keywords
        self.positive_keywords = {"good", "great", "excellent", "amazing", "wonderful", "fantastic", "love", "happy", "best", "enjoy"}
        self.negative_keywords = {"bad", "terrible", "awful", "horrible", "poor", "disappointing", "hate", "sad", "worst", "annoying"}

    def classify_sentiment(self, sentence):
        # Convert sentence to lowercase and split into words
        words = sentence.lower().split()

        # Count positive and negative keywords
        positive_count = sum(1 for word in words if word in self.positive_keywords)
        negative_count = sum(1 for word in words if word in self.negative_keywords)

        # Determine sentiment based on counts
        if positive_count > negative_count:
            return "Positive"
        elif negative_count > positive_count:
            return "Negative"
        else:
            return "Neutral"

