def check_dict_case(dct):
    # Check if dictionary is empty
    if not dct:
        return False

    # Count lowercase and uppercase keys
    lower_case = sum([k.islower() for k in dct.keys()])
    upper_case = sum([k.isupper() for k in dct.keys()])

    # Check if all keys are lowercase
    if lower_case == len(dct):
        return all(v.islower() for v in dct.values())
    # Check if all keys are uppercase
    elif upper_case == len(dct):
        return all(v.isupper() for v in dct.values())
    else:
        return False

# Computes the Longest Common Subsequence using memoization
def lcs(X, Y, m, n, dp):
    # Base case: if either string is empty
    if m == 0 or n == 0:
        return 0

    # Return cached result if already computed
    if dp[m][n] != -1:
        return dp[m][n]

    # Characters match
    if X[m-1] == Y[n-1]:
        dp[m][n] = 1 + lcs(X, Y, m-1, n-1, dp)
    else:
        # Take maximum of two possibilities
        dp[m][n] = max(
            lcs(X, Y, m, n-1, dp),
            lcs(X, Y, m-1, n, dp)
        )

    return dp[m][n]

# Finds the LCS among multiple strings iteratively
def find_lcs(strings):
    if not strings:
        return ""

    n = len(strings)
    lcs_str = strings[0]

    for i in range(1, n):
        m = len(lcs_str)
        n_len = len(strings[i])
        dp = [[-1] * (n_len+1) for _ in range(m+1)]

        lcs_length = lcs(lcs_str, strings[i], m, n_len, dp)
        lcs_str = build_lcs(lcs_str, strings[i], dp)

    return lcs_str

# Builds the actual LCS string from DP table
def build_lcs(X, Y, dp):
    m = len(X)
    n = len(Y)
    lcs_str = []

    i, j = m, n
    while i > 0 and j > 0:
        if X[i-1] == Y[j-1]:
            lcs_str.append(X[i-1])
            i -= 1
            j -= 1
        elif dp[i-1][j] > dp[i][j-1]:
            i -= 1
        else:
            j -= 1

    return ''.join(reversed(lcs_str))

# Finds the shortest unique subsequence across all strings
def find_sus(strings):
    if not strings:
        return ""

    sus = None

    for string in strings:
        for i in range(len(string)):
            for j in range(i + 1, len(string) + 1):
                subseq = string[i:j]

                # Check if this subsequence is unique to current string
                if all(subseq not in s for s in strings if s != string):
                    if sus is None or len(subseq) < len(sus):
                        sus = subseq

    return sus

# Processes inputs to get SUS and LCS length
def process_inputs(input1, input2):
    all_strings = input1 + input2

    lcs_result = find_lcs(all_strings)
    sus_result = find_sus(all_strings)

    return sus_result, len(lcs_result)

# Example usage
input1 = ["ALGORITHMS", "LOGARITHM", "GRIMTHALO"]
input2 = ["LOGARITHM", "GRIMTHALO", "ALGORITHMS"]

sus, lcs_length = process_inputs(input1, input2)

print(f"Shortest Unique Subsequence: {sus}")
print(f"Length of Longest Common Subsequence: {lcs_length}")

# Rubik's Cube implementation
class RubiksCube:
    def __init__(self):
        # Each face is represented as a 3x3 list of lists
        self.faces = {
            'U': [['W', 'W', 'W'], ['W', 'W', 'W'], ['W', 'W', 'W']],  # White (Up)
            'D': [['Y', 'Y', 'Y'], ['Y', 'Y', 'Y'], ['Y', 'Y', 'Y']],  # Yellow (Down)
            'L': [['G', 'G', 'G'], ['G', 'G', 'G'], ['G', 'G', 'G']],  # Green (Left)
            'R': [['B', 'B', 'B'], ['B', 'B', 'B'], ['B', 'B', 'B']],  # Blue (Right)
            'F': [['R', 'R', 'R'], ['R', 'R', 'R'], ['R', 'R', 'R']],  # Red (Front)
            'B': [['O', 'O', 'O'], ['O', 'O', 'O'], ['O', 'O', 'O']]   # Orange (Back)
        }

    def rotate_face(self, face, clockwise=True):
        if clockwise:
            self.faces[face] = [list(x) for x in zip(*self.faces[face][::-1])]
        else:
            self.faces[face] = [list(x) for x in zip(*self.faces[face])][::-1]

    def rotate_cube(self, move):
        if move == 'U':
            self.rotate_face('U')
            self.faces['L'][0], self.faces['F'][0], self.faces['R'][0], self.faces['B'][0] = \
                self.faces['F'][0], self.faces['R'][0], self.faces['B'][0], self.faces['L'][0]
        elif move == 'D':
            self.rotate_face('D')
            self.faces['L'][2], self.faces['F'][2], self.faces['R'][2], self.faces['B'][2] = \
                self.faces['B'][2], self.faces['L'][2], self.faces['F'][2], self.faces['R'][2]
        elif move == 'L':
            self.rotate_face('L')
            for i in range(3):
                self.faces['U'][i][0], self.faces['F'][i][0], self.faces['D'][i][0], self.faces['B'][2-i][2] = \
                    self.faces['F'][i][0], self.faces['D'][i][0], self.faces['B'][2-i][2], self.faces['U'][i][0]
        elif move == 'R':
            self.rotate_face('R')
            for i in range(3):
                self.faces['U'][i][2], self.faces['F'][i][2], self.faces['D'][i][2], self.faces['B'][2-i][0] = \
                    self.faces['B'][2-i][0], self.faces['U'][i][2], self.faces['F'][i][2], self.faces['D'][i][2]
        elif move == 'F':
            self.rotate_face('F')
            for i in range(3):
                self.faces['U'][2][i], self.faces['R'][0][2-i], self.faces['D'][0][2-i], self.faces['L'][2][i] = \
                    self.faces['L'][2][i], self.faces['U'][2][i], self.faces['R'][0][2-i], self.faces['D'][0][2-i]
        elif move == 'B':
            self.rotate_face('B')
            for i in range(3):
                self.faces['U'][0][i], self.faces['L'][0][2-i], self.faces['D'][2][2-i], self.faces['R'][2][i] = \
                    self.faces['R'][2][i], self.faces['U'][0][i], self.faces['L'][0][2-i], self.faces['D'][2][2-i]

    def display(self):
        for face in self.faces:
            print(f"Face {face}:")
            for row in self.faces[face]:
                print(' '.join(row))
            print()

