@app.route('/weather/historic', methods=['GET'])
def historic_weather():
    city = request.args.get('city')

    if not city:
        return jsonify({"error": "City parameter is required"}), 400

    # Note: This endpoint requires prior knowledge of coordinates
    # For simplicity, we'll use placeholder values; in practice, fetch from /weather/current first
    url = f"{BASE_URL}onecall/timemachine?lat=0.0&lon=0.0&appid={API_KEY}&units=metric&dt={int(time.time()) - 7 * 24 * 60 * 60}"
    response = requests.get(url)

    if response.status_code != 200:
        return jsonify({"error": "Error fetching historic weather data"}), response.status_code

    data = response.json()
    return jsonify(data)

@app.route('/weather/analysis', methods=['GET'])
def weather_analysis():
    city = request.args.get('city')

    if not city:
        return jsonify({"error": "City parameter is required"}), 400

    # Fetch current weather
    current_url = f"{BASE_URL}weather?q={city}&appid={API_KEY}&units=metric"
    current_response = requests.get(current_url)

    if current_response.status_code != 200:
        return jsonify({"error": "Error fetching current weather data"}), current_response.status_code

    current_data = current_response.json()

    # Fetch historic weather
    lat, lon = current_data['coord']['lat'], current_data['coord']['lon']
    historic_url = f"{BASE_URL}onecall/timemachine?lat={lat}&lon={lon}&appid={API_KEY}&units=metric&dt={int(time.time()) - 7 * 24 * 60 * 60}"
    historic_response = requests.get(historic_url)

    if historic_response.status_code != 200:
        return jsonify({"error": "Error fetching historic weather data"}), historic_response.status_code

    historic_data = historic_response.json()

    # Parse and analyze data
    temperatures = [hour['temp'] for hour in historic_data['hourly']]
    average_temp = sum(temperatures) / len(temperatures)

    overall_conditions = [hour['weather'][0]['main'] for hour in historic_data['hourly']]
    conditions_count = {}

    for condition in overall_conditions:
        if condition in conditions_count:
            conditions_count[condition] += 1
        else:
            conditions_count[condition] = 1

    # Identify trends
    temp_trend = "stable"
    if temperatures[0] < temperatures[-1]:
        temp_trend = "increasing"
    elif temperatures[0] > temperatures[-1]:
        temp_trend = "decreasing"

    analysis = {
        "city": city,
        "average_temperature": average_temp,
        "overall_conditions": conditions_count,
        "temperature_trend": temp_trend
    }

    return jsonify(analysis)

