# Drone Control System Implementation
import threading
import time
from abc import ABC, abstractmethod
from typing import List, Dict


class DroneControlSystem:
    def __init__(self):
        self._modules: List['Module'] = []
        self._running = False
        self._lock = threading.Lock()

    def add_module(self, module: 'Module'):
        with self._lock:
            if module not in self._modules:
                self._modules.append(module)
                module.register_to_system(self)

    def remove_module(self, module: 'Module'):
        with self._lock:
            if module in self._modules:
                module.unregister_from_system()
                self._modules.remove(module)

    def start(self):
        with self._lock:
            if not self._running:
                self._running = True
                for module in self._modules:
                    module.start()

    def stop(self):
        with self._lock:
            if self._running:
                self._running = False
                for module in self._modules:
                    module.stop()

    def handle_error(self, error: Exception):
        print(f"Error occurred: {error}")
        # Additional error handling logic can be added here


class Module(ABC):
    def __init__(self):
        self._system: DroneControlSystem = None
        self._running = False
        self._thread = None

    def register_to_system(self, system: DroneControlSystem):
        self._system = system

    def unregister_from_system(self):
        self._system = None

    def start(self):
        if not self._running:
            self._running = True
            self._thread = threading.Thread(target=self.run)
            self._thread.start()

    def stop(self):
        if self._running:
            self._running = False
            self._thread.join()

    @abstractmethod
    def run(self):
        pass


class FlightControlModule(Module):
    def __init__(self):
        super().__init__()
        self._flight_data = {}

    def run(self):
        while self._running:
            try:
                self._update_flight_data()
                self._execute_flight_commands()
                time.sleep(1)  # Simulate a 1-second loop
            except Exception as e:
                self._system.handle_error(e)

    def _update_flight_data(self):
        # Simulate fetching flight data from sensors
        self._flight_data['altitude'] = 100  # Example altitude
        self._flight_data['speed'] = 50      # Example speed

    def _execute_flight_commands(self):
        # Simulate executing flight commands
        print("Executing flight commands based on current data:", self._flight_data)


class NavigationModule(Module):
    def __init__(self):
        super().__init__()
        self._waypoints: List[Dict[str, float]] = []

    def add_waypoint(self, latitude: float, longitude: float):
        self._waypoints.append({'latitude': latitude, 'longitude': longitude})

    def run(self):
        while self._running:
            try:
                self._navigate_to_next_waypoint()
                time.sleep(1)  # Simulate a 1-second loop
            except Exception as e:
                self._system.handle_error(e)

    def _navigate_to_next_waypoint(self):
        if self._waypoints:
            waypoint = self._waypoints.pop(0)
            print(f"Navigating to waypoint: {waypoint}")
        else:
            print("No more waypoints to navigate to.")


class CommunicationModule(Module):
    def __init__(self):
        super().__init__()
        self._messages: List[str] = []

    def send_message(self, message: str):
        self._messages.append(message)

    def run(self):
        while self._running:
            try:
                self._send_pending_messages()
                time.sleep(1)  # Simulate a 1-second loop
            except Exception as e:
                self._system.handle_error(e)

    def _send_pending_messages(self):
