# Function to check if a number is prime
def is_prime(n):
    # Numbers <= 1 are not prime
    if n <= 1:
        return False

    # Check divisors from 2 to sqrt(n)
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False

    return True

# Function to find all divisors of a number
def find_divisors(n):
    divisors = []

    # Check up to sqrt(n) for efficiency
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.append(i)
            # Add the corresponding divisor if it's different
            if i != n // i:
                divisors.append(n // i)

    return sorted(divisors)

# Euclidean algorithm for GCD
def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

# LCM using GCD relationship
def lcm(a, b):
    return abs(a * b) // gcd(a, b)

# Main processing function
def process_input(input_value):
    # Handle numeric types (int, float)
    if isinstance(input_value, (int, float)):
        # Convert float to nearest integer
        input_value = int(round(input_value))

        # Calculate various properties
        divisors = find_divisors(input_value)
        divisors_count_even = len(divisors) % 2 == 0
        divisors_sum = sum(divisors)
        max_prime = max(filter(is_prime, divisors), default=None)
        lcm_value = lcm(*divisors) if len(divisors) > 1 else None
        gcd_value = gcd(*divisors) if len(divisors) > 1 else None

        return (divisors_count_even, divisors, divisors_sum, max_prime, 
                (lcm_value, gcd_value), None, None, None, None)

    # Handle complex numbers
    elif isinstance(input_value, complex):
        real_part = input_value.real
        imag_part = input_value.imag

        # Sum of rounded real and imaginary parts
        input_value = int(round(real_part)) + int(round(imag_part))

        divisors = find_divisors(input_value)
        divisors_count_even = len(divisors) % 2 == 0
        divisors_sum = sum(divisors)
        max_prime = max(filter(is_prime, divisors), default=None)
        lcm_value = lcm(*divisors) if len(divisors) > 1 else None
        gcd_value = gcd(*divisors) if len(divisors) > 1 else None

        return (divisors_count_even, divisors, divisors_sum, max_prime,
                (lcm_value, gcd_value), real_part, imag_part, None, None)

    # Handle string inputs
    elif isinstance(input_value, str):
        try:
            # Try converting to int first
            input_value = int(input_value)
            return process_input(input_value)
        except ValueError:
            try:
                # Then try float
                input_value = float(input_value)
                return process_input(input_value)
            except ValueError:
                return "Input is not a valid number"

    # Handle collections (list, tuple, set)
    elif isinstance(input_value, (list, tuple, set)):
        results = {}
        for item in input_value:
            results[item] = process_input(item)
        return results

    # Unsupported types
    else:
        return "Unsupported input type"

