# Fitness and health calculator program

def calculate_bmi(weight, height):
    """Calculate Body Mass Index (BMI)."""
    bmi = weight / (height ** 2)
    return round(bmi, 2)

def calculate_whr(waist, hip):
    """Calculate Waist-to-Hip Ratio (WHR)."""
    whr = waist / hip
    return round(whr, 2)

def calculate_bmr(weight, body_fat_percentage):
    """Calculate Basal Metabolic Rate (BMR) using the Katch-McArdle formula."""
    lbm = weight * (1 - (body_fat_percentage / 100))
    bmr = 370 + (21.6 * lbm)
    return round(bmr, 2)

def calculate_mhr(age, sex):
    """Calculate Maximum Heart Rate (MHR) using the Tanaka equation."""
    if sex.lower() == 'male':
        mhr = 208 - (0.7 * age)
    elif sex.lower() == 'female':
        mhr = 206 - (0.88 * age)
    else:
        raise ValueError("Sex must be 'male' or 'female'.")
    return round(mhr)

def main():
    # User input
    weight = float(input("Enter your weight in kg: "))
    height = float(input("Enter your height in meters: "))
    waist = float(input("Enter your waist circumference in cm: "))
    hip = float(input("Enter your hip circumference in cm: "))
    body_fat_percentage = float(input("Enter your body fat percentage: "))
    age = int(input("Enter your age: "))
    sex = input("Enter your sex (male/female): ")

    # Calculations
    bmi = calculate_bmi(weight, height)
    whr = calculate_whr(waist, hip)
    bmr = calculate_bmr(weight, body_fat_percentage)
    mhr = calculate_mhr(age, sex)

    # Output results
    print(f"Your Body Mass Index (BMI) is: {bmi}")
    print(f"Your Waist-to-Hip Ratio (WHR) is: {whr}")
    print(f"Your Basal Metabolic Rate (BMR) is: {bmr} calories/day")
    print(f"Your Maximum Heart Rate (MHR) is: {mhr} bpm")

    # Warnings and suggestions
    if sex.lower() == 'male':
        if whr > 0.9:
            print("Warning: Your Waist-to-Hip Ratio (WHR) is above the recommended limit for men.")
            print("Suggested lifestyle changes: Consider reducing abdominal fat through diet and exercise.")
    elif sex.lower() == 'female':
        if whr > 0.85:
            print("Warning: Your Waist-to-Hip Ratio (WHR) is above the recommended limit for women.")
            print("Suggested lifestyle changes: Consider reducing abdominal fat through diet and exercise.")

    if body_fat_percentage > 25 and sex.lower() == 'male':
        print("Warning: Your body fat percentage is above the healthy range for men.")
        print("Suggested lifestyle changes: Consider a balanced diet and regular exercise to reduce body fat.")
    elif body_fat_percentage > 32 and sex.lower() == 'female':
        print("Warning: Your body fat percentage is above the healthy range for women.")
        print("Suggested lifestyle changes: Consider a balanced diet and regular exercise to reduce body fat.")

