# Student Management System with indexing for efficient queries

class Student:
    def __init__(self, student_id, full_name, age, grades, activities):
        self.student_id = student_id
        self.full_name = full_name
        self.age = age
        self.grades = grades
        self.activities = activities


class StudentSystem:
    def __init__(self):
        self.students = []
        self.age_index = {}
        self.grade_range_index = {}
        self.activity_index = {}

    def add_student(self, student_id, full_name, age, grades, activities):
        student = Student(student_id, full_name, age, grades, activities)
        self.students.append(student)
        self._update_indices(student, add=True)

    def update_student(self, student_id, full_name=None, age=None, grades=None, activities=None):
        for student in self.students:
            if student.student_id == student_id:
                if full_name is not None:
                    student.full_name = full_name
                if age is not None:
                    student.age = age
                if grades is not None:
                    student.grades = grades
                if activities is not None:
                    student.activities = activities
                self._update_indices(student, add=True)
                return
        raise ValueError(f"Student with ID {student_id} not found")

    def get_students_by_age(self, age):
        return [student for student in self.students 
                if student.student_id in self.age_index.get(age, [])]

    def get_students_by_grade_range(self, min_grade, max_grade):
        grade_range = (min_grade, max_grade)
        return [student for student in self.students 
                if student.student_id in self.grade_range_index.get(grade_range, [])]

    def get_students_by_activity(self, activity):
        return [student for student in self.students 
                if student.student_id in self.activity_index.get(activity, [])]

    def _update_indices(self, student, add=False):
        if add:
            # Update age index
            self.age_index.setdefault(student.age, []).append(student.student_id)

            # Update grade range index
            for grade in student.grades:
                grade_range = (min(grade), max(grade))
                self.grade_range_index.setdefault(grade_range, []).append(student.student_id)

            # Update activity index
            for activity in student.activities:
                self.activity_index.setdefault(activity, []).append(student.student_id)
        else:
            # Remove from age index
            self.age_index[student.age].remove(student.student_id)

            # Remove from grade range index
            for grade in student.grades:
                grade_range = (min(grade), max(grade))
                self.grade_range_index[grade_range].remove(student.student_id)

            # Remove from activity index
            for activity in student.activities:
                self.activity_index[activity].remove(student.student_id)


