# Text-based adventure game with rooms, items, and puzzles

class Room:
    def __init__(self, name, description, items=None, exits=None, puzzle=None, puzzle_solution=None):
        self.name = name
        self.description = description
        self.items = items if items is not None else []
        self.exits = exits if exits is not None else {}
        self.puzzle = puzzle
        self.puzzle_solution = puzzle_solution

    def add_item(self, item):
        self.items.append(item)

    def remove_item(self, item):
        if item in self.items:
            self.items.remove(item)

    def solve_puzzle(self, solution):
        if self.puzzle and solution == self.puzzle_solution:
            print("Puzzle solved!")
            self.puzzle = None
            self.puzzle_solution = None
            return True
        else:
            print("That doesn't seem to solve the puzzle.")
            return False

    def describe(self):
        print(f"--- {self.name} ---")
        print(self.description)
        if self.items:
            print("Items in the room:", ", ".join(self.items))
        if self.puzzle:
            print("There is a puzzle to solve here.")
        print("Exits:", ", ".join(self.exits.keys()))

