# Hash Table implementation using chaining for collision resolution
class HashTable:
    def __init__(self, size=100):
        self.size = size
        # Initialize table with None values
        self.table = [None] * size

    # Internal hash function to compute index for a given key
    def _hash(self, key):
        # Uses Python's built-in hash function and modulo operation
        return hash(key) % self.size

    # Insert a key-value pair into the hash table
    def insert(self, key, value):
        index = self._hash(key)

        # Create new bucket if none exists at this index
        if self.table[index] is None:
            self.table[index] = []

        # Check if key already exists and update value if so
        for i, (k, v) in enumerate(self.table[index]):
            if k == key:
                self.table[index][i] = (key, value)
                return

        # Otherwise append new key-value pair
        self.table[index].append((key, value))

    # Retrieve value for a given key
    def get(self, key):
        index = self._hash(key)

        # Search through bucket if it exists
        if self.table[index] is not None:
            for k, v in self.table[index]:
                if k == key:
                    return v

        # Raise error if key not found
        raise KeyError(f"Key {key} not found")

    # Delete a key-value pair from the hash table
    def delete(self, key):
        index = self._hash(key)

        # Search through bucket if it exists
        if self.table[index] is not None:
            for i, (k, v) in enumerate(self.table[index]):
                if k == key:
                    del self.table[index][i]
                    return

        # Raise error if key not found
        raise KeyError(f"Key {key} not found")

    # String representation of the hash table
    def __repr__(self):
        return str(self.table)


