# Import required libraries
from flask import Flask, request, render_template
from geopy.geocoders import Nominatim
from geopy.distance import geodesic

app = Flask(__name__)

# Load store data from CSV file
def load_stores():
    stores = []
    with open('stores.csv', 'r') as file:
        for line in file:
            name, address, lat, lon = line.strip().split(',')
            stores.append((name, address, float(lat), float(lon)))
    return stores

# Geocode customer address using Nominatim API
def geocode_address(address):
    geolocator = Nominatim(user_agent="nearest_store_app")
    location = geolocator.geocode(address)
    if location:
        return (location.latitude, location.longitude)
    return None

# Find the nearest store based on geographic distance
def find_nearest_store(stores, customer_coords):
    nearest_store = None
    min_distance = float('inf')

    for store in stores:
        store_coords = (store[2], store[3])
        distance = geodesic(customer_coords, store_coords).kilometers

        if distance < min_distance:
            min_distance = distance
            nearest_store = store

    return nearest_store, min_distance

# Main route handling both GET and POST requests
@app.route('/', methods=['GET', 'POST'])
def index():
    if request.method == 'POST':
        customer_address = request.form['address']
        customer_coords = geocode_address(customer_address)

        if customer_coords:
            stores = load_stores()
            nearest_store, distance = find_nearest_store(stores, customer_coords)
            return render_template('index.html', nearest_store=nearest_store, distance=distance)
        else:
            return render_template('index.html', error="Address not found")

    return render_template('index.html')

