# Student class definition
class Student:
    def __init__(self, name, age, grade_level):
        self.name = name
        self.age = age
        self.grade_level = grade_level
        self.subjects = []  # List to store subjects
        self.grades = {}    # Dictionary to store grades for each subject

    def add_subject(self, subject):
        # Add a subject if not already enrolled
        if subject not in self.subjects:
            self.subjects.append(subject)
            self.grades[subject] = None  # Initialize grade for the subject as None

    def remove_subject(self, subject):
        # Remove a subject and its grade if enrolled
        if subject in self.subjects:
            self.subjects.remove(subject)
            del self.grades[subject]

    def get_subjects(self):
        # Return list of enrolled subjects
        return self.subjects

    def set_grade(self, subject, grade):
        # Set grade for a subject with validation
        if subject in self.subjects:
            if 0 <= grade <= 100:
                self.grades[subject] = grade
            else:
                raise ValueError("Grade must be between 0 and 100")
        else:
            raise ValueError(f"Subject {subject} is not enrolled")

    def get_average_grade(self):
        # Calculate average grade across all subjects with grades
        total_grades = 0
        count = 0
        for subject, grade in self.grades.items():
            if grade is not None:
                total_grades += grade
                count += 1
        if count == 0:
            return None  # No grades available
        return total_grades / count


