from typing import Tuple, Optional

# Definition for a binary tree node.
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def process_bst(root: Optional[TreeNode]) -> Tuple[int, int, int]:
    # Base case: empty tree
    if not root:
        return (0, 0, 0)

    # Helper function to count total nodes in subtree
    def count_nodes(node: Optional[TreeNode]) -> int:
        if not node:
            return 0
        return 1 + count_nodes(node.left) + count_nodes(node.right)

    # Helper function to count nodes less than and greater than root_val
    def count_less_and_greater(node: Optional[TreeNode], root_val: int) -> Tuple[int, int]:
        if not node:
            return (0, 0)

        less_count, greater_count = 0, 0

        # Check current node
        if node.val < root_val:
            less_count += 1
            # Recursively check children
            less_count += count_less_and_greater(node.left, root_val)[0]
            less_count += count_less_and_greater(node.right, root_val)[0]
        elif node.val > root_val:
            greater_count += 1
            # Recursively check children
            greater_count += count_less_and_greater(node.left, root_val)[1]
            greater_count += count_less_and_greater(node.right, root_val)[1]

        return (less_count, greater_count)

    # Calculate totals
    total_nodes = count_nodes(root)
    less_than_root, greater_than_root = count_less_and_greater(root, root.val)

    # Return (greater_count, less_count, total_nodes)
    return (greater_than_root, less_than_root, total_nodes)


