    user_input = input("Enter your choice (Rock, Paper, Scissors): ").strip().capitalize()

    if user_input in ["Rock", "Paper", "Scissors"]:
        return user_input
    else:
        print("Invalid choice. Please enter Rock, Paper, or Scissors.")
        return get_user_choice()

def get_computer_choice():
    # Randomly select computer's choice
    return random.choice(["Rock", "Paper", "Scissors"])

def determine_winner(user_choice, computer_choice):
    # Determine the winner based on game rules
    if user_choice == computer_choice:
        return "It's a tie!"
    elif ((user_choice == "Rock" and computer_choice == "Scissors") or 
          (user_choice == "Paper" and computer_choice == "Rock") or 
          (user_choice == "Scissors" and computer_choice == "Paper")):
        return "You win!"
    else:
        return "Computer wins!"

def play_game():
    # Main game logic
    print("Let's play Rock-Paper-Scissors!")
    user_choice = get_user_choice()
    computer_choice = get_computer_choice()

    print(f"You chose {user_choice}, and the computer chose {computer_choice}.")
    result = determine_winner(user_choice, computer_choice)
    print(result)

def main():
    # Game loop
    while True:
        play_game()
        play_again = input("Do you want to play again? (yes/no): ").strip().lower()

        if play_again != "yes":
            print("Thanks for playing! Goodbye!")
            break

if __name__ == "__main__":
    main()

# Lecturer class definition
class Lecturer:
    def __init__(self, name, academic_qualification, subject_knowledge, professional_experience):
        self.name = name
        self._academic_qualification = academic_qualification
        self._subject_knowledge = subject_knowledge
        self._professional_experience = professional_experience
        # Flag to track if complexity has been managed
        self._complexity_managed = False

    # Getter and Setter for academic_qualification
    @property
    def academic_qualification(self):
        return self._academic_qualification

    @academic_qualification.setter
    def academic_qualification(self, value):
        self._academic_qualification = value

    # Getter and Setter for subject_knowledge
    @property
    def subject_knowledge(self):
        return self._subject_knowledge

    @subject_knowledge.setter
    def subject_knowledge(self, value):
        self._subject_knowledge = value

    # Getter and Setter for professional_experience
    @property
    def professional_experience(self):
        return self._professional_experience

    @professional_experience.setter
    def professional_experience(self, value):
        self._professional_experience = value

    def manage_complexity(self):
        if not self._complexity_managed:
            # Perform complex operations here
            print("Managing time or space complexity...")
            self._complexity_managed = True
        else:
            print("Complexity already managed.")

    def __str__(self):
        return (f"Lecturer: {self.name}\n"
                f"Academic Qualification: {self._academic_qualification}\n"
                f"Subject Knowledge: {self._subject_knowledge}\n"
                f"Professional Experience: {self._professional_experience}")


