# Address structure class for managing address details
class AddressStructure:
    def __init__(self, house_number, street_name, apartment_number=None):
        self.set_address(house_number, street_name, apartment_number)

    def set_address(self, house_number, street_name, apartment_number=None):
        # Validate house number
        if not isinstance(house_number, int) or house_number <= 0:
            raise ValueError("House number must be a positive integer.")

        # Validate street name
        if not isinstance(street_name, str) or not street_name:
            raise ValueError("Street name must be a non-empty string.")

        # Validate apartment number if provided
        if apartment_number is not None and not isinstance(apartment_number, str):
            raise ValueError("Apartment number must be a string if provided.")

        # Store the address tuple
        self.address = (house_number, street_name, apartment_number)

    def update_house_number(self, new_house_number):
        self.set_address(new_house_number, self.address[1], self.address[2])

    def update_street_name(self, new_street_name):
        self.set_address(self.address[0], new_street_name, self.address[2])

    def update_apartment_number(self, new_apartment_number):
        self.set_address(self.address[0], self.address[1], new_apartment_number)

    def delete_apartment_number(self):
        self.set_address(self.address[0], self.address[1], None)

    def get_address(self):
        return self.address

    def get_house_number(self):
        return self.address[0]

    def get_street_name(self):
        return self.address[1]

    def get_apartment_number(self):
        return self.address[2]

    @classmethod
    def get_even_houses(cls, addresses):
        # Filter addresses with even house numbers
        return [addr for addr in addresses if addr.get_house_number() % 2 == 0]

    @classmethod
    def get_odd_houses(cls, addresses):
        # Filter addresses with odd house numbers
        return [addr for addr in addresses if addr.get_house_number() % 2 != 0]


# Example usage:
if __name__ == "__main__":
    # Create initial address objects
    addr1 = AddressStructure(123, "Main St", "Apt 4B")
    addr2 = AddressStructure(456, "Oak St")
    addr3 = AddressStructure(789, "Pine St", "Suite 101")

    print("Initial Addresses:")
    print(addr1.get_address())
    print(addr2.get_address())
    print(addr3.get_address())

    # Update some address components
    addr1.update_house_number(124)
    addr2.update_street_name("Maple St")
    addr3.update_apartment_number("Suite 102")

    print("\nUpdated Addresses:")
    print(addr1.get_address())
    print(addr2.get_address())
    print(addr3.get_address())

    # Delete apartment number from first address
    addr1.delete_apartment_number()

    print("\nAfter Deleting Apartment Number:")
    print(addr1.get_address())

    # Collect all addresses for filtering
    addresses = [addr1, addr2, addr3]

    print("\nEven House Numbers:")
    for addr in AddressStructure.get_even_houses(addresses):
        print(addr.get_address())

    print("\nOdd House Numbers:")
    for addr in AddressStructure.get_odd_houses(addresses):
        print(addr.get_address())

# Import Flask modules
from flask import Flask, render_template, request, redirect, url_for

app = Flask(__name__)

# In-memory data structures for blog posts and comments
posts = []
comments = []

# Sample data structure for blog posts
class Post:
    def __init__(self, id, title, content):
        self.id = id
        self.title = title
        self.content = content

# Sample data structure for comments
class Comment:
    def __init__(self, post_id, content):
        self.post_id = post_id
        self.content = content

# Route to display all blog posts
@app.route('/')
def index():
    return render_template('index.html', posts=posts)

# Route to display a single blog post and its comments
@app.route('/post/<int:post_id>')
def post(post_id):
    # Find the requested post
    post = next((p for p in posts if p.id == post_id), None)

    # Get all comments for this post
    post_comments = [c for c in comments if c.post_id == post_id]

    if post:
        return render_template('post.html', post=post, comments=post_comments)
    else:
        return "Post not found", 404

# Route to add a new blog post
@app.route('/add_post', methods=['GET', 'POST'])
def add_post():
    if request.method == 'POST':
        title = request.form['title']
        content = request.form['content']

        # Create new post with auto-incremented ID
        new_post = Post(id=len(posts) + 1, title=title, content=content)
        posts.append(new_post)

        return redirect(url_for('index'))

    return render_template('add_post.html')

# Route to add a comment to a blog post
@app.route('/add_comment/<int:post_id>', methods=['GET', 'POST'])
def add_comment(post_id):
    if request.method == 'POST':
        content = request.form['content']

        # Create new comment
        new_comment = Comment(post_id=post_id, content=content)
        comments.append(new_comment)

        return redirect(url_for('post', post_id=post_id))

    return render_template('add_comment.html', post_id=post_id)

# Run the application in debug mode
if __name__ == '__main__':
    app.run(debug=True)

# Import required modules
import random
import math

# Calculate Euclidean distance between two points
def distance(p1, p2):
    return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

# Compute the unique circle passing through three points
def circle_from_points(p1, p2, p3):
    ax, ay = p1
    bx, by = p2
    cx, cy = p3

    # Compute denominator
    d = 2 * (ax * (by - cy) + bx * (cy - ay) + cx * (ay - by))

    # Compute center coordinates
    ux = ((ax ** 2 + ay ** 2) * (by - cy) + (bx ** 2 + by ** 2) * (cy - ay) + (cx ** 2 + cy ** 2) * (ay - by)) / d
    uy = ((ax ** 2 + ay ** 2) * (cx - bx) + (bx ** 2 + by ** 2) * (ax - cx) + (cx ** 2 + cy ** 2) * (bx - ax)) / d

    # Compute radius as distance from center to any point
    radius = distance((ux, uy), p1)
    return (ux, uy), radius

# Compute smallest circle with two points on boundary
def circle_from_two_points(p1, p2):
    cx = (p1[0] + p2[0]) / 2
    cy = (p1[1] + p2[1]) / 2
    radius = distance(p1, p2) / 2
    return (cx, cy), radius

# Compute circle with single point (radius zero)
def circle_from_one_point(p1):
    return p1, 0

# Welzl's algorithm for minimum enclosing circle
def welzl(points, boundary_points=[]):
    # Base case: no points or 3 boundary points
    if not points or len(boundary_points) == 3:
        if len(boundary_points) == 0:
            return None, None
        elif len(boundary_points) == 1:
            return circle_from_one_point(boundary_points[0])
        elif len(boundary_points) == 2:
            return circle_from_two_points(boundary_points[0], boundary_points[1])
        else:
            return circle_from_points(boundary_points[0], boundary_points[1], boundary_points[2])

    # Randomize points order
    random.shuffle(points)

    for point in points:
        # Recursively compute circle without current point
        center, radius = welzl(points[1:], boundary_points)

        # Check if current point is outside the circle
        if radius is None or distance(point, center) > radius:
            # Add point to boundary and recurse again
            boundary_points.append(point)
            center, radius = welzl(points[1:], boundary_points)
            boundary_points.pop()

        return center, radius

# Wrapper function for minimum enclosing circle
def smallest_enclosing_circle(points):
    return welzl(points)

