# Function to check if an object is considered 'empty'
def is_empty(obj):
    """User-defined function to check if an object is considered 'empty'."""
    # Check if the object has an is_empty method
    if hasattr(obj, 'is_empty'):
        return obj.is_empty()
    return False


# Recursive function to find empty values in nested structures
def find_empty_values(data, path=None):
    # Initialize path if not provided
    if path is None:
        path = []

    # Handle lists and tuples
    if isinstance(data, (list, tuple)):
        results = []
        for index, item in enumerate(data):
            sub_path = path + [index]
            sub_results = find_empty_values(item, sub_path)
            if sub_results:
                results.extend(sub_results)
        return results

    # Handle dictionaries
    elif isinstance(data, dict):
        results = []
        for key, value in data.items():
            sub_path = path + [key]
            sub_results = find_empty_values(value, sub_path)
            if sub_results:
                results.extend(sub_results)
        return results

    # Handle sets
    elif isinstance(data, set):
        results = []
        for index, item in enumerate(data):
            sub_path = path + [index]
            sub_results = find_empty_values(item, sub_path)
            if sub_results:
                results.extend(sub_results)
        return results

    # Check for None, 0, or empty string
    elif data is None or data == 0 or data == '':
        return [path]

    # Check using custom is_empty method
    elif is_empty(data):
        return [path]

    return []


# Count and list all empty values
def count_and_list_empty_values(data):
    results = find_empty_values(data)
    if not results:
        return "No None values, empty strings, zeros, or 'empty' objects found"

    count = len(results)
    return {
        "total_count": count,
        "locations": results
    }


