# Flattens a nested list using recursion and generators
def flatten(lst):
    """Flatten a nested list."""
    for el in lst:
        if isinstance(el, list):
            yield from flatten(el)
        else:
            yield el

# Converts various types (bool, str, etc.) to numeric types
def convert_to_numeric(value):
    """Convert boolean, string, and other values to numeric types."""
    if isinstance(value, bool):
        return int(value)

    if isinstance(value, str):
        try:
            return int(value)
        except ValueError:
            try:
                return float(value)
            except ValueError:
                return None

    if isinstance(value, (int, float, complex)):
        return value

    return None

# Finds the minimum disparity between any two numeric elements in an array
def find_min_disparity(arr):
    # Flatten the input array
    flat_arr = list(flatten(arr))

    # Convert elements to numeric and filter out non-numeric ones
    numeric_arr = [convert_to_numeric(x) for x in flat_arr if convert_to_numeric(x) is not None]

    # Handle edge cases where there aren't enough numeric elements
    if len(numeric_arr) < 2:
        return "Array should contain at least two numeric elements for comparison."

    # Sort the numeric array based on absolute value for complex numbers
    numeric_arr.sort(key=lambda x: abs(x) if isinstance(x, complex) else x)

    # Initialize tracking variables for minimum disparity and corresponding pair
    min_disparity = float('inf')
    min_pair = (None, None)

    # Iterate through adjacent pairs to find minimum disparity
    for i in range(len(numeric_arr) - 1):
        current_disparity = abs(numeric_arr[i] - numeric_arr[i + 1])
        if current_disparity < min_disparity:
            min_disparity = current_disparity
            min_pair = (numeric_arr[i], numeric_arr[i + 1])

    return min_disparity, min_pair

# Unit tests to verify correctness of find_min_disparity function
def test_find_min_disparity():
    assert find_min_disparity([1, 5, 3, 9, 2]) == (1, (1, 2))
    assert find_min_disparity([1, 1, 1, 1]) == (0, (1, 1))
    assert find_min_disparity([1, 2, 3, 4, 5]) == (1, (1, 2))
    assert find_min_disparity([1, 2, 3, 4, 5, 1.01]) == (0.01, (1, 1.01))
    assert find_min_disparity([1, 2, 3, 4, 5, 1.01, '2.01']) == (0.01, (1, 1.01))
    assert find_min_disparity([1, 2, 3, 4, 5, True, False]) == (1, (0, 1))
    assert find_min_disparity([1, 2, 3, 4, 5, None, 'a', [1, 2], 1.01]) == (0.01, (1, 1.01))
    assert find_min_disparity([1, 2, 3, 4, 5, complex(1, 1), complex(1, 2)]) == (1, (1, 1.4142135623730951))
    assert find_min_disparity([]) == "Array should contain at least two numeric elements for comparison."
    assert find_min_disparity([1]) == "Array should contain at least two numeric elements for comparison."
    assert find_min_disparity(['a', 'b', 'c']) == "Array should contain at least two numeric elements for comparison."
    assert find_min_disparity([None, None, None]) == "Array should contain at least two numeric elements for comparison."
    assert find_min_disparity([1, '2', '3.14', True, False, None, [1, 2], 1.01]) == (0.01, (1, 1.01))
    assert find_min_disparity([1, 2, 3, 4, 5, complex(1, 1), complex(1, 2), 1.01]) == (0.01, (1, 1.01))

test_find_min_disparity()
print("All tests passed.")

# GPA Calculator with grade trend analysis
import statistics

# Define grade conversion and GPA calculation
GRADE_SCALE = {
    (90, 100): ('A', 4.0),
    (80, 89): ('B', 3.0),
    (70, 79): ('C', 2.0),
    (60, 69): ('D', 1.0),
    (0, 59): ('F', 0.0)
}

# Define weight for AP and honors courses
COURSE_WEIGHTS = {
    'AP': 1.0,
    'Honors': 0.5,
    'Regular': 0.0
}

def numeric_to_grade(score):
    # Convert numeric score to letter grade and GPA
    for (low, high), (grade, gpa) in GRADE_SCALE.items():
        if low <= score <= high:
            return grade, gpa
    raise ValueError("Score out of range (1-100)")

def calculate_weighted_gpa(scores, course_types):
    # Calculate weighted GPA based on scores and course types
    if len(scores) != len(course_types):
        raise ValueError("Number of scores and course types must match")

    total_gpa = 0
    for score, course_type in zip(scores, course_types):
        grade, gpa = numeric_to_grade(score)
        total_gpa += gpa + COURSE_WEIGHTS[course_type]

    return total_gpa / len(scores)

def evaluate_grade_trend(grades):
    # Evaluate grade trend using linear regression
    if len(grades) < 2:
        return "Not enough data to evaluate trend"

    trend = statistics.linear_regression(range(len(grades)), grades).slope
    if trend > 0:
        return "Improving"
    elif trend < 0:
        return "Declining"
    else:
        return "Stable"

class Student:
    def __init__(self, name):
        self.name = name
        self.grades = []
        self.course_types = []

    def add_grades(self, scores, course_types):
        # Add grades and validate inputs
        if len(scores) != len(course_types):
            raise ValueError("Number of scores and course types must match")

        for score, course_type in zip(scores, course_types):
            if not (1 <= score <= 100):
                raise ValueError(f"Invalid score: {score}. Scores must be between 1 and 100.")
            if course_type not in COURSE_WEIGHTS:
                raise ValueError(f"Invalid course type: {course_type}. Valid types are {', '.join(COURSE_WEIGHTS.keys())}.")

        self.grades.extend(scores)
        self.course_types.extend(course_types)

    def get_report(self):
        # Generate student report
        if not self.grades:
            return f"No grades available for {self.name}"

        numeric_grades = [numeric_to_grade(score)[0] for score in self.grades]
        gpa = calculate_weighted_gpa(self.grades, self.course_types)
        trend = evaluate_grade_trend(self.grades)

        report = (f"Report for {self.name}:\n"
                  f"Grades: {', '.join(numeric_grades)}\n"
                  f"Weighted GPA: {gpa:.2f}\n"
                  f"Grade Trend: {trend}\n")

        return report

def main():
    # Main program loop
    students = {}
    while True:
        print("\n1. Add Student\n2. Add Grades\n3. Generate Report\n4. Exit")
        choice = input("Choose an option: ")

        if choice == '1':
            name = input("Enter student name: ")
            if name in students:
                print(f"Student {name} already exists.")
            else:
                students[name] = Student(name)
                print(f"Student {name} added.")

        elif choice == '2':
            name = input("Enter student name: ")
            if name not in students:
                print(f"Student {name} does not exist. Please add the student first.")
                continue

            scores = list(map(int, input("Enter scores (separated by spaces): ").split()))
            course_types = input("Enter course types (separated by spaces, e.g., AP Honors Regular): ").split()

            try:
                students[name].add_grades(scores, course_types)
                print("Grades added successfully.")
            except ValueError as e:
                print(f"Error: {e}")

        elif choice == '3':
            name = input("Enter student name: ")
            if name not in students:
                print(f"Student {name} does not exist.")
                continue

            report = students[name].get_report()
            print(report)

        elif choice == '4':
            print("Exiting program.")
            break

        else:
            print("Invalid choice. Please choose a valid option.")

if __name__ == "__main__":
    main()

# Go board game implementation
class GoBoard:
    def __init__(self, size=19):
        self.size = size
        # Initialize empty board
        self.board = [[None for _ in range(size)] for _ in range(size)]
        # Black starts first
        self.current_player = 'B'  # 'B' for black, 'W' for white

    def print_board(self):
        # Display the current board state
        for row in self.board:
            print(' '.join('.' if cell is None else cell for cell in row))
        print()

    def place_stone(self, row, col):
        # Check if position is already occupied
        if self.board[row][col] is not None:
            print("Position already occupied.")
            return False

        # Place the stone and switch player
        self.board[row][col] = self.current_player
        self.current_player = 'W' if self.current_player == 'B' else 'B'
        return True

    def is_valid_move(self, row, col):
        # Check boundaries
        if row < 0 or row >= self.size or col < 0 or col >= self.size:
            return False

        # Check if position is occupied
        if self.board[row][col] is not None:
            return False

        return True

    def game_over(self):
        # Check if board is completely filled
        for row in self.board:
            for cell in row:
                if cell is None:
                    return False
        return True

    def play(self):
        print("Welcome to Go!")
        self.print_board()

        # Main game loop
        while not self.game_over():
            row = int(input(f"Player {self.current_player}, enter row: "))
            col = int(input(f"Player {self.current_player}, enter column: "))

            if self.is_valid_move(row, col):
                self.place_stone(row, col)
                self.print_board()
            else:
                print("Invalid move, try again.")

        print("Game Over! The board is full.")

# Start the game when run directly
if __name__ == "__main__":
    game = GoBoard()
    game.play()

# Import required modules
import os
import requests
import json

def get_api_key():
    """
    Retrieve the API key from environment variables 
    or a configuration file.
    """
    api_key = os.getenv('API_KEY')

    if not api_key:
        raise ValueError(
            "API key not found. Please set the 'API_KEY' environment variable."
        )

    return api_key

def make_post_request(url, data):
    """
    Make an authenticated POST request to the specified URL 
    with the given data.
    """
    api_key = get_api_key()

    headers = {
        'Authorization': f'Bearer {api_key}',
        'Content-Type': 'application/json'
    }

    try:
        response = requests.post(
            url, 
            headers=headers, 
            data=json.dumps(data)
        )

        # Raise an error for bad status codes
        response.raise_for_status()

        return response.json()

    except requests.exceptions.RequestException as e:
        print(f"An error occurred: {e}")
        return None

def format_output(response):
    """Format the response into a user-readable output."""
    if response:
        return json.dumps(response, indent=4)
    else:
        return "No response received."

def main():
    url = 'https://api.example.com/v1/resource'

    data = {
        "key1": "value1",
        "key2": "value2"
    }

    response = make_post_request(url, data)
    print(format_output(response))

if __name__ == "__main__":
    main()

# Import necessary modules
import abc
from sys import stdout

# Define the base menu class
class BaseMenu(object):
    # Set abstract metaclass
    __metaclass__ = abc.ABCMeta

    # Abstract method for options
    @abc.abstractmethod
    def options(self):
        pass

    # Abstract method for menu name
    @abc.abstractmethod
    def menu_name(self):
        pass

    # Initialize the menu
    def __init__(self):
        self.images = ()
        self.foo = ()

    # Display the menu
    def display(self):
        header = "FooBar YO"
        term = self.get_terminal_size()
        print(header.center(term, '*'))
        print(self.menu_name.center(term, '+'))
        print("Please choose which option:")

        # Loop through options and display them
        for i in self.options:
            print(
                str(self.options.index(i) + 1) + ") " + i.__name__
            )

        # Get user input and execute selected option
        value = int(input("Please Choose: ")) - 1
        self.options[value](self)

    # Static method to get terminal size
