# Import json module for parsing JSON data
import json

def find_key_in_json(data, key):
    """
    Recursively finds and yields all values associated with the specified key in a JSON object.

    :param data: The JSON object (dict or list) to search through.
    :param key: The key to find in the JSON object.
    """
    # Handle dictionary type
    if isinstance(data, dict):
        # Iterate through key-value pairs
        for k, v in data.items():
            # Check if current key matches target key
            if k == key:
                yield v

            # Recursively search nested structures
            if isinstance(v, (dict, list)):
                yield from find_key_in_json(v, key)

    # Handle list type
    elif isinstance(data, list):
        # Process each item in the list
        for item in data:
            yield from find_key_in_json(item, key)

