# StudentData class to manage student information
class StudentData:
    def __init__(self):
        # Dictionary to store student data
        self.students = {}

    def add_student(self, name, age):
        # Check if student already exists
        if name in self.students:
            raise ValueError(f"Student with name '{name}' already exists.")
        # Add new student with age and empty classes list
        self.students[name] = {"age": age, "classes": []}

    def remove_student(self, name):
        # Check if student exists before removal
        if name not in self.students:
            raise ValueError(f"Student with name '{name}' does not exist.")
        # Delete the student from the dictionary
        del self.students[name]

    def update_student_age(self, name, age):
        # Verify student exists before updating age
        if name not in self.students:
            raise ValueError(f"Student with name '{name}' does not exist.")
        # Update the age of the student
        self.students[name]["age"] = age

    def enroll_student(self, name, classname, teacher):
        # Ensure student exists before enrollment
        if name not in self.students:
            raise ValueError(f"Student with name '{name}' does not exist.")
        # Create a new Class object
        class_obj = Class(classname, teacher)
        # Add class only if not already enrolled
        if class_obj not in self.students[name]["classes"]:
            self.students[name]["classes"].append(class_obj)

    def unenroll_student(self, name, classname):
        # Confirm student exists before unenrollment
        if name not in self.students:
            raise ValueError(f"Student with name '{name}' does not exist.")
        # Filter out the class with matching name
        self.students[name]["classes"] = [
            cls for cls in self.students[name]["classes"] 
            if cls.classname != classname
        ]

    def get_student_data(self, name):
        # Validate student existence before returning data
        if name not in self.students:
            raise ValueError(f"Student with name '{name}' does not exist.")
        return self.students[name]

    def __repr__(self):
        return f"StudentData(students={self.students})"


