# Function to compute median without using built-in sorting or extra arrays
def assertive_median(l: list, cmp_func: callable):
    """
    Return median of the list 'l' avoiding forming an array or using built-in features.
    The code should handle tuples represented by both even and odd numbers, duplicates, 
    using cmp_func for comparison. There should be exception handling for incorrect or 
    non-calculable input data, and it should be verified that the list contains at least one element.
    """

    # Input validation checks
    if not isinstance(l, list) or not all(isinstance(x, (int, float)) for x in l):
        raise ValueError("Input must be a list of numbers.")

    if len(l) == 0:
        raise ValueError("List must contain at least one element.")

    if not callable(cmp_func):
        raise ValueError("cmp_func must be a callable comparator function.")

    # Partition function for quickselect
    def partition(arr, low, high):
        pivot = arr[high]
        i = low - 1

        for j in range(low, high):
            if cmp_func(arr[j], pivot) < 0:
                i += 1
                arr[i], arr[j] = arr[j], arr[i]

        arr[i + 1], arr[high] = arr[high], arr[i + 1]
        return i + 1

    # Quickselect implementation to find k-th smallest element
    def quickselect(arr, k, low, high):
        if low == high:
            return arr[low]

        pivot_index = partition(arr, low, high)

        if k == pivot_index:
            return arr[k]
        elif k < pivot_index:
            return quickselect(arr, k, low, pivot_index - 1)
        else:
            return quickselect(arr, k, pivot_index + 1, high)

    # Calculate median based on length parity
    n = len(l)

    if n % 2 == 1:
        # Odd length: return middle element
        return quickselect(l, n // 2, 0, n - 1)
    else:
        # Even length: average of two middle elements
        left_mid = quickselect(l, n // 2 - 1, 0, n - 1)
        right_mid = quickselect(l, n // 2, 0, n - 1)
        return (left_mid + right_mid) / 2

# Test scenarios
assert assertive_median([3, 1, 2, 4, 5], lambda a, b: a - b) == 3
assert assertive_median([-10, 4, 6, 1000, 10, 20], lambda a, b: a - b) == 15.0
assert assertive_median([1, 2, 2, 4, 5], lambda a, b: a - b) == 2

try:
    assertive_median([], lambda a, b: a - b)
except ValueError as e:
    assert str(e) == "List must contain at least one element."

try:
    assertive_median([1, 2, 3], None)
except ValueError as e:
    assert str(e) == "cmp_func must be a callable comparator function."

try:
    assertive_median([1, 2, '3'], lambda a, b: a - b)
except ValueError as e:
    assert str(e) == "Input must be a list of numbers."

