# Student class definition
class Student:
    def __init__(self, name, college, grade_level, gpa):
        self.name = name
        self.college = college
        self.grade_level = grade_level
        self.gpa = gpa
        self.classes = []

    # Update grade level with validation
    def update_grade_level(self, new_grade_level):
        if not isinstance(new_grade_level, int):
            raise ValueError("Grade level must be an integer.")
        if new_grade_level < 1 or new_grade_level > 12:
            raise ValueError("Grade level must be between 1 and 12.")
        self.grade_level = new_grade_level

    # Update GPA with validation
    def update_gpa(self, new_gpa):
        if not isinstance(new_gpa, (int, float)):
            raise ValueError("GPA must be a numeric value.")
        if new_gpa < 0.0 or new_gpa > 4.0:
            raise ValueError("GPA must be between 0.0 and 4.0.")
        self.gpa = new_gpa

    # Add a class to the student's schedule
    def add_class(self, class_name):
        if len(self.classes) >= 7:
            raise ValueError("A student cannot enroll in more than 7 classes.")
        if class_name in self.classes:
            raise ValueError(f"Class {class_name} is already in the class list.")
        self.classes.append(class_name)

    # Calculate GPA based on class grades
    def calculate_gpa(self, class_grades):
        if not isinstance(class_grades, dict):
            raise ValueError("Class grades must be provided as a dictionary.")
        if set(class_grades.keys()) != set(self.classes):
            raise ValueError("Class grades must include all enrolled classes.")

        total_credits = 0
        weighted_grades = 0

        for class_name, grade in class_grades.items():
            if not isinstance(grade, (int, float)):
                raise ValueError(f"Grade for class {class_name} must be a numeric value.")
            if grade < 0.0 or grade > 100.0:
                raise ValueError(f"Grade for class {class_name} must be between 0.0 and 100.0.")

            # Assuming all classes have the same credit (e.g., 4 credits each)
            credits = 4
            total_credits += credits
            weighted_grades += grade * credits

        if total_credits == 0:
            raise ValueError("Total credits cannot be zero.")

        calculated_gpa = weighted_grades / total_credits / 100 * 4.0
        return calculated_gpa


