# Course management system

class Course:
    def __init__(self, cname, ccode, cunits, cinstructor):
        # Validate input types
        if not isinstance(cname, str) or not isinstance(ccode, str) or not isinstance(cinstructor, str):
            raise ValueError("Course Name, Course Code, and Instructor Name must be strings.")

        if not isinstance(cunits, int) or cunits <= 0:
            raise ValueError("Number of Units must be a positive integer.")

        # Initialize attributes
        self.cname = cname
        self.ccode = ccode
        self.cunits = cunits
        self.cinstructor = cinstructor

    def __str__(self):
        return f"Course Name: {self.cname}, Course Code: {self.ccode}, Units: {self.cunits}, Instructor: {self.cinstructor}"


class Courses:
    def __init__(self):
        self.course_list = []

    def add_course(self, cname, ccode, cunits, cinstructor):
        # Check for duplicate course code
        if any(course.ccode == ccode for course in self.course_list):
            raise ValueError(f"Course with code {ccode} already exists.")

        # Create and add new course
        new_course = Course(cname, ccode, cunits, cinstructor)
        self.course_list.append(new_course)

    def get_courses(self):
        return [str(course) for course in self.course_list]

    def update_course(self, ccode, **kwargs):
        # Find and update course
        for course in self.course_list:
            if course.ccode == ccode:
                for key, value in kwargs.items():
                    if key == 'cname':
                        course.cname = value
                    elif key == 'cunits':
                        if not isinstance(value, int) or value <= 0:
                            raise ValueError("Number of Units must be a positive integer.")
                        course.cunits = value
                    elif key == 'cinstructor':
                        course.cinstructor = value
                return

        raise ValueError(f"Course with code {ccode} not found.")

    def delete_course(self, ccode):
        # Find and delete course by index
        for i, course in enumerate(self.course_list):
            if course.ccode == ccode:
                del self.course_list[i]
                return

        raise ValueError(f"Course with code {ccode} not found.")

    def search_by_code(self, ccode):
        # Search for course by code
        for course in self.course_list:
            if course.ccode == ccode:
                return course
        return None

    def search_by_instructor(self, cinstructor):
        # Return list of courses by instructor
        return [course for course in self.course_list if course.cinstructor == cinstructor]

    def sort_courses(self, key='cname'):
        # Sort courses by specified key
        if key not in ['cname', 'cunits']:
            raise ValueError("Sort key must be 'cname' or 'cunits'.")

        return sorted(self.course_list, key=lambda course: getattr(course, key))

# Check if a point is inside the polygon
def in_me(self, point):
    result = False
    n = len(self.corners)

    # Start with the last corner
    p1 = self.corners[-1]

    for i in range(n):
        p2 = self.corners[i]

        # Check if point is within y-range of edge
        if point.y > min(p1.y, p2.y) and point.y <= max(p1.y, p2.y):
            # Check if point is within x-range of edge
            if point.x <= max(p1.x, p2.x):
                # Calculate intersection x-coordinate
                if p1.y != p2.y:
                    xinters = (point.y - p1.y) * (p2.x - p1.x) / (p2.y - p1.y) + p1.x
                else:
                    xinters = p1.x

                # Check if point is on the left side of edge
                if p1.x == p2.x or point.x <= xinters:
                    result = not result

        # Move to next edge
        p1 = p2

    return result

# Car system with state management, observer pattern, and smart features
from abc import ABC, abstractmethod
from enum import Enum

# Engine states enumeration
class EngineState(Enum):
    OFF = 0
    ON = 1

# Battery level enumeration
class BatteryLevel(Enum):
    LOW = 1
    MEDIUM = 2
    HIGH = 3

# Sensor status enumeration
class SensorStatus(Enum):
    OFF = 0
    ON = 1

# Singleton pattern for managing car state
class CarState:
    _instance = None

    @staticmethod
    def get_instance():
        if CarState._instance is None:
            CarState._instance = CarState()
        return CarState._instance

    def __init__(self):
        self.engine_state = EngineState.OFF
        self.battery_level = BatteryLevel.MEDIUM
        self.sensor_status = SensorStatus.OFF

    def set_engine_state(self, state: EngineState):
        self.engine_state = state

    def set_battery_level(self, level: BatteryLevel):
        self.battery_level = level

    def set_sensor_status(self, status: SensorStatus):
        self.sensor_status = status

# Observer interface for state change notifications
class Observer(ABC):
    @abstractmethod
    def update(self, car_state: CarState):
        pass

# SmartCar class implementing observer pattern
class SmartCar:
    def __init__(self):
        self.state = CarState.get_instance()
        self.observers = []

    def add_observer(self, observer: Observer):
        self.observers.append(observer)

    def remove_observer(self, observer: Observer):
        self.observers.remove(observer)

    def notify_observers(self):
        for observer in self.observers:
            observer.update(self.state)

    def start_engine(self):
        self.state.set_engine_state(EngineState.ON)
        print("Engine started.")
        self.notify_observers()

    def stop_engine(self):
        self.state.set_engine_state(EngineState.OFF)
        print("Engine stopped.")
        self.notify_observers()

    def charge_battery(self, level: BatteryLevel):
        self.state.set_battery_level(level)
        print(f"Battery charged to {level.name}.")
        self.notify_observers()

    def activate_sensors(self):
        self.state.set_sensor_status(SensorStatus.ON)
        print("Sensors activated.")
        self.notify_observers()

    def deactivate_sensors(self):
        self.state.set_sensor_status(SensorStatus.OFF)
        print("Sensors deactivated.")
        self.notify_observers()

    def autopilot(self):
        if (self.state.engine_state == EngineState.ON and 
            self.state.sensor_status == SensorStatus.ON):
            print("Autopilot engaged.")
        else:
            print("Autopilot cannot be engaged. Check engine and sensor status.")

    def self_parking(self):
        if self.state.sensor_status == SensorStatus.ON:
            print("Self-parking engaged.")
        else:
            print("Self-parking cannot be engaged. Check sensor status.")

    def collision_warning(self):
        if self.state.sensor_status == SensorStatus.ON:
            print("Collision warning system active.")
        else:
            print("Collision warning system cannot be activated. Check sensor status.")

# Concrete observer for logging car state changes
class CarStateLogger(Observer):
    def update(self, car_state: CarState):
        print(f"Car State Update: Engine={car_state.engine_state.name}, "
              f"Battery={car_state.battery_level.name}, "
              f"Sensors={car_state.sensor_status.name}")

# Example usage demonstration
if __name__ == "__main__":
    car = SmartCar()
    logger = CarStateLogger()
    car.add_observer(logger)

    car.start_engine()
    car.charge_battery(BatteryLevel.HIGH)
    car.activate_sensors()
    car.autopilot()
    car.self_parking()
    car.collision_warning()
    car.stop_engine()
    car.deactivate_sensors()

