# Import uuid module for generating unique identifiers
import uuid


def generate_dictionaries(N, keys=None, values=None, populate_nested=False):
    # Set default empty lists if keys or values are not provided
    if keys is None:
        keys = []
    if values is None:
        values = []

    # Ensure keys and values are unique by using dict.fromkeys()
    unique_keys = list(dict.fromkeys(keys))
    unique_values = list(dict.fromkeys(values))

    # Initialize the result list to store generated dictionaries
    result = []

    # Generate dictionaries for the provided keys
    for key in unique_keys:
        # Stop if we've already generated N dictionaries
        if len(result) >= N:
            break

        # Create nested dictionary if populate_nested is True
        nested_dict = {str(uuid.uuid4()): None} if populate_nested else {}
        result.append({key: nested_dict})

    # Generate dictionaries for the provided values
    for i, value in enumerate(unique_values):
        # Stop if we've already generated N dictionaries
        if len(result) >= N:
            break

        # Build nested dictionary based on value presence
        if value is not None:
            nested_dict = {i: value}
        else:
            nested_dict = {str(uuid.uuid4()): None}

        # Ensure nested_dict has content if populate_nested is True
        if populate_nested and not nested_dict:
            nested_dict = {str(uuid.uuid4()): None}

        result.append({str(uuid.uuid4()): nested_dict})

    # Generate additional dictionaries with unique UUIDs until we reach N
    while len(result) < N:
        key = str(uuid.uuid4())
        nested_dict = {str(uuid.uuid4()): None} if populate_nested else {}
        result.append({key: nested_dict})

    return result


