class ComponentsManager:
    def __init__(self, config: dict):
        # Initialize with configuration and empty components dictionary
        self.config = DictAccessor(config)
        self._components = {}

    def add(self, name: str, component):
        # Add a component with the given name
        self._components[name] = component

    def __getattr__(self, name):
        # Allow attribute-style access to components
        try:
            return self._components[name]
        except KeyError as e:
            raise AttributeError(
                f"'ComponentsManager' object has no attribute '{name}'"
            ) from e


# DictAccessor class for attribute-style dictionary access
class DictAccessor:
    """A helper to allow attribute-style access to dictionaries."""

    def __init__(self, data):
        # Store the underlying data dictionary
        self._data = data

    def __getattr__(self, name):
        # Enable dot notation access (e.g., config.training.lr)
        try:
            value = self._data[name]
            # Recursively wrap nested dicts for deep access
            if isinstance(value, dict):
                return DictAccessor(value)
            return value
        except KeyError as e:
            raise AttributeError(f"No such attribute: {name}") from e

    def __getitem__(self, key):
        # Enable dictionary-style access (e.g., config['training'])
        return self._data[key]

    def __contains__(self, key):
        # Support 'in' operator
        return key in self._data

    def get(self, key, default=None):
        """Get value with optional default like dict.get()."""
        return self._data.get(key, default)

    def __repr__(self):
        # String representation of the accessor
        return repr(self._data)

