        env_buffer_size = os.environ.get('DIFFSYNTH_DISK_MAP_BUFFER_SIZE')
        if env_buffer_size is not None:
            self.buffer_size = int(env_buffer_size)
        else:
            self.buffer_size = buffer_size

        # Initialize files and mappings
        self.files = []
        self.flush_files()
        self.name_map = {}

        for file_id, file in enumerate(self.files):
            for name in file.keys():
                self.name_map[name] = file_id

        self.rename_dict = self.fetch_rename_dict(state_dict_converter)

    def flush_files(self):
        if len(self.files) == 0:
            # First-time file loading
            for path in self.path:
                if path.endswith(".safetensors"):
                    self.files.append(safe_open(path, framework="pt", device=str(self.device)))
                else:
                    self.files.append(SafetensorsCompatibleBinaryLoader(path, device=self.device))
        else:
            # Reload existing files
            for i, path in enumerate(self.path):
                if path.endswith(".safetensors"):
                    self.files[i] = safe_open(path, framework="pt", device=str(self.device))

        self.num_params = 0

    def __getitem__(self, name):
        # Apply renaming if needed
        if self.rename_dict is not None:
            name = self.rename_dict[name]

        # Locate the appropriate file
        file_id = self.name_map[name]
        param = self.files[file_id].get_tensor(name)

        # Type conversion if specified
        if self.torch_dtype is not None and isinstance(param, torch.Tensor):
            param = param.to(self.torch_dtype)

        # Ensure non-CPU tensors are cloned if on CPU
        if isinstance(param, torch.Tensor) and param.device == "cpu":
            param = param.clone()

        # Track parameter count
        if isinstance(param, torch.Tensor):
            self.num_params += param.numel()

        # Flush if buffer exceeded
        if self.num_params > self.buffer_size:
            self.flush_files()

        return param

    def fetch_rename_dict(self, state_dict_converter):
        if state_dict_converter is None:
            return None

        # Build initial state dict mapping
        state_dict = {}
        for file in self.files:
            for name in file.keys():
                state_dict[name] = name

        # Apply converter
        return state_dict_converter(state_dict)

    def __iter__(self):
        if self.rename_dict is not None:
            return iter(self.rename_dict)
        else:
            return iter(self.name_map)

    def __contains__(self, x):
        if self.rename_dict is not None:
            return x in self.rename_dict
        else:
            return x in self.name_map

# Parse telemetry data from JSONL file
import sys, json
from statistics import mean

def load_jsonl(path):
    # Generator that yields parsed JSON objects from a JSONL file
    with open(path, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                yield json.loads(line)
            except json.JSONDecodeError:
                continue

def main(p):
    # Extract energy values (E) and step indices (step_idx) from records
    E, steps = [], []
    for rec in load_jsonl(p):
        e = rec.get('E')
        if isinstance(e, (int, float)):
            E.append(float(e))
        s = rec.get('step_idx')
        if isinstance(s, int):
            steps.append(s)

    # Handle case with no energy values
    if not E:
        print('no energy values found'); return

    # Calculate energy differences and monotonicity ratio
    dE = [E[i]-E[i-1] for i in range(1, len(E))]
    neg = sum(1 for v in dE if v < 0)
    mono_ratio = (neg / len(dE)) if dE else float('nan')

    # Print summary statistics
    print(f'file: {p}')
    print(f'num_steps: {len(E)}  minE: {min(E):.6f}  finalE: {E[-1]:.6f}  meanE: {mean(E):.6f}')

    # Print energy difference statistics if available
    if dE:
        print(f'dE: mean={mean(dE):.6f}  <0 fraction={mono_ratio:.3f}  first={dE[0]:.6f}  last={dE[-1]:.6f}')

    # Print last step index if available
    if steps:
        print(f'last step_idx: {steps[-1]}')

if __name__ == '__main__':
    # Command-line interface
    if len(sys.argv) < 2:
        print('usage: parse_telemetry.py <path/to/telemetry.jsonl>')
        sys.exit(1)
    main(sys.argv[1])

