def get_device_type():
    # Determine the device type based on available hardware
    if torch.cuda.is_available():
        try:
            # Check for HIP (ROCm) support
            if torch.version.hip is not None:
                return "hip"
        except AttributeError:
            pass
        return "cuda"

    # Check for Intel XPU support
    try:
        if hasattr(torch, "xpu") and torch.xpu.is_available():
            return "xpu"
    except (AttributeError, RuntimeError):
        pass

    return "cpu"


def get_device_count(device_type):
    # Return number of available devices for the given device type
    if device_type in ("cuda", "hip"):
        return torch.cuda.device_count()
    elif device_type == "xpu":
        try:
            return torch.xpu.device_count()
        except (AttributeError, RuntimeError):
            return 0
    return 0


# Maximum fused size for Triton kernels
MAX_FUSED_SIZE: int = 65536

# Alias for triton's next_power_of_2 function
next_power_of_2 = triton.next_power_of_2

# Determine current device type and count
DEVICE_TYPE = get_device_type()
DEVICE_COUNT = get_device_count(DEVICE_TYPE)

# Setup GPU device context manager based on device count and type
if DEVICE_COUNT > 1:
    if DEVICE_TYPE in ("cuda", "hip"):
        torch_gpu_device = torch.cuda.device
    elif DEVICE_TYPE == "xpu":
        torch_gpu_device = torch.xpu.device
else:
    def torch_gpu_device(device):
        # Context manager that does nothing (nullcontext-like behavior)
        from contextlib import nullcontext
        return nullcontext()


def calculate_settings(
    n: int,
) -> (
    int,
    int,
):
    # Compute block size as next power of 2
    BLOCK_SIZE: int = next_power_of_2(n)

    # Ensure block size doesn't exceed maximum allowed size
    if BLOCK_SIZE > MAX_FUSED_SIZE:
        raise RuntimeError(
            f"Cannot launch Triton kernel since n = {n} exceeds the maximum CUDA blocksize = {MAX_FUSED_SIZE}."
        )

    # Set number of warps based on block size
    num_warps: int = 4
    if BLOCK_SIZE >= 32768:
        num_warps = 32
    elif BLOCK_SIZE >= 8192:
        num_warps = 16
    elif BLOCK_SIZE >= 2048:
        num_warps = 8

    return BLOCK_SIZE, num_warps

# Handles CRUD operations for items via API Gateway
Routes: POST /items, GET /items/{id}, DELETE /items/{id}
Linked to a DynamoDB table via items link.
"""
import json
import boto3
from stlv_resources import Resources

def main(event, context):
    # Connect to DynamoDB table
    table = boto3.resource("dynamodb").Table(Resources.items.table_name)

    method = event["httpMethod"]
    path_params = event.get("pathParameters") or {}
    item_id = path_params.get("id")

    if method == "POST":
        body = json.loads(event["body"])
        table.put_item(Item=body)
        return {"statusCode": 201, "body": json.dumps(body)}

    if method == "GET" and item_id:
        resp = table.get_item(Key={"pk": item_id})
        item = resp.get("Item")
        if not item:
            return {"statusCode": 404, "body": "not found"}
        return {"statusCode": 200, "body": json.dumps(item)}

    if method == "DELETE" and item_id:
        table.delete_item(Key={"pk": item_id})
        return {"statusCode": 200, "body": "deleted"}

    return {"statusCode": 400, "body": "bad request"}

