import numpy as np
import torch
import torch.nn as nn

def layer_init(layer, std=np.sqrt(2), bias_const=0.0):
    # Orthogonal initialization for weights and constant initialization for biases
    torch.nn.init.orthogonal_(layer.weight, std)
    torch.nn.init.constant_(layer.bias, bias_const)
    return layer

def get_act_func(activation):
    # Return the appropriate activation function class based on string input
    if activation.lower() == "relu":
        act = nn.ReLU
    elif activation.lower() == "gelu":
        act = nn.GELU
    elif activation.lower() == "tanh":
        act = nn.Tanh
    else:
        raise ValueError(f"Unsupported activation: {activation}")
    return act

def make_mlp(
    in_channels, mlp_channels, act_builder=nn.ReLU, last_act=True, use_layer_norm=False
):
    # Build a list of layers for an MLP
    c_in = in_channels
    module_list = []

    for idx, c_out in enumerate(mlp_channels):
        # Add linear layer
        module_list.append(nn.Linear(c_in, c_out))

        # Add normalization and activation (except possibly after the last layer)
        if last_act or idx < len(mlp_channels) - 1:
            if use_layer_norm:
                module_list.append(nn.LayerNorm(c_out))
            module_list.append(act_builder())

        c_in = c_out

    return module_list

def init_mlp_weights(mlp, nonlinearity):
    # Initialize weights for MLP modules
    for m in mlp:
        if isinstance(m, nn.Linear):
            if m is mlp[-1]:
                # Special initialization for the final layer
                nn.init.normal_(m.weight, mean=0.0, std=0.02)
                if m.bias is not None:
                    nn.init.zeros_(m.bias)
            else:
                # Kaiming initialization for hidden layers
                nn.init.kaiming_normal_(
                    m.weight, mode="fan_out", nonlinearity=nonlinearity
                )
                if m.bias is not None:
                    nn.init.zeros_(m.bias)

