import numpy as np

class DiagonalGaussianDistribution:
    def __init__(self, parameters, deterministic=False, dim=1):
        self.parameters = parameters
        # Split parameters into mean and logvar
        self.mean, self.logvar = torch.chunk(parameters, 2, dim=dim)
        # Clamp logvar to prevent numerical instability
        self.logvar = torch.clamp(self.logvar, -30.0, 20.0)

        self.deterministic = deterministic

        # Compute standard deviation and variance
        self.std = torch.exp(0.5 * self.logvar)
        self.var = torch.exp(self.logvar)

        # For deterministic case, set std and var to zero
        if self.deterministic:
            self.var = self.std = torch.zeros_like(self.mean, 
                                                   device=self.parameters.device, 
                                                   dtype=self.parameters.dtype)

    def sample(self, generator=None):
        # Reparameterization trick: mean + std * noise
        x = self.mean + self.std * torch.randn(self.mean.shape, 
                                               device=self.parameters.device,
                                               dtype=self.parameters.dtype, 
                                               generator=generator)
        return x

    def kl(self, other=None):
        if self.deterministic:
            return torch.Tensor([0.])
        else:
            if other is None:
                # KL divergence with standard normal
                return 0.5 * torch.sum(torch.pow(self.mean, 2)
                       + self.var - 1.0 - self.logvar, dim=[1, 2, 3])
            else:
                # KL divergence between two Gaussians
                return 0.5 * torch.sum(
                       torch.pow(self.mean - other.mean, 2) / other.var
                       + self.var / other.var - 1.0 - self.logvar + other.logvar, 
                       dim=[1, 2, 3])

    def nll(self, sample, dims=(1, 2, 3)):
        if self.deterministic:
            return torch.Tensor([0.])

        logtwopi = np.log(2.0 * np.pi)
        # Negative log-likelihood
        return 0.5 * torch.sum(logtwopi + self.logvar
               + torch.pow(sample - self.mean, 2) / self.var, 
               dim=dims)

    def mode(self):
        return self.mean

