# Validates if the given date string is in correct format and valid
if not date:
    return False

try:
    # Split the date by hyphen
    parts = date.split('-')

    # Check if there are exactly 3 parts (mm-dd-yyyy)
    if len(parts) != 3:
        return False

    # Extract month, day, year
    mm, dd, yyyy = parts

    # Validate length of each part
    if len(mm) != 2 or len(dd) != 2 or len(yyyy) != 4:
        return False

    # Convert to integers
    month = int(mm)
    day = int(dd)
    year = int(yyyy)

    # Validate month range
    if month < 1 or month > 12:
        return False

    # Validate day is positive
    if day < 1:
        return False

    # Check days based on month
    if month in [1, 3, 5, 7, 8, 10, 12]:
        if day > 31:
            return False
    elif month in [4, 6, 9, 11]:
        if day > 30:
            return False
    elif month == 2:
        # February can have up to 29 days (leap year handling not required per spec)
        if day > 29:
            return False

    return True
except:
    # Any exception means invalid date
    return False

