import bisect
from collections.abc import Iterable
from typing import NamedTuple
from torch.utils.data import ConcatDataset

# can't be a local class as it is required to be pickleable
class _InterleavedConcatDataset(ConcatDataset):
    """`torch.utils.data.ConcatDataset` but it returns the dataset index."""

    def __getitem__(self, idx):
        if idx < 0:
            if -idx > len(self):
                raise ValueError("absolute value of index should not exceed dataset length")
            idx = len(self) + idx

        dataset_idx = bisect.bisect_right(self.cumulative_sizes, idx)

        if dataset_idx == 0:
            sample_idx = idx
        else:
            sample_idx = idx - self.cumulative_sizes[dataset_idx - 1]

        return dataset_idx, self.datasets[dataset_idx][sample_idx]


# can't be a local class as it is required to be pickleable
class _InterleavedCollator:
    """Holds a list of collators and calls a single one of them based on the dataset_idx that was returned."""

    def __init__(self, collators):
        self.collators = collators

    def __call__(self, data):
        dataset_idxs, data = zip(*data, strict=True)

        if not all(dataset_idxs[0] == idx for idx in dataset_idxs):
            raise ValueError("All samples in a batch must come from the same dataset.")

        return self.collators[dataset_idxs[0]](data)


class SamplerOutput(NamedTuple):  #  lint-ignore: NoNamedTuple
    """Output of the InterleavedSampler. Contains the sample index and the dataset index."""
    is_full_batch: bool
    idx: int


# can't be a local class as it is required to be pickleable
class _InterleavedBatchSampler:
    """Creates batches of indices from an iterable of indices."""

    def __init__(self, sampler: Iterable[SamplerOutput]):
        super().__init__()
        self.sampler = sampler

    def __iter__(self):
        idxs = []

        for is_full_batch, idx in self.sampler:
            idxs.append(idx)

            if is_full_batch:
                yield idxs
                idxs = []

        assert len(idxs) == 0

    def __len__(self):
        raise NotImplementedError

# WebSocket API endpoints for management and monitoring.
"""
from flask import Blueprint, request, g
from auth.unified import require_auth
from utils.response import success_response, error_response
from websocket import (
    get_connected_clients_info,
    get_connected_clients_count,
    emit_system_alert,
    EventType
)

# Create WebSocket blueprint with URL prefix
websocket_bp = Blueprint('websocket', __name__, url_prefix='/api/v2/websocket')


@websocket_bp.route('/status', methods=['GET'])
@require_auth()
def get_status():
    """Get WebSocket server status."""
    clients_info = get_connected_clients_info()

    return success_response(data={
        'websocket': {
            'enabled': True,
            'connected_clients': clients_info['count'],
            'endpoint': '/socket.io'
        }
    })


@websocket_bp.route('/clients', methods=['GET'])
@require_auth()
def get_clients():
    """Get list of connected WebSocket clients (admin only)."""
    clients_info = get_connected_clients_info()

    return success_response(data=clients_info)


@websocket_bp.route('/broadcast', methods=['POST'])
@require_auth()
def broadcast_message():
    """Broadcast a system alert to all connected clients (admin only)."""
    data = request.get_json()
    message = data.get('message', '')
    alert_type = data.get('alert_type', 'system')
    severity = data.get('severity', 'info')

    # Validate required fields
    if not message:
        return error_response('Message required', 400)

    # Emit the system alert
    emit_system_alert(alert_type, message, severity)

    # Get username from current user context
    user = g.current_user.username if hasattr(g, 'current_user') else 'unknown'

    return success_response(data={
        'message': 'Broadcast sent',
        'details': {
            'alert_type': alert_type,
            'severity': severity,
            'sent_by': user
        }
    })


@websocket_bp.route('/events', methods=['GET'])
def get_event_types():
    """
    Get list of all available WebSocket event types.
    ---
    tags:
      - WebSocket
    responses:
      200:
        description: List of event types
    """
    events = [
        {'name': e.name, 'value': e.value}
        for e in EventType
    ]

    return success_response(data={'events': events})

# HTTP server router implementation
from http.server import BaseHTTPRequestHandler
import json
import logging

logger = logging.getLogger(__name__)

class Router:
    def __init__(self):
        # paths: method -> path -> handler
        self.routes: Dict[str, Dict[str, Callable]] = {
            "GET": {},
            "POST": {}
        }

    def add_route(self, method: str, path: str, handler: Callable):
        method = method.upper()
        if method not in self.routes:
            self.routes[method] = {}
        self.routes[method][path] = handler

    def get(self, path: str):
        def decorator(func: Callable):
            self.add_route("GET", path, func)
            return func
        return decorator

    def post(self, path: str):
        def decorator(func: Callable):
            self.add_route("POST", path, func)
            return func
        return decorator

    def dispatch(self, handler: BaseHTTPRequestHandler):
        path = handler.path.split('?')[0]  # Simple path matching
        method = handler.command.upper()

        if method in self.routes and path in self.routes[method]:
            try:
                self.routes[method][path](handler)
            except Exception as e:
                logger.error(f"Error handling {method} {path}: {e}")
                self._send_error(handler, 500, str(e))
        else:
            self._send_error(handler, 404, "Not Found")

    def _send_error(self, handler: BaseHTTPRequestHandler, code: int, message: str):
        handler.send_response(code)
        handler.send_header('Content-type', 'application/json')
        handler.end_headers()
        handler.wfile.write(json.dumps({"error": message}).encode('utf-8'))


# Global router instance
_router = Router()


def get_router() -> Router:
    return _router

# Error handling function for API errors
def Error(message: str):
    return "API Error: " + message

# Handler for VolcResponse
def HandlerVolcResponse(response: dict):
    # Check for empty response
    if not response:
        return Error("Empty response")

    # Parse JSON response if it's a string
    json_response = response if not isinstance(response, str) else json.loads(response)

    # Extract error information
    error = json_response.get("ResponseMetadata", {}).get("Error")

    # Handle error if present
    if error and isinstance(error, dict):
        message = error.get("Message", "Unknown error")
        return Error(message)

    # Return string representation of response if no error
    return str(response)

