# Process text to replace spaces
result = []
i = 0

while i < len(text):
    if text[i] == ' ':
        # Count consecutive spaces
        space_count = 0

        while i < len(text) and text[i] == ' ':
            space_count += 1
            i += 1

        # If more than 2 consecutive spaces, replace with -
        if space_count > 2:
            result.append('-')
        else:
            # Replace each space with underscore
            result.append('_' * space_count)
    else:
        result.append(text[i])
        i += 1

return ''.join(result)

# Import necessary modules
from datetime import datetime
from langchain_core.messages import BaseMessage
from langgraph.graph.message import add_messages
from typing import Sequence, TypedDict, Annotated

def add_messages_with_timestamp(left: Sequence[BaseMessage], right: Sequence[BaseMessage]):
    """Returns the result of add_messages after adding timestamps to messages."""
    # Convert right to list if it's not already a list
    new_messages = right if isinstance(right, list) else [right]

    # Add timestamp to new messages if not already present
    created_at = datetime.now().isoformat()

    for msg in new_messages:
        # Handle messages with additional_kwargs attribute
        if hasattr(msg, 'additional_kwargs'):
            if "created_at" not in msg.additional_kwargs:
                msg.additional_kwargs["created_at"] = created_at

        # Handle dictionary-style messages
        elif isinstance(msg, dict):
            if "additional_kwargs" not in msg:
                msg["additional_kwargs"] = {}
            if "created_at" not in msg["additional_kwargs"]:
                msg["additional_kwargs"]["created_at"] = created_at

    return add_messages(left, new_messages)


