# Financial account management module
from datetime import datetime, timedelta
from typing import List, Optional

class FinancialEntry:
    def __init__(self, entry_type: str, value: float, note: Optional[str] = None):
        self.entry_type = entry_type
        self.value = value
        self.note = note
        self.creation_time = datetime.now()

    def __repr__(self):
        return (f"FinancialEntry(type={self.entry_type}, value={self.value}, "
                f"note={self.note}, creation_time={self.creation_time})")

class PremiumBankAccount:
    def __init__(self, owner_name: str, contact_email: str, starting_balance: float = 0.0):
        self.owner_name = owner_name
        self.contact_email = contact_email
        self.current_balance = starting_balance
        self.entries_log: List[FinancialEntry] = []

    def add_funds(self, amount: float, note: Optional[str] = None) -> None:
        if amount <= 0:
            raise ValueError("Amount to add must be greater than zero.")
        self.current_balance += amount
        self.entries_log.append(FinancialEntry("credit", amount, note))

    def remove_funds(self, amount: float, note: Optional[str] = None) -> None:
        if amount <= 0:
            raise ValueError("Amount to remove must be greater than zero.")
        if amount > self.current_balance:
            raise ValueError("Not enough funds available.")
        self.current_balance -= amount
        self.entries_log.append(FinancialEntry("debit", amount, note))

    def move_funds(self, target_account: 'PremiumBankAccount', amount: float, note: Optional[str] = None) -> None:
        if amount <= 0:
            raise ValueError("Transfer amount must be positive.")
        if amount > self.current_balance:
            raise ValueError("Insufficient balance for transfer.")

        self.current_balance -= amount
        self.entries_log.append(FinancialEntry("transfer_out", amount, note))

        target_account.add_funds(amount, note=f"Received transfer from {self.owner_name}")

    def retrieve_entries(self, from_date: Optional[datetime] = None, until_date: Optional[datetime] = None) -> List[FinancialEntry]:
        if from_date is None:
            from_date = datetime.min
        if until_date is None:
            until_date = datetime.max

        return [entry for entry in self.entries_log if from_date <= entry.creation_time <= until_date]

    def calculate_balance_at_time(self, reference_date: datetime) -> float:
        current_total = 0.0
        for entry in self.entries_log:
            if entry.creation_time <= reference_date:
                if entry.entry_type == "credit":
                    current_total += entry.value
                elif entry.entry_type in ("debit", "transfer_out"):
                    current_total -= entry.value
        return current_total

# Demonstration of functionality:
if __name__ == "__main__":
    primary_account = PremiumBankAccount("Alice", "redacted@example.invalid", 1000.0)
    secondary_account = PremiumBankAccount("Bob", "redacted@example.invalid")

    primary_account.add_funds(500.0, "Salary deposit")
    primary_account.remove_funds(200.0, "Shopping expenses")
    primary_account.move_funds(secondary_account, 300.0, "Rent payment")

    print(f"Primary Account Balance: {primary_account.current_balance}")
    print(f"Secondary Account Balance: {secondary_account.current_balance}")

    print("Primary Account Entry Log:")
    for entry in primary_account.retrieve_entries():
        print(entry)

    print("Secondary Account Entry Log:")
    for entry in secondary_account.retrieve_entries():
        print(entry)

    previous_date = datetime.now() - timedelta(days=1)
    print(f"Primary Account Balance on {previous_date}: {primary_account.calculate_balance_at_time(previous_date)}")

# Employee Management System Implementation
from datetime import datetime
import uuid

class StaffMember:
    def __init__(self, full_name, years_old, compensation, position, join_date):
        self.identifier = str(uuid.uuid4())  # Generate unique identifier
        self.full_name = full_name
        self.years_old = years_old
        self.compensation = compensation
        self.position = position
        self.join_date = join_date

    def compute_tenure(self):
        current_date = datetime.today()
        start_date = datetime.strptime(self.join_date, '%Y-%m-%d')
        days_worked = (current_date - start_date).days
        return days_worked // 365

    def __str__(self):
        return f"ID: {self.identifier}, Name: {self.full_name}, Age: {self.years_old}, Compensation: {self.compensation}, Position: {self.position}, Join Date: {self.join_date}"

class HumanResourcesManager:
    def __init__(self):
        self.staff_members = []

    def register_staff(self, full_name, years_old, compensation, position, join_date):
        new_member = StaffMember(full_name, years_old, compensation, position, join_date)
        self.staff_members.append(new_member)
        print(f"Staff member {full_name} registered successfully.")

    def deregister_staff(self, staff_id):
        for member in self.staff_members:
            if member.identifier == staff_id:
                self.staff_members.remove(member)
                print(f"Staff member with ID {staff_id} removed successfully.")
                return
        print(f"Staff member with ID {staff_id} not found.")

    def modify_staff(self, staff_id, **kwargs):
        for member in self.staff_members:
            if member.identifier == staff_id:
                for attribute, new_value in kwargs.items():
                    setattr(member, attribute, new_value)
                print(f"Staff member with ID {staff_id} updated successfully.")
                return
        print(f"Staff member with ID {staff_id} not found.")

    def retrieve_staff(self, staff_id):
        for member in self.staff_members:
            if member.identifier == staff_id:
                return member
        print(f"Staff member with ID {staff_id} not found.")
        return None

    def get_tenure(self, staff_id):
        staff_member = self.retrieve_staff(staff_id)
        if staff_member:
            return staff_member.compute_tenure()
        return None

    def display_all_staff(self):
        for member in self.staff_members:
            print(member)

    def is_executive_role(self, staff_id):
        staff_member = self.retrieve_staff(staff_id)
        if staff_member and staff_member.position.lower() == 'management':
            return True
        return False

# Demonstration of usage
if __name__ == "__main__":
    hrs = HumanResourcesManager()

    # Register some staff members
    hrs.register_staff("Eva", 28, 70000, "Executive", "2019-05-10")
    hrs.register_staff("Frank", 32, 45000, "Engineer", "2021-07-22")
    hrs.register_staff("Grace", 40, 85000, "Executive", "2016-11-30")

    # Show all registered staff
    print("All registered staff:")
    hrs.display_all_staff()

    # Modify a staff member's details
    hrs.modify_staff(hrs.staff_members[0].identifier, compensation=75000)

    # Remove a staff member
    hrs.deregister_staff(hrs.staff_members[1].identifier)

    # Calculate tenure for a staff member
    print(f"Tenure for {hrs.staff_members[0].full_name}: {hrs.get_tenure(hrs.staff_members[0].identifier)} years")

    # Check if a staff member holds an executive role
    print(f"Is {hrs.staff_members[0].full_name} in executive role? {hrs.is_executive_role(hrs.staff_members[0].identifier)}")

