# Type checking implementation for SimpleLanguage 
from antlr4 import *
from SimpleLanguageLexer import SimpleLanguageLexer
from SimpleLanguageParser import SimpleLanguageParser
from SimpleLanguageVisitor import SimpleLanguageVisitor

class VariableStore:
    def __init__(self):
        self.storage = {}

    def declare_variable(self, identifier, data_type):
        self.storage[identifier] = data_type

    def retrieve_type(self, identifier):
        return self.storage.get(identifier)

class TypeValidator(SimpleLanguageVisitor):
    def __init__(self):
        self.variable_store = VariableStore()

    def visitVarDecl(self, ctx):
        identifier = ctx.ID().getText()
        data_type = ctx.type().getText()
        self.variable_store.declare_variable(identifier, data_type)
        return self.visitChildren(ctx)

    def visitAssignment(self, ctx):
        identifier = ctx.ID().getText()
        if identifier not in self.variable_store.storage:
            raise ValueError(f"Variable '{identifier}' is not declared")
        expression_type = self.visit(ctx.expr())
        variable_type = self.variable_store.retrieve_type(identifier)
        if expression_type != variable_type:
            raise ValueError(f"Type mismatch: {expression_type} does not match {variable_type}")
        return variable_type

    def visitExpr(self, ctx):
        if ctx.INT():
            return 'int'
        identifier = ctx.ID().getText()
        return self.variable_store.retrieve_type(identifier)

def execute():
    source_file = FileStream('input.txt')
    tokenizer = SimpleLanguageLexer(source_file)
    token_stream = CommonTokenStream(tokenizer)
    parser = SimpleLanguageParser(token_stream)
    syntax_tree = parser.prog()

    validator = TypeValidator()
    validator.visit(syntax_tree)

if __name__ == '__main__':
    execute()

