        return None

def run_sql_query(connection, sql_statement):
    try:
        cursor = connection.cursor()
        cursor.execute(sql_statement)
        results = cursor.fetchall()
        cursor.close()
        return results
    except Exception as error:
        print(f"Query execution error: {error}")
        return None

def generate_xml_data(results):
    root_element = ET.Element("Clients")
    for record in results:
        client = ET.SubElement(root_element, "Client")
        for index, field in enumerate(record):
            ET.SubElement(client, f"field_{index}").text = str(field)

    # Format the XML output with proper indentation
    raw_xml = ET.tostring(root_element, encoding="utf-8")
    return minidom.parseString(raw_xml).toprettyxml(indent="  ")

