    sql_query = """
    SELECT * FROM clients 
    WHERE client_city ILIKE '%New York%' 
    AND registration_date BETWEEN '2020-01-01' AND '2020-03-01';
    """

    db_connection = establish_database_connection()
    if db_connection:
        query_results = run_sql_query(db_connection, sql_query)
