import tokenize
import io
import re

def check_snake_case(identifier):
    return re.match(r'^[a-z]+(_[a-z]+)*$', identifier)

def convert_to_kebab(identifier):
    return identifier.replace('_', '-')

def transform_source(source):
    source_buffer = io.StringIO(source)
    result_buffer = io.StringIO()
    token_stream = tokenize.generate_tokens(source_buffer.readline)

    for token in token_stream:
        tok_kind, tok_val, pos_start, pos_end, orig_line = token
        if tok_kind == tokenize.NAME and check_snake_case(tok_val):
            tok_val = convert_to_kebab(tok_val)
        result_buffer.write(tok_val)

    result_buffer.seek(0)
    return result_buffer.read()

def execute():
    sample_code = """
    # This is a comment
    my_variable = "Hello World"
    second_variable = 456
    print(my_variable, second_variable)
    """

    transformed_code = transform_source(sample_code)
    print("Original Code:")
    print(sample_code)
    print("\nTransformed Code:")
    print(transformed_code)

if __name__ == "__main__":
    execute()

# Implementation of a Binary Search Tree with various operations
from typing import List, Optional

class Node:
    def __init__(self, data: int):
        self.data = data
        self.left = None
        self.right = None

class BST:
    def __init__(self):
        self.root_node = None

    def insert(self, value: int) -> None:
        if self.root_node is None:
            self.root_node = Node(value)
        else:
            self._insert_recursive(self.root_node, value)

    def _insert_recursive(self, current_node: Node, value: int) -> None:
        if value < current_node.data:
            if current_node.left is None:
                current_node.left = Node(value)
            else:
                self._insert_recursive(current_node.left, value)
        elif value > current_node.data:
            if current_node.right is None:
                current_node.right = Node(value)
            else:
                self._insert_recursive(current_node.right, value)

    def delete(self, value: int) -> bool:
        self.root_node, deleted = self._delete_recursive(self.root_node, value)
        return deleted

    def _delete_recursive(self, node: Optional[Node], value: int) -> (Optional[Node], bool):
        if node is None:
            return None, False

        if value < node.data:
            node.left, deleted = self._delete_recursive(node.left, value)
        elif value > node.data:
            node.right, deleted = self._delete_recursive(node.right, value)
        else:
            # Node found
            if node.left is None and node.right is None:
                return None, True
            elif node.left is None:
                return node.right, True
            elif node.right is None:
                return node.left, True
            else:
                # Two children: find in-order successor (minimum in right subtree)
                successor = self._find_minimum(node.right)
                node.data = successor.data
                node.right, _ = self._delete_recursive(node.right, successor.data)
                deleted = True

        return node, deleted

    def find(self, value: int) -> bool:
        return self._search_recursive(self.root_node, value)

    def _search_recursive(self, node: Optional[Node], value: int) -> bool:
        if node is None:
            return False
        if value == node.data:
            return True
        elif value < node.data:
            return self._search_recursive(node.left, value)
        else:
            return self._search_recursive(node.right, value)

    def get_inorder(self) -> List[int]:
        result = []
        self._inorder_traversal(self.root_node, result)
        return result

    def _inorder_traversal(self, node: Optional[Node], result: List[int]) -> None:
        if node:
            self._inorder_traversal(node.left, result)
            result.append(node.data)
            self._inorder_traversal(node.right, result)

    def get_preorder(self) -> List[int]:
        result = []
        self._preorder_traversal(self.root_node, result)
        return result

    def _preorder_traversal(self, node: Optional[Node], result: List[int]) -> None:
        if node:
            result.append(node.data)
            self._preorder_traversal(node.left, result)
            self._preorder_traversal(node.right, result)

    def get_postorder(self) -> List[int]:
        result = []
        self._postorder_traversal(self.root_node, result)
        return result

    def _postorder_traversal(self, node: Optional[Node], result: List[int]) -> None:
        if node:
            self._postorder_traversal(node.left, result)
            self._postorder_traversal(node.right, result)
            result.append(node.data)

    def get_level_order(self) -> List[int]:
        if not self.root_node:
            return []
        result = []
        queue = [self.root_node]
        while queue:
            current = queue.pop(0)
            result.append(current.data)
            if current.left:
                queue.append(current.left)
            if current.right:
                queue.append(current.right)
        return result

    def find_min(self) -> int:
        if self.root_node is None:
            raise ValueError("Tree is empty")
        return self._find_minimum(self.root_node).data

    def _find_minimum(self, node: Node) -> Node:
        while node.left:
            node = node.left
        return node

    def find_max(self) -> int:
        if self.root_node is None:
            raise ValueError("Tree is empty")
        return self._find_maximum(self.root_node).data

    def _find_maximum(self, node: Node) -> Node:
        while node.right:
            node = node.right
        return node

    def calculate_height(self) -> int:
        return self._calculate_height_recursive(self.root_node)

    def _calculate_height_recursive(self, node: Optional[Node]) -> int:
        if node is None:
            return 0
        left_height = self._calculate_height_recursive(node.left)
        right_height = self._calculate_height_recursive(node.right)
        return max(left_height, right_height) + 1

# Example usage:
tree = BST()
tree.insert(10)
tree.insert(5)
tree.insert(15)
tree.insert(3)
tree.insert(7)
tree.insert(12)
tree.insert(18)

print("In-order traversal:", tree.get_inorder())
print("Pre-order traversal:", tree.get_preorder())
print("Post-order traversal:", tree.get_postorder())
print("Level-order traversal:", tree.get_level_order())
print("Minimum value:", tree.find_min())
