# Display specified number of lines from log files matching given patterns
import os

def show_content(file_path, count, reverse=False):
    with open(file_path, "r") as file:
        all_lines = file.readlines()
        if reverse:
            selected_lines = all_lines[-count:]
        else:
            selected_lines = all_lines[:count]
        print(f"---{file_path}---")
        print(''.join(selected_lines))

def process_files(directory, patterns, line_count, reverse=False):
    for current_dir, subdirs, filenames in os.walk(directory):
        for filename in filenames:
            if any(pattern in filename for pattern in patterns):
                full_path = os.path.join(current_dir, filename)
                show_content(full_path, line_count, reverse)

if __name__ == "__main__":
