# Modified version of the original code with renamed variables and restructured logic
from typing import List, Dict, Any, Optional


class CustomIterator:
    def __init__(self, items):
        self.items = items
        self.position = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self.position == len(self.items):
            raise StopIteration
        else:
            value = self.items[self.position]
            self.position += 1
            return value


class TableData:
    def __init__(self, records: Optional[Dict[str, List[Any]]] = None, field_names: Optional[List[str]] = None):
        if not records and not field_names:
            self.records = {}
            self.field_names = []
        elif field_names:
            self.field_names = field_names
            self.records = {field: CustomIterator([]) for field in field_names}
        else:
            raise ValueError("Field names must be provided when data is present")
        if records:
            for field, values in records.items():
                if field not in self.field_names:
                    self.field_names.append(field)
                self.records[field].items = values
        self.row_map = {}

    def define_row_index(self, key_field: str):
        if key_field in self.records.keys():
            col_data = self.records.pop(key_field)
            self.row_map = {name: idx for idx, name in enumerate(col_data)}

    def __setitem__(self, field_name: str, new_values: List[Any]):
        if field_name not in self.field_names:
            self.field_names.append(field_name)
            self.records[field_name] = CustomIterator([])
        self.records[field_name].items = new_values

    def __getitem__(self, field_name: str) -> CustomIterator:
        return self.records[field_name]

    def locate_row(self, row_key: str) -> Dict[str, Any]:
        pos = self.row_map[row_key]
        return {field: self.records[field][pos] for field in self.field_names}

    def get_columns(self):
        return self.records.items()

    def get_rows(self):
        for name, pos in self.row_map.items():
            row_data = self.locate_row(name)
            yield name, row_data

    def convert_type(self, target_type: type, field_name: Optional[str] = None):
        if field_name:
            self.records[field_name] = CustomIterator([target_type(x) for x in self.records[field_name]])
        else:
            for field in self.field_names:
                self.records[field] = CustomIterator([target_type(x) for x in self.records[field]])

    def remove_column(self, field_name: str):
        if field_name in self.field_names:
            self.field_names.remove(field_name)
            self.records.pop(field_name)

    def average(self) -> Dict[str, float]:
        output = {}
        for field in self.field_names:
            total_sum = sum(self.records[field])
            avg_value = total_sum / len(self.records[field])
            output[field] = avg_value
        return output

    def __str__(self):
        layout = [self.field_names]
        for row in zip(*self.records.values()):
            layout.append(list(row))
        return "\n".join(["\t".join([str(item) for item in row]) for row in layout])


