# Implementation of a doubly linked list data structure
class ListNode:
    def __init__(self, item):
        self.item = item
        self.forward = None
        self.backward = None

class DoublyList:
    def __init__(self):
        self.start = None
        self.end = None
        self.length = 0

    def is_empty(self):
        return self.length == 0

    def insert_head(self, item):
        new_node = ListNode(item)
        if self.is_empty():
            self.start = self.end = new_node
        else:
            new_node.forward = self.start
            self.start.backward = new_node
            self.start = new_node
        self.length += 1

    def insert_tail(self, item):
        new_node = ListNode(item)
        if self.is_empty():
            self.start = self.end = new_node
        else:
            new_node.backward = self.end
            self.end.forward = new_node
            self.end = new_node
        self.length += 1

    def insert_at(self, position, item):
        if position < 0 or position > self.length:
            raise IndexError("Position out of bounds")
        if position == 0:
            self.insert_head(item)
        elif position == self.length:
            self.insert_tail(item)
        else:
            new_node = ListNode(item)
            current = self.start
            for _ in range(position - 1):
                current = current.forward
            new_node.forward = current.forward
            new_node.backward = current
            current.forward.backward = new_node
            current.forward = new_node
            self.length += 1

    def delete_head(self):
        if self.is_empty():
            raise IndexError("List is empty")
        value = self.start.item
        if self.start == self.end:
            self.start = self.end = None
        else:
            self.start = self.start.forward
            self.start.backward = None
        self.length -= 1
        return value

    def delete_tail(self):
        if self.is_empty():
            raise IndexError("List is empty")
        value = self.end.item
        if self.start == self.end:
            self.start = self.end = None
        else:
            self.end = self.end.backward
            self.end.forward = None
        self.length -= 1
        return value

    def delete_at(self, position):
        if position < 0 or position >= self.length:
            raise IndexError("Position out of bounds")
        if position == 0:
            return self.delete_head()
        if position == self.length - 1:
            return self.delete_tail()
        current = self.start
        for _ in range(position):
            current = current.forward
        value = current.item
        current.backward.forward = current.forward
        current.forward.backward = current.backward
        self.length -= 1
        return value

    def to_array(self):
        output = []
        current = self.start
        while current:
            output.append(current.item)
            current = current.forward
        return output

def validate_doubly_linked_list():
    dll = DoublyList()

    # Test insertion operations
    dll.insert_head(5)
    dll.insert_tail(7)
    dll.insert_at(1, 6)
    assert dll.to_array() == [5, 6, 7], "Insertion tests failed"

    # Test deletion operations
    dll.delete_head()
    dll.delete_tail()
    dll.delete_at(0)
    assert dll.to_array() == [], "Deletion tests failed"

    # Test error handling
    try:
        dll.insert_at(-1, 10)
        assert False, "Inserting at negative position should raise an error"
    except IndexError:
        pass

    try:
        dll.insert_at(1, 10)
        assert False, "Inserting at invalid position should raise an error"
    except IndexError:
        pass

    try:
        dll.delete_at(-1)
        assert False, "Deleting at negative position should raise an error"
    except IndexError:
        pass

    try:
        dll.delete_at(0)
        assert False, "Deleting from empty list should raise an error"
    except IndexError:
        pass

    print("All validation checks passed!")

