validate_doubly_linked_list()

# Import required modules for timing and mathematical operations
import time
import math

def factorial_iterative_version(n):
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers")
    product = 1
    for j in range(2, n + 1):
        product *= j
    return product

def factorial_recursive_version(n):
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers")
    if n == 0 or n == 1:
        return 1
    return n * factorial_recursive_version(n - 1)

def calculate_execution_time(function, value):
    begin = time.time()
    output = function(value)
    finish = time.time()
    return output, finish - begin

def run_program():
    n = int(input("Enter a non-negative integer: "))

    # Calculate factorial using iterative approach
    iterative_result, iterative_duration = calculate_execution_time(factorial_iterative_version, n)

    # Calculate factorial using recursive approach
    recursive_result, recursive_duration = calculate_execution_time(factorial_recursive_version, n)

    print(f"Factorial of {n} (Iterative): {iterative_result}")
    print(f"Time taken (Iterative): {iterative_duration:.6f} seconds")

    print(f"Factorial of {n} (Recursive): {recursive_result}")
    print(f"Time taken (Recursive): {recursive_duration:.6f} seconds")

    if iterative_result == recursive_result:
        print("Both methods produced the same result.")
    else:
        print("The methods produced different results.")

if __name__ == "__main__":
    run_program()

# Convert XML data to JSON format 
import xml.etree.ElementTree as ET
import json

def convert_xml_to_dictionary(xml_element):
    """Recursively transforms an XML element into a dictionary structure."""
    element_data = {xml_element.tag: {} if xml_element.attrib else None}
    sub_elements = list(xml_element)

    if sub_elements:
        intermediate_dict = {}
        for child_result in map(convert_xml_to_dictionary, sub_elements):
            for key, value in child_result.items():
                try:
                    intermediate_dict[key].append(value)
                except KeyError:
                    intermediate_dict[key] = [value]
        element_data = {xml_element.tag: {k: v[0] if len(v) == 1 else v for k, v in intermediate_dict.items()}}

    if xml_element.attrib:
        element_data[xml_element.tag].update((attr_key, attr_value) for attr_key, attr_value in xml_element.attrib.items())

    if xml_element.text:
        cleaned_text = xml_element.text.strip()
        if sub_elements or xml_element.attrib:
            if cleaned_text:
                element_data[xml_element.tag]['#text'] = cleaned_text
        else:
            element_data[xml_element.tag] = cleaned_text
    return element_data

def transform_xml_to_json(xml_content):
    """Processes an XML string and returns its JSON representation."""
    tree_root = ET.fromstring(xml_content)
    dictionary_form = convert_xml_to_dictionary(tree_root)
    json_result = json.dumps(dictionary_form, indent=4)
    return json_result

