import csv
from sympy import isprime

def locate_primes(limit):
    """Locate all prime numbers less than or equal to the given limit."""
    return [num for num in range(2, limit + 1) if isprime(num)]

def decimal_to_binary(value):
    """Transform a number into its binary string representation."""
    return bin(value)[2:]

def produce_table(prime_list, mode='decimal'):
    """Produce the multiplication table for the provided list of primes in the chosen format."""
    if mode not in ['decimal', 'binary']:
        raise ValueError("Mode must be either 'decimal' or 'binary'")

    grid = []
    title_row = [''] + [str(p) if mode == 'decimal' else decimal_to_binary(p) for p in prime_list]
    grid.append(title_row)

    for prime in prime_list:
        current_row = [str(prime) if mode == 'decimal' else decimal_to_binary(prime)]
        for secondary_prime in prime_list:
            result = prime * secondary_prime
            current_row.append(str(result) if mode == 'decimal' else decimal_to_binary(result))
        grid.append(current_row)

    return grid

def export_to_csv(filepath, grids, mode='decimal'):
    """Export the multiplication grids to a CSV file."""
    with open(filepath, 'w', newline='') as file:
        writer = csv.writer(file)
        for grid in grids:
            for line in grid:
                writer.writerow(line)
            writer.writerow([])  # Insert a blank row between grids

def run():
    # Sample parameters
    inputs = [5, 7]  # Extend this list with additional values as needed
    modes = ['decimal', 'binary']

    all_grids = []
    for value in inputs:
        primes = locate_primes(value)
        for mode in modes:
            grid = produce_table(primes, mode)
            all_grids.append(grid)

    export_to_csv("prime_multiplication_tables.csv", all_grids)

if __name__ == "__main__":
