# Filter out non-even elements from a nested structure
def filter_even_values(data):
    def check_even_string(val):
        """Determine if a string corresponds to an even number."""
        try:
            value = float(val)
            return value.is_integer() and value % 2 == 0
        except ValueError:
            return False

    def transform_item(item):
        """Convert lists and dictionaries into tuples for uniform processing."""
        if isinstance(item, list) or isinstance(item, dict):
            return tuple(item)
        return item

    def keep_item(item):
        """Decide whether to retain an item based on its type and evenness."""
        if isinstance(item, int) and item % 2 == 0:
            return True
        elif isinstance(item, float) and item.is_integer() and item % 2 == 0:
            return True
        elif isinstance(item, str) and check_even_string(item):
            return True
        elif isinstance(item, tuple):
            return True
        return False

    def traverse_structure(data):
        """Apply filtering recursively to all nested tuples."""
        output = ()
        for obj in data:
            transformed_obj = transform_item(obj)
            if isinstance(transformed_obj, tuple):
                output += (traverse_structure(transformed_obj),)
            elif keep_item(transformed_obj):
                output += (transformed_obj,)
        return output

    return traverse_structure(data)

