# Modified version of the expression tree evaluator
from abc import ABC, abstractmethod
from typing import List

class TreeNode(ABC):
    @abstractmethod
    def compute(self) -> int:
        pass

    @abstractmethod
    def display(self) -> str:
        pass

class ValueNode(TreeNode):
    def __init__(self, number: int):
        self.number = number

    def compute(self) -> int:
        return self.number

    def display(self) -> str:
        return str(self.number)

class OperationNode(TreeNode):
    def __init__(self, op: str, lhs: TreeNode, rhs: TreeNode):
        self.op = op
        self.lhs = lhs
        self.rhs = rhs

    def compute(self) -> int:
        if self.op == '+':
            return self.lhs.compute() + self.rhs.compute()
        elif self.op == '-':
            return self.lhs.compute() - self.rhs.compute()
        elif self.op == '*':
            return self.lhs.compute() * self.rhs.compute()
        elif self.op == '/':
            return self.lhs.compute() // self.rhs.compute()

    def display(self) -> str:
        left_part = self.lhs.display()
        right_part = self.rhs.display()
        return f"({left_part} {self.op} {right_part})"

def construct_tree(postfix_expr: List[str]) -> TreeNode:
    stack = []
    for item in postfix_expr:
        if item.isdigit():
            stack.append(ValueNode(int(item)))
        else:
            right_operand = stack.pop()
            left_operand = stack.pop()
            stack.append(OperationNode(item, left_operand, right_operand))
    return stack[0]

def process_expression(postfix_expr: List[str]) -> (int, str):
    expr_tree = construct_tree(postfix_expr)
    computed_value = expr_tree.compute()
    formatted_expr = expr_tree.display()
    return computed_value, formatted_expr

