# Find the shortest unique substring across a list of strings
def minimal_distinct_substring(word_list):
    def construct_suffix_array(text):
        length = len(text)
        suffix_pairs = [(text[i:], i) for i in range(length)]
        suffix_pairs.sort()
        return [pos for _, pos in suffix_pairs]

    def contains_elsewhere(part, collection, skip_index):
        for idx, word in enumerate(collection):
            if idx == skip_index:
                continue
            if part in word:
                return False
        return True

    def locate_minimal_unique_segment(text, collection, skip_index):
        n = len(text)
        suffix_order = construct_suffix_array(text)
        for size in range(1, n + 1):
            frequency_map = {}
            for start_pos in suffix_order:
                end_pos = start_pos + size
                if end_pos > n:
                    break
                segment = text[start_pos:end_pos]
                frequency_map[segment] = frequency_map.get(segment, 0) + 1
            for segment, occurrences in frequency_map.items():
                if occurrences == 1 and contains_elsewhere(segment, collection, skip_index):
                    return segment
        return None

    best_match = None
    for index, word in enumerate(word_list):
        if not word.strip():
            continue
        candidate = locate_minimal_unique_segment(word, word_list, index)
        if candidate and (best_match is None or len(candidate) < len(best_match)):
            best_match = candidate

    if best_match:
        return best_match
    else:
        return "No distinct sub-string detected"

