# Convert RGB to HSV color space
def rgb_to_hsv(red, green, blue):
    if not (0 <= red <= 255 and 0 <= green <= 255 and 0 <= blue <= 255):
        raise ValueError("RGB values must be in the range 0 to 255.")

    r_norm, g_norm, b_norm = red / 255.0, green / 255.0, blue / 255.0
    max_val = max(r_norm, g_norm, b_norm)
    min_val = min(r_norm, g_norm, b_norm)
    diff = max_val - min_val

    if diff == 0:
        hue = 0
    elif max_val == r_norm:
        hue = ((g_norm - b_norm) / diff) % 6
    elif max_val == g_norm:
        hue = (b_norm - r_norm) / diff + 2
    else:
        hue = (r_norm - g_norm) / diff + 4

    hue = (hue * 60) + (hue < 0) * 360
    saturation = 0 if max_val == 0 else diff / max_val
    value = max_val

    return hue, saturation, value

# Convert HSV to RGB color space
def hsv_to_rgb(hue, saturation, value):
    if not (0 <= hue <= 360 and 0 <= saturation <= 1 and 0 <= value <= 1):
        raise ValueError("HSV values must be h in the range 0 to 360, s and v in the range 0 to 1.")

    chroma = value * saturation
    second_component = chroma * (1 - abs((hue / 60) % 2 - 1))
    adjustment = value - chroma

    if hue < 60:
        red, green, blue = chroma, second_component, 0
    elif hue < 120:
        red, green, blue = second_component, chroma, 0
    elif hue < 180:
        red, green, blue = 0, chroma, second_component
    elif hue < 240:
        red, green, blue = 0, second_component, chroma
    elif hue < 300:
        red, green, blue = second_component, 0, chroma
    else:
        red, green, blue = chroma, 0, second_component

    red, green, blue = (red + adjustment) * 255, (green + adjustment) * 255, (blue + adjustment) * 255
    return int(red), int(green), int(blue)

