# Authentication system using FastAPI and JWT
from fastapi import FastAPI, Depends, HTTPException, status
from fastapi.security import OAuth2PasswordBearer
from pydantic import BaseModel
from jose import JWTError, jwt
from passlib.context import CryptContext
from datetime import datetime, timedelta
from typing import Optional

# Initialize FastAPI application
api = FastAPI()

# User credentials storage
credentials = {"Alice": "123456", "Bob": "789012"}

# Configuration for JWT
SECRET = "my_secret_key"
SIGN_METHOD = "HS256"
TOKEN_VALIDITY_MINUTES = 30

# Password hashing configuration
hashing_context = CryptContext(schemes=["bcrypt"], deprecated="auto")

# OAuth2 scheme setup
oauth2_scheme = OAuth2PasswordBearer(tokenUrl="auth/token")

# Data models
class AccessToken(BaseModel):
    token: str
    type: str

class TokenPayload(BaseModel):
    user: Optional[str] = None

class Credentials(BaseModel):
    username: str
    password: str

# Helper functions
def check_password(plain_text, hashed):
    return hashing_context.verify(plain_text, hashed)

def hash_user_password(password):
    return hashing_context.hash(password)

def fetch_user(username: str):
    if username in credentials:
        return Credentials(username=username, password=credentials[username])
    return None

def login_user(username: str, password: str):
    user = fetch_user(username)
    if not user:
        return None
    if not check_password(password, user.password):
        return None
    return user

def generate_token(data: dict, expiry: Optional[timedelta] = None):
    payload = data.copy()
    if expiry:
        expiration = datetime.utcnow() + expiry
    else:
        expiration = datetime.utcnow() + timedelta(minutes=15)
    payload.update({"exp": expiration})
    token = jwt.encode(payload, SECRET, algorithm=SIGN_METHOD)
    return token

async def current_user(token: str = Depends(oauth2_scheme)):
    auth_error = HTTPException(
        status_code=status.HTTP_401_UNAUTHORIZED,
        detail="Authentication failed",
        headers={"WWW-Authenticate": "Bearer"},
    )
    try:
        decoded = jwt.decode(token, SECRET, algorithms=[SIGN_METHOD])
        username: str = decoded.get("sub")
        if username is None:
            raise auth_error
        payload_data = TokenPayload(user=username)
    except JWTError:
        raise auth_error
    user = fetch_user(username=payload_data.user)
    if user is None:
        raise auth_error
    return user

# API endpoints
@api.post("/auth/token", response_model=AccessToken)
async def obtain_access_token(user: Credentials):
    authenticated = login_user(user.username, user.password)
    if not authenticated:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Invalid login credentials",
            headers={"WWW-Authenticate": "Bearer"},
        )
    token_duration = timedelta(minutes=TOKEN_VALIDITY_MINUTES)
    access_token = generate_token(
        data={"sub": authenticated.username}, expiry=token_duration
    )
    return {"token": access_token, "type": "bearer"}

@api.get("/profile", response_model=Credentials)
async def get_profile(current: Credentials = Depends(current_user)):
    return current

