# Import required modules for hashing and time management
import hashlib
import time
from datetime import datetime, timedelta

# Simulated user database with hashed passwords and lockout tracking
user_database = {
    'alice': {
        'password_hash': hashlib.sha256('my_secret_pass'.encode()).hexdigest(),
        'failed_attempts': 0,
        'last_failed_time': None
    },
    'bob': {
        'password_hash': hashlib.sha256('another_strong_password'.encode()).hexdigest(),
        'failed_attempts': 0,
        'last_failed_time': None
    }
}

# Security settings
MAX_ATTEMPTS_BEFORE_LOCKOUT = 3
ACCOUNT_LOCK_TIME = timedelta(minutes=5)

def compute_sha256(password):
    return hashlib.sha256(password.encode()).hexdigest()

def check_lock_status(username):
    account_info = user_database.get(username)
    if not account_info:
        return False
    if account_info['failed_attempts'] >= MAX_ATTEMPTS_BEFORE_LOCKOUT:
        last_attempt = account_info['last_failed_time']
        if last_attempt and datetime.now() - last_attempt < ACCOUNT_LOCK_TIME:
            return True
    return False

def authenticate_user(username, password):
    if check_lock_status(username):
        print(f"Account '{username}' is currently locked. Try again later.")
        return False

    account = user_database.get(username)
    if not account:
        print("User does not exist.")
        return False

    if compute_sha256(password) == account['password_hash']:
        account['failed_attempts'] = 0
        account['last_failed_time'] = None
        print(f"Authentication successful for '{username}'.")
        return True
    else:
        account['failed_attempts'] += 1
        account['last_failed_time'] = datetime.now()
        remaining = MAX_ATTEMPTS_BEFORE_LOCKOUT - account['failed_attempts']
        print(f"Authentication failed for '{username}'. {remaining} attempts left.")
        return False

