# Process tagged text data and evaluate performance 
def load_tagged_data(file_location):
    """Loads a tagged file and returns a list of sentences, each containing (token, label) pairs."""
    data = []
    with open(file_location, 'r', encoding='utf-8') as f:
        for row in f:
            if row.strip():  # Ignore blank lines
                tokens = []
                segments = row.strip().split()
                for segment in segments:
                    token, label = segment.rsplit('/', 1)  # Split on last '/' to separate token and label
                    tokens.append((token, label))
                data.append(tokens)
    return data

def compute_evaluation_scores(reference_data, predicted_data):
    """Computes precision and recall per label."""
    label_stats = {}

    for sent_ref, sent_pred in zip(reference_data, predicted_data):
        for (tok_ref, lbl_ref), (tok_pred, lbl_pred) in zip(sent_ref, sent_pred):
            if tok_ref != tok_pred:
                raise ValueError(f"Token mismatch: {tok_ref} != {tok_pred}")

            if lbl_ref not in label_stats:
                label_stats[lbl_ref] = {'TP': 0, 'FP': 0, 'FN': 0}

            if lbl_pred not in label_stats:
                label_stats[lbl_pred] = {'TP': 0, 'FP': 0, 'FN': 0}

            if lbl_ref == lbl_pred:
                label_stats[lbl_ref]['TP'] += 1
            else:
                label_stats[lbl_ref]['FN'] += 1
                label_stats[lbl_pred]['FP'] += 1

    # Derive precision and recall for each label
    for label, stats in label_stats.items():
        TP = stats['TP']
        FP = stats['FP']
        FN = stats['FN']

        precision = TP / (TP + FP) if (TP + FP) > 0 else 0
        recall = TP / (TP + FN) if (TP + FN) > 0 else 0

        label_stats[label]['precision'] = precision
        label_stats[label]['recall'] = recall

    return label_stats

# Example usage
reference_file = 'path/to/reference_corpus.txt'
predicted_file = 'path/to/predicted_corpus.txt'

reference_set = load_tagged_data(reference_file)
predicted_set = load_tagged_data(predicted_file)

evaluation_results = compute_evaluation_scores(reference_set, predicted_set)

# Display outcomes
for label, stats in evaluation_results.items():
    print(f"Label: {label}")
    print(f"  Precision: {stats['precision']:.4f}")
    print(f"  Recall: {stats['recall']:.4f}")

# Modified version of the Algorithm Visualizer with renamed variables and reordered logic
import ast
import graphviz as gv

class CodeFlowGrapher:
    def __init__(self, source_code):
        self.source_code = source_code
        self.ast_root = None
        self.graph = gv.Digraph(comment='Code Execution Structure')

    def analyze_code(self):
        try:
            self.ast_root = ast.parse(self.source_code)
        except SyntaxError as error:
            print(f"Syntax issue detected: {error}")
            return False
        return True

    def generate_flow_chart(self):
        if self.ast_root is None:
            print("No abstract syntax tree available for visualization.")
            return

        self._explore_ast_nodes(self.ast_root.body, "Entry Point")

        # Save and display the generated diagram
        self.graph.render('code_execution_structure', view=True)

    def _explore_ast_nodes(self, node_list, predecessor_label):
        for current_node in node_list:
            node_identifier = repr(current_node)
            self.graph.node(node_identifier, node_identifier)
            self.graph.edge(predecessor_label, node_identifier)

            if isinstance(current_node, ast.FunctionDef):
                self._explore_ast_nodes(current_node.body, node_identifier)
            elif isinstance(current_node, (ast.For, ast.While)):
                self._explore_ast_nodes(current_node.body, node_identifier)
            elif isinstance(current_node, ast.If):
                self._explore_ast_nodes(current_node.body, node_identifier)
                if current_node.orelse:
                    self._explore_ast_nodes(current_node.orelse, node_identifier + "_alternative")

