# Calculate prime numbers and their products from multiple lists
from math import isqrt
from functools import reduce
from operator import mul

def check_prime(num):
    """Determine whether a number is prime."""
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    for divisor in range(5, isqrt(num) + 1, 6):
        if num % divisor == 0 or num % (divisor + 2) == 0:
            return False
    return True

def extract_primes_and_products(data_sets):
    output = []

    for dataset in data_sets:
        primes_list = []
        try:
            for value in dataset:
                if isinstance(value, int):
                    if check_prime(value):
                        primes_list.append(value)
                else:
                    raise ValueError(f"Non-integer value encountered: {value}")
        except Exception as error:
            print(f"Exception while processing list: {error}")
            continue

        primes_list.sort()
        prime_product = reduce(mul, primes_list, 1) if primes_list else 1
        output.append((primes_list, prime_product))

    return output

