app.config['RESULT_DIR'] = 'outputs/'
app.config['VALID_EXTENSIONS'] = {'mp4', 'avi', 'mov'}

def is_valid_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in app.config['VALID_EXTENSIONS']

def frame_to_ascii_image(frame, mapping_chars, reduction_factor):
    gray_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    resized_frame = cv2.resize(gray_frame, (int(gray_frame.shape[1] // reduction_factor), int(gray_frame.shape[0] // reduction_factor)), interpolation=cv2.INTER_AREA)

    ascii_art = ''
    for line in resized_frame:
        for brightness_value in line:
            ascii_art += mapping_chars[int(brightness_value // (256 / len(mapping_chars)))]
        ascii_art += '\n'

    return ascii_art

@app.route('/', methods=['GET', 'POST'])
def home():
    if request.method == 'POST':
        uploaded_file = request.files.get('video_file')
        char_set = request.form.get('characters') or '@%#*+=-:. '
        resize_scale = float(request.form.get('resolution') or 2.5)

        if uploaded_file and is_valid_file(uploaded_file.filename):
            input_video_path = os.path.join(app.config['UPLOAD_DIR'], uploaded_file.filename)
            output_text_path = os.path.join(app.config['RESULT_DIR'], f"{uploaded_file.filename.rsplit('.', 1)[0]}_ascii_output.txt")

            uploaded_file.save(input_video_path)

            video_clip = VideoFileClip(input_video_path)
            frames_per_second = video_clip.fps

            video_capture = cv2.VideoCapture(input_video_path)

            with open(output_text_path, 'w') as result_file:
                current_frame_index = 1
                while video_capture.isOpened():
                    success, image_frame = video_capture.read()
                    if success:
                        if current_frame_index % (round(frames_per_second) // 2) == 0:
                            ascii_representation = frame_to_ascii_image(image_frame, char_set, resize_scale)
                            result_file.write(ascii_representation)
                            result_file.write('\n')
                        current_frame_index += 1
                    else:
                        break

            video_capture.release()
            return redirect(url_for('serve_result', filename=f"{uploaded_file.filename.rsplit('.', 1)[0]}_ascii_output.txt"))

    return render_template('upload.html')

