class PostInstallTask(Command):
    description = "Execute tasks after installation"
    user_options = []

    def initialize_options(self):
        pass

    def finalize_options(self):
        pass

    def execute(self):
        if not self.dry_run:
            from subprocess import call
            interpreter_path = sys.executable
            target_dir = self.distribution.get_command_obj('install_lib').install_dir
            target_file = f"{target_dir}/my_package/my_script.py"
            call([interpreter_path, target_file])

