# In-memory storage for the To-Do items
todo_items = []

def create_todo_item(title):
    todo_items.append({"id": len(todo_items) + 1, "title": title, "completed": False})
    return {"id": len(todo_items), "title": title, "completed": False}

def retrieve_all_todos():
    return todo_items

def fetch_todo_by_id(todo_id):
    for item in todo_items:
        if item["id"] == todo_id:
            return item
    return None

def modify_todo(todo_id, title=None, completed=None):
    for item in todo_items:
        if item["id"] == todo_id:
            if title is not None:
                item["title"] = title
            if completed is not None:
                item["completed"] = completed
            return item
    return None

def remove_todo(todo_id):
    global todo_items
    todo_items = [item for item in todo_items if item["id"] != todo_id]
    return True

@app.route('/jsonrpc', methods=['POST'])
def handle_jsonrpc():
    try:
        payload = request.json
        operation = payload['method']
        arguments = payload.get('params', [])
        request_id = payload['id']

        if operation == 'addTodo':
            outcome = create_todo_item(*arguments)
        elif operation == 'getTodos':
            outcome = retrieve_all_todos()
        elif operation == 'getTodo':
            outcome = fetch_todo_by_id(*arguments)
        elif operation == 'updateTodo':
            outcome = modify_todo(*arguments)
