# A basic sentiment classification system 
class BasicEmotionClassifier:
    def __init__(self):
        self.positive_terms = {"good", "great", "excellent", "amazing", "wonderful", "fantastic", "love", "happy", "best", "enjoy"}
        self.negative_terms = {"bad", "terrible", "awful", "horrible", "poor", "disappointing", "hate", "sad", "worst", "annoying"}

    def determine_sentiment(self, text):
        tokens = text.lower().split()
        pos_score = sum(1 for token in tokens if token in self.positive_terms)
        neg_score = sum(1 for token in tokens if token in self.negative_terms)

        if pos_score > neg_score:
            return "Positive"
        elif neg_score > pos_score:
            return "Negative"
        else:
            return "Neutral"

