# Scrapy spider to scrape article data from a website
import scrapy

class ArticleSpider(scrapy.Spider):
    name = 'articles_spider'
    allowed_domains = ['articlesite.com']
    start_urls = ['https://articlesite.com/newest-posts']

    def parse(self, response):
        # Get all article elements from the page
        items = response.css('div.post-container > div.post-item')

        for item in items:
            yield {
                'headline': item.css('h3.headline::text').get(),
                'link': item.css('a::attr(href)').get(),
                'timestamp': item.css('time.pub-date::text').get(),
            }

        # Navigate to the next page if available
        next_link = response.css('a.pagination-next::attr(href)').get()
        if next_link:
            yield response.follow(next_link, callback=self.parse)

# Find the longest common substring appearing at least k times
from typing import List, Optional

def longest_shared_substring(texts: List[str], threshold: int) -> Optional[str]:
    if not texts or threshold <= 0:
        return None

    # Helper function to generate all substrings of a string
    def extract_substrings(word: str) -> List[str]:
        length = len(word)
        return [word[i:l] for i in range(length) for l in range(i + 1, length + 1)]

    # Dictionary to track how many times each substring appears
    frequency_map = {}

    # Process each string and count substring occurrences
    for word in texts:
        substrings = extract_substrings(word)
        for fragment in substrings:
            if fragment in frequency_map:
                frequency_map[fragment] += 1
            else:
                frequency_map[fragment] = 1

    # Identify the longest substring meeting the frequency requirement
    best_substring = None
    highest_length = -1

    for fragment, occurrences in frequency_map.items():
        if occurrences >= threshold and len(fragment) > highest_length:
            best_substring = fragment
            highest_length = len(fragment)

    return best_substring

