# Process JSON data with validation and modification
import json

def decode_json(json_data):
    try:
        return json.loads(json_data)
    except json.JSONDecodeError as err:
        raise ValueError(f"Malformed JSON: {err}")

def ensure_dict_structure(data_obj):
    if not isinstance(data_obj, dict):
        raise ValueError("Expected a JSON object (dictionary)")

def verify_required_fields(data_obj, needed_keys):
    for field in needed_keys:
        if field not in data_obj:
            raise KeyError(f"Required field '{field}' is absent")

def compute_and_assign(data_obj, dest_field, src1, src2):
    try:
        data_obj[dest_field] = data_obj[src1] + data_obj[src2]
    except TypeError:
        raise ValueError(f"Fields '{src1}' and '{src2}' must contain numeric values")

def handle_json_data(json_input, destination, source_a, source_b):
    try:
        parsed_data = decode_json(json_input)
        ensure_dict_structure(parsed_data)
        verify_required_fields(parsed_data, [destination, source_a, source_b])
        compute_and_assign(parsed_data, destination, source_a, source_b)
        return json.dumps(parsed_data, indent=2)
    except (ValueError, KeyError) as issue:
        return str(issue)

