# Modified version with Type I clone transformations
import re
import random
from typing import Tuple

# Simulated user's previous banking history
MIN_LIMIT = 1000
MAX_LIMIT = 100000

# List of common dictionary words (for simplicity, using a small list)
DICTIONARY_TERMS = ["password", "123456", "qwerty", "letmein", "admin"]

def is_secure_password(password: str) -> bool:
    """Check if the password meets security requirements."""
    if len(password) < 10:
        return False
    if not re.search(r"[a-z]", password):
        return False
    if not re.search(r"[A-Z]", password):
        return False
    if not re.search(r"\d", password):
        return False
    if not re.search(r"[!@#$%^&*(),.?\":{}|<>]", password):
        return False
    return True

def are_credentials_similar(username: str, password: str) -> bool:
    """Check if the username and password share too many similarities."""
    return username.lower() in password.lower() or password.lower() in username.lower()

def has_common_term(password: str) -> bool:
    """Check if the password contains common insecure terms."""
    return any(term in password.lower() for term in DICTIONARY_TERMS)

def is_balance_valid(amount: float) -> bool:
    """Verify that the account balance falls within acceptable limits."""
    return MIN_LIMIT <= amount <= MAX_LIMIT

class BankAccount:
    def __init__(self, user_name: str, pass_code: str, initial_amount: float):
        self.user_name = user_name
        self.pass_code = pass_code
        self.initial_amount = initial_amount

    def __str__(self):
        return f"Account for {self.user_name} created with a balance of ${self.initial_amount:.2f}"

def establish_bank_account() -> Tuple[bool, str]:
    """Function to establish a new bank account after validating all inputs."""
    user_name = input("Enter a unique username: ")
    pass_code = input("Enter a strong password: ")
    initial_amount = float(input("Enter your desired account balance: "))

    if not is_secure_password(pass_code):
        return False, "Password does not meet security requirements. It must be at least 10 characters long and include uppercase, lowercase, numbers, and special characters."

    if are_credentials_similar(user_name, pass_code):
        return False, "Username and password are too similar."

    if has_common_term(pass_code):
        return False, "Password contains common words or patterns."

    if not is_balance_valid(initial_amount):
        return False, f"Balance must be between ${MIN_LIMIT} and ${MAX_LIMIT}."

    account = BankAccount(user_name, pass_code, initial_amount)
    return True, str(account)

# Example usage
success, message = establish_bank_account()
if success:
    print(message)
else:
    print("Failed to create account:", message)

# Compute average of a numeric list recursively 
def compute_average(values, pos=0, accum=0):
    if pos == len(values):
        return accum / len(values)
    return compute_average(values, pos + 1, accum + values[pos])

def compute_standard_deviation(values, avg, pos=0, sq_diff_total=0):
    if pos == len(values):
        return (sq_diff_total / len(values)) ** 0.5
    return compute_standard_deviation(values, avg, pos + 1, sq_diff_total + (values[pos] - avg) ** 2)

def scale_array(values, avg=None, std=None, pos=0):
    if not isinstance(values, list) or not all(isinstance(val, (int, float)) for val in values):
        raise TypeError("Input must be a list of numbers")

    if avg is None:
        avg = compute_average(values)
    if std is None:
        std = compute_standard_deviation(values, avg)

    if pos == len(values):
        return [(val - avg) / std for val in values]

    scaled_list = scale_array(values, avg, std, pos + 1)
    scaled_list[pos] = (values[pos] - avg) / std
    return scaled_list

def reverse_scale_array(scaled_list, original_values, avg=None, std=None, pos=0):
    if not isinstance(scaled_list, list) or not all(isinstance(val, (int, float)) for val in scaled_list):
        raise TypeError("Input must be a list of numbers")

    if avg is None:
        avg = compute_average(original_values)
    if std is None:
        std = compute_standard_deviation(original_values, avg)

    if pos == len(scaled_list):
        return [val * std + avg for val in scaled_list]

    unscaled_list = reverse_scale_array(scaled_list, original_values, avg, std, pos + 1)
    unscaled_list[pos] = scaled_list[pos] * std + avg
    return unscaled_list

# Demonstration
data = [4, 8, 15, 23, 42]

try:
    scaled_data = scale_array(data)
    print("Scaled Data:", scaled_data)

    unscaled_data = reverse_scale_array(scaled_data, data)
    print("Unscaled Data:", unscaled_data)
except TypeError as err:
    print(err)

# Module for parsing and converting date/time strings to ISO 8601 format
import re
from datetime import datetime, timedelta
import pytz

class DateTimeConverter:
    def __init__(self, date_input, time_input, tz_input):
        self.date_input = date_input
        self.time_input = time_input
        self.tz_input = tz_input
        self.date_obj = None
        self.time_obj = None
        self.tz_obj = None

    def extract_date(self):
        date_formats = [
            r'(\d{4})-(\d{2})-(\d{2})',  # YYYY-MM-DD
            r'(\d{2})/(\d{2})/(\d{4})',  # MM/DD/YYYY
            r'(\d{4})/(\d{2})/(\d{2})'   # YYYY/MM/DD
        ]
        for regex in date_formats:
            result = re.match(regex, self.date_input)
            if result:
                y, m, d = result.groups()
                self.date_obj = datetime(int(y), int(m), int(d))
                return True
        return False

    def extract_time(self):
        time_formats = [
            r'(\d{2}):(\d{2})',           # HH:MM
            r'(\d{2}):(\d{2}):(\d{2})'    # HH:MM:SS
        ]
        for pattern in time_formats:
            match = re.match(pattern, self.time_input)
            if match:
                groups = match.groups()
                h, min_val = groups[0], groups[1]
                sec_val = groups[2] if len(groups) == 3 else '00'
                self.time_obj = datetime(1, 1, 1, int(h), int(min_val), int(sec_val))
                return True
        return False

    def extract_timezone(self):
        try:
            upper_tz = self.tz_input.upper()
            if upper_tz in pytz.all_timezones:
                self.tz_obj = pytz.timezone(self.tz_input)
            elif re.match(r'UTC[+-]\d{2}:\d{2}', upper_tz):
                hours = int(upper_tz[3:6])
                minutes = int(upper_tz[7:9])
                offset = timedelta(hours=hours, minutes=minutes)
                self.tz_obj = pytz.FixedOffset(offset.total_seconds() / 60)
            else:
                raise ValueError("Invalid timezone specification")
        except Exception:
            return False
        return True

    def check_validity(self):
        if not self.extract_date():
            return "Date string does not match supported formats"
        if not self.extract_time():
            return "Time string does not match supported formats"
        if not self.extract_timezone():
            return "Timezone string is invalid"
        return None

    def generate_iso_string(self):
        combined_dt = datetime.combine(self.date_obj, self.time_obj.time())
        localized_dt = self.tz_obj.localize(combined_dt)
        utc_dt = localized_dt.astimezone(pytz.utc)
        return utc_dt.isoformat()

def transform_to_iso8601(date_str, time_str, tz_str):
    converter = DateTimeConverter(date_str, time_str, tz_str)
    validation_error = converter.check_validity()
    if validation_error:
        return validation_error
    return converter.generate_iso_string()

# Example usage:
date_str = "2023-10-05"
time_str = "14:30"
tz_str = "America/New_York"
print(transform_to_iso8601(date_str, time_str, tz_str))  # Output: 2023-10-05T18:30:00Z

