# Calculate HCF and check divisibility for four numbers
import math

def highest_common_factor(a, b, c, d):
    """Determine the highest common factor of four integers."""
    return math.gcd(math.gcd(a, b), math.gcd(c, d))

def nearest_multiple(value, base):
    """Find the nearest integer to 'value' that is a multiple of 'base'."""
    q = value // base
    r = value % base
    if r < base / 2:
        return q * base
    else:
        return (q + 1) * base

def analyze_numbers(n1, n2, n3, n4, divisor_val):
    try:
        # Compute the HCF of the provided numbers
        hcf_value = highest_common_factor(n1, n2, n3, n4)
        print(f"The Highest Common Factor (HCF) of {n1}, {n2}, {n3}, and {n4} is: {hcf_value}")

        # Analyze each number for divisibility and find nearest multiples if needed
        output_dict = {}
        for val in [n1, n2, n3, n4]:
            if val % divisor_val == 0:
                output_dict[val] = f"{val} is divisible by {divisor_val}"
            else:
                nearest = nearest_multiple(val, divisor_val)
                output_dict[val] = f"{val} is not divisible by {divisor_val}. The closest divisible number is {nearest}"

        for key, msg in output_dict.items():
            print(msg)

    except ZeroDivisionError:
        print("Error: Divisor cannot be zero.")
    except TypeError:
        print("Error: All inputs must be integers.")
    except Exception as err:
        print(f"An unexpected error occurred: {err}")

