# Calculate square roots for a range of numbers with validation
import math
import unittest

def generate_sqrt_mapping(low, high):
    try:
        # Convert inputs to integers if possible
        low = int(low)
        high = int(high)

        # Validate range order
        if low > high:
            raise ValueError("Lower bound must be less than or equal to upper bound.")

        # Build dictionary using comprehension
        return {x: math.sqrt(x) for x in range(low, high + 1)}

    except ValueError as err:
        print(f"Validation error: {err}")
        return {}
    except TypeError:
        print("Error: Inputs must be numeric values.")
        return {}

# Test suite for sqrt mapping function
class TestGenerateSqrtMapping(unittest.TestCase):
    def test_correct_range(self):
        output = generate_sqrt_mapping(1, 25)
        target = {i: math.sqrt(i) for i in range(1, 26)}
        self.assertEqual(output, target)

    def test_reversed_range(self):
        output = generate_sqrt_mapping(25, 1)
        self.assertEqual(output, {})

    def test_string_inputs(self):
        output = generate_sqrt_mapping('x', 25)
        self.assertEqual(output, {})

    def test_decimal_inputs(self):
        output = generate_sqrt_mapping(1.0, 25.0)
        target = {i: math.sqrt(i) for i in range(1, 26)}
        self.assertEqual(output, target)

