# Parse SQL query and extract components
import sqlparse

query = "SELECT d_year, s_nation, p_category, sum(lo_revenue - lo_supplycost) as profit FROM DATES, CUSTOMER, SUPPLIER, PART, LINEORDER WHERE lo_custkey = c_custkey AND lo_suppkey = s_suppkey AND lo_partkey = p_partkey AND lo_orderdate = d_datekey AND c_region = 'AFRICA' AND s_region = 'AFRICA' AND (d_year = 1996 OR d_year = 1997) AND (p_mfgr = 'MFGR#2' OR p_mfgr = 'MFGR#4') GROUP BY d_year, s_nation, p_category ORDER BY d_year, s_nation, p_category"

parsed_query = sqlparse.parse(query)[0]

def get_tables_from_clause(parsed_obj):
    from_found = False
    table_list = []
    for token in parsed_obj.tokens:
        if from_found:
            if token.ttype is sqlparse.tokens.Keyword:
                break
            if isinstance(token, sqlparse.sql.IdentifierList):
                for identifier in token.get_identifiers():
                    table_list.append(identifier.get_name())
            elif isinstance(token, sqlparse.sql.Identifier):
                table_list.append(token.get_name())
        if token.ttype is sqlparse.tokens.Keyword and token.value.upper() == 'FROM':
            from_found = True
    return table_list

def get_where_conditions(parsed_obj):
    where_found = False
    condition_parts = []
    for token in parsed_obj.tokens:
        if where_found:
            condition_parts.append(str(token))
        if token.ttype is sqlparse.tokens.Keyword and token.value.upper() == 'WHERE':
            where_found = True
    return ' '.join(condition_parts)

def get_group_by_columns(parsed_obj):
    group_found = False
    group_cols = []
    for token in parsed_obj.tokens:
        if group_found:
            if token.ttype is sqlparse.tokens.Keyword:
                break
            if isinstance(token, sqlparse.sql.IdentifierList):
                for identifier in token.get_identifiers():
                    group_cols.append(identifier.get_name())
            elif isinstance(token, sqlparse.sql.Identifier):
                group_cols.append(token.get_name())
        if token.ttype is sqlparse.tokens.Keyword and token.value.upper() == 'GROUP BY':
            group_found = True
    return group_cols

def get_order_by_columns(parsed_obj):
    order_found = False
    order_cols = []
    for token in parsed_obj.tokens:
        if order_found:
            if token.ttype is sqlparse.tokens.Keyword:
                break
            if isinstance(token, sqlparse.sql.IdentifierList):
                for identifier in token.get_identifiers():
                    order_cols.append(identifier.get_name())
            elif isinstance(token, sqlparse.sql.Identifier):
                order_cols.append(token.get_name())
        if token.ttype is sqlparse.tokens.Keyword and token.value.upper() == 'ORDER BY':
            order_found = True
    return order_cols

# Extract information from the parsed query
table_names = get_tables_from_clause(parsed_query)
where_clause_text = get_where_conditions(parsed_query)
grouping_columns = get_group_by_columns(parsed_query)
sorting_columns = get_order_by_columns(parsed_query)

# Display extracted data
print("Tables:", table_names)
print("Where Conditions:", where_clause_text)
print("Group By Columns:", grouping_columns)
print("Order By Columns:", sorting_columns)

# AWS Lambda function to send an email notification when a file is uploaded to S3
import json
import boto3
import os

def lambda_handler(event, context):
    # Extract S3 event details from the incoming event
    s3_record = event['Records'][0]['s3']
    bucket = s3_record['bucket']['name']
    key = s3_record['object']['key']

    # Initialize SES client for sending emails
    ses = boto3.client('ses')

    # Retrieve email configuration from environment variables
    from_addr = os.environ['SENDER_EMAIL']
    to_addr = os.environ['RECIPIENT_EMAIL']
