for group in example_tuples:
    def check_numeric(val):
        return isinstance(val, (int, float, complex))

    def get_real_part(val):
        return val.real if isinstance(val, complex) else val

    def traverse_and_add(container):
        running_total = 0
        for element in container:
            if isinstance(element, tuple):
                running_total += traverse_and_add(element)
            elif check_numeric(element):
                running_total += get_real_part(element)
        return running_total

    accum += traverse_and_add(group)

