# Determine if dictionary has consistent key case and matching value case
def verify_dictionary_case(data):
    # Empty dictionary returns False
    if not data:
        return False

    # Count lowercase and uppercase keys
    lowercase_keys = sum([key.islower() for key in data.keys()])
    uppercase_keys = sum([key.isupper() for key in data.keys()])

    # Check if all keys are lowercase and all values are lowercase
    if lowercase_keys == len(data):
        return all(val.islower() for val in data.values())
    # Check if all keys are uppercase and all values are uppercase
    elif uppercase_keys == len(data):
        return all(val.isupper() for val in data.values())
    else:
        return False

# Modified version of the original code with Type I clone transformations
def longest_common_subsequence(str1, str2, len1, len2, memo):
    if len1 == 0 or len2 == 0:
        return 0
    if memo[len1][len2] != -1:
        return memo[len1][len2]
    if str1[len1-1] == str2[len2-1]:
        memo[len1][len2] = 1 + longest_common_subsequence(str1, str2, len1-1, len2-1, memo)
    else:
        memo[len1][len2] = max(longest_common_subsequence(str1, str2, len1, len2-1, memo),
                               longest_common_subsequence(str1, str2, len1-1, len2, memo))
    return memo[len1][len2]

def extract_lcs_sequence(strings_list):
    if not strings_list:
        return ""
    count = len(strings_list)
    common_str = strings_list[0]
    for idx in range(1, count):
        length1 = len(common_str)
        length2 = len(strings_list[idx])
        memo_table = [[-1] * (length2+1) for _ in range(length1+1)]
        lcs_len = longest_common_subsequence(common_str, strings_list[idx], length1, length2, memo_table)
        common_str = construct_lcs(common_str, strings_list[idx], memo_table)
    return common_str

def construct_lcs_sequence(first_str, second_str, memo):
    len1 = len(first_str)
    len2 = len(second_str)
    lcs_chars = []
    p, q = len1, len2
    while p > 0 and q > 0:
        if first_str[p-1] == second_str[q-1]:
            lcs_chars.append(first_str[p-1])
            p -= 1
            q -= 1
        elif memo[p-1][q] > memo[p][q-1]:
            p -= 1
        else:
            q -= 1
    return ''.join(reversed(lcs_chars))

def find_unique_substring(strings_data):
    if not strings_data:
        return ""
    unique_candidate = None
    for text in strings_data:
        for start_idx in range(len(text)):
            for end_idx in range(start_idx + 1, len(text) + 1):
                substring = text[start_idx:end_idx]
                if all(substring not in s for s in strings_data if s != text):
                    if unique_candidate is None or len(substring) < len(unique_candidate):
                        unique_candidate = substring
    return unique_candidate

def execute_analysis(data1, data2):
    combined_data = data1 + data2
    lcs_output = extract_lcs_sequence(combined_data)
    sus_output = find_unique_substring(combined_data)
    return sus_output, len(lcs_output)

