# Rubik's Cube implementation with rotation functionality
class MagicCube:
    def __init__(self):
        # Initialize each face as a 3x3 grid of colors
        self.sides = {
            'U': [['W', 'W', 'W'], ['W', 'W', 'W'], ['W', 'W', 'W']],  # White
            'D': [['Y', 'Y', 'Y'], ['Y', 'Y', 'Y'], ['Y', 'Y', 'Y']],  # Yellow
            'L': [['G', 'G', 'G'], ['G', 'G', 'G'], ['G', 'G', 'G']],  # Green
            'R': [['B', 'B', 'B'], ['B', 'B', 'B'], ['B', 'B', 'B']],  # Blue
            'F': [['R', 'R', 'R'], ['R', 'R', 'R'], ['R', 'R', 'R']],  # Red
            'B': [['O', 'O', 'O'], ['O', 'O', 'O'], ['O', 'O', 'O']]   # Orange
        }

    def spin_face(self, side, direction=True):
        if direction:
            self.sides[side] = [list(x) for x in zip(*self.sides[side][::-1])]
        else:
            self.sides[side] = [list(x) for x in zip(*self.sides[side])][::-1]

    def spin_cube(self, action):
        if action == 'U':
            self.spin_face('U')
            self.sides['L'][0], self.sides['F'][0], self.sides['R'][0], self.sides['B'][0] = \
                self.sides['F'][0], self.sides['R'][0], self.sides['B'][0], self.sides['L'][0]
        elif action == 'D':
            self.spin_face('D')
            self.sides['L'][2], self.sides['F'][2], self.sides['R'][2], self.sides['B'][2] = \
                self.sides['B'][2], self.sides['L'][2], self.sides['F'][2], self.sides['R'][2]
        elif action == 'L':
            self.spin_face('L')
            for idx in range(3):
                self.sides['U'][idx][0], self.sides['F'][idx][0], self.sides['D'][idx][0], self.sides['B'][2-idx][2] = \
                    self.sides['F'][idx][0], self.sides['D'][idx][0], self.sides['B'][2-idx][2], self.sides['U'][idx][0]
        elif action == 'R':
            self.spin_face('R')
            for idx in range(3):
                self.sides['U'][idx][2], self.sides['F'][idx][2], self.sides['D'][idx][2], self.sides['B'][2-idx][0] = \
                    self.sides['B'][2-idx][0], self.sides['U'][idx][2], self.sides['F'][idx][2], self.sides['D'][idx][2]
        elif action == 'F':
            self.spin_face('F')
            for idx in range(3):
                self.sides['U'][2][idx], self.sides['R'][0][2-idx], self.sides['D'][0][2-idx], self.sides['L'][2][idx] = \
                    self.sides['L'][2][idx], self.sides['U'][2][idx], self.sides['R'][0][2-idx], self.sides['D'][0][2-idx]
        elif action == 'B':
            self.spin_face('B')
            for idx in range(3):
                self.sides['U'][0][idx], self.sides['L'][0][2-idx], self.sides['D'][2][2-idx], self.sides['R'][2][idx] = \
                    self.sides['R'][2][idx], self.sides['U'][0][idx], self.sides['L'][0][2-idx], self.sides['D'][2][2-idx]

    def show(self):
        for side in self.sides:
            print(f"Side {side}:")
            for line in self.sides[side]:
                print(' '.join(line))
            print()

