# Generate text using GPT4Free model via Flask
import os
import uuid
from flask import Flask, request, redirect, url_for, send_from_directory
from transformers import GPT2LMHeadModel, GPT2Tokenizer

app = Flask(__name__)

# Load the pre-trained GPT4Free model and tokenizer
model = GPT2LMHeadModel.from_pretrained("xtekky/GPT4Free")
tokenizer = GPT2Tokenizer.from_pretrained("xtekky/GPT4Free")


def create_text(prompt, length=60):
    # Encode input prompt and generate output
    token_ids = tokenizer.encode(prompt, return_tensors="pt")
    generated_tokens = model.generate(token_ids, max_length=length, num_return_sequences=1, pad_token_id=50256)
    result_text = tokenizer.decode(generated_tokens[0], skip_special_tokens=True)
    return result_text


@app.route("/", methods=["GET", "POST"])
def home():
    data = {"title": "Home", "route": "main", "content": "", "message": ""}
    return redirect(url_for("upload_document"))


@app.route("/upload", methods=["GET", "POST"])
def upload_document():
    if request.method == "POST":
        uploaded_file = request.files["file"]
        if not uploaded_file:
            return redirect(request.url)

        # Check file extension
        _, ext = os.path.splitext(uploaded_file.filename)
        if ext != ".txt":
            return redirect(request.url)

        # Rename file with UUID
        new_filename = f"{str(uuid.uuid4())}.txt"

        # Get form data
        gender = request.form["gender"]
        max_length = request.form.get("length", 60)

        # Process file content
        content = uploaded_file.read().decode("utf-8")
        generated_output = create_text(content, length=int(max_length))

        # Save generated text to file
        with open(f"generated/{new_filename}", "w") as file:
            file.write(generated_output)

        return redirect(url_for("get_file", filename=new_filename))

    return """
    <!doctype html>
    <title>Upload a .txt file</title>
    <h1>Upload a .txt file</h1>
    <form method=post enctype=multipart/form-data>
      Length: <input type=text value=60 name=length><br>
      <input type=file name=file>
      <input type=submit value=Upload>
    </form>
    """


