# Perform Caesar cipher encoding with shift of 2 
def transform_text(message):
    result = []
    for char in message:
        if char.islower():
            # Shift lowercase letters by 2 and wrap around if needed
            result.append(chr((ord(char) - ord('a') + 2) % 26 + ord('a')))
        elif char.isupper():
            # Shift uppercase letters by 2 and wrap around if needed
            result.append(chr((ord(char) - ord('A') + 2) % 26 + ord('A')))
        else:
            # Keep non-alphabetic characters as they are
            result.append(char)
    return ''.join(result)

def reverse_transform(text):
    original = []
    for char in text:
        if char.islower():
            # Reverse shift lowercase letters by -2 and handle underflow
            original.append(chr((ord(char) - ord('a') - 2) % 26 + ord('a')))
        elif char.isupper():
            # Reverse shift uppercase letters by -2 and handle underflow
            original.append(chr((ord(char) - ord('A') - 2) % 26 + ord('A')))
        else:
            # Keep non-alphabetic characters unchanged
            original.append(char)
    return ''.join(original)

def verify_transformation(input_text):
    transformed = transform_text(input_text)
    restored = reverse_transform(transformed)
    if input_text == restored:
        print(f"Original: {input_text}")
        print(f"Transformed: {transformed}")
        print(f"Restored: {restored}")
        print("Transformation and restoration are correct.")
    else:
        print("An error occurred during transformation or restoration.")

