# Function to generate prime numbers using the Sieve of Eratosthenes algorithm
def find_primes(limit):
    """Create a list of prime numbers up to the given limit using the Sieve of Eratosthenes method."""
    prime_flags = [True] * (limit + 1)
    prime_flags[0] = prime_flags[1] = False  # 0 and 1 are not prime
    current_prime = 2
    while current_prime * current_prime <= limit:
        if prime_flags[current_prime]:
            for multiple in range(current_prime * current_prime, limit + 1, current_prime):
                prime_flags[multiple] = False
        current_prime += 1
    return [index for index in range(limit + 1) if prime_flags[index]]

# Function to compute the product of all primes up to a given number
def multiply_primes(upper_bound):
    """Compute the product of all prime numbers up to and including the upper bound."""
    primes_list = find_primes(upper_bound)
    result = 1
    for prime_value in primes_list:
        result *= prime_value
    return result

