# Check for perfect squares in a nested list structure
import math

def check_perfect_square(value):
    if not isinstance(value, int):
        return False
    square_root = int(math.isqrt(value))
    return square_root * square_root == value

def extract_perfect_squares(data_list):
    squares_dict = {}

    for inner_list in data_list:
        for element in inner_list:
            if isinstance(element, int) and check_perfect_square(element):
                root_value = int(math.isqrt(element))
                squares_dict[element] = root_value

    return squares_dict

