# Function to select suitable cooking methods based on health constraints
def select_appropriate_methods(cooking_options, nutrition_info, dietary_limits):
    suitable_methods = {}
    for method, chance in cooking_options.items():
        if (nutrition_info[method]['calories'] <= dietary_limits['max_calories'] and
            nutrition_info[method]['fat'] <= dietary_limits['max_fat']):
            suitable_methods[method] = chance
    return suitable_methods

# Function to randomly choose a method according to probability weights
def weighted_random_choice(method_probs):
    total_weight = sum(method_probs.values())
    threshold = random.uniform(0, total_weight)
    running_sum = 0
    for method, weight in method_probs.items():
        running_sum += weight
        if threshold <= running_sum:
            return method
    return None  # Safety fallback

# Function to prepare beef
def prepare_beef():
    appropriate_methods = select_appropriate_methods(beef_cooking_options, nutrition_info, dietary_limits)
    if not appropriate_methods:
        return "No healthy preparation methods found for beef."
