# Fitness and health metrics calculator
def compute_body_mass_index(mass, stature):
    """Compute Body Mass Index (BMI)."""
    bmi_value = mass / (stature ** 2)
    return round(bmi_value, 2)

def compute_waist_hip_ratio(waist_measurement, hip_measurement):
    """Compute Waist-to-Hip Ratio (WHR)."""
    ratio = waist_measurement / hip_measurement
    return round(ratio, 2)

def compute_resting_metabolic_rate(mass, fat_ratio):
    """Compute Resting Metabolic Rate (RMR) using the Katch-McArdle formula."""
    lean_body_mass = mass * (1 - (fat_ratio / 100))
    rmr = 370 + (21.6 * lean_body_mass)
    return round(rmr, 2)

def compute_max_heart_rate(years, gender):
    """Compute Maximum Heart Rate (MHR) using the Tanaka equation."""
    if gender.lower() == 'male':
        max_hr = 208 - (0.7 * years)
    elif gender.lower() == 'female':
        max_hr = 206 - (0.88 * years)
    else:
        raise ValueError("Gender must be 'male' or 'female'.")
    return round(max_hr)

def main():
