import numpy as np
from scipy.integrate import quad

def check_parameters(r1, r2, a, b, h, f_func, g_func):
    if r1 < 0 or r2 < 0 or a < 0 or b < 0 or h < 0:
        raise ValueError("Invalid input: negative values are not allowed")
    if f_func is not None and not callable(f_func):
        raise ValueError("Invalid input: f must be a callable function")
    if g_func is not None and not callable(g_func):
        raise ValueError("Invalid input: g must be a callable function")

def frustum_surface_area_and_volume(r_top, r_bottom, height):
    surface_area = np.pi * (r_top + r_bottom) * np.sqrt((r_top - r_bottom)**2 + height**2)
    volume = (1/3) * np.pi * height * (r_top**2 + r_top*r_bottom + r_bottom**2)
    return surface_area, volume

def elliptical_frustum_surface_area_and_volume(a1, b1, a2, b2, height):
    surface_area = quad(lambda h: 2 * np.pi * np.sqrt(a1**2 + b1**2) * np.sqrt(1 + (a1 - a2)**2 / h**2), 0, height)[0]
    volume = (1/3) * np.pi * height * (a1 * b1 + a1 * b2 + a2 * b2)
    return surface_area, volume

def variable_radius_cone_surface_area_and_volume(radius_func, height):
    surface_area = quad(lambda h: 2 * np.pi * radius_func(h) * np.sqrt(1 + (radius_func(h + 1e-6) - radius_func(h))**2 / 1e-6), 0, height)[0]
    volume = quad(lambda h: np.pi * radius_func(h)**2, 0, height)[0]
    return surface_area, volume

def compute_cone_properties(r1, r2, a, b, h, f_func, g_func, time_values=None):
    check_parameters(r1, r2, a, b, h, f_func, g_func)

    if g_func is not None:
        output = []
        for t in time_values:
            r1_t, r2_t, a_t, b_t, h_t = g_func(t)
            A, V = compute_cone_properties(r1_t, r2_t, a_t, b_t, h_t, f_func, None)
            output.append((A, V))
        return output

    if f_func is not None:
        return variable_radius_cone_surface_area_and_volume(f_func, h)

    if a > 0 and b > 0:
        return elliptical_frustum_surface_area_and_volume(r1, r1, r2, r2, h)

    return frustum_surface_area_and_volume(r1, r2, h)

def process_all_cones(cone_list, time_values=None):
    final_results = []
    for cone in cone_list:
        r1, r2, a, b, h, f_func, g_func = cone
        outcome = compute_cone_properties(r1, r2, a, b, h, f_func, g_func, time_values)
        final_results.append(outcome)
    return final_results

