# Recursive solution for Tower of Hanoi problem
def solve_hanoi(disks, origin, helper, destination, move_count=1):
    if disks == 1:
        print(f"Move {move_count}: Transfer disk 1 from {origin} to {destination}")
        return 1
    else:
        move_count = solve_hanoi(disks - 1, origin, destination, helper, move_count)
        print(f"Move {move_count + 1}: Transfer disk {disks} from {origin} to {destination}")
        move_count += 1
        move_count = solve_hanoi(disks - 1, helper, origin, destination, move_count + 1)
        return move_count

def execute_tower_solution(n_disks):
    if not isinstance(n_disks, int) or n_disks <= 0:
        raise ValueError("Disk count must be a positive integer.")

    print(f"Processing Tower of Hanoi with {n_disks} disks:")
    total_moves = solve_hanoi(n_disks, 'Peg X', 'Peg Y', 'Peg Z')
    print(f"Total moves executed: {total_moves}")

if __name__ == "__main__":
    try:
        user_input = input("Specify the number of disks: ")
        disk_quantity = int(user_input)
        execute_tower_solution(disk_quantity)
    except ValueError as error_msg:
        print(f"Exception caught: {error_msg}")

# Function to find the second smallest odd number in a list
def find_second_min_odd(nums: list):
    first, second = None, None
    for val in nums:
        if val % 2 != 0:
            if first is None:
                first = val
            elif val < first:
                second = first
                first = val
            elif second is None or val < second:
                second = val
    return second

