# Generate all possible tilings for a 3x3 board using 1x1 and 2x1 blocks
def display_grid(grid):
    for line in grid:
        print(' '.join(str(cell) for cell in line))
    print('---')

def check_validity(grid, r, c):
    size = len(grid)
    if r < 0 or r >= size or c < 0 or c >= size:
        return False
    if grid[r][c] != 0:
        return False
    return True

def add_tile(grid, r, c, tile_type):
    if tile_type == '1x1':
        grid[r][c] = 1
    elif tile_type == '2x1':
        grid[r][c] = 2
        grid[r][c + 1] = 2

def delete_tile(grid, r, c, tile_type):
    if tile_type == '1x1':
        grid[r][c] = 0
    elif tile_type == '2x1':
        grid[r][c] = 0
        grid[r][c + 1] = 0

def explore(grid, r, c, results):
    size = len(grid)
    if r == size:
        results.append([line[:] for line in grid])
        return

    if c == size:
        explore(grid, r + 1, 0, results)
        return

    if grid[r][c] != 0:
        explore(grid, r, c + 1, results)
        return

    # Attempt placing a 1x1 tile
    add_tile(grid, r, c, '1x1')
    explore(grid, r, c + 1, results)
    delete_tile(grid, r, c, '1x1')

    # Attempt placing a 2x1 tile
    if c + 1 < size and grid[r][c + 1] == 0:
        add_tile(grid, r, c, '2x1')
        explore(grid, r, c + 2, results)
        delete_tile(grid, r, c, '2x1')

def enumerate_all_arrangements():
    dimension = 3
    grid = [[0] * dimension for _ in range(dimension)]
    arrangements = []
    explore(grid, 0, 0, arrangements)
    for arrangement in arrangements:
        display_grid(arrangement)

enumerate_all_arrangements()

