import os
from os.path import join, getsize

def CalculateDirectorySize(directory_path):
    total_size = 0
    for item in os.scandir(directory_path):
        if item.is_file():
            try:
                total_size += item.stat().st_size
            except OSError:
                print("error with file: " + item.path)
        elif item.is_dir():
            total_size += CalculateDirectorySize(item.path)
    return total_size

