# Define a class for rooms in the game
class Chamber:
    def __init__(self, title, info, objects=None, pathways=None, challenge=None, answer=None):
        self.title = title
        self.info = info
        self.objects = objects if objects is not None else []
        self.pathways = pathways if pathways is not None else {}
        self.challenge = challenge
        self.answer = answer

    def collect_object(self, obj):
        self.objects.append(obj)

    def discard_object(self, obj):
        if obj in self.objects:
            self.objects.remove(obj)

    def attempt_challenge(self, response):
        if self.challenge and response == self.answer:
            print("Challenge completed!")
            self.challenge = None
            self.answer = None
            return True
        else:
            print("That does not appear to solve the challenge.")
            return False

    def inspect(self):
        print(f"--- {self.title} ---")
        print(self.info)
        if self.objects:
            print("Objects in the chamber:", ", ".join(self.objects))
        if self.challenge:
            print("There is a challenge to solve here.")
        print("Pathways:", ", ".join(self.pathways.keys()))

def start_game():
    # Create chambers
    kitchen = Chamber(
        title="Kitchen",
        info="You are in a dimly lit kitchen. There is a table with some utensils and a door leading to the hallway.",
        objects=["knife", "spoon"],
        pathways={"east": "hallway"}
    )

    corridor = Chamber(
        title="Hallway",
        info="You are in a long corridor. There are doors to the north, south, and east.",
        pathways={"north": "bedroom", "south": "kitchen", "east": "living room"}
    )

    bedroom = Chamber(
        title="Bedroom",
        info="You are in a cozy bedroom. There is a bed and a small desk with a locked drawer.",
        objects=["book"],
        challenge="What is the combination to the drawer?",
        answer="1234"
    )

    living_room = Chamber(
        title="Living Room",
        info="You are in a spacious living room. There is a couch, a TV, and a door to the outside.",
        objects=["remote", "key"],
        pathways={"west": "corridor", "east": "outside"}
    )

    outdoors = Chamber(
        title="Outside",
        info="You are outside the house. You have escaped! Congratulations!",
        pathways={}
    )

    # Establish connections between chambers
    kitchen.pathways["east"] = corridor
    corridor.pathways["north"] = bedroom
    corridor.pathways["south"] = kitchen
    corridor.pathways["east"] = living_room
    living_room.pathways["west"] = corridor
    living_room.pathways["east"] = outdoors

    # Player's backpack
    backpack = []

    # Initial chamber
    current_chamber = kitchen

    while True:
        current_chamber.inspect()
        user_input = input("What would you like to do? ").lower().split()

        if not user_input:
            continue

        verb = user_input[0]

        if verb == "move":
            if len(user_input) > 1:
                direction = user_input[1]
                if direction in current_chamber.pathways:
                    current_chamber = current_chamber.pathways[direction]
                else:
                    print("You cannot move in that direction.")
            else:
                print("Move where?")

        elif verb == "grab":
            if len(user_input) > 1:
                item = user_input[1]
                if item in current_chamber.objects:
                    current_chamber.discard_object(item)
                    backpack.append(item)
                    print(f"You pick up the {item}.")
                else:
                    print("No such item exists here.")
            else:
                print("Grab what?")

        elif verb == "apply":
            if len(user_input) > 1:
                item = user_input[1]
                if item in backpack:
                    if current_chamber.challenge:
                        if current_chamber.attempt_challenge(item):
                            if item == "key" and current_chamber.title == "Living Room":
                                print("You use the key to unlock the door and escape!")
                                break
                    else:
                        print("No challenge to solve here.")
                else:
                    print("You do not possess that item.")
            else:
                print("Apply what?")

        elif verb == "backpack":
            if backpack:
                print("You are carrying:", ", ".join(backpack))
            else:
                print("Your backpack is empty.")

        elif verb == "examine":
            current_chamber.inspect()

        elif verb == "exit":
            print("Goodbye! Thanks for playing!")
            break

        else:
            print("I do not understand that command.")

