# Definition for singly-linked list node
class Node:
    def __init__(self, val=0, following=None):
        self.val = val
        self.following = following

def find_length_and_end(current_node):
    count = 0
    while current_node:
        count += 1
        if not current_node.following:
            return count, current_node
        current_node = current_node.following
    return count, None

def locate_intersection_point(first_head, second_head):
    len1, end1 = find_length_and_end(first_head)
    len2, end2 = find_length_and_end(second_head)

    # If the ending nodes differ, there's no intersection
    if end1 != end2:
        return None

    # Align starting positions by advancing the longer list's head
    if len1 > len2:
        for _ in range(len1 - len2):
            first_head = first_head.following
    else:
        for _ in range(len2 - len1):
            second_head = second_head.following

    # Traverse both lists simultaneously until intersection found
    while first_head != second_head:
        first_head = first_head.following
        second_head = second_head.following

    return first_head

