# A simple hash table implementation with collision handling via chaining
class HashMap:
    def __init__(self, capacity=100):
        self.capacity = capacity
        self.buckets = [None] * capacity

    def _compute_index(self, key):
        # Compute index using Python's built-in hash and modulo capacity
        return hash(key) % self.capacity

    def put(self, key, value):
        pos = self._compute_index(key)
        if self.buckets[pos] is None:
            self.buckets[pos] = []
        # Check if key already exists and update it
        for idx, (existing_key, existing_val) in enumerate(self.buckets[pos]):
            if existing_key == key:
                self.buckets[pos][idx] = (key, value)
                return
        # Otherwise, append new key-value pair
        self.buckets[pos].append((key, value))

    def retrieve(self, key):
        pos = self._compute_index(key)
        if self.buckets[pos] is not None:
            for k, v in self.buckets[pos]:
                if k == key:
                    return v
        raise KeyError(f"Key '{key}' does not exist")

    def remove(self, key):
        pos = self._compute_index(key)
        if self.buckets[pos] is not None:
            for idx, (k, v) in enumerate(self.buckets[pos]):
                if k == key:
                    del self.buckets[pos][idx]
                    return
        raise KeyError(f"Key '{key}' does not exist")

    def __str__(self):
        return str(self.buckets)

