# Convert ISO timestamp to human-readable words format 
from datetime import datetime

def digits_to_text(num):
    digit_map = {
        0: 'Zero', 1: 'One', 2: 'Two', 3: 'Three', 4: 'Four', 5: 'Five',
        6: 'Six', 7: 'Seven', 8: 'Eight', 9: 'Nine', 10: 'Ten',
        11: 'Eleven', 12: 'Twelve', 13: 'Thirteen', 14: 'Fourteen',
        15: 'Fifteen', 16: 'Sixteen', 17: 'Seventeen', 18: 'Eighteen',
        19: 'Nineteen', 20: 'Twenty', 30: 'Thirty', 40: 'Forty',
        50: 'Fifty', 60: 'Sixty', 70: 'Seventy', 80: 'Eighty', 90: 'Ninety'
    }

    if num in digit_map:
        return digit_map[num]
    elif num < 100:
        return digit_map[num - num % 10] + '-' + digit_map[num % 10].lower()
    elif num < 1000:
        if num % 100 == 0:
            return digit_map[num // 100] + ' Hundred'
        else:
            return digit_map[num // 100] + ' Hundred and ' + digits_to_text(num % 100)
    else:
        raise ValueError("Number out of supported range")

def month_name(month_num):
    month_dict = {
        1: 'January', 2: 'February', 3: 'March', 4: 'April', 5: 'May', 6: 'June',
        7: 'July', 8: 'August', 9: 'September', 10: 'October', 11: 'November', 12: 'December'
    }
    return month_dict[month_num]

def iso_to_spoken_form(timestamp_str):
    dt_obj = datetime.fromisoformat(timestamp_str.replace('Z', '+00:00'))

    # Extract date/time components
    year_val = dt_obj.year
    month_val = dt_obj.month
    day_val = dt_obj.day
    hour_val = dt_obj.hour
    minute_val = dt_obj.minute
    second_val = dt_obj.second

    # Transform numbers to words
    year_text = digits_to_text(year_val)
    month_text = month_name(month_val)
    day_text = digits_to_text(day_val)

    if hour_val == 0:
        hour_text = 'Twelve'
    else:
        hour_text = digits_to_text(hour_val % 12)

    minute_text = digits_to_text(minute_val)
    period = 'AM' if hour_val < 12 else 'PM'

    # Assemble final string
    formatted_time = f"{hour_text} {minute_text} {period}, {day_text} of {month_text} {year_text}"

    return formatted_time

