# Prime factorization implementation using trial division and Pollard's Rho algorithm
import math
from random import randint

def check_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    j = 5
    while j * j <= num:
        if num % j == 0 or num % (j + 2) == 0:
            return False
        j += 6
    return True

def rho_factor(n):
    if n % 2 == 0:
        return 2
    if check_prime(n):
        return n

    def polynomial(x):
        return (x * x + 1) % n

    a, b, g = 2, 2, 1
    while g == 1:
        a = polynomial(a)
        b = polynomial(polynomial(b))
        g = math.gcd(abs(a - b), n)
    return g

def get_prime_factors(value):
    if value == 1:
        return []
    prime_factors = set()
    # Handle even factors first
    while value % 2 == 0:
        prime_factors.add(2)
        value //= 2
    # Check odd divisors up to square root
    for k in range(3, int(math.sqrt(value)) + 1, 2):
        while value % k == 0:
            prime_factors.add(k)
            value //= k
    # Remaining prime factor if any
    if value > 2:
        prime_factors.add(value)
    # Apply Pollard's Rho for composite numbers
    while not check_prime(value) and value > 1:
        divisor = rho_factor(value)
        prime_factors.add(divisor)
        value //= divisor
    return sorted(prime_factors)

# Validation tests
def run_tests():
    assert get_prime_factors(8) == [2]
    assert get_prime_factors(25) == [5]
    assert get_prime_factors(70) == [2, 5, 7]
    assert get_prime_factors(100) == [2, 5]
    assert get_prime_factors(1000003) == [1000003]
    assert get_prime_factors(1000000007) == [1000000007]
    assert get_prime_factors(1234567890123456789) == [3, 7, 11, 13, 37, 101, 9901, 99990001]

run_tests()

