# Find the nearest store based on customer address
from flask import Flask, request, render_template
from geopy.geocoders import Nominatim
from geopy.distance import geodesic

app = Flask(__name__)

# Load store data from CSV file
def load_store_locations():
    locations = []
    with open('stores.csv', 'r') as data_file:
        for record in data_file:
            name, addr, latitude, longitude = record.strip().split(',')
            locations.append((name, addr, float(latitude), float(longitude)))
    return locations

# Convert customer address to coordinates
def get_coordinates(address):
    locator = Nominatim(user_agent="store_locator_app")
    result = locator.geocode(address)
    if result:
        return (result.latitude, result.longitude)
    return None

# Determine closest store using distance calculation
def locate_closest_store(locations, user_coords):
    closest = None
    shortest = float('inf')
    for loc in locations:
        loc_coords = (loc[2], loc[3])
        dist = geodesic(user_coords, loc_coords).kilometers
        if dist < shortest:
            shortest = dist
            closest = loc
    return closest, shortest

@app.route('/', methods=['GET', 'POST'])
def home():
    if request.method == 'POST':
        user_address = request.form['address']
        user_location = get_coordinates(user_address)
        if user_location:
            store_list = load_store_locations()
            closest_store, separation = locate_closest_store(store_list, user_location)
            return render_template('index.html', nearest_store=closest_store, distance=separation)
        else:
            return render_template('index.html', error="Unable to locate address")
    return render_template('index.html')

if __name__ == '__main__':
    app.run(debug=True)

# Modified version of TicTacToe class with renamed variables and reordered logic
import numpy as np

class TicTacToeGame:
    def __init__(self):
        self.grid = np.zeros((3, 3))
        self.turn = 1  # 1 for player X, -1 for player O
        self.game_over = False
        self.result = None

    def restart(self):
        self.grid = np.zeros((3, 3))
        self.turn = 1
        self.game_over = False
        self.result = None
        return self.grid

    def get_valid_moves(self):
        return [(row, col) for row in range(3) for col in range(3) if self.grid[row, col] == 0]

    def play_move(self, position):
        if self.grid[position] != 0:
            return self.grid, -1, True, "Invalid move"

        self.grid[position] = self.turn
        if self.check_victory():
            self.game_over = True
            self.result = self.turn
            reward = 1
        elif len(self.get_valid_moves()) == 0:
            self.game_over = True
            reward = 0
        else:
            self.turn = -self.turn
            reward = 0

        return self.grid, reward, self.game_over, {}

    def check_victory(self):
        # Check rows and columns
        for idx in range(3):
            if np.all(self.grid[idx, :] == self.turn) or np.all(self.grid[:, idx] == self.turn):
                return True
        # Check diagonals
        if np.all(np.diag(self.grid) == self.turn) or np.all(np.diag(np.fliplr(self.grid)) == self.turn):
            return True
        return False

    def display(self):
        print(self.grid)

