# Compute prime factorizations using parallel processing
import concurrent.futures
import random

def find_prime_factors(number):
    factors_list = []
    for divisor in range(2, number):
        quotient, remainder = divmod(number, divisor)
        if not remainder:
            factors_list.extend(find_prime_factors(divisor))
            factors_list.extend(find_prime_factors(quotient))
            break
    else:
        factors_list = [number]
    return factors_list

if __name__ == '__main__':
    numbers_to_analyze = [random.randint(100000, 50000000) for _ in range(20)]

    with concurrent.futures.ProcessPoolExecutor() as pool:
        factor_results = list(pool.map(find_prime_factors, numbers_to_analyze))

    for num, factor_list in zip(numbers_to_analyze, factor_results):
        print(f"The factors of {num} are {factor_list}")

# Class representing a student with subjects and grades
class Learner:
    def __init__(self, full_name, years_old, current_year):
        self.full_name = full_name
        self.years_old = years_old
        self.current_year = current_year
        self.enrolled_courses = []  # List to store courses
        self.marks = {}             # Dictionary to store marks for each course

    def enroll_course(self, course):
        if course not in self.enrolled_courses:
            self.enrolled_courses.append(course)
            self.marks[course] = None  # Initialize mark for the course as None

    def drop_course(self, course):
        if course in self.enrolled_courses:
            self.enrolled_courses.remove(course)
            del self.marks[course]

    def list_courses(self):
        return self.enrolled_courses

    def assign_mark(self, course, score):
        if course in self.enrolled_courses:
            if 0 <= score <= 100:
                self.marks[course] = score
            else:
                raise ValueError("Score must be between 0 and 100")
        else:
            raise ValueError(f"Course {course} is not enrolled")

    def calculate_mean_score(self):
        total_scores = 0
        number_of_subjects = 0
        for course, score in self.marks.items():
            if score is not None:
                total_scores += score
                number_of_subjects += 1
        if number_of_subjects == 0:
            return None  # No scores available
        return total_scores / number_of_subjects

