# Calculate BST statistics: count of nodes greater than root, less than root, and total nodes
from typing import Tuple, Optional

class BinaryTreeNode:
    def __init__(self, value=0, left_child=None, right_child=None):
        self.value = value
        self.left = left_child
        self.right = right_child

def bst_analysis(root_node: Optional[BinaryTreeNode]) -> Tuple[int, int, int]:
    if root_node is None:
        return (0, 0, 0)

    def node_counter(node: Optional[BinaryTreeNode]) -> int:
        if node is None:
            return 0
        return 1 + node_counter(node.left) + node_counter(node.right)

    def compare_subtree(node: Optional[BinaryTreeNode], target_value: int) -> Tuple[int, int]:
        if node is None:
            return (0, 0)

        smaller_count, larger_count = 0, 0

        if node.value < target_value:
            smaller_count += 1
            smaller_count += compare_subtree(node.left, target_value)[0]
            smaller_count += compare_subtree(node.right, target_value)[0]
        elif node.value > target_value:
            larger_count += 1
            larger_count += compare_subtree(node.left, target_value)[1]
            larger_count += compare_subtree(node.right, target_value)[1]

        return (smaller_count, larger_count)

    all_nodes = node_counter(root_node)
    below_root, above_root = compare_subtree(root_node, root_node.value)

    return (above_root, below_root, all_nodes)

# Example usage:
# Construct the tree:
#       25 
#      /   \          
#    15     35
#   /  \    /  \ 
#  10  20  30  40
root = BinaryTreeNode(25)
root.left = BinaryTreeNode(15, BinaryTreeNode(10), BinaryTreeNode(20))
root.right = BinaryTreeNode(35, BinaryTreeNode(30), BinaryTreeNode(40))

result = bst_analysis(root)
print(result)  # Output: (3, 3, 7)

