import re

def assess_password_strength(password):
    """
    Assesses the robustness of a password.

    :param password: The password to assess.
    :return: A dictionary containing the assessment results.
    """
    min_len = 8
    max_len = 64
    has_upper = re.search(r'[A-Z]', password)
    has_lower = re.search(r'[a-z]', password)
    has_number = re.search(r'\d', password)
    has_special = re.search(r'[!@#$%^&*(),.?":{}|<>]', password)

    points = 0
    suggestions = []

    if len(password) < min_len:
        suggestions.append(f"Password should be at least {min_len} characters long.")
    if len(password) > max_len:
        suggestions.append(f"Password should be no more than {max_len} characters long.")
    if not has_upper:
        suggestions.append("Password must include at least one uppercase letter.")
    if not has_lower:
        suggestions.append("Password must include at least one lowercase letter.")
    if not has_number:
        suggestions.append("Password must include at least one numeric digit.")
    if not has_special:
        suggestions.append("Password must include at least one special character.")

    if len(password) >= min_len:
        points += 1
    if has_upper:
        points += 1
    if has_lower:
        points += 1
    if has_number:
        points += 1
    if has_special:
        points += 1

    return {
        "points": points,
        "suggestions": suggestions,
        "is_secure": points >= 3
    }

