# Huffman coding implementation for data compression and decompression
import heapq
from collections import defaultdict, Counter

class TreeNode:
    def __init__(self, character, count):
        self.char = character
        self.freq = count
        self.left = None
        self.right = None

    def __lt__(self, other):
        return self.freq < other.freq

def construct_huffman_tree(freq_dict):
    priority_queue = [TreeNode(char, count) for char, count in freq_dict.items()]
    heapq.heapify(priority_queue)

    while len(priority_queue) > 1:
        first_node = heapq.heappop(priority_queue)
        second_node = heapq.heappop(priority_queue)
        combined = TreeNode(None, first_node.freq + second_node.freq)
        combined.left = first_node
        combined.right = second_node
        heapq.heappush(priority_queue, combined)

    return priority_queue[0]

def create_huffman_codes(tree_node, current_code="", mapping=None):
    if mapping is None:
        mapping = {}
    if tree_node is not None:
        if tree_node.char is not None:
            mapping[tree_node.char] = current_code
        create_huffman_codes(tree_node.left, current_code + "0", mapping)
        create_huffman_codes(tree_node.right, current_code + "1", mapping)
    return mapping

def encode_input(input_text, encoding_table):
    return ''.join(encoding_table[char] for char in input_text)

def decode_input(encoded_string, tree_root):
    current = tree_root
    decoded_output = []
    for digit in encoded_string:
        if digit == '0':
            current = current.left
        else:
            current = current.right
        if current.char is not None:
            decoded_output.append(current.char)
            current = tree_root
    return ''.join(decoded_output)

def execute():
    text = "this is an example for huffman encoding"
    char_counts = Counter(text)

    # Build the Huffman tree
    huffman_tree = construct_huffman_tree(char_counts)

    # Generate Huffman codes
    encoding_table = create_huffman_codes(huffman_tree)

    # Compress the data
    encoded = encode_input(text, encoding_table)
    print(f"Compressed data: {encoded}")

    # Decompress the data
    decoded = decode_input(encoded, huffman_tree)
    print(f"Decompressed data: {decoded}")

if __name__ == "__main__":
    execute()

# Check if a number is an Armstrong/Narcissistic number
def check_armstrong_value(value):
    digits_str = str(value)
    digit_count = len(digits_str)
    return value == sum(int(d) ** digit_count for d in digits_str)

def verify_narcissistic_value(value):
    return check_armstrong_value(value)

def process_range(initial, final):
    # Validate input types
    if not (isinstance(initial, int) and isinstance(final, int)):
        raise ValueError("Both initial and final must be integers.")
    if initial > final:
        raise ValueError("Initial must be less than or equal to final.")

    armstrong_list = []
    narcissistic_list = []
    remaining_list = []

    for val in range(initial, final + 1):
        if check_armstrong_value(val):
            armstrong_list.append(val)
            narcissistic_list.append(val)  # Armstrong and Narcissistic are equivalent
        else:
            remaining_list.append(val)

    total_count = final - initial + 1
    output = {
        'armstrong_values': armstrong_list,
        'narcissistic_values': narcissistic_list,
        'remaining_values': remaining_list,
        'frequencies': {
            'armstrong': len(armstrong_list),
            'narcissistic': len(narcissistic_list),
            'remaining': len(remaining_list),
            'total': total_count
        },
        'ratios': {
            'armstrong': (len(armstrong_list) / total_count) * 100,
            'narcissistic': (len(narcissistic_list) / total_count) * 100,
            'remaining': (len(remaining_list) / total_count) * 100
        }
    }

    return output

def execute():
    try:
        initial_val = 100
        final_val = 1000
        analysis = process_range(initial_val, final_val)

        print(f"Armstrong Values: {analysis['armstrong_values']}")
        print(f"Narcissistic Values: {analysis['narcissistic_values']}")
        print(f"Remaining Values: {analysis['remaining_values']}")

        print(f"Frequencies: {analysis['frequencies']}")
        print(f"Ratios: {analysis['ratios']:.2f}%")

    except ValueError as err:
        print(f"Exception: {err}")

if __name__ == "__main__":
    execute()

