import random

def get_player_selection():
    player_input = input("Choose your move (Rock, Paper, Scissors): ").strip().capitalize()
    if player_input in ["Rock", "Paper", "Scissors"]:
        return player_input
    else:
        print("Invalid selection. Please choose Rock, Paper, or Scissors.")
        return get_player_selection()

def get_computer_selection():
    return random.choice(["Rock", "Paper", "Scissors"])

def decide_outcome(player_move, computer_move):
    if player_move == computer_move:
        return "Draw!"
    elif (player_move == "Rock" and computer_move == "Scissors") or \
         (player_move == "Paper" and computer_move == "Rock") or \
         (player_move == "Scissors" and computer_move == "Paper"):
        return "Player wins!"
    else:
        return "Computer wins!"

def run_round():
    print("Welcome to Rock-Paper-Scissors!")
    player_move = get_player_selection()
    computer_move = get_computer_selection()
    print(f"You selected {player_move}, computer selected {computer_move}.")
