# House address management system 
class HomeAddress:
    def __init__(self, building_num, road_name, unit_number=None):
        self.configure_address(building_num, road_name, unit_number)

    def configure_address(self, building_num, road_name, unit_number=None):
        if not isinstance(building_num, int) or building_num <= 0:
            raise ValueError("Building number must be a positive integer.")
        if not isinstance(road_name, str) or not road_name:
            raise ValueError("Road name must be a non-empty string.")
        if unit_number is not None and not isinstance(unit_number, str):
            raise ValueError("Unit number must be a string if provided.")

        self.address_data = (building_num, road_name, unit_number)

    def change_building_number(self, updated_building_num):
        self.configure_address(updated_building_num, self.address_data[1], self.address_data[2])

    def change_road_name(self, updated_road_name):
        self.configure_address(self.address_data[0], updated_road_name, self.address_data[2])

    def change_unit_number(self, updated_unit_number):
        self.configure_address(self.address_data[0], self.address_data[1], updated_unit_number)

    def remove_unit_number(self):
        self.configure_address(self.address_data[0], self.address_data[1], None)

    def retrieve_address(self):
        return self.address_data

    def retrieve_building_number(self):
        return self.address_data[0]

    def retrieve_road_name(self):
        return self.address_data[1]

    def retrieve_unit_number(self):
        return self.address_data[2]

    @classmethod
    def filter_even_buildings(cls, address_list):
        return [home for home in address_list if home.retrieve_building_number() % 2 == 0]

    @classmethod
    def filter_odd_buildings(cls, address_list):
        return [home for home in address_list if home.retrieve_building_number() % 2 != 0]

# Demonstration usage:
