# Compute the smallest enclosing circle for a set of points
import random
import math

def euclidean_distance(pt1, pt2):
    return math.sqrt((pt1[0] - pt2[0]) ** 2 + (pt1[1] - pt2[1]) ** 2)

def circumcircle(p1, p2, p3):
    x1, y1 = p1
    x2, y2 = p2
    x3, y3 = p3
    denom = 2 * (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2))
    cx = ((x1 ** 2 + y1 ** 2) * (y2 - y3) + (x2 ** 2 + y2 ** 2) * (y3 - y1) + (x3 ** 2 + y3 ** 2) * (y1 - y2)) / denom
    cy = ((x1 ** 2 + y1 ** 2) * (x3 - x2) + (x2 ** 2 + y2 ** 2) * (x1 - x3) + (x3 ** 2 + y3 ** 2) * (x2 - x1)) / denom
    r = euclidean_distance((cx, cy), p1)
    return (cx, cy), r

def diameter_circle(p1, p2):
    center_x = (p1[0] + p2[0]) / 2
    center_y = (p1[1] + p2[1]) / 2
    radius = euclidean_distance(p1, p2) / 2
    return (center_x, center_y), radius

def point_circle(p1):
    return p1, 0

def min_enclosing_disk(points, boundary=[]):
    if not points or len(boundary) == 3:
        if len(boundary) == 0:
            return None, None
        elif len(boundary) == 1:
            return point_circle(boundary[0])
        elif len(boundary) == 2:
            return diameter_circle(boundary[0], boundary[1])
        else:
            return circumcircle(boundary[0], boundary[1], boundary[2])

    random.shuffle(points)
    for pt in points:
        center, rad = min_enclosing_disk(points[1:], boundary)
        if rad is None or euclidean_distance(pt, center) > rad:
            boundary.append(pt)
            center, rad = min_enclosing_disk(points[1:], boundary)
            boundary.pop()
        return center, rad

def find_smallest_circle(points):
    return min_enclosing_disk(points)

# Example usage
pts = [[0, 0], [0, 1], [1, 0], [0, 2], [2, 0]]
center_point, circle_radius = find_smallest_circle(pts)
print(f"Center: {center_point}, Radius: {circle_radius}")

# Check for empty or zero-like values in nested structures
def is_blank(item):
    """Custom function to determine if an object qualifies as 'blank'."""
    if hasattr(item, 'is_blank'):
        return item.is_blank()
    return False

def locate_blank_entries(container, current_path=None):
    if current_path is None:
        current_path = []

    if isinstance(container, (list, tuple)):
        output = []
        for idx, element in enumerate(container):
            new_path = current_path + [idx]
            partial_results = locate_blank_entries(element, new_path)
            if partial_results:
                output.extend(partial_results)
        return output

    elif isinstance(container, dict):
        output = []
        for key, val in container.items():
            new_path = current_path + [key]
            partial_results = locate_blank_entries(val, new_path)
            if partial_results:
                output.extend(partial_results)
        return output

    elif isinstance(container, set):
        output = []
        for idx, element in enumerate(container):
            new_path = current_path + [idx]
            partial_results = locate_blank_entries(element, new_path)
            if partial_results:
                output.extend(partial_results)
        return output

    elif container is None or container == 0 or container == '':
        return [current_path]

    elif is_blank(container):
        return [current_path]

    return []

def tally_and_report_blank_entries(container):
    found_paths = locate_blank_entries(container)
    if not found_paths:
        return "No null entries, blank strings, zeros, or 'blank' objects detected"

    total = len(found_paths)
    return {
        "overall_count": total,
        "positions": found_paths
    }

