# Calculate the minimum disparity between adjacent numeric values in a potentially nested list
def flatten_list(data):
    """Flatten a nested list structure."""
    for item in data:
        if isinstance(item, list):
            yield from flatten_list(item)
        else:
            yield item

def transform_to_number(val):
    """Convert various types (bool, string, etc.) to numeric representations."""
    if isinstance(val, bool):
        return int(val)
    if isinstance(val, str):
        try:
            return int(val)
        except ValueError:
            try:
                return float(val)
            except ValueError:
                return None
    if isinstance(val, (int, float, complex)):
        return val
    return None

def compute_min_difference(matrix):
    # Flatten the input structure
    flattened = list(flatten_list(matrix))

    # Transform and retain only valid numeric entries
    processed = [transform_to_number(x) for x in flattened if transform_to_number(x) is not None]

    # Validate minimum required elements
    if len(processed) < 2:
        return "Input must contain at least two numeric elements for comparison."

    # Sort based on magnitude (with special handling for complex numbers)
    processed.sort(key=lambda x: abs(x) if isinstance(x, complex) else x)

    # Track smallest difference and corresponding pair
    smallest_diff = float('inf')
    closest_pair = (None, None)

    # Scan adjacent pairs for minimum difference
    for idx in range(len(processed) - 1):
        diff = abs(processed[idx] - processed[idx + 1])
        if diff < smallest_diff:
            smallest_diff = diff
            closest_pair = (processed[idx], processed[idx + 1])

    return smallest_diff, closest_pair

# Verification tests
def run_tests():
    assert compute_min_difference([1, 5, 3, 9, 2]) == (1, (1, 2))
    assert compute_min_difference([1, 1, 1, 1]) == (0, (1, 1))
    assert compute_min_difference([1, 2, 3, 4, 5]) == (1, (1, 2))
    assert compute_min_difference([1, 2, 3, 4, 5, 1.01]) == (0.01, (1, 1.01))
    assert compute_min_difference([1, 2, 3, 4, 5, 1.01, '2.01']) == (0.01, (1, 1.01))
    assert compute_min_difference([1, 2, 3, 4, 5, True, False]) == (1, (0, 1))
    assert compute_min_difference([1, 2, 3, 4, 5, None, 'a', [1, 2], 1.01]) == (0.01, (1, 1.01))
    assert compute_min_difference([1, 2, 3, 4, 5, complex(1, 1), complex(1, 2)]) == (1, (1, 1.4142135623730951))
    assert compute_min_difference([]) == "Input must contain at least two numeric elements for comparison."
    assert compute_min_difference([1]) == "Input must contain at least two numeric elements for comparison."
    assert compute_min_difference(['a', 'b', 'c']) == "Input must contain at least two numeric elements for comparison."
    assert compute_min_difference([None, None, None]) == "Input must contain at least two numeric elements for comparison."
    assert compute_min_difference([1, '2', '3.14', True, False, None, [1, 2], 1.01]) == (0.01, (1, 1.01))
    assert compute_min_difference([1, 2, 3, 4, 5, complex(1, 1), complex(1, 2), 1.01]) == (0.01, (1, 1.01))

run_tests()
print("All tests passed.")

import statistics

# Define grade conversion and GPA calculation
SCORE_RANGES = {
    (90, 100): ('A', 4.0),
    (80, 89): ('B', 3.0),
    (70, 79): ('C', 2.0),
    (60, 69): ('D', 1.0),
    (0, 59): ('F', 0.0)
}

# Define weight for AP and honors courses
CLASS_MULTIPLIERS = {
    'AP': 1.0,
    'Honors': 0.5,
    'Regular': 0.0
}

def convert_score_to_letter(score):
    for (min_val, max_val), (letter, gpa_value) in SCORE_RANGES.items():
        if min_val <= score <= max_val:
            return letter, gpa_value
    raise ValueError("Score out of range (0-100)")

def compute_weighted_gpa(grade_list, class_types):
    if len(grade_list) != len(class_types):
        raise ValueError("Number of grades and class types must match")

    cumulative_gpa = 0
    for grade, class_type in zip(grade_list, class_types):
        letter, base_gpa = convert_score_to_letter(grade)
        cumulative_gpa += base_gpa + CLASS_MULTIPLIERS[class_type]

    return cumulative_gpa / len(grade_list)

def analyze_performance_trend(grades):
    if len(grades) < 2:
        return "Insufficient data to determine trend"

    slope = statistics.linear_regression(range(len(grades)), grades).slope
    if slope > 0:
        return "Improving"
    elif slope < 0:
        return "Declining"
    else:
        return "Stable"

class Learner:
    def __init__(self, learner_name):
        self.learner_name = learner_name
        self.score_records = []
        self.class_categories = []

    def record_scores(self, new_scores, new_class_types):
        if len(new_scores) != len(new_class_types):
            raise ValueError("Number of scores and class types must match")

        for score, class_type in zip(new_scores, new_class_types):
            if not (1 <= score <= 100):
                raise ValueError(f"Invalid score: {score}. Scores must be between 1 and 100.")
            if class_type not in CLASS_MULTIPLIERS:
                raise ValueError(f"Invalid course type: {class_type}. Valid types are {', '.join(CLASS_MULTIPLIERS.keys())}.")

        self.score_records.extend(new_scores)
        self.class_categories.extend(new_class_types)

    def generate_summary(self):
        if not self.score_records:
            return f"No academic records available for {self.learner_name}"

        letter_grades = [convert_score_to_letter(score)[0] for score in self.score_records]
        weighted_gpa = compute_weighted_gpa(self.score_records, self.class_categories)
        performance_trend = analyze_performance_trend(self.score_records)

        summary = (f"Academic Summary for {self.learner_name}:\n"
                   f"Grades: {', '.join(letter_grades)}\n"
                   f"Weighted GPA: {weighted_gpa:.2f}\n"
                   f"Performance Trend: {performance_trend}\n")

        return summary

def main():
    student_database = {}
    while True:
        print("\n1. Add Student\n2. Record Grades\n3. Generate Report\n4. Exit")
        selection = input("Select an option: ")

        if selection == '1':
            name = input("Enter student name: ")
            if name in student_database:
                print(f"Student {name} already exists.")
            else:
                student_database[name] = Learner(name)
                print(f"Student {name} has been added.")

        elif selection == '2':
            name = input("Enter student name: ")
            if name not in student_database:
                print(f"Student {name} does not exist. Please add the student first.")
                continue

            scores = list(map(int, input("Enter scores (separated by spaces): ").split()))
            class_types = input("Enter course types (separated by spaces, e.g., AP Honors Regular): ").split()

            try:
                student_database[name].record_scores(scores, class_types)
                print("Grades recorded successfully.")
            except ValueError as error:
                print(f"Error: {error}")

        elif selection == '3':
            name = input("Enter student name: ")
            if name not in student_database:
                print(f"Student {name} does not exist.")
                continue

            report = student_database[name].generate_summary()
            print(report)

        elif selection == '4':
            print("Program terminated.")
            break

        else:
            print("Invalid selection. Please choose a valid option.")

if __name__ == "__main__":
    main()

# A simple implementation of a Go board game
class GoBoard:
    def __init__(self, dimension=19):
        self.dimension = dimension
        self.grid = [[None for _ in range(dimension)] for _ in range(dimension)]
        self.turn = 'B'  # 'B' for black, 'W' for white

    def display_board(self):
        for line in self.grid:
            print(' '.join('.' if cell is None else cell for cell in line))
        print()

    def put_stone(self, row, col):
        if self.grid[row][col] is not None:
            print("Position already occupied.")
            return False
        self.grid[row][col] = self.turn
        self.turn = 'W' if self.turn == 'B' else 'B'
        return True

    def check_valid_move(self, row, col):
        if row < 0 or row >= self.dimension or col < 0 or col >= self.dimension:
            return False
        if self.grid[row][col] is not None:
            return False
        return True

    def end_game(self):
        # Simple check: if all positions are occupied
        for line in self.grid:
            for cell in line:
                if cell is None:
                    return False
        return True

    def run(self):
        print("Welcome to Go!")
        self.display_board()
        while not self.end_game():
            row = int(input(f"Player {self.turn}, enter row: "))
            col = int(input(f"Player {self.turn}, enter column: "))
            if self.check_valid_move(row, col):
                self.put_stone(row, col)
                self.display_board()
            else:
                print("Invalid move, try again.")

        print("Game Over! The board is full.")

if __name__ == "__main__":
    match = GoBoard()
    match.run()

# Import necessary modules for environment handling, HTTP requests, and JSON processing
import os
import requests
import json

def fetch_api_credentials():
    """Fetch the API token from environment variables or configuration."""
    api_token = os.getenv('API_TOKEN')
    if not api_token:
        raise ValueError("API token missing. Please configure the 'API_TOKEN' environment variable.")
    return api_token

def send_authenticated_post(url, payload):
    """Send a POST request with authentication headers to the given URL containing the payload."""
    api_token = fetch_api_credentials()
    headers = {
        'Authorization': f'Bearer {api_token}',
        'Content-Type': 'application/json'
    }

    try:
        response = requests.post(url, headers=headers, data=json.dumps(payload))
        response.raise_for_status()  # Trigger exception for HTTP error codes
        return response.json()
    except requests.exceptions.RequestException as error:
        print(f"Request failed: {error}")
        return None

def pretty_print_response(api_response):
    """Convert the API response into a readable string format."""
    if api_response:
        return json.dumps(api_response, indent=4)
    else:
        return "No data returned from server."

def run_application():
    endpoint_url = 'https://api.example.com/v1/resource'
    request_body = {
        "param1": "value1",
        "param2": "value2"
    }

    result = send_authenticated_post(endpoint_url, request_body)
    print(pretty_print_response(result))

if __name__ == "__main__":
    run_application()

