def extract_values_by_key(obj, target_key):
    """
    Recursively searches through a JSON structure to find all values 
    corresponding to the given key.

    :param obj: The JSON object (dict or list) to traverse.
    :param target_key: The key whose associated values we want to collect.
    """
    if isinstance(obj, dict):
        for k, val in obj.items():
            if k == target_key:
                yield val
            # Recurse into nested structures
            if isinstance(val, (dict, list)):
                yield from extract_values_by_key(val, target_key)
    elif isinstance(obj, list):
        for element in obj:
            yield from extract_values_by_key(element, target_key)

