# Retrieve active tax regulations as of specified date
def get_active_tax_rules(as_of_date):
    return TaxRule.query.filter(
        (TaxRule.effective_date <= as_of_date) &
        ((TaxRule.expiration_date == None) | (TaxRule.expiration_date > as_of_date))
    ).all()

# Assess whether provided data satisfies conditions of a tax regulation
def check_conditions(rule, record):
    # Gather all individual conditions for this rule
    conditions = TaxCriterion.query.filter_by(tax_rule_id=rule.tax_rule_id).all()
    # Get how conditions should be combined
    logic = TaxCriterionCombination.query.filter_by(tax_rule_id=rule.tax_rule_id).first()

    outcomes = []
    for condition in conditions:
        field_value = record.get(condition.criterion_field)

        if condition.criterion_type == 'boolean':
            match = field_value == (condition.value == 'true')
        elif condition.criterion_type == 'numeric':
            match = eval(f"{field_value} {condition.operator} {condition.value}")
        elif condition.criterion_type == 'categorical':
            match = field_value == condition.value
        outcomes.append(match)

    # Apply logical combination
    if logic.combination_type == 'and':
        return all(outcomes)
    elif logic.combination_type == 'or':
        return any(outcomes)

# Compute tax liability based on current data and date
def compute_tax(record, as_of_date):
    active_rules = get_active_tax_rules(as_of_date)
    for rule in active_rules:
        if check_conditions(rule, record):
            record['tax_amount'] += record['taxable_amount'] * rule.tax_rate
    return record

# Modified version with renamed variables and reordered logic
from typing import List, Tuple, Dict

class InsufficientBalanceException(Exception):
    pass

def below_zero(transactions: Dict[int, List[Tuple[str, int]]], case_insensitive: bool = False) -> Dict[str, List[int]]:
    """
    Starting with zero balance, implement a system to track deposit and withdrawal operations on different bank accounts. 
    Recognize when a balance turns negative and invoke an "InsufficientBalanceException" at such instances. 
    End the operation by returning a dictionary presenting a list of account numbers that stayed above zero. 
    If a case_insensitive flag is true, interpret 'Deposit' and 'deposit', 'Withdrawal' and 'withdrawal' as identical, 
    and consider the balance at zero as well.

    Input dictionary presents tuples in the structure (Operation_type, Operation_value) as the value and Account_number as the key.
    """

    result_accounts = {}

    for acc_id, op_list in transactions.items():
        current_balance = 0
        for transaction_type, amount in op_list:
            if case_insensitive:
                transaction_type = transaction_type.lower()

            if transaction_type == 'deposit':
                current_balance += amount
            elif transaction_type == 'withdrawal':
                current_balance -= amount
            else:
                raise ValueError(f"Unknown operation type: {transaction_type}")

            # Check for insufficient balance conditions
            if current_balance < 0 or (case_insensitive and current_balance == 0):
                raise InsufficientBalanceException(f'Account {acc_id} has insufficient balance.')

        result_accounts[acc_id] = ['No negative balance']

    return result_accounts

# Example usage:
if __name__ == "__main__":
    try:
        print(below_zero({1: [('Deposit', 1), ('Deposit', 2), ('Deposit', 3)]}))
        print(below_zero({1: [('Deposit', 1), ('Deposit', 2), ('Withdrawal', 4), ('Deposit', 5)]}))
        print(below_zero({1: [('Deposit', 1), ('Deposit', 2), ('withdrawal', 3)]}, True))
    except InsufficientBalanceException as e:
        print(e)

