class StudentRegistry:
    def __init__(self):
        self.learners = {}

    def register_student(self, fullname, years_old):
        if fullname in self.learners:
            raise ValueError(f"Student with name '{fullname}' already exists.")
        self.learners[fullname] = {"age": years_old, "courses": []}

    def deregister_student(self, fullname):
        if fullname not in self.learners:
            raise ValueError(f"Student with name '{fullname}' does not exist.")
        del self.learners[fullname]

    def modify_student_age(self, fullname, years_old):
        if fullname not in self.learners:
            raise ValueError(f"Student with name '{fullname}' does not exist.")
        self.learners[fullname]["age"] = years_old

    def add_course_to_student(self, fullname, coursename, instructor):
        if fullname not in self.learners:
            raise ValueError(f"Student with name '{fullname}' does not exist.")
        course_obj = Course(coursename, instructor)
        if course_obj not in self.learners[fullname]["courses"]:
            self.learners[fullname]["courses"].append(course_obj)

    def drop_course_from_student(self, fullname, coursename):
        if fullname not in self.learners:
            raise ValueError(f"Student with name '{fullname}' does not exist.")
        self.learners[fullname]["courses"] = [crs for crs in self.learners[fullname]["courses"] if crs.coursename != coursename]

    def retrieve_student_info(self, fullname):
        if fullname not in self.learners:
            raise ValueError(f"Student with name '{fullname}' does not exist.")
        return self.learners[fullname]

    def __repr__(self):
        return f"StudentRegistry(learners={self.learners})"

