# Calculate median of a list without using built-in sorting or additional arrays
def find_median_value(values: list, comparison_func: callable):
    """Compute the median value from the list 'values' without creating new arrays or relying on built-in functions.
    The implementation supports both even and odd-length lists, handles duplicate values, uses comparison_func for ordering,
    includes error handling for invalid or non-computable inputs, and ensures the list has at least one item.
    """
    # Validate input data
    if not isinstance(values, list) or not all(isinstance(item, (int, float)) for item in values):
        raise ValueError("Input must be a list of numbers.")
    if len(values) == 0:
        raise ValueError("List must contain at least one element.")
    if not callable(comparison_func):
        raise ValueError("comparison_func must be a callable comparator function.")

    def divide_and_conquer(arr, start, end):
        pivot_val = arr[end]
        boundary = start - 1
        for idx in range(start, end):
            if comparison_func(arr[idx], pivot_val) < 0:
                boundary += 1
                arr[boundary], arr[idx] = arr[idx], arr[boundary]
        arr[boundary + 1], arr[end] = arr[end], arr[boundary + 1]
        return boundary + 1

    def select_kth_element(arr, k, start, finish):
        if start == finish:
            return arr[start]

        pivot_pos = divide_and_conquer(arr, start, finish)

        if k == pivot_pos:
            return arr[k]
        elif k < pivot_pos:
            return select_kth_element(arr, k, start, pivot_pos - 1)
        else:
            return select_kth_element(arr, k, pivot_pos + 1, finish)

    size = len(values)
    if size % 2 == 1:
        # Odd number of elements: return the middle one
        return select_kth_element(values, size // 2, 0, size - 1)
    else:
        # Even number of elements: average the two middle ones
        left_center = select_kth_element(values, size // 2 - 1, 0, size - 1)
        right_center = select_kth_element(values, size // 2, 0, size - 1)
        return (left_center + right_center) / 2

# Test cases
assert find_median_value([3, 1, 2, 4, 5], lambda x, y: x - y) == 3
assert find_median_value([-10, 4, 6, 1000, 10, 20], lambda x, y: x - y) == 15.0
assert find_median_value([1, 2, 2, 4, 5], lambda x, y: x - y) == 2

