    find_median_value([], lambda x, y: x - y)
except ValueError as err:
    assert str(err) == "List must contain at least one element."

try:
    find_median_value([1, 2, 3], None)
except ValueError as err:
    assert str(err) == "comparison_func must be a callable comparator function."

try:
    find_median_value([1, 2, '3'], lambda x, y: x - y)
except ValueError as err:
    assert str(err) == "Input must be a list of numbers."

