# Define a Student class to track academic information
class Learner:
    def __init__(self, full_name, institution, year, average):
        self.full_name = full_name
        self.institution = institution
        self.year = year
        self.average = average
        self.enrollments = []

    def change_year(self, new_year):
        if not isinstance(new_year, int):
            raise TypeError("Year must be an integer.")
        if new_year < 1 or new_year > 12:
            raise ValueError("Year must be between 1 and 12.")
        self.year = new_year

    def modify_average(self, new_average):
        if not isinstance(new_average, (int, float)):
            raise TypeError("Average must be a numeric value.")
        if new_average < 0.0 or new_average > 4.0:
            raise ValueError("Average must be between 0.0 and 4.0.")
        self.average = new_average

    def register_course(self, course_title):
        if len(self.enrollments) >= 7:
            raise ValueError("A learner cannot register for more than 7 courses.")
        if course_title in self.enrollments:
            raise ValueError(f"Course {course_title} is already registered.")
        self.enrollments.append(course_title)

    def compute_average(self, course_scores):
        if not isinstance(course_scores, dict):
            raise TypeError("Course scores must be provided as a dictionary.")
        if set(course_scores.keys()) != set(self.enrollments):
            raise ValueError("Course scores must include all registered courses.")

        total_credits = 0
        weighted_sum = 0

        for course_name, score in course_scores.items():
            if not isinstance(score, (int, float)):
                raise TypeError(f"Score for course {course_name} must be numeric.")
            if score < 0.0 or score > 100.0:
                raise ValueError(f"Score for course {course_name} must be between 0.0 and 100.0.")

            # Each course carries equal credit weight (e.g., 4 credits)
            credits = 4
            total_credits += credits
            weighted_sum += score * credits

        if total_credits == 0:
            raise ValueError("Total credits cannot be zero.")

        computed_average = weighted_sum / total_credits / 100 * 4.0
        return computed_average

