#!/usr/bin/env python3
import os
import subprocess
import time
import signal
import concurrent.futures

os.makedirs("temp_dir", exist_ok=True)
os.chdir("temp_dir")

def build_and_execute(val):
    file_name = f"sample_{val}.c"
    with open(file_name, "w") as fp:
        fp.write(f"const main={val};")

    try:
        subprocess.run(["gcc", file_name, "-o", f"sample_{val}"], check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except subprocess.CalledProcessError as err:
        return f"const main={hex(val)} : Compilation failed: {err.stderr.decode().strip()}"

    proc = subprocess.Popen(f"./sample_{val}", shell=True)
    exit_status = proc.wait()

    if exit_status == -11:
        exit_status = "segfault"
    elif exit_status == -10:
        exit_status = "bus error"
    elif exit_status == -4:
        exit_status = "illegal instruction"
    elif exit_status == -5:
        exit_status = "trap"
    else:
        exit_status = f"exit code {exit_status}"

    return f"const main={hex(val)} : {exit_status}"

with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:
    tasks = [pool.submit(build_and_execute, j) for j in range(65536)]
    for task in concurrent.futures.as_completed(tasks):
        print(task.result())

# Convert SQL query to Elasticsearch query format
import sqlparse
import json

def convert_sql_to_elasticsearch(sql_statement):
    try:
        parsed = sqlparse.parse(sql_statement)
        if not parsed:
            raise ValueError("Invalid SQL statement")

        statement = parsed[0]
        es_body = {}

        # Extract SELECT fields
        select_tokens = [token for token in statement.tokens if isinstance(token, sqlparse.sql.IdentifierList) or isinstance(token, sqlparse.sql.Identifier)]
        selected_columns = [col.value for col in select_tokens[0].tokens if isinstance(col, sqlparse.sql.Identifier)]

        es_body['_source'] = selected_columns

        # Extract FROM clause (table name)
        from_tokens = [token for token in statement.tokens if isinstance(token, sqlparse.sql.Identifier) and token.value.lower() != 'from']
        table_name = from_tokens[0].value
        es_body['index'] = table_name

        # Extract WHERE conditions
        where_tokens = [token for token in statement.tokens if isinstance(token, sqlparse.sql.Where)]
        if where_tokens:
            es_body['query'] = {'bool': {'must': []}}
            where_parts = extract_where_conditions(where_tokens[0])
            es_body['query']['bool']['must'].extend(where_parts)

        # Extract GROUP BY clause
        group_by_tokens = [token for token in statement.tokens if isinstance(token, sqlparse.sql.Token) and token.value.lower() == 'group by']
        if group_by_tokens:
            group_result = extract_group_by(statement)
            es_body['aggs'] = group_result

        # Extract HAVING clause
        having_tokens = [token for token in statement.tokens if isinstance(token, sqlparse.sql.Token) and token.value.lower() == 'having']
        if having_tokens:
            having_result = extract_having_conditions(statement)
            es_body['query']['bool']['filter'] = having_result

        return json.dumps(es_body, indent=4)
    except Exception as ex:
        return f"Error: {str(ex)}"

def extract_where_conditions(where_part):
    filter_list = []
    for token in where_part.tokens:
        if isinstance(token, sqlparse.sql.Comparison):
            filter_list.append(build_comparison_filter(token))
        elif isinstance(token, sqlparse.sql.Token) and token.value.lower() in ('and', 'or'):
            filter_list.append(token.value.lower())
    return filter_list

def build_comparison_filter(comparison_expr):
    left_side = comparison_expr.left.value
    right_side = comparison_expr.right.value
    op_symbol = comparison_expr.token_next(0, skip_cm=True).value

    if op_symbol == '=':
        return {'term': {left_side: right_side}}
    elif op_symbol == '!=':
        return {'bool': {'must_not': {'term': {left_side: right_side}}}}
    elif op_symbol in ('>', '<', '>=', '<='):
        return {'range': {left_side: {op_symbol: right_side}}}
    elif op_symbol == 'like':
        return {'wildcard': {left_side: right_side}}
    elif op_symbol == 'in':
        value_list = [val.value for val in comparison_expr.right.get_identifiers()]
        return {'terms': {left_side: value_list}}
    else:
        raise ValueError(f"Unsupported operator: {op_symbol}")

def extract_group_by(statement_obj):
    group_result = {}
    for token in statement_obj.tokens:
        if isinstance(token, sqlparse.sql.Token) and token.value.lower() == 'group by':
            group_fields = [field.value for field in statement_obj.tokens[token.pos + 1].get_identifiers()]
            group_result = {'grouping': {}}
            for field in group_fields:
                group_result['grouping'][field] = {'terms': {'field': field}}
            break
    return group_result

def extract_having_conditions(statement_obj):
    having_filters = []
    for token in statement_obj.tokens:
        if isinstance(token, sqlparse.sql.Token) and token.value.lower() == 'having':
            having_filters = extract_where_conditions(token)
            break
    return having_filters

# Example usage
sql_input = """
SELECT name, age
FROM users
WHERE age > 25 AND name LIKE 'J%'
GROUP BY name
HAVING COUNT(name) > 1
"""

es_output = convert_sql_to_elasticsearch(sql_input)
print(es_output)

# Modified version of CostCenterManager with renamed variables and reordered logic
import json
import os

class CostCenterController:
    def __init__(self, data_file='records/cost_centers.json'):
        self.data_path = data_file
        self.cost_center_list = self._load_data()
        if not self.cost_center_list:
            self.current_id = 1
        else:
            self.current_id = max(int(item['identifier']) for item in self.cost_center_list) + 1

    def _load_data(self):
        if os.path.isfile(self.data_path):
            with open(self.data_path, 'r') as f:
                return json.load(f)
        return []

    def _save_data(self):
        with open(self.data_path, 'w') as f:
            json.dump(self.cost_center_list, f, indent=4)

    def _validate_entry(self, proj_name, labels, state):
        if len(proj_name) > 50 or len(labels) > 50:
            raise ValueError("Project name and labels must not exceed 50 characters.")
        if state not in ['active', 'inactive']:
            raise ValueError("State must be either 'active' or 'inactive'.")

    def _verify_admin_access(self, actor, label):
        if label == 'admin_only' and actor != 'admin':
            raise PermissionError("Only users with admin privileges can modify cost centers with the 'admin_only' label.")

    def create_cost_center(self, actor, proj_name, labels, state):
        self._validate_entry(proj_name, labels, state)
        self._verify_admin_access(actor, labels)

        entry = {
            'identifier': self.current_id,
            'project_name': proj_name,
            'labels': labels,
            'state': state
        }
        self.cost_center_list.append(entry)
        self._save_data()
        self.current_id += 1
        return entry

    def modify_cost_center(self, actor, cc_id, proj_name=None, labels=None, state=None):
        cost_center = next((cc for cc in self.cost_center_list if cc['identifier'] == cc_id), None)
        if not cost_center:
            raise ValueError(f"Cost center with ID {cc_id} does not exist.")

        if labels:
            self._verify_admin_access(actor, labels)

        if proj_name:
            self._validate_entry(proj_name, cost_center['labels'], cost_center['state'])
            cost_center['project_name'] = proj_name

        if labels:
            self._validate_entry(cost_center['project_name'], labels, cost_center['state'])
            cost_center['labels'] = labels

        if state:
            self._validate_entry(cost_center['project_name'], cost_center['labels'], state)
            cost_center['state'] = state

        self._save_data()
        return cost_center

    def remove_cost_center(self, actor, cc_id):
        cost_center = next((cc for cc in self.cost_center_list if cc['identifier'] == cc_id), None)
        if not cost_center:
            raise ValueError(f"Cost center with ID {cc_id} does not exist.")

        self._verify_admin_access(actor, cost_center['labels'])

        self.cost_center_list.remove(cost_center)
        self._save_data()
        return cost_center

# Example usage:
if __name__ == "__main__":
    controller = CostCenterController()

    # Create a new cost center
    new_cc = controller.create_cost_center('admin', 'Project X', 'admin_only', 'active')
    print("Created Cost Center:", new_cc)

    # Modify an existing cost center
    modified_cc = controller.modify_cost_center('admin', new_cc['identifier'], proj_name='Project Y', labels='public', state='inactive')
    print("Modified Cost Center:", modified_cc)

    # Remove a cost center
    removed_cc = controller.remove_cost_center('admin', new_cc['identifier'])
    print("Removed Cost Center:", removed_cc)

