# Generate a list of dictionaries with unique identifiers and optional nesting
import uuid

def create_dict_list(count, key_list=None, val_list=None, add_nested=False):
    if key_list is None:
        key_list = []
    if val_list is None:
        val_list = []

    # Remove duplicates while preserving order
    distinct_keys = list(dict.fromkeys(key_list))
    distinct_vals = list(dict.fromkeys(val_list))

    # Prepare the output container
    output = []

    # Create dictionaries using provided keys
    for k in distinct_keys:
        if len(output) >= count:
            break
        inner_dict = {str(uuid.uuid4()): None} if add_nested else {}
        output.append({k: inner_dict})

    # Create dictionaries using provided values
    for idx, v in enumerate(distinct_vals):
        if len(output) >= count:
            break
        inner_dict = {idx: v} if v is not None else {str(uuid.uuid4()): None}
        if add_nested and not inner_dict:
            inner_dict = {str(uuid.uuid4()): None}
        output.append({str(uuid.uuid4()): inner_dict})

    # Fill remaining slots with random keys and nested structures
    while len(output) < count:
        random_key = str(uuid.uuid4())
        inner_dict = {str(uuid.uuid4()): None} if add_nested else {}
        output.append({random_key: inner_dict})

    return output

