# Calculate and verify a Pythagorean quadruplet for a given sum
import time
import math

def check_quadruplet_condition(x1, x2, x3, x4):
    """
    Determine if the numbers satisfy the Pythagorean quadruplet condition.
    """
    return x1**2 + x2**2 + x3**2 == x4**2

def search_for_quadruplet(target_sum):
    """
    Search for the smallest Pythagorean quadruplet that sums to target_sum.

    :param target_sum: The desired total sum of the quadruplet.
    :return: A tuple (x1, x2, x3, x4) if found, otherwise None.
    """
    for x1 in range(1, target_sum):
        for x2 in range(x1, target_sum - x1):
            for x3 in range(x2, target_sum - x1 - x2):
                x4 = target_sum - x1 - x2 - x3
                if x4 > x3 and check_quadruplet_condition(x1, x2, x3, x4):
                    return (x1, x2, x3, x4)
    return None

def execute_search(target_sum):
    """
    Main function to find and validate the Pythagorean quadruplet while measuring execution time.

    :param target_sum: The desired total sum of the quadruplet.
    """
    if not isinstance(target_sum, int):
        raise ValueError("Input must be an integer.")

    start_time = time.time()

    result = search_for_quadruplet(target_sum)

    end_time = time.time()
    elapsed_time = end_time - start_time

    if result:
        x1, x2, x3, x4 = result
        print(f"Found Pythagorean quadruplet: {result}")
        print(f"Verification: {x1}^2 + {x2}^2 + {x3}^2 = {x4}^2")
        print(f"Sum: {x1} + {x2} + {x3} + {x4} = {target_sum}")
    else:
        print("No Pythagorean quadruplet found for the given sum.")

    print(f"Execution time: {elapsed_time:.6f} seconds")

if __name__ == "__main__":
    target_sum = 30
    try:
        execute_search(target_sum)
    except ValueError as e:
        print(e)

# Calculate a mathematical expression that evaluates to the target value
import itertools
import math
from typing import List, Tuple

def create_expression(values: List[int], goal: int, permit_repeats: bool) -> Tuple[str, int]:
    def compute_result(formula: str) -> float:
        try:
            return eval(formula)
        except ZeroDivisionError:
            return float('inf')
        except Exception:
            return float('nan')

    def check_validity(formula: str) -> bool:
        try:
            eval(formula)
            return True
        except:
            return False

    def construct_formulas(nums: List[int], goal: int, max_depth: int) -> Tuple[str, int]:
        if not nums:
            return "", -1

        # Generate all permutations of the input numbers
        all_permutations = list(itertools.permutations(nums))
        if not permit_repeats:
            all_permutations = list(set(all_permutations))

        # Define available mathematical operations
        ops_list = ['+', '-', '*', '/', '**', 'math.log']

        for perm in all_permutations:
            for depth in range(1, max_depth + 1):
                for combo in itertools.product(ops_list, repeat=depth):
                    formula = str(perm[0])
                    count = 1
                    for j, operator in enumerate(combo):
                        if count < len(perm):
                            if operator == 'math.log':
                                if perm[count] > 0 and perm[count] != 1:
                                    formula += f" {operator}({perm[count]})"
                                    count += 1
                                else:
                                    break
                            else:
                                formula += f" {operator} {perm[count]}"
                                count += 1
                        else:
                            break

                    if check_validity(formula):
                        value = compute_result(formula)
                        if math.isclose(value, goal, rel_tol=1e-9):
                            return formula, depth

        return "", -1

    # Limit the maximum number of operations
    max_depth = 5
    formula, depth = construct_formulas(values, goal, max_depth)
    return formula, depth

