print(f"Depth: {depth}")

# Count occurrences of substring in string (overlapping allowed)
def count_occurrences(text, pattern):
    if not pattern or not text:
        return 0

    occurrences = 0
    index = 0

    while True:
        position = text.find(pattern, index)
        if position == -1:
            break
        occurrences += 1
        index = position + 1

    return occurrences

# Modified version with Type I clone transformations applied
import json
from concurrent.futures import TimeoutError as FutureTimeout
import main

def _receive_json_with_timeout(websocket_conn, *, timeout_s: float = 1.0):
    future_obj = websocket_conn.portal.start_task_soon(websocket_conn._send_rx.receive)
    try:
        message = future_obj.result(timeout=timeout_s)
    except FutureTimeout:
        # Best-effort: close to unblock the pending receive task.
        try:
            websocket_conn.close()
        except Exception:
            pass
        try:
            future_obj.result(timeout=2.0)
        except Exception:
            pass
        raise AssertionError("Timed out waiting for WebSocket message")
    websocket_conn._raise_on_close(message)
    return json.loads(message["text"])


