# GPU utility function emitters for MLIR
from mlir.dialects import func, gpu, bufferization, arith

def convert_memref_to_tensor(memref_val: ir.Value, **opts) -> ir.Value:
    memref_typ = memref_val.type
    dims = memref_typ.shape
    elem_typ = memref_typ.element_type
    tensor_typ = ir.RankedTensorType.get(dims, elem_typ)
    return bufferization.to_tensor(tensor_typ, memref_val, **opts)

def create_gpu_alloc(suffix: str, element_type: ir.Type, ndim: int = 2):
    dynamic = ir.ShapedType.get_dynamic_size()
    memref_dynamic_t = ir.MemRefType.get(ndim * (dynamic,), element_type)
    index_typ = ir.IndexType.get()
    i32_typ = ir.IntegerType.get_signless(32)
    arg_types = ndim * (i32_typ,)

    @func.func(*arg_types, name="gpu_alloc_" + suffix)
    def alloc_impl(*shape_args):
        dim_list = [arith.index_cast(index_typ, arg) for arg in shape_args]
        allocation = gpu.alloc(memref_dynamic_t, None, [], dim_list, [])
        return allocation

    alloc_impl.func_op.attributes["llvm.emit_c_interface"] = ir.UnitAttr.get()

def create_gpu_dealloc(suffix: str, element_type: ir.Type, ndim: int = 2):
    dynamic = ir.ShapedType.get_dynamic_size()
    memref_dynamic_t = ir.MemRefType.get(ndim * (dynamic,), element_type)

    @func.func(memref_dynamic_t, name="gpu_dealloc_" + suffix)
    def dealloc_impl(memref_buffer):
        gpu.dealloc(None, [], memref_buffer)

    dealloc_impl.func_op.attributes["llvm.emit_c_interface"] = ir.UnitAttr.get()

def create_gpu_copy(suffix: str, element_type: ir.Type, ndim: int = 2):
    """Generate GPU memory copy function."""
    dynamic = ir.ShapedType.get_dynamic_size()
    memref_dynamic_t = ir.MemRefType.get(ndim * (dynamic,), element_type)

    @func.func(memref_dynamic_t, memref_dynamic_t, name="gpu_copy_" + suffix)
    def copy_impl(source, destination):
        gpu.memcpy(None, [], destination, source)

    copy_impl.func_op.attributes["llvm.emit_c_interface"] = ir.UnitAttr.get()

def register_gpu_util_funcs(element_type: ir.Type):
    """Register GPU utility functions for memory management and data transfer."""
    suffix_map = {
        ir.F16Type: "f16",
        ir.F32Type: "f32",
    }
    suffix = suffix_map[type(element_type)]
    create_gpu_alloc(suffix, element_type)
    create_gpu_dealloc(suffix, element_type)
    create_gpu_copy(suffix, element_type)

# Function to sort numbers by their digit sum
def arrange_by_digit_total(values):
    """
    Implement a function that arranges the provided list of integers
    in ascending order based on the sum of their individual digits.
    Note: if multiple elements have the same digit sum,
    maintain their original relative ordering.
    For example:
    >>> arrange_by_digit_total([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> arrange_by_digit_total([]) == []
    """
    def calculate_digit_sum(num):
        num_str = str(num)
        if num_str[0] == '-':
            return -int(num_str[1]) + sum(int(digit) for digit in num_str[2:])
        else:
            return sum(int(digit) for digit in num_str)

    return sorted(values, key=calculate_digit_sum)

import sys
from pypdf import PdfReader
# Extracts data for the fillable form fields in a PDF and outputs JSON that
# Claude uses to fill the fields. See forms.md.
# This matches the format used by PdfReader `get_fields` and `update_page_form_field_values` methods.
def get_full_annotation_field_id(annotation):
    parts = []
    while annotation:
        field_name = annotation.get('/T')
        if field_name:
            parts.append(field_name)
        annotation = annotation.get('/Parent')
    return ".".join(reversed(parts)) if parts else None

def create_field_dict(field, field_identifier):
    field_dict = {"field_id": field_identifier}
    ft = field.get('/FT')
    if ft == "/Tx":
        field_dict["type"] = "text"
    elif ft == "/Btn":
        field_dict["type"] = "checkbox"  # radio groups handled separately
        states = field.get("/_States_", [])
        if len(states) == 2:
            # "/Off" seems to always be the unchecked value, as suggested by
            # https://opensource.adobe.com/dc-acrobat-sdk-docs/standards/pdfstandards/pdf/PDF32000_2008.pdf#page=448
            # It can be either first or second in the "/_States_" list.
            if "/Off" in states:
                field_dict["checked_value"] = states[0] if states[0] != "/Off" else states[1]
                field_dict["unchecked_value"] = "/Off"
            else:
                print(f"Unexpected state values for checkbox `${field_identifier}`. Its checked and unchecked values may not be correct; if you're trying to check it, visually verify the results.")
                field_dict["checked_value"] = states[0]
                field_dict["unchecked_value"] = states[1]
    elif ft == "/Ch":
        field_dict["type"] = "choice"
        states = field.get("/_States_", [])
        field_dict["choice_options"] = [{
            "value": state[0],
            "text": state[1],
        } for state in states]
    else:
        field_dict["type"] = f"unknown ({ft})"
    return field_dict

# Returns a list of fillable PDF fields:
# [
#   {
#     "field_id": "name",
#     "page": 1,
#     "type": ("text", "checkbox", "radio_group", or "choice")
#     // Per-type additional fields described in forms.md
#   },
# ]
def extract_field_info(reader: PdfReader):
    fields = reader.get_fields()
    field_map = {}
    potential_radio_names = set()

    for field_id, field in fields.items():
        # Skip if this is a container field with children, except that it might be
        # a parent group for radio button options.
        if field.get("/Kids"):
            if field.get("/FT") == "/Btn":
                potential_radio_names.add(field_id)
            continue
        field_map[field_id] = create_field_dict(field, field_id)

    # Bounding rects are stored in annotations in page objects.
    # Radio button options have a separate annotation for each choice;
    # all choices have the same field name.
    # See https://westhealth.github.io/exploring-fillable-forms-with-pdfrw.html
    radio_map = {}
    for page_index, page in enumerate(reader.pages):
        annotations = page.get('/Annots', [])
        for ann in annotations:
            field_id = get_full_annotation_field_id(ann)
            if field_id in field_map:
                field_map[field_id]["page"] = page_index + 1
                field_map[field_id]["rect"] = ann.get('/Rect')
            elif field_id in potential_radio_names:
                try:
                    # ann['/AP']['/N'] should have two items. One of them is '/Off',
                    # the other is the active value.
                    on_values = [v for v in ann["/AP"]["/N"] if v != "/Off"]
                except KeyError:
                    continue
                if len(on_values) == 1:
                    rect = ann.get("/Rect")
                    if field_id not in radio_map:
                        radio_map[field_id] = {
                            "field_id": field_id,
                            "type": "radio_group",
                            "page": page_index + 1,
                            "radio_options": [],
                        }
                    # Note: at least on macOS 15.7, Preview.app doesn't show selected
                    # radio buttons correctly. (It does if you remove the leading slash
                    # from the value, but that causes them not to appear correctly in
                    # Chrome/Firefox/Acrobat/etc).
                    radio_map[field_id]["radio_options"].append({
                        "value": on_values[0],
                        "rect": rect,
                    })

    # Some PDFs have form field definitions without corresponding annotations,
    # so we can't tell where they are. Ignore these fields for now.
    fields_with_location = []
    for field_info in field_map.values():
        if "page" in field_info:
            fields_with_location.append(field_info)
        else:
            print(f"Unable to determine location for field id: {field_info.get('field_id')}, ignoring")

    # Sort by page number, then Y position (flipped in PDF coordinate system), then X.
    def sort_key(f):
        if "radio_options" in f:
            rect = f["radio_options"][0]["rect"] or [0, 0, 0, 0]
        else:
            rect = f.get("rect") or [0, 0, 0, 0]
        adjusted_position = [-rect[1], rect[0]]
        return [f.get("page"), adjusted_position]

    sorted_fields = fields_with_location + list(radio_map.values())
    sorted_fields.sort(key=sort_key)
    return sorted_fields

def save_field_info(pdf_path: str, json_output_path: str):
    reader = PdfReader(pdf_path)
    field_info = extract_field_info(reader)
    with open(json_output_path, "w") as f:
        import json
        json.dump(field_info, f, indent=2)
    print(f"Wrote {len(field_info)} fields to {json_output_path}")

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: extract_form_field_info.py [input pdf] [output json]")
        sys.exit(1)
    save_field_info(sys.argv[1], sys.argv[2])

