class FileBucketingStrategy:
    def get_buckets(self, input_file_path, is_prompt_mode):
        prompt_list = []
        decode_list = []
        with open(input_file_path, 'r') as file_handle:
            for current_line in file_handle:
                current_line = current_line.strip()
                if not current_line or current_line.startswith('#'):
                    continue
                try:
                    bucket_data = eval(current_line, {"__builtins__": None}, {"range": range})
                except Exception as error:
                    print(f"Skipping line due to eval error: {error} - {current_line}")
                    continue
                if not isinstance(bucket_data, tuple) or len(bucket_data) != 3:
                    print('Skipping line due to incorrect format - ', bucket_data)
                    continue
                x_values = convert_to_list(bucket_data[0])
                y_values = convert_to_list(bucket_data[1])
                z_values = convert_to_list(bucket_data[2])
                for combined_bucket in itertools.product(x_values, y_values, z_values):
                    x_val, y_val, z_val = map(int, combined_bucket)
                    if y_val == 1:
                        decode_list.append((x_val, y_val, z_val))
                    else:
                        prompt_list.append((x_val, y_val, z_val))
        return sorted(prompt_list) if is_prompt_mode else sorted(decode_list)

def convert_to_list(data_value):
    if isinstance(data_value, list):
        return data_value
    elif isinstance(data_value, range):
        return list(data_value)
    else:
        return [data_value]

