import librosa.filters
import numpy as np
# import tensorflow as tf
from scipy import signal
from scipy.io import wavfile
from src.utils.hparams import hparams as hp

def load_audio(path, sample_rate):
    return librosa.core.load(path, sr=sample_rate)[0]

def save_audio(audio_data, output_path, sample_rate):
    audio_data *= 32767 / max(0.01, np.max(np.abs(audio_data)))
    # Suggested by @dsmiller
    wavfile.write(output_path, sample_rate, audio_data.astype(np.int16))

def save_wavenet_audio(audio_data, output_path, sample_rate):
    librosa.output.write_wav(output_path, audio_data, sr=sample_rate)

def apply_preemphasis(audio_signal, alpha, do_preemph=True):
    if do_preemph:
        return signal.lfilter([1, -alpha], [1], audio_signal)
    return audio_signal

def apply_inverse_preemphasis(audio_signal, alpha, do_inv_preemph=True):
    if do_inv_preemph:
        return signal.lfilter([1], [1, -alpha], audio_signal)
    return audio_signal

def compute_hop_length():
    hop_len = hp.hop_size
    if hop_len is None:
        assert hp.frame_shift_ms is not None
        hop_len = int(hp.frame_shift_ms / 1000 * hp.sample_rate)
    return hop_len

def linear_spectrogram(audio_signal):
    D = _stft(apply_preemphasis(audio_signal, hp.preemphasis, hp.preemphasize))
    S = _amp_to_db(np.abs(D)) - hp.ref_level_db

    if hp.signal_normalization:
        return _normalize(S)
    return S

def mel_spectrogram(audio_signal):
    D = _stft(apply_preemphasis(audio_signal, hp.preemphasis, hp.preemphasize))
    S = _amp_to_db(_linear_to_mel(np.abs(D))) - hp.ref_level_db

    if hp.signal_normalization:
        return _normalize(S)
    return S

def _create_lws_instance():
    import lws
    return lws.lws(hp.n_fft, compute_hop_length(), fftsize=hp.win_size, mode="speech")

def _compute_stft(y):
    if hp.use_lws:
        return _create_lws_instance(hp).stft(y).T
    else:
        return librosa.stft(y=y, n_fft=hp.n_fft, hop_length=compute_hop_length(), win_length=hp.win_size)

##########################################################
# These are only accurate when using lws!!! (This was causing issues with Wavenet quality for a long time!)
def count_frames(signal_length, frame_size, frame_shift):
    """Estimate the number of spectrogram frames
    """
    padding = (frame_size - frame_shift)
    if signal_length % frame_shift == 0:
        num = (signal_length + padding * 2 - frame_size) // frame_shift + 1
    else:
        num = (signal_length + padding * 2 - frame_size) // frame_shift + 2
    return num

def compute_padding_bounds(x, frame_size, frame_shift):
    """Calculate left and right padding values
    """
    num_frames = count_frames(len(x), frame_size, frame_shift)
    padding = (frame_size - frame_shift)
    total_len = len(x) + 2 * padding
    remainder = (num_frames - 1) * frame_shift + frame_size - total_len
    return padding, padding + remainder
##########################################################

# Librosa's correct padding method
def librosa_compute_padding(x, frame_size, frame_shift):
    return 0, (x.shape[0] // frame_shift + 1) * frame_shift - x.shape[0]

# Conversion utilities
_mel_filterbank = None

def _convert_to_mel(linear_spec):
    global _mel_filterbank
    if _mel_filterbank is None:
        _mel_filterbank = _construct_mel_filterbank()
    return np.dot(_mel_filterbank, linear_spec)

def _construct_mel_filterbank():
    assert hp.fmax <= hp.sample_rate // 2
    return librosa.filters.mel(sr=hp.sample_rate, n_fft=hp.n_fft, n_mels=hp.num_mels,
                               fmin=hp.fmin, fmax=hp.fmax)

def _amplitude_to_db(x):
    min_val = np.exp(hp.min_level_db / 20 * np.log(10))
    return 20 * np.log10(np.maximum(min_val, x))

def _db_to_amplitude(x):
    return np.power(10.0, x * 0.05)

def _normalize_spectrum(S):
    if hp.allow_clipping_in_normalization:
        if hp.symmetric_mels:
            return np.clip((2 * hp.max_abs_value) * ((S - hp.min_level_db) / (-hp.min_level_db)) - hp.max_abs_value,
                           -hp.max_abs_value, hp.max_abs_value)
        else:
            return np.clip(hp.max_abs_value * ((S - hp.min_level_db) / (-hp.min_level_db)), 0, hp.max_abs_value)

    assert S.max() <= 0 and S.min() - hp.min_level_db >= 0
    if hp.symmetric_mels:
        return (2 * hp.max_abs_value) * ((S - hp.min_level_db) / (-hp.min_level_db)) - hp.max_abs_value
    else:
        return hp.max_abs_value * ((S - hp.min_level_db) / (-hp.min_level_db))

def _denormalize_spectrum(D):
    if hp.allow_clipping_in_normalization:
        if hp.symmetric_mels:
            return (((np.clip(D, -hp.max_abs_value,
                              hp.max_abs_value) + hp.max_abs_value) * -hp.min_level_db / (2 * hp.max_abs_value))
                    + hp.min_level_db)
        else:
            return ((np.clip(D, 0, hp.max_abs_value) * -hp.min_level_db / hp.max_abs_value) + hp.min_level_db)

    if hp.symmetric_mels:
        return (((D + hp.max_abs_value) * -hp.min_level_db / (2 * hp.max_abs_value)) + hp.min_level_db)
    else:
        return ((D * -hp.min_level_db / hp.max_abs_value) + hp.min_level_db)

