def verify_structure(root_dir="memory/personality/"):
    result = {"pillars": {}, "overall": "GREEN"}

    for item in PILLARS:
        full_path = os.path.join(root_dir, item)
        found = os.path.exists(full_path)
        status = "EXISTS" if found else "MISSING"
        result["pillars"][item] = status
        if not found:
