    result["pillars"]["core_memories/"] = "EXISTS" if dir_exists else "MISSING"
    if not dir_exists:
        result["overall"] = "RED"

    return result

def update_vault(root_dir="memory/personality/"):
    vault_data = {"timestamp": "", "identity": {}, "status": "INITIALIZED"}

    for section in PILLARS:
        file_path = os.path.join(root_dir, section)
        if os.path.exists(file_path):
            with open(file_path, 'r') as file:
