# Security audit script for detecting potential risks in skill.md files
EXFIL_LIST = [r"http[s]?://", r"webhook", r"pastebin", r"ngrok", r"tunnel", r"request\.bin", r"discordapp"]
FILES_LIST = [r"\.env", r"\.ssh", r"/etc/", r"credentials", r"token", r"apikey", r"private"]
SHELL_LIST = [r"curl .*\| bash", r"chmod \+x", r"sudo", r"rm -rf"]
detection_rules = [("EXFIL", EXFIL_LIST), ("FILES", FILES_LIST), ("SHELL", SHELL_LIST)]
risk_level = 0
detected_issues = []
input_file = pathlib.Path(sys.argv[1]) if len(sys.argv) > 1 else None
if not input_file or not input_file.exists():
    print("Usage: python audit.py path/to/skill.md", file=sys.stderr)
    sys.exit(1)
content = input_file.read_text(errors="ignore")
line_list = content.splitlines()
for idx, current_line in enumerate(line_list, 1):
    lower_line = current_line.lower()
    for category, regex_patterns in detection_rules:
        for pattern in regex_patterns:
            if re.search(pattern, lower_line):
                detected_issues.append({"line_num": idx, "category": category, "text": current_line.strip()[:200]})
                if category == "EXFIL":
                    risk_level += 3
                elif category == "FILES":
                    risk_level += 2
