# Custom fused LeakyReLU implementation with JIT compilation support
import os
import torch
from torch import nn
from torch.autograd import Function

# Check for JIT compilation environment variable
JIT_MODE = os.getenv('BASICSR_JIT')
if JIT_MODE == 'True':
    from torch.utils.cpp_extension import load
    current_dir = os.path.dirname(__file__)
    fused_module = load(
        'fused',
        sources=[
            os.path.join(current_dir, 'src', 'fused_bias_act.cpp'),
            os.path.join(current_dir, 'src', 'fused_bias_act_kernel.cu'),
        ],
    )
else:
    try:
        from . import fused_act_ext as fused_module
    except ImportError:
        pass
        # avoid annoying print output
        # print(f'Cannot import fused_module. Error: {error}. You may need to: \n '
        #       '1. compile with BASICSR_EXT=True. or\n '
        #       '2. set BASICSR_JIT=True during running')

class FusedLeakyReLUBackward(Function):
    @staticmethod
    def forward(ctx, grad_out, activation_out, slope, scale_factor):
        ctx.save_for_backward(activation_out)
        ctx.slope = slope
        ctx.scale_factor = scale_factor
        dummy_tensor = grad_out.new_empty(0)
        grad_in = fused_module.fused_bias_act(grad_out, dummy_tensor, activation_out, 3, 1, slope, scale_factor)
        reduction_dims = [0]
        if grad_in.dim() > 2:
            reduction_dims.extend(range(2, grad_in.dim()))
        grad_b = grad_in.sum(reduction_dims).detach()
        return grad_in, grad_b

    @staticmethod
    def backward(ctx, grad_grad_in, grad_grad_b):
        activation_out, = ctx.saved_tensors
        grad_grad_out = fused_module.fused_bias_act(grad_grad_in, grad_grad_b, activation_out, 3, 1,
                                                    ctx.slope, ctx.scale_factor)
        return grad_grad_out, None, None, None

class FusedLeakyReLUForward(Function):
    @staticmethod
    def forward(ctx, x_input, bias_param, slope, scale_factor):
        dummy_tensor = x_input.new_empty(0)
        output = fused_module.fused_bias_act(x_input, bias_param, dummy_tensor, 3, 0, slope, scale_factor)
        ctx.save_for_backward(output)
        ctx.slope = slope
        ctx.scale_factor = scale_factor
        return output

    @staticmethod
    def backward(ctx, grad_output):
        output, = ctx.saved_tensors
        grad_in, grad_bias = FusedLeakyReLUBackward.apply(grad_output, output, ctx.slope, ctx.scale_factor)
        return grad_in, grad_bias, None, None

class FusedLeakyReLU(nn.Module):
    def __init__(self, num_channels, slope=0.2, scale=2**0.5):
        super().__init__()
        self.bias_param = nn.Parameter(torch.zeros(num_channels))
        self.slope = slope
        self.scale = scale

    def forward(self, input_tensor):
        return custom_leaky_relu(input_tensor, self.bias_param, self.slope, self.scale)

def custom_leaky_relu(input_tensor, bias, slope=0.2, scale=2**0.5):
    return FusedLeakyReLUForward.apply(input_tensor, bias, slope, scale)

