class ConfigWrapper:
    """A utility to enable dot notation access for dictionary data."""
    def __init__(self, payload):
        self._payload = payload

    def __getattr__(self, attr_name):
        try:
            result = self._payload[attr_name]
            # Recursively wrap nested dictionaries for chained access (e.g., config.dataset.params)
            if isinstance(result, dict):
                return ConfigWrapper(result)
            return result
        except KeyError as error:
            raise AttributeError(f"Missing configuration key: {attr_name}") from error

    def __getitem__(self, index_key):
