# Check if the array can be sorted by rotating it
def check_sorted_by_rotation(arr):
    if len(arr) == 0:
        return True

    # Count the number of "drops" where arr[i] > arr[i+1]
    # In a rotated sorted array, there should be at most one such drop
    drops = 0
    length = len(arr)

    for index in range(length):
        if arr[index] > arr[(index + 1) % length]:
            drops += 1

    # If there's at most one drop, the array can be sorted by rotation
    return drops <= 1

from transformers import CLIPVisionModel
from megatron.training import get_args
from mindspeed_mm.data.data_utils.transform_pipeline import get_transforms


class WanVideoI2VProcessor(torch.nn.Module):
    def __init__(self, config):
        super().__init__()
        args = get_args()

        shape_config = {
            "max_height": args.mm.data.dataset_param.preprocess_parameters.max_height,
            "max_width": args.mm.data.dataset_param.preprocess_parameters.max_width,
            "max_hxw": args.mm.data.dataset_param.preprocess_parameters.max_hxw,
        }

        if "image_encoder" in config:
            self.visual_backbone = CLIPVisionModel.from_pretrained(config["image_encoder"]).eval()

            first_frame_clip_settings = {
                "video": args.mm.data.dataset_param.preprocess_parameters.train_pipeline.first_frame_clip
            }

            self.clip_first_frame_transform = get_transforms(
                is_video=True, train_pipeline=first_frame_clip_settings, transform_size=shape_config
            )
        else:
            self.visual_backbone = None
            self.clip_first_frame_transform = None

        first_frame_vae_settings = {
            "video": args.mm.data.dataset_param.preprocess_parameters.train_pipeline.first_frame_vae
        }

        self.vae_first_frame_transform = get_transforms(
            is_video=True, train_pipeline=first_frame_vae_settings, transform_size=shape_config
        )

        # i2v_vae_encode_tiling mode:
        # 1. auto: Align image encoder and video encoder configurations
        # 2. true: Force enable during image encoding
        # 3. false: Force disable during image encoding
        self.i2v_vae_tile_mode = config.get("i2v_vae_encode_tiling", "auto")

    def __call__(self, vae_model, videos, first_frame, **kwargs):
        if self.visual_backbone:
            clip_input = self.clip_first_frame_transform(first_frame).to(
                dtype=self.visual_backbone.dtype, device=self.visual_backbone.device
            )
            clip_features = self.visual_backbone(clip_input, output_hidden_states=True).hidden_states[-2]
        else:
            clip_features = None

        batch_size, _, seq_len, height, width = videos.shape
        mask = torch.ones(batch_size, seq_len, height // 8, width // 8, device=videos.device)
        mask[:, 1:] = 0
        mask = torch.concat([torch.repeat_interleave(mask[:, 0:1], repeats=4, dim=1), mask[:, 1:]], dim=1)
        mask = mask.view(batch_size, mask.shape[1] // 4, 4, height // 8, width // 8).transpose(1, 2)

        vae_input = torch.concat(
            [self.vae_first_frame_transform(first_frame).unsqueeze(2).to(videos), torch.zeros(batch_size, 3, seq_len - 1, height, width).to(videos)], dim=2
        )

        # set vae tiling mode for i2v processor
        current_tiling_state = vae_model.get_tiling_state()
        if self.i2v_vae_tile_mode != "auto" and self.i2v_vae_tile_mode != current_tiling_state:
            self.configure_vae_tiling(vae_model, self.i2v_vae_tile_mode)

        vae_encodings = vae_model.encode(vae_input)
        vae_encodings = torch.concat([mask.to(vae_encodings.dtype), vae_encodings], dim=1)

        # restore vae tiling mode for video encode
        if vae_model.get_tiling_state() != current_tiling_state:
            self.configure_vae_tiling(vae_model, current_tiling_state)

        return {
            "i2v_clip_feature": clip_features,
            "i2v_vae_feature": vae_encodings
        }

    def configure_vae_tiling(self, vae_model, use_tiling):
        if use_tiling:
            vae_model.enable_tiling()
        else:
            vae_model.disable_tiling()

