import torch, os

class SafeTensorAdapter:
    def __init__(self, tensor_data):
        self.tensor_data = tensor_data

    def get_dimensions(self):
        return list(self.tensor_data.shape)

class BinaryLoaderAdapter:
    def __init__(self, file_path, target_device):
        print("Non-safetensors format detected; loading may be slower. Consider converting to safetensors for better performance.")
        self.parameter_dict = torch.load(file_path, weights_only=True, map_location=target_device)

    def list_keys(self):
        return self.parameter_dict.keys()

    def retrieve_tensor(self, key_name):
        return self.parameter_dict[key_name]

    def extract_slice(self, key_name):
        return SafeTensorAdapter(self.parameter_dict[key_name])

class StorageMapper:
    def __init__(self, source_paths, compute_device, data_type=None, converter=None, cache_limit=10**9):
        self.source_paths = source_paths if isinstance(source_paths, list) else [source_paths]
        self.compute_device = compute_device
        self.data_type = data_type
        if os.environ.get('DIFFSYNTH_STORAGE_MAPPER_CACHE_LIMIT') is not None:
            self.cache_limit = int(os.environ.get('DIFFSYNTH_STORAGE_MAPPER_CACHE_LIMIT'))
        else:
            self.cache_limit = cache_limit
        self.storage_list = []
        self.reset_storage()
        self.key_mapping = {}
        for idx, storage_file in enumerate(self.storage_list):
            for key in storage_file.list_keys():
                self.key_mapping[key] = idx
        self.alias_dict = self.generate_alias_map(converter)

    def reset_storage(self):
        if len(self.storage_list) == 0:
            for path in self.source_paths:
                if path.endswith(".safetensors"):
                    self.storage_list.append(safe_open(path, framework="pt", device=str(self.compute_device)))
                else:
                    self.storage_list.append(BinaryLoaderAdapter(path, target_device=self.compute_device))
        else:
            for i, path in enumerate(self.source_paths):
                if path.endswith(".safetensors"):
                    self.storage_list[i] = safe_open(path, framework="pt", device=str(self.compute_device))
        self.total_elements = 0

    def __getitem__(self, key):
        if self.alias_dict is not None: 
            key = self.alias_dict[key]
        storage_id = self.key_mapping[key]
        value = self.storage_list[storage_id].retrieve_tensor(key)
        if self.data_type is not None and isinstance(value, torch.Tensor):
            value = value.to(self.data_type)
        if isinstance(value, torch.Tensor) and value.device == "cpu":
            value = value.clone()
        if isinstance(value, torch.Tensor):
            self.total_elements += value.numel()
        if self.total_elements > self.cache_limit:
            self.reset_storage()
        return value

    def generate_alias_map(self, converter_func):
        if converter_func is None:
            return None
        temp_dict = {}
        for storage in self.storage_list:
            for key in storage.list_keys():
                temp_dict[key] = key
        temp_dict = converter_func(temp_dict)
        return temp_dict

    def __iter__(self):
        if self.alias_dict is not None:
            return self.alias_dict.__iter__()
        else:
            return self.key_mapping.__iter__()

    def __contains__(self, item):
        if self.alias_dict is not None:
            return item in self.alias_dict
        else:
            return item in self.key_mapping

# Mask sensitive information in URL's network location
def hide_credentials_in_url(url):
    if not url:
        return url
    parsed = urlparse(url)
    host_part = parsed.hostname or ""
    if parsed.port:
        host_part += f":{parsed.port}"
    if parsed.username or parsed.password:
        host_part = f"***:***@{host_part}"
    return urlunparse(parsed._replace(netloc=host_part))

# Analyze telemetry data from a JSONL file
import sys, json
from statistics import mean

def read_telemetry_file(filepath):
    with open(filepath, 'r', encoding='utf-8') as file:
        for record in file:
            record = record.strip()
            if not record:
                continue
            try:
                yield json.loads(record)
            except json.JSONDecodeError:
                continue

def process_data(file_path):
    energies, step_indices = [], []
    for entry in read_telemetry_file(file_path):
        energy_val = entry.get('E')
        if isinstance(energy_val, (int, float)):
            energies.append(float(energy_val))
        step_val = entry.get('step_idx')
        if isinstance(step_val, int):
            step_indices.append(step_val)

    if not energies:
        print('no energy values found'); return

    energy_differences = [energies[i] - energies[i-1] for i in range(1, len(energies))]
    negative_count = sum(1 for diff in energy_differences if diff < 0)
    monotonic_ratio = (negative_count / len(energy_differences)) if energy_differences else float('nan')

    print(f'file: {file_path}')
    print(f'num_steps: {len(energies)}  minE: {min(energies):.6f}  finalE: {energies[-1]:.6f}  meanE: {mean(energies):.6f}')

    if energy_differences:
        print(f'dE: mean={mean(energy_differences):.6f}  <0 fraction={monotonic_ratio:.3f}  first={energy_differences[0]:.6f}  last={energy_differences[-1]:.6f}')

    if step_indices:
        print(f'last step_idx: {step_indices[-1]}')

if __name__ == '__main__':
    if len(sys.argv) < 2:
        print('usage: parse_telemetry.py <path/to/telemetry.jsonl>')
        sys.exit(1)
    process_data(sys.argv[1])

