                packed_query_sequence = temp_seq
        else:
            packed_query_sequence = weights.norm.apply(packed_query_sequence)
        return packed_query_sequence

    def llm2vae(self, weights, input_tensor):
        input_tensor = input_tensor.to(AI_DEVICE).to(torch.bfloat16)
        output = weights.llm2vae.apply(input_tensor)
        return output

