import random
from dataclasses import dataclass
from typing import List
from training.dataset.vos_segment_loader import LazySegments

MAX_ATTEMPTS = 1000

@dataclass
class FrameObjectSample:
    selected_frames: List[int]
    selected_objects: List[int]

class VideoSampler:
    def __init__(self, order_by_frame=True):
        # Frames are sorted by frame index when order_by_frame is True
        self.order_by_frame = order_by_frame

    def sample(self, video_data):
        raise NotImplementedError()

class UniformRandomSampler(VideoSampler):
    def __init__(
        self,
        num_samples,
        max_objects,
        flip_time_prob=0.0,
    ):
        self.num_samples = num_samples
        self.max_objects = max_objects
        self.flip_time_prob = flip_time_prob

    def sample(self, video_data, segment_provider, current_epoch=None):
        for attempt in range(MAX_ATTEMPTS):
            if len(video_data.frames) < self.num_samples:
                raise Exception(
                    f"Cannot extract {self.num_samples} frames from video {video_data.video_name} since it contains only {len(video_data.frames)} annotated frames."
                )

            begin_idx = random.randrange(0, len(video_data.frames) - self.num_samples + 1)
            sampled_frames = [video_data.frames[begin_idx + offset] for offset in range(self.num_samples)]

            if random.uniform(0, 1) < self.flip_time_prob:
                # Reverse temporal order
                sampled_frames = sampled_frames[::-1]

            # Extract object IDs visible in the first selected frame
            candidate_objects = []
            loaded_masks = segment_provider.load(sampled_frames[0].frame_idx)

            if isinstance(loaded_masks, LazySegments):
                # For SA1BRawDataset using LazySegments
                candidate_objects = list(loaded_masks.keys())
            else:
                for obj_id, mask in segment_provider.load(sampled_frames[0].frame_idx).items():
                    if mask.sum() > 0:
                        candidate_objects.append(obj_id)

            # Ensure at least one object is visible in the first frame
            if len(candidate_objects) > 0:
                break

            if attempt >= MAX_ATTEMPTS - 1:
                raise Exception("No visible objects found in any sampled frames")

        # Randomly select up to max_objects from candidate objects
        final_objects = random.sample(
            candidate_objects,
            min(len(candidate_objects), self.max_objects),
        )

        return FrameObjectSample(selected_frames=sampled_frames, selected_objects=final_objects)

class EvaluationSampler(VideoSampler):
    """
    VOS Sampler for evaluation: selects all frames and all objects in a video
    """
    def __init__(self):
        super().__init__()

    def sample(self, video_data, segment_provider, current_epoch=None):
        """
        Selects all available frames and objects from the video
        """
        if self.order_by_frame:
            # Sort frames by their index
            frames_list = sorted(video_data.frames, key=lambda f: f.frame_idx)
        else:
            # Preserve original frame order
            frames_list = video_data.frames

        # Get object IDs from the first frame
        object_ids = list(segment_provider.load(frames_list[0].frame_idx).keys())

