class MotorControllers:
    def __init__(self, i2c_bus, addr=0x40, hz=50, min_pulse=600, max_pulse=2400,
                 angle_range=180):
        self.total_period = 1000000 / hz
        self.min_duty_cycle = self._micros_to_duty(min_pulse)
        self.max_duty_cycle = self._micros_to_duty(max_pulse)
        self.angle_limit = angle_range
        self.frequency = hz
        self.controller = PCA9685(i2c_bus, addr)
        self.controller.freq(hz)
        self.servo_positions = [0] * 16

    def _micros_to_duty(self, micros_value):
        return int(4095 * micros_value / self.total_period)

    def set_position(self, channel, degrees=None, radians=None, microseconds=None, duty_cycle=None, apply_now=True):
        start_time = time.ticks_us()

        if duty_cycle is not None:
            target_duty = duty_cycle
        elif degrees is not None:
            duty_span = self.max_duty_cycle - self.min_duty_cycle
            target_duty = self.min_duty_cycle + duty_span * degrees / self.angle_limit
        elif radians is not None:
            duty_span = self.max_duty_cycle - self.min_duty_cycle
            target_duty = self.min_duty_cycle + duty_span * radians / math.radians(self.angle_limit)
        elif microseconds is not None:
            target_duty = self._micros_to_duty(microseconds)
        else:
            return self.controller.duty(channel)

        print('Processing delay:', time.ticks_diff(time.ticks_us(), start_time))

        # Clamp duty cycle to valid range (commented out in original)
        #target_duty = min(self.max_duty_cycle, max(self.min_duty_cycle, int(target_duty)))

        start_time = time.ticks_us()
        self.servo_positions[channel] = target_duty
        print('Storage duration:', time.ticks_diff(time.ticks_us(), start_time))

        start_time = time.ticks_us()
        if apply_now:
            self.controller.duty(channel, target_duty)
        print('Update latency:', time.ticks_diff(time.ticks_us(), start_time), 'apply:', apply_now)

    def set_duty(self, channel, duty_value):
        self.servo_positions[channel] = duty_value
        self.controller.duty(channel, duty_value)

    def disable_channel(self, channel):
        self.controller.duty(channel, 0)

    def disable_all(self):
        for idx in range(16): 
            self.servo_positions[idx] = 0
        self.update_outputs()

    def update_outputs(self):
        self.controller.allpwm(self.servo_positions)

