# Function to format statistical data into a table
def format_statistics(stats: dict[str, float], columns=4, precision=".4e") -> str:
    pairs = list(stats.items())
    # Determine number of rows required for the table layout
    num_rows = (len(pairs) + columns - 1) // columns
    # Rearrange data in column-wise order
    rearranged = []
    for r in range(num_rows):
        current_row = []
        for c in range(columns):
            pos = r + c * num_rows
            if pos < len(pairs):
                current_row.extend(pairs[pos])
        rearranged.append(current_row)
    return tabulate(rearranged, floatfmt=precision, tablefmt="fancy_grid")

# Define a registration system for platform-specific components
class Registry:
    def __init__(self, *args, **kwargs):
        super(Registry, self).__init__(*args, **kwargs)
        self._registry = {}

    def __call__(self, target_or_name):
        if callable(target_or_name):
            return self.register(target_or_name)
        else:
            return lambda x: self.register(x, key=target_or_name)

    def register(self, target, key=None):
        if not callable(target):
            raise Exception(f"Error: {target} must be callable!")
        if key is None:
            key = target.__name__
        if key in self._registry:
            raise Exception(f"{key} already exists.")
        self[key] = target
        return target

    def __setitem__(self, key, value):
        self._registry[key] = value

    def __getitem__(self, key):
        return self._registry[key]

    def __contains__(self, key):
        return key in self._registry

    def __str__(self):
        return str(self._registry)

    def keys(self):
        return self._registry.keys()

    def values(self):
        return self._registry.values()

    def items(self):
        return self._registry.items()

    def get(self, key, default=None):
        return self._registry.get(key, default)

    def merge(self, other_registry):
        for key, value in other_registry.items():
            if key in self._registry:
                raise Exception(f"{key} already exists in target registry.")
            self[key] = value

# Create global registries for different platform components
