from collections import OrderedDict
from cosmos_rl.utils.logging import logger

class LRUCacheDict:
    """
    A dictionary implementation that maintains a limited number of entries,
    discarding the least recently accessed when capacity is exceeded.
    Functions as a basic key-value storage with LRU eviction policy.
    """
    def __init__(self, capacity=100000):
        self.capacity = capacity
        self.cache = OrderedDict()

    def __setitem__(self, item_key, item_value):
        # If key already exists, remove it to update position
        if item_key in self.cache:
            del self.cache[item_key]
        # Insert new or updated entry
        self.cache[item_key] = item_value
        # Remove oldest entry if exceeding capacity
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)  # last=False removes first (least recent)

    def __getitem__(self, item_key):
        # Move accessed item to end (most recently used)
        retrieved_value = self.cache.pop(item_key)
        self.cache[item_key] = retrieved_value
        return retrieved_value

    def __delitem__(self, item_key):
        del self.cache[item_key]

    def __len__(self):
        return len(self.cache)

    def __contains__(self, item_key):
        return item_key in self.cache

    def fetch(self, item_key, fallback=None):
        if item_key in self.cache:
            return self.__getitem__(item_key)
        return fallback

    def keys(self):
        return self.cache.keys()

    def values(self):
        return self.cache.values()

    def items(self):
        return self.cache.items()

    def __repr__(self):
        return f"LRUCacheDict({list(self.cache.items())})"


class LightweightKVStore:
    """
    A minimal key-value store using LRUCacheDict for local storage.
    Serves as a Redis alternative for development, testing, or low-demand scenarios.
    """
    def __init__(self):
        self.backend = LRUCacheDict()

    async def assign(self, key: str, value: str):
        self.backend[key] = value
        logger.info(f"[LightweightKVStore] Assigned key '{key}' with value '{value}'")

    async def retrieve(self, key: str):
        return self.backend.fetch(key, None)

# Decorator to ensure only one instance of a class is created
def singleton_decorator(cls):
    _instances = {}
    def get_instance(*args, **kwargs):
        if cls not in _instances:
            _instances[cls] = cls(*args, **kwargs)
        return _instances[cls]
    return get_instance

import ctypes
import gc
import sys
import torch

def deep_copy_if_shared(obj):
    if isinstance(obj, torch.Tensor):
        return obj.clone() if obj.is_shared() else obj
    elif isinstance(obj, list):
        return [deep_copy_if_shared(item) for item in obj]
    elif isinstance(obj, tuple):
        return tuple(deep_copy_if_shared(item) for item in obj)
    elif isinstance(obj, dict):
        return {key: deep_copy_if_shared(value) for key, value in obj.items()}
    else:
        return obj

def force_release_tensor(tensor):
    if not torch.is_tensor(tensor):
        return
    try:
        ref_count = sys.getrefcount(tensor)
        for _ in range(ref_count + 15):
            ctypes.pythonapi.Py_DecRef(ctypes.py_object(tensor))
    except Exception as error:
        print(f"Exception during forced deletion: {error}")

def clear_cuda_memory():
    for item in gc.get_objects():
        if torch.is_tensor(item) and item.is_cuda:
            force_release_tensor(item)
    gc.collect()
    torch.cuda.empty_cache()

