def determine_device_backend():
    # Check for CUDA availability first
    if torch.cuda.is_available():
        try:
            # Check if HIP backend is being used (ROCm)
            if torch.version.hip is not None:
                return "hip"
        except AttributeError:
            pass
        return "cuda"

    # Check for Intel XPU support
    try:
        if hasattr(torch, "xpu") and torch.xpu.is_available():
            return "xpu"
    except (AttributeError, RuntimeError):
        pass

    # Default fallback to CPU
    return "cpu"

def get_hardware_parallel_units(device_type):
    # Return number of available devices based on type
    if device_type in ("cuda", "hip"):
        return torch.cuda.device_count()
    elif device_type == "xpu":
        try:
            return torch.xpu.device_count()
        except (AttributeError, RuntimeError):
            return 0
    return 0

# Define maximum fused operation size constraint
MAX_KERNEL_SIZE: int = 65536
# Reference to Triton's next power-of-2 utility function
find_next_power_of_two = triton.next_power_of_2

# Determine active device and count at module initialization
CURRENT_DEVICE = determine_device_backend()
AVAILABLE_UNITS = get_hardware_parallel_units(CURRENT_DEVICE)

# Set up context manager for GPU device handling
if AVAILABLE_UNITS > 1:
    if CURRENT_DEVICE in ("cuda", "hip"):
        gpu_context_manager = torch.cuda.device
    elif CURRENT_DEVICE == "xpu":
        gpu_context_manager = torch.xpu.device
else:
    def gpu_context_manager(device):
        from contextlib import nullcontext
        return nullcontext()

def configure_kernel_parameters(
    element_count: int,
) -> (
    int,
    int,
):
    # Calculate optimal block size as next power of two
    BLOCK_DIM: int = find_next_power_of_two(element_count)

    # Validate against maximum allowed size
    if BLOCK_DIM > MAX_KERNEL_SIZE:
        raise RuntimeError(
            f"Cannot launch Triton kernel since n = {element_count} exceeds the maximum CUDA blocksize = {MAX_KERNEL_SIZE}."
        )

    # Configure warp count based on block size
    warps_per_block: int = 4
    if BLOCK_DIM >= 32768:
        warps_per_block = 32
    elif BLOCK_DIM >= 8192:
        warps_per_block = 16
    elif BLOCK_DIM >= 2048:
        warps_per_block = 8

    return BLOCK_DIM, warps_per_block

# Handle CRUD operations for items using DynamoDB
import json
import boto3
from stlv_resources import Resources

def handler(event, context):
    db_table = boto3.resource("dynamodb").Table(Resources.items.table_name)
    request_method = event["httpMethod"]
    path_vars = event.get("pathParameters") or {}
    item_key = path_vars.get("id")

    if request_method == "POST":
        payload = json.loads(event["body"])
        db_table.put_item(Item=payload)
        return {"statusCode": 201, "body": json.dumps(payload)}

    if request_method == "GET" and item_key:
        response = db_table.get_item(Key={"pk": item_key})
        record = response.get("Item")
        if not record:
            return {"statusCode": 404, "body": "not found"}
        return {"statusCode": 200, "body": json.dumps(record)}

    if request_method == "DELETE" and item_key:
        db_table.delete_item(Key={"pk": item_key})
        return {"statusCode": 200, "body": "deleted"}

    return {"statusCode": 400, "body": "bad request"}

