import numpy as np
from transformers import Pipeline

def softmax_function(output_values):
    # Compute max for numerical stability
    max_values = np.max(output_values, axis=-1, keepdims=True)
    shifted_exp = np.exp(output_values - max_values)
    return shifted_exp / shifted_exp.sum(axis=-1, keepdims=True)

class TextPairClassifierPipeline(Pipeline):
    def _sanitize_parameters(self, **parameters):
        # Prepare preprocessing arguments
        preprocess_args = {}
        if "pair_text" in parameters:
            preprocess_args["second_text"] = parameters["pair_text"]
        return preprocess_args, {}, {}

    def preprocess(self, first_text, second_text=None):
        # Tokenize input text pair
        return self.tokenizer(first_text, text_pair=second_text, return_tensors=self.framework)

    def _forward(self, input_features):
        # Run model forward pass
        return self.model(**input_features)

    def postprocess(self, model_results):
        # Extract logits and compute probabilities
        raw_logits = model_results.logits[0].numpy()
        probs = softmax_function(raw_logits)

        # Determine best prediction
        predicted_class = np.argmax(probs)
        predicted_label = self.model.config.id2label[predicted_class]
        confidence_score = probs[predicted_class].item()

        # Prepare output
        logits_list = raw_logits.tolist()
        return {"label": predicted_label, "score": confidence_score, "logits": logits_list}

