import numpy as np
import torch
import torch.nn as nn

def initialize_layer(layer, std=np.sqrt(2), bias_value=0.0):
    torch.nn.init.orthogonal_(layer.weight, std)
    torch.nn.init.constant_(layer.bias, bias_value)
    return layer

def retrieve_activation_function(activation_type):
    if activation_type.lower() == "relu":
        act = nn.ReLU
    elif activation_type.lower() == "gelu":
        act = nn.GELU
    elif activation_type.lower() == "tanh":
        act = nn.Tanh
    else:
        raise ValueError(f"Unsupported activation: {activation_type}")
    return act

def construct_mlp(
    input_dim, hidden_dims, act_constructor=nn.ReLU, apply_final_activation=True, 
    normalize_layers=False
):
    c_in = input_dim
    layers_list = []
    for i, c_out in enumerate(hidden_dims):
        layers_list.append(nn.Linear(c_in, c_out))
        if apply_final_activation or i < len(hidden_dims) - 1:
            if normalize_layers:
                layers_list.append(nn.LayerNorm(c_out))
            layers_list.append(act_constructor())
        c_in = c_out
    return layers_list

def apply_mlp_weight_initialization(mlp_modules, activation_func_name):
    for module in mlp_modules:
        if isinstance(module, nn.Linear):
            if module is mlp_modules[-1]:
                nn.init.normal_(module.weight, mean=0.0, std=0.02)
                if module.bias is not None:
                    nn.init.zeros_(module.bias)
            else:
                nn.init.kaiming_normal_(
                    module.weight, mode="fan_out", nonlinearity=activation_func_name
                )
                if module.bias is not None:
                    nn.init.zeros_(module.bias)

