import numpy as np
import torch

def create_data_iterators(train_loader=None, val_loader=None, test_loader=None, mode="cyclic"):
    def _infinite_cycle(loader):
        while True:
            for batch in loader:
                yield batch

    def _create_iterator(data_loader, iter_mode=mode):
        """Generate appropriate iterator based on mode."""
        if iter_mode == "single":
            return iter(data_loader)
        elif iter_mode == "cyclic":
            return iter(_infinite_cycle(data_loader))
        else:
            raise ValueError(f"Unsupported iterator mode: {iter_mode}")

    # Create iterators conditionally based on provided loaders
    train_iterator = _create_iterator(train_loader) if train_loader is not None else None
    val_iterator = _create_iterator(val_loader) if val_loader is not None else None
    test_iterator = _create_iterator(test_loader) if test_loader is not None else None

    return train_iterator, val_iterator, test_iterator

def setup_deterministic_worker(seed_value):
    """Configure workers for reproducible dataloading."""
    def worker_init_fn(worker_id):
        # Set seeds for all relevant libraries
        np.random.seed(seed_value)
        torch.manual_seed(seed_value)
        random.seed(seed_value)
    return worker_init_fn

