import numpy as np
import torch

class DiagonalGaussianDistribution:
    def __init__(self, params, is_deterministic=False, axis=1):
        self.params = params
        self.mean, self.logvariance = torch.chunk(params, 2, dim=axis)
        self.logvariance = torch.clamp(self.logvariance, -30.0, 20.0)
        self.is_deterministic = is_deterministic
        self.standard_deviation = torch.exp(0.5 * self.logvariance)
        self.variance = torch.exp(self.logvariance)
        if self.is_deterministic:
            self.variance = self.standard_deviation = torch.zeros_like(self.mean, device=params.device, dtype=params.dtype)

    def sample(self, rng=None):
        noise = torch.randn(self.mean.shape, device=self.params.device,
                            dtype=self.params.dtype, generator=rng)
        sample = self.mean + self.standard_deviation * noise
        return sample

    def kl_divergence(self, reference=None):
        if self.is_deterministic:
            return torch.tensor([0.])
        else:
            if reference is None:
                return 0.5 * torch.sum(torch.pow(self.mean, 2) +
                       self.variance - 1.0 - self.logvariance, dim=[1, 2, 3])
            else:
                return 0.5 * torch.sum(
                       torch.pow(self.mean - reference.mean, 2) / reference.variance
                       + self.variance / reference.variance - 1.0 - self.logvariance + reference.logvariance, 
                       dim=[1, 2, 3])

    def negative_log_likelihood(self, observation, axes=(1, 2, 3)):
        if self.is_deterministic:
            return torch.tensor([0.])
        log_two_pi = np.log(2.0 * np.pi)
        return 0.5 * torch.sum(log_two_pi + self.logvariance +
               torch.pow(observation - self.mean, 2) / self.variance, dim=axes)

    def maximum_a_posteriori(self):
        return self.mean

