# Wrapper utilities and decorators
from functools import wraps

def wrapable(name=None):
    def decorator(func):
        func._wrapable = True
        func._wrap_name = name or func.__name__
        return func
    return decorator

def wrap_get_method(kwargs):
    return kwargs.pop('__method', None)

def wrap_get_method_name(kwargs):
    return kwargs.pop('__method_name', None)

def wrap_remove_meta(kwargs):
    kwargs.pop('__method', None)
    kwargs.pop('__method_name', None)
    return kwargs

def wrap(target, source, wrapper_func):
    for attr_name in dir(source):
        if not attr_name.startswith('_'):
            attr = getattr(source, attr_name)
            if callable(attr) and hasattr(attr, '_wrapable'):
                wrapped = _make_wrapper(attr, attr_name, wrapper_func)
                setattr(target, attr_name, wrapped)

def _make_wrapper(method, method_name, wrapper_func):
    @wraps(method)
    def wrapper(*args, **kwargs):
        kwargs['__method'] = method
        kwargs['__method_name'] = method_name
        return wrapper_func(*args, **kwargs)
    return wrapper

class Calculator:
    def __init__(self):
        self.remaining = 2

    @wrapable()
    def add(self, a, b):
        return a + b + self.remaining

    @wrapable(name="multiply")
    def mul(self, x, y):
        return x * y * self.remaining

class EnhancedCalculator:
    def __init__(self, obj: Calculator):
        super().__init__()
        self.prefix = "Result:"
        self.calculator = obj
        wrap(self, obj, self._wrap_call)

    def _wrap_call(self, *args, **kwargs):
        method_name = wrap_get_method_name(kwargs)
        method = wrap_get_method(kwargs)
        kwargs = wrap_remove_meta(kwargs)
        print("wrap method: ", method_name)
        print("wrap method: ", method)
        return method(*args, **kwargs)

def test_wrapper():
    calc = Calculator()
    enhancer = EnhancedCalculator(calc)
    assert enhancer.add(2, 3) == 7
    assert enhancer.multiply(4, 5) == 40

if __name__ == "__main__":
    test_wrapper()

