import string
import re
from collections import Counter

def preprocess_text(text):
    def strip_articles(input_text):
        return re.sub(r"\b(a|an|the)\b", " ", input_text)

    def normalize_whitespace(input_text):
        return " ".join(input_text.split())

    def filter_punctuation(input_text):
        punctuation_set = set(string.punctuation)
        return "".join(char for char in input_text if char not in punctuation_set)

    def to_lowercase(input_text):
        return input_text.lower()

    processed = to_lowercase(filter_punctuation(strip_articles(normalize_whitespace(text))))
    return processed

def compute_f1(pred, target):
    NULL_RESULT = (0.0, 0.0, 0.0)

    if pred is None:
        return NULL_RESULT

    clean_pred = preprocess_text(pred)
    clean_target = preprocess_text(target)

    # Handle special cases for yes/no/noanswer
    if clean_pred in ["yes", "no", "noanswer"] and clean_pred != clean_target:
        return NULL_RESULT
    if clean_target in ["yes", "no", "noanswer"] and clean_pred != clean_target:
        return NULL_RESULT

    pred_tokens = clean_pred.split()
    truth_tokens = clean_target.split()

    overlapping = Counter(pred_tokens) & Counter(truth_tokens)
    match_count = sum(overlapping.values())

    if match_count == 0:
        return NULL_RESULT

    precision_val = match_count / len(pred_tokens)
    recall_val = match_count / len(truth_tokens)

    f1_val = (2 * precision_val * recall_val) / (precision_val + recall_val)

    return f1_val, precision_val, recall_val

