import math

def calculate_bucket_lowerings(grid, capacity):
    # Calculate the total number of bucket lowerings needed to empty all wells
    total_operations = 0
    for well in grid:
        water_amount = sum(well)
        if water_amount > 0:
            total_operations += math.ceil(water_amount / capacity)
    return total_operations

def sort_numbers(numbers):
    """
    Given a list of non-negative integers, return a new list after sorting,
    you will sort the given list in ascending order if the sum( first element, last element) is odd,
    or sort it in descending order if the sum( first element, last element) is even.
    Note:
    * don't modify the original list.
    Examples:
    * sort_numbers([]) => []
    * sort_numbers([7]) => [7]
    * sort_numbers([1, 3, 2, 5, 0, 4]) => [0, 1, 2, 3, 4, 5]
    * sort_numbers([1, 3, 2, 5, 0, 4, 8]) => [8, 5, 4, 3, 2, 1, 0]
    """
    if not numbers:
        return []

    first_last_total = numbers[0] + numbers[-1]

    if first_last_total % 2 == 1:
        return sorted(numbers)
    else:
        return sorted(numbers, reverse=True)

