# ADMET rule-based analysis using RDKit
import json
import argparse
from rdkit import Chem
from rdkit.Chem import Descriptors

def lipinski_rules(molecule):
    acceptors = Descriptors.NumHAcceptors(molecule)
    donors = Descriptors.NumHDonors(molecule)
    molecular_weight = Descriptors.MolWt(molecule)
    octanol_water = Descriptors.MolLogP(molecule)
    count_violations = sum([acceptors > 10, donors > 5, molecular_weight > 500, octanol_water > 5])
    return {"hba": acceptors, "hbd": donors, "mw": molecular_weight, "logp": octanol_water, "ro5_violations": count_violations}

def veber_rules(molecule):
    rotatable_bonds = Descriptors.NumRotatableBonds(molecule)
    polar_surface_area = Descriptors.TPSA(molecule)
    count_violations = sum([rotatable_bonds > 10, polar_surface_area > 140])
    return {"rotb": rotatable_bonds, "tpsa": polar_surface_area, "veber_violations": count_violations}

def structural_alerts(molecule):
    smiles_representation = Chem.MolToSmiles(molecule)
    alert_patterns = ['c1ncnc2c1ncn2', 'cc1ccc2nsnc2c1']  # example PAINS filters
    detected_alerts = [pattern for pattern in alert_patterns if pattern in smiles_representation]
    return {"pains_alerts": detected_alerts, "num_alerts": len(detected_alerts)}

def main():
    parser = argparse.ArgumentParser(description="RDKit ADMET rule-based screening")
    parser.add_argument("--smiles", required=True, help="Single SMILES string input")
    parser.add_argument("--target_smiles", help="Comma-separated batch of SMILES strings")
    arguments = parser.parse_args()

    def analyze_compound(smiles_string):
        molecule = Chem.MolFromSmiles(smiles_string)
        if molecule is None:
            return {"smiles": smiles_string, "error": "Invalid structure"}
        return {
            "smiles": smiles_string,
            **lipinski_rules(molecule),
            **veber_rules(molecule),
            **structural_alerts(molecule)
        }

    if arguments.target_smiles:
        compound_list = [analyze_compound(s.strip()) for s in arguments.target_smiles.split(",")]
        print(json.dumps({"screen": compound_list}))
    else:
        single_result = analyze_compound(arguments.smiles)
        print(json.dumps(single_result))

if __name__ == "__main__":
    main()

# AI2D evaluation dataset implementation for Mindspeed-MM
import pandas as pd
import string
from mindspeed_mm.tasks.evaluation.eval_datasets.datasets_base import BaseEvalDataset
from mindspeed_mm.tasks.evaluation.utils.string_utils import string_to_list

class AI2DEvalDataset(BaseEvalDataset):
    def __init__(self, data_folder, dataset_identifier):
        super().__init__(data_folder, dataset_identifier)

    def construct_prompt(self, row_data):
        # Handle integer index input
        if isinstance(row_data, int):
            row_data = self.data.iloc[row_data]

        # Determine image path based on meta_only flag
        if self.meta_only:
            image_paths = string_to_list(row_data['image_path'])
        else:
            image_paths = self.dump_image(row_data)

        # Extract question and options
        query_text = row_data['question']
        choices = {
            option_label: row_data[option_label]
            for option_label in string.ascii_uppercase
            if option_label in row_data and not pd.isna(row_data[option_label])
        }

        # Build options prompt
        options_text = 'Choices:\n'
        for label, content in choices.items():
            options_text += f'{label}. {content}\n'

        # Handle optional hint
        hint_text = row_data['hint'] if ('hint' in row_data and not pd.isna(row_data['hint'])) else None

        # Construct final prompt
        full_prompt = ''
        if hint_text is not None:
            full_prompt += f'Suggestion: {hint_text}\n'
        full_prompt += f'Query: {query_text}\n'

        if len(choices) > 0:
            full_prompt += options_text
            full_prompt += 'Choose the correct answer from the given choices. \n'

        # Prepare message list with images and text
        message_list = []
        if isinstance(image_paths, list):
            message_list.extend([dict(type='image', value=path) for path in image_paths])
        else:
            message_list = [dict(type='image', value=image_paths)]

        message_list.append(dict(type='text', value=full_prompt))
        return message_list

