# Calculate the number of layers per device and assign them evenly
from math import ceil

def validate_device_assignment(device_assignment, total_layers):
    layer_indices = list(range(0, total_layers))
    assigned_layers = [item for sublist in list(device_assignment.values()) for item in sublist]

    # Check for repeated assignments
    repeated_layers = []
    for idx in assigned_layers:
        if assigned_layers.count(idx) > 1 and idx not in repeated_layers:
            repeated_layers.append(idx)

    # Identify unassigned layers
    unassigned_layers = [idx for idx in layer_indices if idx not in assigned_layers]
    invalid_layers = [idx for idx in assigned_layers if idx not in layer_indices]

    if len(repeated_layers) != 0:
        raise ValueError(
            "Duplicate layer indices found in device_assignment. Each layer must be assigned to exactly one device."
            " The following layers were assigned multiple times: " + str(repeated_layers)
        )
    if len(unassigned_layers) != 0:
        raise ValueError(
            "Some model layers are not included in the device_assignment. Include these layers in a device:"
            " " + str(unassigned_layers)
        )
    if len(invalid_layers) != 0:
        raise ValueError(
            "The device_assignment contains layer indices that exceed the model's layer count. Remove these from the device_assignment:"
            + str(invalid_layers)
        )

def distribute_layers(num_layers, available_devices):
    """Returns a mapping of devices to their assigned layers, distributed as evenly as possible."""
    all_layers = list(range(num_layers))
    layers_per_device = int(ceil(num_layers / len(available_devices)))
    layer_chunks = [all_layers[i : i + layers_per_device] for i in range(0, num_layers, layers_per_device)]
    return dict(zip(available_devices, layer_chunks))

# Validate if the given date string is in correct format and valid
def is_valid_date(date_str):
    if not date_str:
        return False

    try:
        components = date_str.split('-')
        if len(components) != 3:
            return False

        month_str, day_str, year_str = components

        if len(month_str) != 2 or len(day_str) != 2 or len(year_str) != 4:
            return False

        month = int(month_str)
        day = int(day_str)
        year = int(year_str)

        if month < 1 or month > 12:
            return False

        if day < 1:
            return False

        if month in [1, 3, 5, 7, 8, 10, 12]:
            if day > 31:
                return False
        elif month in [4, 6, 9, 11]:
            if day > 30:
                return False
        elif month == 2:
            if day > 29:
                return False

        return True
    except:
        return False

