import transformers
class HunyuanMllmTokenizer:
    def __init__(
        self,
        **kwargs,
    ):
        config_path = kwargs.pop("template_file_path")
        template_name = kwargs.pop("template_id", "hyv-llm-encode-video")
        with open(config_path, "r") as file:
            data = json.load(file)
        self.template_data = data[template_name]
        self.tokenizer = transformers.AutoTokenizer.from_pretrained(**kwargs)

    @staticmethod
    def format_text(text, template):
        if isinstance(text, str):
            return [template.format(text)]
        elif isinstance(text, (list, tuple)):
            return [template.format(t) for t in text]
        else:
            raise NotImplementedError(f"Not Support text type: {type(text)}")

    def __call__(
        self, 
        input_prompt,
        padding: str = "max_length",
        max_length: int = 256,
        truncation: bool = True,
        return_attention_mask: bool = True,
        add_special_tokens: bool = True,
        return_tensors: str = "pt",
        **extra_kwargs,
    ):
        input_prompt = HunyuanMllmTokenizer.format_text(input_prompt, self.template_data["template"])
        text_inputs = self.tokenizer(
            input_prompt,
            padding=padding,
            max_length=max_length + self.template_data["crop_start"],
            truncation=truncation,
            return_attention_mask=return_attention_mask,
            add_special_tokens=add_special_tokens,
            return_tensors=return_tensors,
            **extra_kwargs,
        )
        return text_inputs

    def __getattr__(self, attr_name):
        if attr_name in dir(self):
            return super().__getattr__(attr_name)
        else:
            return getattr(self.tokenizer, attr_name)

