# Speech-to-text transcription using ElevenLabs Scribe API
import os
from dotenv import load_dotenv
load_dotenv()

class ElevenLabsTranscriber:
    """Convert speech to text using ElevenLabs Scribe service"""

    def __init__(self, api_token=None):
        self.api_token = api_token or os.getenv('ELEVENLABS_API_KEY')
        self.endpoint_url = "https://api.elevenlabs.io/v1"

    def convert_audio_to_text(self, audio_path, lang_code=None, mark_events=True, 
                              speaker_count=None, time_unit="word"):
        """
        Transcribe an audio file into text using ElevenLabs Scribe

        Supported formats: mp3, mp4, mpeg, mpga, m4a, wav, webm
        Maximum file size: 100 MB
        """
        request_url = f"{self.endpoint_url}/speech-to-text"

        auth_headers = {
            "xi-api-key": self.api_token
        }

        payload = {
            "model_id": "scribe_v1",
            "tag_audio_events": str(mark_events).lower(),
            "timestamps_granularity": time_unit
        }

        if lang_code:
            payload["language_code"] = lang_code
        if speaker_count:
            payload["num_speakers"] = speaker_count

        try:
            with open(audio_path, 'rb') as audio_data:
                upload_files = {
                    'file': (os.path.basename(audio_path), audio_data)
                }

                api_response = requests.post(request_url, headers=auth_headers, data=payload, files=upload_files, timeout=120)
                api_response.raise_for_status()

                output = api_response.json()
                return {
                    "success": True,
                    "transcript": output.get('text', ''),
                    "detected_language": output.get('language_code', 'unknown'),
                    "word_details": output.get('words', []),
                    "speaker_info": output.get('speakers', [])
                }

        except requests.exceptions.RequestException as ex:
            return {"success": False, "error": f"API call failed: {str(ex)}"}
        except Exception as ex:
            return {"success": False, "error": str(ex)}

def execute():
    import argparse

    parser = argparse.ArgumentParser(description='ElevenLabs Scribe STT Tool')
    parser.add_argument('audio_file', help='Path to the input audio file')
    parser.add_argument('--language', '-l', help='Language code (e.g., ar, en)')
    parser.add_argument('--speakers', '-s', type=int, help='Expected number of speakers')

    arguments = parser.parse_args()

    transcriber = ElevenLabsTranscriber()
    transcription_result = transcriber.convert_audio_to_text(arguments.audio_file, lang_code=arguments.language, speaker_count=arguments.speakers)
    print(transcription_result)

if __name__ == "__main__":
    import json
    execute()

import bisect
from collections.abc import Iterable
from typing import NamedTuple
from torch.utils.data import ConcatDataset

# Cannot be a local class as it needs to be pickleable
class _InterleavedConcatDataset(ConcatDataset):
    """`torch.utils.data.ConcatDataset` but returns the dataset index."""
    def __getitem__(self, idx):
        if idx < 0:
            if -idx > len(self):
                raise ValueError("absolute value of index should not exceed dataset length")
            idx = len(self) + idx
        dataset_idx = bisect.bisect_right(self.cumulative_sizes, idx)
        if dataset_idx == 0:
            sample_idx = idx
        else:
            sample_idx = idx - self.cumulative_sizes[dataset_idx - 1]
        return dataset_idx, self.datasets[dataset_idx][sample_idx]

# Cannot be a local class as it needs to be pickleable
class _InterleavedCollator:
    """Holds a list of collators and calls one based on the dataset index returned."""
    def __init__(self, collators_list):
        self.collators = collators_list

    def __call__(self, batch_data):
        dataset_indices, data_items = zip(*batch_data, strict=True)
        if not all(dataset_indices[0] == idx for idx in dataset_indices):
            raise ValueError("All samples in a batch must come from the same dataset.")
        return self.collators[dataset_indices[0]](data_items)

class SamplerOutput(NamedTuple):  # lint-ignore: NoNamedTuple
    """Output of the InterleavedSampler. Contains the sample index and the dataset index."""
    is_full_batch: bool
    sample_index: int

# Cannot be a local class as it needs to be pickleable
class _InterleavedBatchSampler:
    """Generates batches of indices from an iterable of SamplerOutput objects."""
    def __init__(self, sampling_sequence: Iterable[SamplerOutput]):
        super().__init__()
        self.sampling_sequence = sampling_sequence

    def __iter__(self):
        batch_indices = []
        for is_complete_batch, sample_id in self.sampling_sequence:
            batch_indices.append(sample_id)
            if is_complete_batch:
                yield batch_indices
                batch_indices = []
        assert len(batch_indices) == 0

    def __len__(self):
        raise NotImplementedError

import torch.nn as nn

try:
    import torch_npu
except ImportError:
    tmo = None

class NpuQuantLinearInt8(nn.Module):
    def __init__(self, input_dim, output_dim, has_bias=True, precision=torch.bfloat16):
        super().__init__()
        self.input_dim = input_dim
        self.output_dim = output_dim
        self.register_buffer("quant_weight", torch.empty((output_dim, input_dim), dtype=torch.int8))
        self.register_buffer("quant_scale", torch.empty((output_dim, 1), dtype=torch.float32))
        if has_bias:
            self.register_buffer("bias_term", torch.empty(output_dim, dtype=precision))
        else:
            self.register_buffer("bias_term", None)

    def dynamic_quantize(self, x):
        quantized_input, scale_factor = torch_npu.npu_dynamic_quant(x)
        return quantized_input, scale_factor

    def forward(self, input_data):
        data_type = input_data.dtype
        quantized_input, input_scale = self.dynamic_quantize(input_data)
        result = torch_npu.npu_quant_matmul(
            quantized_input, 
            self.quant_weight.t(), 
            self.quant_scale.reshape(-1), 
            offset=None, 
            bias=self.bias_term, 
            pertoken_scale=input_scale.reshape(-1), 
            output_dtype=data_type
        )
        if len(result.shape) == 2:
            return result.unsqueeze(0)
        elif len(result.shape) == 3:
            return result

    def _apply(self, transform_fn):
        for submodule in self.children():
            submodule._apply(transform_fn)

        def safe_transform(tensor):
            if tensor is not None and tensor.device != transform_fn(tensor).device:
                return transform_fn(tensor)
            return tensor

        self.quant_weight = safe_transform(self.quant_weight)
        self.quant_scale = safe_transform(self.quant_scale)
        self.bias_term = safe_transform(self.bias_term)
        return self

