websocket_admin_bp = Blueprint('ws_admin', __name__, url_prefix='/api/v2/websocket')
@websocket_admin_bp.route('/health', methods=['GET'])
@require_auth()
def check_connection_status():
    """Retrieve current WebSocket server health and connection metrics."""
    client_details = fetch_active_clients_details()

    return success_response(data={
        'websocket': {
            'active': True,
            'active_connections': client_details['total'],
            'path': '/socket.io'
        }
    })
@websocket_admin_bp.route('/connections', methods=['GET'])
@require_auth()
def list_active_connections():
    """Fetch detailed information about connected WebSocket clients (restricted to administrators)."""
    client_details = fetch_active_clients_details()

    return success_response(data=client_details)
@websocket_admin_bp.route('/notify', methods=['POST'])
@require_auth()
def dispatch_alert():
    """Send a system-wide notification to all active WebSocket clients (admin-only functionality)."""
    payload = request.get_json()
    content = payload.get('content', '')
    category = payload.get('category', 'system')
    priority = payload.get('priority', 'info')

    if not content:
        return error_response('Content field is mandatory', 400)

    send_system_notification(category, content, priority)

    operator = g.current_user.username if hasattr(g, 'current_user') else 'anonymous'

    return success_response(data={
        'message': 'Notification transmitted',
        'metadata': {
            'category': category,
            'priority': priority,
            'originator': operator
        }
    })
@websocket_admin_bp.route('/types', methods=['GET'])
def retrieve_event_categories():
    """
    Retrieve all supported WebSocket event categories.
    ---
    tags:
      - WebSocket
    responses:
      200:
        description: Collection of event categories
    """
    categories = [
        {'label': c.name, 'identifier': c.value}
        for c in EventCategory
    ]

    return success_response(data={'categories': categories})

# HTTP request handler with routing capabilities
from http.server import BaseHTTPRequestHandler
import json
import logging

logger = logging.getLogger(__name__)

class RouteManager:
    def __init__(self):
        # routes: method -> path -> handler function
        self.endpoints: Dict[str, Dict[str, Callable]] = {
            "GET": {},
            "POST": {}
        }

    def register_route(self, method: str, endpoint: str, callback: Callable):
        method = method.upper()
        if method not in self.endpoints:
            self.endpoints[method] = {}
        self.endpoints[method][endpoint] = callback

    def get_endpoint(self, path: str):
        def wrapper(func: Callable):
            self.register_route("GET", path, func)
            return func
        return wrapper

    def post_endpoint(self, path: str):
        def wrapper(func: Callable):
            self.register_route("POST", path, func)
            return func
        return wrapper

    def handle_request(self, request_handler: BaseHTTPRequestHandler):
        path = request_handler.path.split('?')[0]  # Extract base path without query params
        method = request_handler.command.upper()

        if method in self.endpoints and path in self.endpoints[method]:
            try:
                self.endpoints[method][path](request_handler)
            except Exception as e:
                logger.error(f"Error processing {method} {path}: {e}")
                self._send_json_error(request_handler, 500, str(e))
        else:
            self._send_json_error(request_handler, 404, "Resource not found")

    def _send_json_error(self, request_handler: BaseHTTPRequestHandler, status_code: int, error_msg: str):
        request_handler.send_response(status_code)
        request_handler.send_header('Content-type', 'application/json')
        request_handler.end_headers()
        response_body = json.dumps({"error": error_msg})
        request_handler.wfile.write(response_body.encode('utf-8'))

# Singleton router instance
_main_router = RouteManager()

def get_application_router() -> RouteManager:
    return _main_router

# Check bounding boxes for form fields in JSON format
import json
import sys

@dataclass
class BoxAndField:
    box: list[float]
    box_type: str
    field: dict

def validate_bounding_boxes(json_stream) -> list[str]:
    output_lines = []
    data = json.load(json_stream)
    output_lines.append(f"Loaded {len(data['form_fields'])} fields")

    def boxes_overlap(b1, b2):
        # Check if boxes are disjoint horizontally or vertically
        no_overlap_x = b1[0] >= b2[2] or b1[2] <= b2[0]
        no_overlap_y = b1[1] >= b2[3] or b1[3] <= b2[1]
        return not (no_overlap_x or no_overlap_y)

    boxes_and_items = []
    for item in data["form_fields"]:
        boxes_and_items.append(BoxAndField(item["label_bounding_box"], "label", item))
        boxes_and_items.append(BoxAndField(item["entry_bounding_box"], "entry", item))

    found_issues = False

    # Check for intersections between bounding boxes on the same page
    for idx, current_box in enumerate(boxes_and_items):
        for other_idx in range(idx + 1, len(boxes_and_items)):
            other_box = boxes_and_items[other_idx]

            # Only check if they're on the same page and overlap
            if (current_box.field["page_number"] == other_box.field["page_number"] and 
                boxes_overlap(current_box.box, other_box.box)):

                found_issues = True

                if current_box.field is other_box.field:
                    output_lines.append(
                        f"ERROR: overlapping label and entry boxes for `{current_box.field['description']}` "
                        f"({current_box.box}, {other_box.box})"
                    )
                else:
                    output_lines.append(
                        f"ERROR: {current_box.box_type} box for `{current_box.field['description']}` "
                        f"({current_box.box}) overlaps with {other_box.box_type} box for "
                        f"`{other_box.field['description']}` ({other_box.box})"
                    )

                # Limit number of messages to avoid overwhelming output
                if len(output_lines) >= 20:
                    output_lines.append("Stopping further checks; please fix issues and re-run")
                    return output_lines

    # Check entry box height against font size
    for box_item in boxes_and_items:
        if box_item.box_type == "entry":
            if "entry_text" in box_item.field:
                text_info = box_item.field["entry_text"]
                font_size = text_info.get("font_size", 14)
                box_height = box_item.box[3] - box_item.box[1]

                if box_height < font_size:
                    found_issues = True
                    output_lines.append(
                        f"ERROR: entry box height ({box_height}) for `{box_item.field['description']}` "
                        f"is insufficient for font size ({font_size}). Please increase box height or reduce font size."
                    )

                    if len(output_lines) >= 20:
                        output_lines.append("Stopping further checks; please fix issues and re-run")
                        return output_lines

    if not found_issues:
        output_lines.append("OK: All bounding boxes meet requirements")

    return output_lines

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: validate_form_boxes.py [fields.json]")
        sys.exit(1)

    with open(sys.argv[1]) as file:
        results = validate_bounding_boxes(file)

    for line in results:
        print(line)

# PULSE Magazine CLI Tool - Updated version
import json
import requests
import argparse

API_BASE = "https://pulse.gemdynamics.dev"

def fetch_intelligence_data():
    response = requests.get(f"{API_BASE}/api/v1/intelligence")
    if response.status_code == 200:
        print(json.dumps(response.json(), indent=2))
    else:
        print(json.dumps({"error": f"Error retrieving intelligence: {response.status_code}"}))

def view_article(article_slug):
    response = requests.get(f"{API_BASE}/api/v1/articles/{article_slug}")
    if response.status_code == 200:
        print(json.dumps(response.json(), indent=2))
    else:
        print(json.dumps({"error": f"Unable to load article: {response.status_code}"}))

def submit_comment(article_slug, commenter_name, comment_text):
    data = {"author": commenter_name, "content": comment_text}
    response = requests.post(f"{API_BASE}/api/v1/articles/{article_slug}/comments", json=data)
    if response.status_code == 200:
        print(json.dumps(response.json(), indent=2))
    else:
        print(json.dumps({"error": f"Comment submission failed: {response.status_code}"}))

if __name__ == "__main__":
    cli_parser = argparse.ArgumentParser(description="PULSE Magazine Command Line Interface")
    command_subparsers = cli_parser.add_subparsers(dest="action")

    # Intelligence command
    command_subparsers.add_parser("intelligence")

    # Read command
    read_cmd = command_subparsers.add_parser("read")
    read_cmd.add_argument("--slug", required=True)

    # Comment command
    comment_cmd = command_subparsers.add_parser("comment")
    comment_cmd.add_argument("--slug", required=True)
    comment_cmd.add_argument("--author", required=True)
    comment_cmd.add_argument("--content", required=True)

    arguments = cli_parser.parse_args()

    if arguments.action == "intelligence":
        fetch_intelligence_data()
    elif arguments.action == "read":
        view_article(arguments.slug)
    elif arguments.action == "comment":
        submit_comment(arguments.slug, arguments.author, arguments.content)
    else:
        cli_parser.print_help()

def ApiError(err_msg: str) -> str:
    return "API Error: " + err_msg

def ProcessVolcResponse(api_response: dict):
    if not api_response:
        return ApiError("Empty response")

    parsed_response = api_response if not isinstance(api_response, str) else json.loads(api_response)
    error_info = parsed_response.get("ResponseMetadata", {}).get("Error")

    if error_info and isinstance(error_info, dict):
        error_message = error_info.get("Message", "Unknown error")
        return ApiError(error_message)

    return str(api_response)

