from whimbox.common.cvars import *
from whimbox.ui.template.posi_manager import Area

class TextTemplate(AssetBase):
    def __init__(self, content: str, region: Area, identifier=None, matching_strategy=CONTAIN_MATCHING, logging_flag=LOG_WHEN_TRUE):
        if identifier is None:
            super().__init__(get_name_from_caller(depth=2))
        else:
            super().__init__(identifier)

        self.content = content
        self.region = region
        self.matching_strategy = matching_strategy
        self.logging_flag = logging_flag

    def get_content(self):
        return self.content

    def check_results(self, results: list):
        if isinstance(results, str):
            results = [results]
        for item in results:
            # TODO: add match rules
            if item == '':
                continue
            if self.matching_strategy == CONTAIN_MATCHING:
                if self.content in item:
                    return True
                else:
                    continue
            elif self.matching_strategy == ACCURATE_MATCHING:
                if self.content == item:
                    return True
                else:
                    continue
        return False

class Text(TextTemplate):
    def __init__(self, text, area, identifier=None, logging_flag=LOG_WHEN_TRUE) -> None:
        if identifier is None:
            identifier = get_name_from_caller(depth=2)
        super().__init__(text, cap_area=area, name=identifier, print_log=logging_flag)

