# Check if the directory contains a single model configuration
def is_single_model_directory(model_path):
    return os.path.isfile(f"{model_path}/graph_net.json") and os.path.isfile(
        f"{model_path}/model.py"
    )

# Recursively search for model directories starting from root
def find_model_paths_recursively(base_dir):
    for directory in get_immediate_subdirectories(base_dir):
        if is_single_model_directory(directory):
            yield directory
        else:
            yield from find_model_paths_recursively(directory)

# Get list of direct subdirectory paths under parent directory
def get_immediate_subdirectories(parent_path):
    return [
        subdir
        for name in os.listdir(parent_path)
        for subdir in [os.path.join(parent_path, name)]
        if os.path.isdir(subdir)
    ]

