# Import necessary modules for file operations and JSON loading
import os
from rlinf.envs.metaworld.utils import load_prompt_from_json

class MetaWorldBenchmark:
    def __init__(self, benchmark_name):
        # Validate the provided benchmark name
        assert benchmark_name in [
            "metaworld_50",
            "metaworld_45_ind",
            "metaworld_45_ood",
        ]
        self.benchmark_name = benchmark_name
        # Construct path to configuration file
        config_file_path = os.path.join(os.path.dirname(__file__), "metaworld_config.json")
        # Load task descriptions and ML45 split data from JSON
        self.task_info_dict = load_prompt_from_json(config_file_path, "TASK_DESCRIPTIONS")
        self.ML45_split_dict = load_prompt_from_json(config_file_path, "ML45")

    def count_tasks(self):
        # Return number of tasks based on benchmark type
        if self.benchmark_name == "metaworld_50":
            return 50
        elif self.benchmark_name == "metaworld_45_ind":
            return 45
        elif self.benchmark_name == "metaworld_45_ood":
            return 5

    def trials_per_task(self):
        # Return number of trials per task based on benchmark type
        if self.benchmark_name == "metaworld_50":
            return 10
        elif self.benchmark_name == "metaworld_45_ind":
            return 10
        elif self.benchmark_name == "metaworld_45_ood":
            return 20

    def list_env_names(self):
        # Return list of environment names based on benchmark type
        if self.benchmark_name == "metaworld_50":
            return list(self.task_info_dict.keys())
        elif self.benchmark_name == "metaworld_45_ind":
            return self.ML45_split_dict["train"]
        elif self.benchmark_name == "metaworld_45_ood":
            return self.ML45_split_dict["test"]

    def retrieve_task_descriptions(self):
        # Collect all task descriptions for current benchmark
        descriptions_list = []
        for env_name in self.list_env_names():
            descriptions_list.append(self.task_info_dict[env_name])
        return descriptions_list

output = []
    index = 0
    while index < len(text):
        if text[index] == ' ':
            # Count consecutive spaces
            space_counter = 0
            while index < len(text) and text[index] == ' ':
                space_counter += 1
                index += 1
            # If more than 2 consecutive spaces, replace with -
            if space_counter > 2:
                output.append('-')
            else:
                # Replace each space with underscore
                output.append('_' * space_counter)
        else:
            output.append(text[index])
            index += 1
    return ''.join(output)

# Import required modules for datetime, LangChain messages, and LangGraph utilities
from datetime import datetime
from langchain_core.messages import BaseMessage
from langgraph.graph.message import add_messages
from typing import Sequence, TypedDict, Annotated

def append_messages_with_time(left: Sequence[BaseMessage], right: Sequence[BaseMessage]):
    """Returns the result of add_messages after appending timestamps to messages."""
    # Ensure right is a list
    new_items = right if isinstance(right, list) else [right]

    # Generate current timestamp in ISO format
    timestamp = datetime.now().isoformat()
    for item in new_items:
        # Handle message objects with additional_kwargs attribute
        if hasattr(item, 'additional_kwargs'):
            if "timestamp" not in item.additional_kwargs:
                item.additional_kwargs["timestamp"] = timestamp
        # Handle dictionary-style messages
        elif isinstance(item, dict):
            if "additional_kwargs" not in item:
                item["additional_kwargs"] = {}
            if "timestamp" not in item["additional_kwargs"]:
                item["additional_kwargs"]["timestamp"] = timestamp
    return add_messages(left, new_items)

class AgentInfo(TypedDict):
    """Details about the chosen agent."""
    agent_name: str
    execution_mode: str  # auto/manual

class ConversationSummary(TypedDict):
    """Summary metadata for the conversation."""
    content: str
    interaction_count: int

class WorkflowState(TypedDict):
    """Current state of the workflow."""
    selected_agent: AgentInfo
    messages: Annotated[Sequence[BaseMessage], append_messages_with_time]
    summary: ConversationSummary

