# This module offers utilities to identify the App Engine environment.
"""
import os

def detect_appengine():
    return detect_local_appengine() or detect_production_appengine()

def is_first_generation_sandbox():
    """Indicates whether the application is operating within the initial 
    generation sandbox environment.
    The second-generation runtimes operate in a sandbox as well, but it is 
    significantly less restrictive; thus, such checks are typically unnecessary.
    see https://cloud.google.com/appengine/docs/standard/runtimes
    """
    return detect_appengine() and os.environ["APPENGINE_RUNTIME"] == "python27"

def detect_local_appengine():
    return "APPENGINE_RUNTIME" in os.environ and os.environ.get(
        "SERVER_SOFTWARE", ""
    ).startswith("Development/")

def detect_production_appengine():
    return "APPENGINE_RUNTIME" in os.environ and os.environ.get(
        "SERVER_SOFTWARE", ""
    ).startswith("Google App Engine/")

def is_mvms_environment():
