        super().__init__(questions_file, images_dir)

    def construct_prompt(self, sample):
        messages = super().construct_prompt(sample)
        if messages[-1]['format'] != 'text':
            raise ValueError(
                "The final message in the sequence should be of type 'text', but encountered '{}'.".format(messages[-1]['format']))
        messages[-1]['content'] += '\nRespond to the question with a single word or short phrase.'
        return messages

# Modified version with Type I clone transformations
import json
import sys

@dataclass
class BoxAndData:
    box: list[float]
    box_type: str
    data: dict

def validate_bounding_boxes(json_data_stream) -> list[str]:
    output_lines = []
    data = json.load(json_data_stream)
    output_lines.append(f"Processed {len(data['form_fields'])} fields")

    def boxes_overlap(b1, b2):
        non_overlapping_x = b1[0] >= b2[2] or b1[2] <= b2[0]
        non_overlapping_y = b1[1] >= b2[3] or b1[3] <= b2[1]
        return not (non_overlapping_x or non_overlapping_y)

    boxes_and_items = []
    for item in data["form_fields"]:
        boxes_and_items.append(BoxAndData(item["label_bounding_box"], "label", item))
        boxes_and_items.append(BoxAndData(item["entry_bounding_box"], "entry", item))

    found_issues = False

    for idx, current_box in enumerate(boxes_and_items):
        for next_idx in range(idx + 1, len(boxes_and_items)):
            next_box = boxes_and_items[next_idx]

            if (current_box.data["page_number"] == next_box.data["page_number"] and 
                boxes_overlap(current_box.box, next_box.box)):

                found_issues = True

                if current_box.data is next_box.data:
                    output_lines.append(
                        f"ERROR: overlapping label and entry bounding boxes for `{current_box.data['description']}` "
                        f"({current_box.box}, {next_box.box})"
                    )
                else:
                    output_lines.append(
                        f"ERROR: {current_box.box_type} bounding box for `{current_box.data['description']}` "
                        f"({current_box.box}) overlaps with {next_box.box_type} bounding box for "
                        f"`{next_box.data['description']}` ({next_box.box})"
                    )

                if len(output_lines) >= 20:
                    output_lines.append("Stopping additional checks; correct bounding boxes and re-run")
                    return output_lines

        if current_box.box_type == "entry":
            if "entry_text" in current_box.data:
                text_info = current_box.data["entry_text"]
                font_size = text_info.get("font_size", 14)
                box_height = current_box.box[3] - current_box.box[1]

                if box_height < font_size:
                    found_issues = True
                    output_lines.append(
                        f"ERROR: entry bounding box height ({box_height}) for `{current_box.data['description']}` "
                        f"is insufficient for the text content (font size: {font_size}). "
                        f"Either increase the box height or reduce the font size."
                    )

                    if len(output_lines) >= 20:
                        output_lines.append("Stopping additional checks; correct bounding boxes and re-run")
                        return output_lines

    if not found_issues:
        output_lines.append("OK: All bounding boxes meet requirements")

    return output_lines

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: check_bounding_boxes.py [fields.json]")
        sys.exit(1)

    with open(sys.argv[1]) as file:
        results = validate_bounding_boxes(file)

    for line in results:
        print(line)

# Data structures that power Requests.
"""
from collections import OrderedDict
from .compat import Mapping, MutableMapping

class CaseInsensitiveDict(MutableMapping):
    """A case-insensitive ``dict``-like object.
    Implements all methods and operations of
    ``MutableMapping`` as well as dict's ``copy``. Also
    provides ``lower_items``.
    All keys are expected to be strings. The structure remembers the
    case of the last key to be set, and ``iter(instance)``,
    ``keys()``, ``items()``, ``iterkeys()``, and ``iteritems()``
    will contain case-sensitive keys. However, querying and contains
    testing is case insensitive::
        cid = CaseInsensitiveDict()
        cid['Accept'] = 'application/json'
        cid['aCCEPT'] == 'application/json'  # True
        list(cid) == ['Accept']  # True
    For example, ``headers['content-encoding']`` will return the
    value of a ``'Content-Encoding'`` response header, regardless
    of how the header name was originally stored.
    If the constructor, ``.update``, or equality comparison
    operations are given keys that have equal ``.lower()``s, the
    behavior is undefined.
    """
    def __init__(self, data=None, **kwargs):
        self._data = OrderedDict()
        if data is None:
            data = {}
        self.update(data, **kwargs)

    def __setitem__(self, key, value):
        # Store the original key with its value, using lowercase for lookup
        self._data[key.lower()] = (key, value)

    def __getitem__(self, key):
        return self._data[key.lower()][1]

    def __delitem__(self, key):
        del self._data[key.lower()]

    def __iter__(self):
        return (original_key for original_key, _ in self._data.values())

    def __len__(self):
        return len(self._data)

    def lower_items(self):
        """Like iteritems(), but with all lowercase keys."""
        return ((lower_key, value) for lower_key, (_, value) in self._data.items())

    def __eq__(self, other):
        if isinstance(other, Mapping):
            other = CaseInsensitiveDict(other)
        else:
            return NotImplemented
        # Compare insensitively
        return dict(self.lower_items()) == dict(other.lower_items())

    # Copy is required
    def copy(self):
        return CaseInsensitiveDict(self._data.values())

    def __repr__(self):
        return str(dict(self.items()))


class LookupDict(dict):
    """Dictionary lookup object."""
    def __init__(self, name=None):
        self.name = name
        super().__init__()

    def __repr__(self):
        return f"<lookup '{self.name}'>"

    def __getitem__(self, key):
        # We allow fall-through here, so values default to None
        return getattr(self, '__dict__', {}).get(key, None)

    def get(self, key, default=None):
        return getattr(self, '__dict__', {}).get(key, default)

