import logging
from app.collectors.base import Collector, CollectorResult

logger = logging.getLogger("docsis.collector.backup")

class BackupDataCollector(Collector):
    """Collector responsible for generating scheduled data backups."""
    identifier = "backup"

    def __init__(self, config_handler, check_interval=86400, **options):
        super().__init__(check_interval)
        self._config_handler = config_handler

    def is_active(self):
        return self._config_handler.is_backup_enabled()

    def execute(self):
        from .backup import generate_backup_file, remove_expired_backups

        storage_dir = self._config_handler.data_directory
        target_path = self._config_handler.fetch("backup_location", "/backup")
        keep_count = self._config_handler.fetch("backup_retention_days", 5)

        try:
            backup_file = generate_backup_file(storage_dir, target_path)
            remove_expired_backups(target_path, max_kept=keep_count)
            logger.info("Automated backup completed: %s", backup_file)
            return CollectorResult.success(self.identifier, {"path": backup_file})
        except Exception as error:
            logger.warning("Backup process failed: %s", error)
            return CollectorResult.error(self.identifier, str(error))

# Simulate banking operations with transaction tracking and balance history

from datetime import datetime, timedelta
from typing import List, Optional

class FinancialOperation:
    def __init__(self, operation_kind: str, value: float, note: Optional[str] = None):
        self.operation_kind = operation_kind
        self.value = value
        self.note = note
        self.timestamp = datetime.now()

    def __repr__(self):
        return (f"FinancialOperation(kind={self.operation_kind}, value={self.value}, "
                f"note={self.note}, timestamp={self.timestamp})")

class EnhancedBankingAccount:
    def __init__(self, owner_name: str, contact_email: str, starting_amount: float = 0.0):
        self.owner_name = owner_name
        self.contact_email = contact_email
        self.current_amount = starting_amount
        self.operation_log: List[FinancialOperation] = []

    def add_funds(self, amount: float, note: Optional[str] = None) -> None:
        if amount <= 0:
            raise ValueError("Amount to add must be greater than zero.")
        self.current_amount += amount
        self.operation_log.append(FinancialOperation("add", amount, note))

    def remove_funds(self, amount: float, note: Optional[str] = None) -> None:
        if amount <= 0:
            raise ValueError("Amount to remove must be greater than zero.")
        if amount > self.current_amount:
            raise ValueError("Insufficient balance for this operation.")
        self.current_amount -= amount
        self.operation_log.append(FinancialOperation("remove", amount, note))

    def shift_funds(self, target_account: 'EnhancedBankingAccount', amount: float, note: Optional[str] = None) -> None:
        if amount <= 0:
            raise ValueError("Transfer amount must be positive.")
        if amount > self.current_amount:
            raise ValueError("Insufficient funds for transfer.")

        self.remove_funds(amount, f"Outgoing transfer to {target_account.owner_name}")
        target_account.add_funds(amount, f"Incoming transfer from {self.owner_name}")

    def fetch_operation_records(self, from_time: Optional[datetime] = None, until_time: Optional[datetime] = None) -> List[FinancialOperation]:
        if from_time is None:
            from_time = datetime.min
        if until_time is None:
            until_time = datetime.max

        return [record for record in self.operation_log if from_time <= record.timestamp <= until_time]

    def calculate_balance_at_time(self, reference_time: datetime) -> float:
        current_balance = 0.0
        for record in self.operation_log:
            if record.timestamp <= reference_time:
                if record.operation_kind == "add":
                    current_balance += record.value
                elif record.operation_kind in ("remove", "shift"):
                    current_balance -= record.value
        return current_balance

# Demonstration usage:
if __name__ == "__main__":
    user_account1 = EnhancedBankingAccount("Alice", "redacted@example.invalid", 1000.0)
    user_account2 = EnhancedBankingAccount("Bob", "redacted@example.invalid")

    user_account1.add_funds(500.0, "Salary deposit")
    user_account1.remove_funds(200.0, "Retail purchase")
    user_account1.shift_funds(user_account2, 300.0, "Rent transfer")

    print(f"User Account 1 Balance: {user_account1.current_amount}")
    print(f"User Account 2 Balance: {user_account2.current_amount}")

    print("User Account 1 Operation Log:")
    for record in user_account1.fetch_operation_records():
        print(record)

    print("User Account 2 Operation Log:")
    for record in user_account2.fetch_operation_records():
        print(record)

    previous_date = datetime.now() - timedelta(days=1)
    print(f"User Account 1 Balance on {previous_date}: {user_account1.calculate_balance_at_time(previous_date)}")

# Employee Management System - Alternative Implementation

import uuid
from datetime import date

class StaffMember:
    def __init__(self, full_name, years_exp, compensation, position, join_date_str):
        self.unique_identifier = str(uuid.uuid4())
        self.full_name = full_name
        self.years_exp = years_exp
        self.compensation = compensation
        self.position = position
        self.join_date_str = join_date_str

    def compute_tenure(self):
        current_date = date.today()
        year, month, day = map(int, self.join_date_str.split('-'))
        join_date_obj = date(year, month, day)
        delta_days = (current_date - join_date_obj).days
        return delta_days // 365

    def __repr__(self):
        return f"Staff ID: {self.unique_identifier}, Name: {self.full_name}, Age: {self.years_exp}, Pay: {self.compensation}, Position: {self.position}, Joined: {self.join_date_str}"

class HumanResourcesManager:
    def __init__(self):
        self.staff_list = []

    def register_staff(self, full_name, years_exp, compensation, position, join_date_str):
        new_member = StaffMember(full_name, years_exp, compensation, position, join_date_str)
        self.staff_list.append(new_member)
        print(f"Staff member {full_name} has been registered.")

    def deregister_staff(self, target_id):
        for member in self.staff_list:
            if member.unique_identifier == target_id:
                self.staff_list.remove(member)
                print(f"Staff member with ID {target_id} has been removed.")
                return
        print(f"No staff member found with ID {target_id}.")

    def modify_staff_details(self, target_id, **changes):
        for member in self.staff_list:
            if member.unique_identifier == target_id:
                for attribute, new_value in changes.items():
                    setattr(member, attribute, new_value)
                print(f"Staff member with ID {target_id} has been updated.")
                return
        print(f"No staff member found with ID {target_id}.")

    def locate_staff(self, target_id):
        for member in self.staff_list:
            if member.unique_identifier == target_id:
                return member
        print(f"Staff member with ID {target_id} not found.")
        return None

    def get_tenure(self, target_id):
        staff_member = self.locate_staff(target_id)
        if staff_member:
            return staff_member.compute_tenure()
        return None

    def display_all_staff(self):
        for member in self.staff_list:
            print(member)

    def is_executive_role(self, target_id):
        staff_member = self.locate_staff(target_id)
        if staff_member and staff_member.position.lower() == 'management':
            return True
        return False

# Demonstration
if __name__ == "__main__":
    hr_system = HumanResourcesManager()

    # Register team members
    hr_system.register_staff("Alice", 30, 50000, "Management", "2018-01-01")
    hr_system.register_staff("Bob", 25, 30000, "Developer", "2020-03-15")
    hr_system.register_staff("Charlie", 35, 60000, "Management", "2015-06-20")

    # Show all registered staff
    print("All registered staff:")
    hr_system.display_all_staff()

    # Modify one staff member's details
    hr_system.modify_staff_details(hr_system.staff_list[0].unique_identifier, compensation=55000)

    # Remove a staff member
    hr_system.deregister_staff(hr_system.staff_list[1].unique_identifier)

    # Calculate tenure for remaining staff
    print(f"Tenure for {hr_system.staff_list[0].full_name}: {hr_system.get_tenure(hr_system.staff_list[0].unique_identifier)} years")

    # Check executive status
    print(f"Is {hr_system.staff_list[0].full_name} in management? {hr_system.is_executive_role(hr_system.staff_list[0].unique_identifier)}")

