# Check for duplicate characters in a string using a different approach

def contains_repeated_chars(text):
    """
    Determine if the input string has any repeated characters.

    :param text: The string to examine
    :return: True if duplicates exist, False otherwise
    """
    char_counts = {}
    for character in text:
        if character in char_counts:
            return True
        char_counts[character] = 1
    return False

