import json

def filter_out_empty_values(obj):
    if isinstance(obj, dict):
        result = {}
        for key, value in obj.items():
            processed_value = filter_out_empty_values(value)
            # Keep the item if it's truthy, or if it's explicitly False/0 (to preserve intentional falsy values)
            if processed_value or isinstance(processed_value, bool) or processed_value == 0:
                result[key] = processed_value
        return result
    elif isinstance(obj, list):
        filtered_list = []
        for item in obj:
            processed_item = filter_out_empty_values(item)
            if processed_item or isinstance(processed_item, bool) or processed_item == 0:
                filtered_list.append(processed_item)
        return filtered_list
    return obj

