# Custom type-checking implementation for a simple language

from antlr4 import *
from SimpleLanguageLexer import SimpleLanguageLexer
from SimpleLanguageParser import SimpleLanguageParser
from SimpleLanguageVisitor import SimpleLanguageVisitor

class VariableScope:
    def __init__(self):
        self.variables = {}

    def declare(self, identifier, var_type):
        self.variables[identifier] = var_type

    def lookup(self, identifier):
        return self.variables.get(identifier)

class TypeValidator(SimpleLanguageVisitor):
    def __init__(self):
        self.scope = VariableScope()

    def visitVariableDeclaration(self, ctx):
        var_name = ctx.ID().getText()
        declared_type = ctx.type().getText()
        self.scope.declare(var_name, declared_type)
        return self.visitChildren(ctx)

    def visitAssignStatement(self, ctx):
        var_id = ctx.ID().getText()
        if var_id not in self.scope.variables:
            raise ValueError(f"Unknown variable referenced: {var_id}")

        expression_type = self.visit(ctx.expression())
        stored_type = self.scope.lookup(var_id)

        if expression_type != stored_type:
            raise ValueError(f"Incompatible types: {expression_type} assigned to {stored_type}")

        return stored_type

    def visitExpression(self, ctx):
        if ctx.INT():
            return 'int'
        elif ctx.ID():
            var_name = ctx.ID().getText()
            return self.scope.lookup(var_name)

def run_analysis():
    file_stream = FileStream('input.txt')
    token_lexer = SimpleLanguageLexer(file_stream)
    token_stream = CommonTokenStream(token_lexer)
    parser = SimpleLanguageParser(token_stream)
    syntax_tree = parser.prog()

    validator = TypeValidator()
    validator.visit(syntax_tree)

if __name__ == "__main__":
    run_analysis()

