def perform_search(query):
    if not query.strip():
        return []

    def matches(item):
        title_check = query.lower() in item['headline'].lower()
        desc_check = query.lower() in item['description'].lower()
        return title_check or desc_check

    return [item for item in items_list if matches(item)]

