# Calculate frustum properties for circular and elliptical shapes

import math

def check_dimensions(r1, r2, h, a1=None, a2=None, b1=None, b2=None):
    # Validate that all provided dimensions are positive
    if r1 <= 0 or r2 <= 0 or h <= 0:
        raise ValueError("All radii and height must be positive.")

    # If elliptical parameters are provided, validate them too
    if all(param is not None for param in [a1, a2, b1, b2]):
        if a1 <= 0 or a2 <= 0 or b1 <= 0 or b2 <= 0:
            raise ValueError("All semi-axes and height must be positive.")

def curved_surface_circular(r1, r2, h):
    # Lateral surface area for circular frustum
    return math.pi * (r1 + r2) * math.sqrt((r2 - r1)**2 + h**2)

def curved_surface_elliptical(a1, a2, b1, b2, h):
    # Lateral surface area for elliptical frustum (sum of two components)
    part1 = math.pi * (a1 + a2) * math.sqrt((a2 - a1)**2 + h**2)
    part2 = math.pi * (b1 + b2) * math.sqrt((b2 - b1)**2 + h**2)
    return part1 + part2

def capacity_circular(r1, r2, h):
    # Volume for circular frustum
    return (math.pi * h / 3) * (r1**2 + r2**2 + r1 * r2)

def capacity_elliptical(a1, a2, b1, b2, h):
    # Volume for elliptical frustum
    return (math.pi * h / 3) * (a1 * b1 + a2 * b2 + math.sqrt(a1 * b1 * a2 * b2))

def process_frustums(frustum_data):
    output = []
    for data in frustum_data:
        r1 = data['r1']
        r2 = data['r2']
        h = data['h']
        a1 = data.get('a1')
        a2 = data.get('a2')
        b1 = data.get('b1')
        b2 = data.get('b2')

        check_dimensions(r1, r2, h, a1, a2, b1, b2)

        if all(param is not None for param in [a1, a2, b1, b2]):
            lateral_area = curved_surface_elliptical(a1, a2, b1, b2, h)
            total_volume = capacity_elliptical(a1, a2, b1, b2, h)
        else:
            lateral_area = curved_surface_circular(r1, r2, h)
            total_volume = capacity_circular(r1, r2, h)

        output.append({
            'curved_surface': lateral_area,
            'capacity': total_volume
        })

    return output

# Example usage
frustum_list = [
    {'r1': 3, 'r2': 5, 'h': 4},
    {'r1': 2, 'r2': 4, 'h': 3, 'a1': 3, 'a2': 5, 'b1': 2, 'b2': 4}
]

results = process_frustums(frustum_list)
for idx, res in enumerate(results):
    print(f"Frustum {idx+1}: Curved Surface Area = {res['curved_surface']:.15f}, Capacity = {res['capacity']:.15f}")

# Type III Clone: Binary Search Tree with alternative implementation approach

class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

class BST:
    def __init__(self):
        self.root = None

    def insert(self, val):
        if not self.root:
            self.root = Node(val)
            return

        current = self.root
        while True:
            if val < current.data:
                if current.left is None:
                    current.left = Node(val)
                    break
                current = current.left
            elif val > current.data:
                if current.right is None:
                    current.right = Node(val)
                    break
                current = current.right
            else:
                # Value already exists, do nothing
                break

    def delete(self, val):
        self.root, found = self._delete_node(self.root, val)
        return found

    def _delete_node(self, node, val):
        if not node:
            return None, False

        if val < node.data:
            node.left, found = self._delete_node(node.left, val)
        elif val > node.data:
            node.right, found = self._delete_node(node.right, val)
        else:
            # Found the node to delete
            if not node.left and not node.right:
                return None, True
            elif not node.left:
                return node.right, True
            elif not node.right:
                return node.left, True
            else:
                # Find in-order successor (minimum in right subtree)
                successor = self._find_min(node.right)
                node.data = successor.data
                node.right, _ = self._delete_node(node.right, successor.data)
                return node, True

        return node, found

    def _find_min(self, node):
        while node.left:
            node = node.left
        return node

    def find(self, val):
        current = self.root
        while current:
            if val == current.data:
                return True
            elif val < current.data:
                current = current.left
            else:
                current = current.right
        return False

    def get_inorder(self):
        result = []
        self._inorder(self.root, result)
        return result

    def _inorder(self, node, result):
        if node:
            self._inorder(node.left, result)
            result.append(node.data)
            self._inorder(node.right, result)

    def get_preorder(self):
        result = []
        self._preorder(self.root, result)
        return result

    def _preorder(self, node, result):
        if node:
            result.append(node.data)
            self._preorder(node.left, result)
            self._preorder(node.right, result)

    def get_postorder(self):
        result = []
        self._postorder(self.root, result)
        return result

    def _postorder(self, node, result):
        if node:
            self._postorder(node.left, result)
            self._postorder(node.right, result)
            result.append(node.data)

    def get_level_order(self):
        if not self.root:
            return []

        result = []
        queue = [self.root]

        while queue:
            current = queue.pop(0)
            result.append(current.data)

            if current.left:
                queue.append(current.left)
            if current.right:
                queue.append(current.right)

        return result

    def minimum(self):
        if not self.root:
            raise ValueError("Tree is empty")
        return self._find_min(self.root).data

    def maximum(self):
        if not self.root:
            raise ValueError("Tree is empty")
        current = self.root
        while current.right:
            current = current.right
        return current.data

    def height(self):
        return self._calculate_height(self.root)

    def _calculate_height(self, node):
        if not node:
            return 0
        left_h = self._calculate_height(node.left)
        right_h = self._calculate_height(node.right)
        return max(left_h, right_h) + 1

# Example usage
tree = BST()
tree.insert(10)
tree.insert(5)
tree.insert(15)
tree.insert(3)
