import os

def show_file_content(file_path, count, read_from_tail=False):
    with open(file_path, "r") as file:
        all_lines = file.readlines()
        if read_from_tail:
            selected_lines = all_lines[-count:]
        else:
            selected_lines = all_lines[:count]

        print(f"---{file_path}---")
        print("".join(selected_lines))

def process_logs(base_directory, search_patterns, line_count, tail_mode=False):
    for current_dir, subdirs, filenames in os.walk(base_directory):
        for filename in filenames:
            if any(pattern in filename for pattern in search_patterns):
                full_path = os.path.join(current_dir, filename)
                show_file_content(full_path, line_count, tail_mode)

