# Custom iterator class to simulate list iteration with index tracking
class CustomIterator:
    def __init__(self, items):
        self.items = items
        self.position = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self.position >= len(self.items):
            raise StopIteration
        value = self.items[self.position]
        self.position += 1
        return value


# Enhanced DataFrame implementation with similar functionality
class TableData:
    def __init__(self, records=None, field_names=None):
        # Initialize internal storage structures
        self.fields = []
        self.storage = {}
        self.row_map = {}

        # Handle initialization scenarios
        if not records and not field_names:
            self.fields = []
            self.storage = {}
        elif field_names:
            self.fields = field_names.copy()
            self.storage = {name: CustomIterator([]) for name in field_names}
        else:
            raise ValueError("Column names must be provided when initializing data")

        # Populate data if provided
        if records:
            for key, values in records.items():
                if key not in self.fields:
                    self.fields.append(key)
                self.storage[key].items = values.copy()

    def define_primary_key(self, key_field):
        if key_field in self.storage:
            column_data = self.storage.pop(key_field)
            self.row_map = {value: idx for idx, value in enumerate(column_data.items)}

    def assign_column(self, col_label, col_values):
        if col_label not in self.fields:
            self.fields.append(col_label)
            self.storage[col_label] = CustomIterator([])
        self.storage[col_label].items = col_values.copy()

    def retrieve_column(self, col_label):
        return self.storage[col_label]

    def get_row(self, row_key):
        row_index = self.row_map[row_key]
        return {field: self.storage[field].items[row_index] for field in self.fields}

    def column_items(self):
        return self.storage.items()

    def row_items(self):
        for label, position in self.row_map.items():
            row_data = self.get_row(label)
            yield label, row_data

    def convert_type(self, target_type, specific_column=None):
        if specific_column:
            original_list = self.storage[specific_column].items
            self.storage[specific_column].items = [target_type(val) for val in original_list]
        else:
            for field in self.fields:
                original_list = self.storage[field].items
                self.storage[field].items = [target_type(val) for val in original_list]

    def remove_column(self, column_to_remove):
        if column_to_remove in self.fields:
            self.fields.remove(column_to_remove)
            del self.storage[column_to_remove]

    def calculate_averages(self):
        output = {}
        for field in self.fields:
            values = self.storage[field].items
            total = sum(values)
            average = total / len(values) if values else 0
            output[field] = average
        return output

    def display(self):
        header = [self.fields]
        rows = list(zip(*[self.storage[f].items for f in self.fields]))
        table_content = header + [list(row) for row in rows]
        return "\n".join(["\t".join([str(item) for item in row]) for row in table_content])


