# Main WSGI application entry point
def wsgi_app(environ, start_response):
    req = AppRequest(environ)
    adapter = routes.bind_to_environ(environ)

    try:
        endpoint, params = adapter.match()
        result = globals()[endpoint](req, **params)
    except HTTPException as error:
        result = error
    except Exception as error:
        result = Response('Server Error Occurred', status=500, content_type='text/html')

    return result(environ, start_response)

