# Custom web crawler to extract image URLs with depth control

import scrapy
from scrapy.linkextractors import LinkExtractor
from scrapy.spiders import CrawlSpider, Rule
from bs4 import BeautifulSoup
import requests

class ImageCrawler(CrawlSpider):
    name = 'image_extractor'
    allowed_domains = ['example.com']
    start_urls = ['http://example.com']

    rules = (
        Rule(LinkExtractor(allow=(), restrict_css=()), callback="extract_images", follow=True, process_request='filter_requests'),
    )

    def filter_requests(self, req):
        # Allow only the initial URL or requests with depth less than 2
        if req.url == self.start_urls[0]:
            return req
        current_depth = req.meta.get('depth', 0)
        if isinstance(current_depth, list):
            current_depth = len(current_depth)
        if current_depth < 2:
            return req

    def extract_images(self, response):
        parsed_page = BeautifulSoup(response.body, 'html.parser')
        img_tags = parsed_page.find_all('img')
        for image_tag in img_tags:
            image_src = image_tag.get('src')
            if image_src:
                yield {
                    'image_url': response.urljoin(image_src),
                    'source_page': response.url
                }

# Determine the largest Fibonacci number among six given integers

def is_perfect_square(n):
    if n < 0:
        return False
    root = int(n ** 0.5)
    return root * root == n

def check_fibonacci_property(value):
    # Using the mathematical property: n is Fibonacci iff 
    # (5n² + 4) or (5n² - 4) is a perfect square
    test1 = 5 * value * value + 4
    test2 = 5 * value * value - 4
    return is_perfect_square(test1) or is_perfect_square(test2)

def locate_max_fibonacci(a, b, c, d, e, f):
    candidates = [a, b, c, d, e, f]
    max_fib = None

    for candidate in candidates:
        if check_fibonacci_property(candidate):
            if max_fib is None or candidate > max_fib:
                max_fib = candidate

    return max_fib

