# Find the maximum profit from a list of stock prices  
# by tracking the lowest price seen so far and computing potential profits  

def max_profit(prices):
    if len(prices) == 0:
        return 0

    min_so_far = float('inf')
    best_gain = 0

    for current_price in prices:
        if current_price < min_so_far:
            min_so_far = current_price

        current_gain = current_price - min_so_far
        if current_gain > best_gain:
            best_gain = current_gain

    return best_gain

# Type III Clone: Doubly Linked List Implementation with Alternative Logic

class ListNode:
    def __init__(self, data):
        self.data = data
        self.forward = None
        self.backward = None

class BidirectionalList:
    def __init__(self):
        self.start = None
        self.end = None
        self.length = 0

    def is_empty(self):
        return self.length == 0

    def insert_head(self, data):
        node = ListNode(data)
        if self.is_empty():
            self.start = self.end = node
        else:
            node.forward = self.start
            self.start.backward = node
            self.start = node
        self.length += 1

    def insert_tail(self, data):
        node = ListNode(data)
        if self.is_empty():
            self.start = self.end = node
        else:
            node.backward = self.end
            self.end.forward = node
            self.end = node
        self.length += 1

    def insert_at(self, position, data):
        if position < 0 or position > self.length:
            raise IndexError("Position out of bounds")

        if position == 0:
            self.insert_head(data)
        elif position == self.length:
            self.insert_tail(data)
        else:
            node = ListNode(data)
            current = self.start
            for _ in range(position - 1):
                current = current.forward

            node.forward = current.forward
            node.backward = current
            current.forward.backward = node
            current.forward = node
            self.length += 1

    def delete_head(self):
        if self.is_empty():
            raise IndexError("List is empty")

        value = self.start.data
        if self.start == self.end:
            self.start = self.end = None
        else:
            self.start = self.start.forward
            self.start.backward = None
        self.length -= 1
        return value

    def delete_tail(self):
        if self.is_empty():
            raise IndexError("List is empty")

        value = self.end.data
        if self.start == self.end:
            self.start = self.end = None
        else:
            self.end = self.end.backward
            self.end.forward = None
        self.length -= 1
        return value

    def delete_at(self, position):
        if position < 0 or position >= self.length:
            raise IndexError("Position out of bounds")

        if position == 0:
            return self.delete_head()
        if position == self.length - 1:
            return self.delete_tail()

        current = self.start
        for _ in range(position):
            current = current.forward

        value = current.data
        current.backward.forward = current.forward
        current.forward.backward = current.backward
        self.length -= 1
        return value

    def to_array(self):
        output = []
        current = self.start
        while current:
            output.append(current.data)
            current = current.forward
        return output

def validate_bidirectional_list():
    bdl = BidirectionalList()

    # Test insertion operations
    bdl.insert_head(1)
    bdl.insert_tail(3)
    bdl.insert_at(1, 2)
    assert bdl.to_array() == [1, 2, 3], "Insertion tests failed"

    # Test deletion operations
    bdl.delete_head()
    bdl.delete_tail()
    bdl.delete_at(0)
    assert bdl.to_array() == [], "Deletion tests failed"

    # Test error handling
    try:
        bdl.insert_at(-1, 1)
        assert False, "Negative index insertion should fail"
    except IndexError:
        pass

    try:
        bdl.insert_at(1, 1)
        assert False, "Out-of-bounds insertion should fail"
    except IndexError:
        pass

    try:
        bdl.delete_at(-1)
        assert False, "Negative index deletion should fail"
    except IndexError:
        pass

    try:
        bdl.delete_at(0)
        assert False, "Deletion from empty list should fail"
    except IndexError:
        pass

    print("All validation checks passed!")

