# Calculate factorial using two different approaches and compare performance

import time

def compute_factorial_loop(n):
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers")
    product = 1
    counter = 2
    while counter <= n:
        product *= counter
        counter += 1
    return product

def compute_factorial_recursion(n):
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers")
    if n == 0 or n == 1:
        return 1
    return n * compute_factorial_recursion(n - 1)

def benchmark_function(func, value):
    begin = time.time()
    outcome = func(value)
    finish = time.time()
    return outcome, finish - begin

def run_comparison():
    user_input = int(input("Enter a non-negative integer: "))

    # Compute using loop-based method
    loop_result, loop_duration = benchmark_function(compute_factorial_loop, user_input)

    # Compute using recursive method
    recursive_result, recursive_duration = benchmark_function(compute_factorial_recursion, user_input)

    print(f"Factorial of {user_input} (Loop Method): {loop_result}")
    print(f"Execution Time (Loop Method): {loop_duration:.6f} seconds")

    print(f"Factorial of {user_input} (Recursive Method): {recursive_result}")
    print(f"Execution Time (Recursive Method): {recursive_duration:.6f} seconds")

    if loop_result == recursive_result:
        print("Both implementations yielded identical results.")
    else:
        print("The implementations produced conflicting outcomes.")

if __name__ == "__main__":
    run_comparison()

import xml.etree.ElementTree as ET
import json

def convert_xml_to_map(node):
    """Transforms an XML node into a nested dictionary structure."""
    result = {node.tag: {} if len(node.attrib) > 0 else None}
    child_nodes = list(node)

    if child_nodes:
        temp_dict = {}
        for child_result in map(convert_xml_to_map, child_nodes):
            for key, value in child_result.items():
                if key in temp_dict:
                    temp_dict[key].append(value)
                else:
                    temp_dict[key] = [value]

        processed = {}
        for k, v in temp_dict.items():
            processed[k] = v[0] if len(v) == 1 else v
        result = {node.tag: processed}

    if node.attrib:
        if result[node.tag] is None:
            result[node.tag] = {}
        result[node.tag].update(node.attrib.items())

    if node.text:
        cleaned_text = node.text.strip()
        if child_nodes or node.attrib:
            if cleaned_text:
                result[node.tag]['#text'] = cleaned_text
        else:
            result[node.tag] = cleaned_text

    return result

def transform_xml_to_json(xml_content):
    """Converts XML content to a formatted JSON string."""
    tree_root = ET.fromstring(xml_content)
    data_map = convert_xml_to_map(tree_root)
    json_formatted = json.dumps(data_map, indent=4)
    return json_formatted

