# Generate prime multiplication tables in decimal and binary formats

import csv

def is_prime(n):
    """Check if a number is prime."""
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def get_primes_up_to(limit):
    """Get all prime numbers up to the given limit."""
    return [num for num in range(2, limit + 1) if is_prime(num)]

def to_binary_string(number):
    """Convert a number to its binary representation without '0b' prefix."""
    return format(number, 'b')

def create_prime_table(prime_list, output_format='decimal'):
    """Create a multiplication table for primes in the specified format."""
    if output_format not in ('decimal', 'binary'):
        raise ValueError("Format must be 'decimal' or 'binary'")

    # Prepare header row
    if output_format == 'decimal':
        header = [''] + list(map(str, prime_list))
    else:
        header = [''] + [to_binary_string(p) for p in prime_list]

    result_table = [header]

    # Build each row of the table
    for p in prime_list:
        if output_format == 'decimal':
            row = [str(p)]
        else:
            row = [to_binary_string(p)]

        for q in prime_list:
            product = p * q
            if output_format == 'decimal':
                row.append(str(product))
            else:
                row.append(to_binary_string(product))

        result_table.append(row)

    return result_table

def write_tables_to_file(filename, all_tables):
    """Write multiple tables to a CSV file with blank rows between them."""
    with open(filename, 'w', newline='') as file:
        writer = csv.writer(file)
        for table in all_tables:
            for row in table:
                writer.writerow(row)
            writer.writerow([])  # Blank line separator between tables

def main():
    # Define input values and output formats
    test_values = [5, 7]
    output_modes = ['decimal', 'binary']

    # Generate all tables
    generated_tables = []
    for value in test_values:
        primes = get_primes_up_to(value)
        for mode in output_modes:
            table = create_prime_table(primes, mode)
            generated_tables.append(table)

    # Save results to CSV
    write_tables_to_file("prime_multiplication.csv", generated_tables)

if __name__ == "__main__":
    main()

# Modified version to filter even elements from nested structures

def extract_even_values(data_structure):
    def check_numeric_even(value_str):
        """Determine if a string can be interpreted as an even number."""
        try:
            numeric_value = float(value_str)
            return numeric_value.is_integer() and int(numeric_value) % 2 == 0
        except (ValueError, TypeError):
            return False

    def normalize_item(item):
        """Convert mutable types (lists/dicts) into immutable tuple form."""
        if isinstance(item, list):
            return tuple(item)
        elif isinstance(item, dict):
            return tuple(item.items())
        return item

    def is_valid_even_component(component):
        """Verify whether the component qualifies as an even element."""
        if isinstance(component, int) and component % 2 == 0:
            return True
        elif isinstance(component, float) and component.is_integer() and int(component) % 2 == 0:
            return True
        elif isinstance(component, str) and check_numeric_even(component):
            return True
        elif isinstance(component, tuple):
            return True
        return False

    def traverse_and_collect(structure):
        """Traverse recursively through the structure and collect valid even components."""
        collected = ()
        for part in structure:
            normalized_part = normalize_item(part)
            if isinstance(normalized_part, tuple):
                collected += (traverse_and_collect(normalized_part),)
            elif is_valid_even_component(normalized_part):
                collected += (normalized_part,)
        return collected

    return traverse_and_collect(data_structure)

