def transform_string(input_text: str) -> str:
    def toggle_case(char):
        if char.isalpha():
            return char.upper() if char.islower() else char.lower()
        return char

    def substitute_even_digit(current_char, previous_digit_val):
        if current_char.isdigit() and int(current_char) % 2 == 0:
            return str(factorial(int(previous_digit_val)))
        return current_char

    def duplicate_non_alphanumeric(char, duplication_factor):
        if not char.isalnum():
            return char * duplication_factor
        return char

    def arrange_descending_ascii(string_val):
        return ''.join(sorted(string_val, reverse=True))

    # Phase 1: Toggle character casing
    transformed = [toggle_case(ch) for ch in input_text]
    input_text = ''.join(transformed)

    # Phase 2: Substitute even digits using preceding digit's factorial
    result_chars = []
    last_digit = None
    for char in input_text:
        if char.isdigit():
            if last_digit is not None:
                result_chars.append(substitute_even_digit(char, last_digit))
            else:
                result_chars.append(char)
            last_digit = char
        else:
            result_chars.append(char)
            last_digit = None
    input_text = ''.join(result_chars)

    # Phase 3: Duplicate special characters based on prime count
    special_occurrences = {}
    for char in input_text:
        if not char.isalnum():
            special_occurrences[char] = special_occurrences.get(char, 0) + 1

    total_specials = sum(special_occurrences.values())
    prime_multiplier = nextprime(total_specials)

    output_chars = []
    for char in input_text:
        output_chars.append(duplicate_non_alphanumeric(char, prime_multiplier))
    input_text = ''.join(output_chars)

    # Phase 4: Sort characters in descending ASCII order
    input_text = arrange_descending_ascii(input_text)

    return input_text

