# Type III Clone: Refactored expression tree evaluator with alternative logic

from abc import ABC, abstractmethod
from typing import List, Union

class ExpressionNode(ABC):
    @abstractmethod
    def compute(self) -> int:
        pass

    @abstractmethod
    def format(self) -> str:
        pass

class NumberNode(ExpressionNode):
    def __init__(self, num: int):
        self.number = num

    def compute(self) -> int:
        return self.number

    def format(self) -> str:
        return str(self.number)

class BinaryOperationNode(ExpressionNode):
    def __init__(self, op_symbol: str, operand_a: ExpressionNode, operand_b: ExpressionNode):
        self.operation = op_symbol
        self.left_operand = operand_a
        self.right_operand = operand_b

    def compute(self) -> int:
        left_val = self.left_operand.compute()
        right_val = self.right_operand.compute()

        if self.operation == '+':
            return left_val + right_val
        elif self.operation == '-':
            return left_val - right_val
        elif self.operation == '*':
            return left_val * right_val
        elif self.operation == '/':
            # Integer division as in original
            return left_val // right_val

    def format(self) -> str:
        left_expr = self.left_operand.format()
        right_expr = self.right_operand.format()
        return f"({left_expr} {self.operation} {right_expr})"

def construct_tree_from_postfix(tokens: List[str]) -> ExpressionNode:
    node_stack = []

    for item in tokens:
        if item.isnumeric():
            node_stack.append(NumberNode(int(item)))
        else:
            # Pop operands in reverse order (right first, then left)
            second_operand = node_stack.pop()
            first_operand = node_stack.pop()

            node_stack.append(BinaryOperationNode(item, first_operand, second_operand))

    return node_stack[0]

def evaluate_expression(postfix_notation: List[str]) -> (int, str):
    expression_tree = construct_tree_from_postfix(postfix_notation)
    computed_value = expression_tree.compute()
    formatted_expression = expression_tree.format()
    return computed_value, formatted_expression

