# Find numbers that are both perfect cubes and factorials

def is_cube_number(value):
    """Determine if a number is a perfect cube."""
    cube_root = round(value ** (1/3))
    return cube_root ** 3 == value

def is_factorial_number(value):
    """Check if a number equals some factorial."""
    if value == 1:
        return True

    current_factorial = 1
    multiplier = 1

    while current_factorial < value:
        multiplier += 1
        current_factorial *= multiplier

    return current_factorial == value

def generate_special_numbers(limit):
    """Yield the first 'limit' numbers that are both perfect cubes and factorials."""
    if not isinstance(limit, int) or limit < 0:
        raise ValueError("Limit must be a non-negative integer.")

    found_count = 0
    test_value = 1

    while found_count < limit:
        if is_cube_number(test_value) and is_factorial_number(test_value):
            yield test_value
            found_count += 1
        test_value += 1

