# Currency converter using exchange rates from Open Exchange Rates API

import requests

API_KEY = 'REDACTED_CREDENTIAL'
API_ENDPOINT = 'https://openexchangerates.org/api/latest.json'

def fetch_exchange_data():
    try:
        response = requests.get(f'{API_ENDPOINT}?app_id={API_KEY}')
        response.raise_for_status()
        data = response.json()
        return data.get('rates', {})
    except requests.RequestException as error:
        print(f"Failed to retrieve exchange rates: {error}")
        return {}

def perform_conversion(value, source_currency, target_currency, rate_table):
    if source_currency == 'USD':
        conversion_rate = rate_table.get(target_currency)
    else:
        source_rate = rate_table.get(source_currency)
        target_rate = rate_table.get(target_currency)
        if source_rate is None or target_rate is None:
            conversion_rate = None
        else:
            conversion_rate = target_rate / source_rate

    if conversion_rate is None:
        return None
    return value * conversion_rate

def run_converter():
    exchange_rates = fetch_exchange_data()
    if not exchange_rates:
        print("Unable to proceed without valid exchange rate data.")
        return

    print("=== Currency Converter ===")
    source = input("Enter source currency code (e.g., USD): ").strip().upper()
    target = input("Enter target currency code (e.g., EUR): ").strip().upper()

    try:
        amount = float(input("Enter amount to convert: "))
    except ValueError:
        print("Invalid amount entered.")
        return

    converted_amount = perform_conversion(amount, source, target, exchange_rates)
    if converted_amount is None:
        print("Conversion failed: one or both currencies are invalid or unsupported.")
    else:
        print(f"{amount:.2f} {source} = {converted_amount:.2f} {target}")

if __name__ == "__main__":
    run_converter()

# Type III Clone: Refactored logic with equivalent functionality but different implementation approach

def check_prime(n):
    # Optimized prime checking using 6k ± 1 optimization
    if n <= 1:
        return False
    elif n <= 3:
        return True
    elif n % 2 == 0 or n % 3 == 0:
        return False

    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def compute_lcm(x, y):
    # Using Euclidean algorithm for GCD then computing LCM
    def euclidean_gcd(a, b):
        while a != 0:
            a, b = b % a, a
        return b

    if x == 0 or y == 0:
        return 0
    return abs(x * y) // euclidean_gcd(x, y)

def compute_gcd(x, y):
    # Direct implementation of Euclidean algorithm
    while y != 0:
        x, y = y, x % y
    return x

def analyze_number(value):
    # Handle string conversion first
    if isinstance(value, str):
        try:
            value = int(value)
        except ValueError:
            try:
                value = float(value)
            except ValueError:
                return "Error: Invalid input type, unable to convert to number."

    # Handle complex numbers
    if isinstance(value, complex):
        real_part = value.real
        imag_part = value.imag

        # Get positive integer parts for factor calculation
        real_int = int(real_part)
        imag_int = int(imag_part)

        # Calculate factors for real part
        real_factors = []
        if real_int > 0:
            for f in range(1, real_int + 1):
                if real_int % f == 0:
                    real_factors.append(f)

        # Calculate factors for imaginary part
        imag_factors = []
        if imag_int > 0:
            for f in range(1, imag_int + 1):
                if imag_int % f == 0:
                    imag_factors.append(f)

        # Analyze real part properties
        real_even_count = len(real_factors) % 2 == 0
        real_sum = sum(real_factors) if real_factors else 0
        real_primes = [f for f in real_factors if check_prime(f)]
        real_max_prime = max(real_primes) if real_primes else None
        real_lcm_val = compute_lcm(real_factors[0], real_factors[-1]) if len(real_factors) >= 2 else None
        real_gcd_val = compute_gcd(real_factors[0], real_factors[-1]) if len(real_factors) >= 2 else None

        # Analyze imaginary part properties
        imag_even_count = len(imag_factors) % 2 == 0
        imag_sum = sum(imag_factors) if imag_factors else 0
        imag_primes = [f for f in imag_factors if check_prime(f)]
        imag_max_prime = max(imag_primes) if imag_primes else None
        imag_lcm_val = compute_lcm(imag_factors[0], imag_factors[-1]) if len(imag_factors) >= 2 else None
        imag_gcd_val = compute_gcd(imag_factors[0], imag_factors[-1]) if len(imag_factors) >= 2 else None

        return {
            'real': (real_even_count, real_factors, real_sum, real_max_prime, (real_lcm_val, real_gcd_val)),
            'imag': (imag_even_count, imag_factors, imag_sum, imag_max_prime, (imag_lcm_val, imag_gcd_val))
        }

    # Validate input type
    if not isinstance(value, (int, float)):
        return "Error: Invalid input type."

    # Convert float to integer by rounding
    if isinstance(value, float):
        value = round(value)

    # Check for positive requirement
    if value <= 0:
        return "Error: Input must be a positive integer or float."

    # Calculate factors
    factors_list = []
    for f in range(1, int(value) + 1):
        if value % f == 0:
            factors_list.append(f)

    # Analyze properties
    is_even_factor_count = len(factors_list) % 2 == 0
    total_factors_sum = sum(factors_list)
    prime_factors = [f for f in factors_list if check_prime(f)]
    largest_prime = max(prime_factors) if prime_factors else None
    lcm_value = compute_lcm(factors_list[0], factors_list[-1]) if len(factors_list) >= 2 else None
    gcd_value = compute_gcd(factors_list[0], factors_list[-1]) if len(factors_list) >= 2 else None

    return (is_even_factor_count, factors_list, total_factors_sum, largest_prime, (lcm_value, gcd_value))

def process_2d_array(arr):
    # Verify it's a valid 2D array structure
    if not isinstance(arr, list) or not all(isinstance(row, list) for row in arr):
        return "Error: Input must be a matrix (list of lists)."

    result_matrix = []
    for row in arr:
        processed_row = []
        for item in row:
            processed_item = analyze_number(item)
            processed_row.append(processed_item)
        result_matrix.append(processed_row)

    return result_matrix

