import hashlib
from datetime import datetime, timedelta

# Simulated user database with security features
user_database = {
    'alice': {
        'hash': hashlib.sha256('secure_password123'.encode()).hexdigest(),
        'error_count': 0,
        'last_error_timestamp': None
    },
    'bob': {
        'hash': hashlib.sha256('another_secure_password123'.encode()).hexdigest(),
        'error_count': 0,
        'last_error_timestamp': None
    }
}

# Security policy settings
MAX_ATTEMPTS_BEFORE_LOCKOUT = 3
LOCK_TIME_LIMIT = timedelta(minutes=5)

def generate_hash(input_string):
    return hashlib.sha256(input_string.encode()).hexdigest()

def check_lock_status(account_name):
    record = user_database.get(account_name)
    if record is None:
        return False
    if record['error_count'] >= MAX_ATTEMPTS_BEFORE_LOCKOUT:
        last_failure = record['last_error_timestamp']
        if last_failure and datetime.now() - last_failure < LOCK_TIME_LIMIT:
            return True
    return False

def authenticate(username, password):
    if check_lock_status(username):
        print(f"Access denied: {username} account is temporarily locked.")
        return False

    account_info = user_database.get(username)
    if account_info is None:
        print("Authentication error: User does not exist.")
        return False

    if generate_hash(password) == account_info['hash']:
        account_info['error_count'] = 0
        account_info['last_error_timestamp'] = None
        print(f"Authentication successful for {username}.")
        return True
    else:
        account_info['error_count'] += 1
        account_info['last_error_timestamp'] = datetime.now()
        remaining = MAX_ATTEMPTS_BEFORE_LOCKOUT - account_info['error_count']
        print(f"Authentication failed for {username}. {remaining} attempts left before lockout.")
        return False

