# Type III clone: Modified version with equivalent functionality but different implementation approach

def load_tagged_sentences(filename):
    """Load sentences from a file, each line contains space-separated word/tag pairs."""
    sentences = []
    with open(filename, 'r', encoding='utf-8') as f:
        for line in f:
            if line.strip():
                sentence_data = []
                tokens = line.strip().split()
                for token in tokens:
                    # Split from the right to handle cases where '/' appears in words
                    idx = token.rfind('/')
                    if idx != -1:
                        word_part = token[:idx]
                        tag_part = token[idx+1:]
                        sentence_data.append((word_part, tag_part))
                sentences.append(sentence_data)
    return sentences

def compute_pos_metrics(reference_data, predicted_data):
    """Compute precision and recall metrics for POS tagging results."""
    result_dict = {}

    # Process each sentence pair
    for ref_sent, pred_sent in zip(reference_data, predicted_data):
        # Ensure same number of tokens in both sentences
        if len(ref_sent) != len(pred_sent):
            raise ValueError("Sentence lengths do not match")

        for ref_token, pred_token in zip(ref_sent, pred_sent):
            ref_word, ref_tag = ref_token
            pred_word, pred_tag = pred_token

            # Verify word consistency between gold and test
            if ref_word != pred_word:
                raise ValueError(f"Word mismatch at position: {ref_word} != {pred_word}")

            # Initialize counters for reference tag if not present
            if ref_tag not in result_dict:
                result_dict[ref_tag] = {'true_pos': 0, 'false_neg': 0, 'false_pos': 0}

            # Initialize counters for predicted tag if not present
            if pred_tag not in result_dict:
                result_dict[pred_tag] = {'true_pos': 0, 'false_neg': 0, 'false_pos': 0}

            # Update counts based on tag comparison
            if ref_tag == pred_tag:
                result_dict[ref_tag]['true_pos'] += 1
            else:
                result_dict[ref_tag]['false_neg'] += 1
                result_dict[pred_tag]['false_pos'] += 1

    # Calculate precision and recall for each tag
    final_metrics = {}
    for tag, counts in result_dict.items():
        tp = counts['true_pos']
        fn = counts['false_neg']
        fp = counts['false_pos']

        # Avoid division by zero
        prec_denom = tp + fp
        rec_denom = tp + fn

        precision_val = tp / prec_denom if prec_denom > 0 else 0.0
        recall_val = tp / rec_denom if rec_denom > 0 else 0.0

        final_metrics[tag] = {
            'precision': precision_val,
            'recall': recall_val
        }

    return final_metrics

