# Modified version of the AlgorithmVisualizer with equivalent functionality but different implementation approach

import ast
import graphviz as gv

class CodeFlowAnalyzer:
    def __init__(self, source_code):
        self.source = source_code
        self.tree = None
        self.flow_diagram = gv.Digraph(comment='Control Flow Visualization')

    def analyze_syntax(self):
        try:
            self.tree = ast.parse(self.source)
            return True
        except SyntaxError as error:
            print(f"Syntax issue detected: {error}")
            return False

    def generate_flow_chart(self):
        if self.tree is None:
            print("No parsed structure available for visualization.")
            return

        # Start from module level
        self._process_ast_nodes(self.tree.body, "Entry")

        # Output the diagram
        self.flow_diagram.render('control_flow_graph', view=True)

    def _process_ast_nodes(self, node_list, parent_label):
        for idx, current_node in enumerate(node_list):
            # Create unique identifier for each node based on type and index
            node_id = f"{type(current_node).__name__}_{idx}"

            # Add node to graph with appropriate label
            label_text = type(current_node).__name__
            self.flow_diagram.node(node_id, label_text)

            # Connect to parent
            self.flow_diagram.edge(parent_label, node_id)

            # Handle different AST node types recursively
            if isinstance(current_node, ast.FunctionDef):
                self._process_ast_nodes(current_node.body, node_id)
            elif isinstance(current_node, (ast.For, ast.While)):
                self._process_ast_nodes(current_node.body, node_id)
            elif isinstance(current_node, ast.If):
                self._process_ast_nodes(current_node.body, node_id)
                # Process else/elif branches if present
                if current_node.orelse:
                    self._process_ast_nodes(current_node.orelse, f"{node_id}_else_branch")

