# Alternative implementation to find prime numbers and compute their products

def check_prime(value):
    """Determine whether a given integer is prime."""
    if value < 2:
        return False
    if value == 2 or value == 3:
        return True
    if value % 2 == 0 or value % 3 == 0:
        return False

    # Check divisors of the form 6k ± 1 up to sqrt(value)
    divisor = 5
    while divisor * divisor <= value:
        if value % divisor == 0 or value % (divisor + 2) == 0:
            return False
        divisor += 6
    return True

def extract_primes_and_compute_products(data_sets):
    output = []

    for dataset in data_sets:
        primes_list = []
        try:
            for item in dataset:
                if not isinstance(item, int):
                    raise TypeError(f"Non-integer value encountered: {item}")
                if check_prime(item):
                    primes_list.append(item)
        except Exception as error:
            print(f"Processing issue detected: {error}")
            continue

        primes_list.sort()
        # Calculate product using iterative multiplication instead of reduce
        product = 1
        for prime in primes_list:
            product *= prime

        output.append((primes_list, product))

    return output

