def transform_to_ascii_image(image, symbols, reduction_factor):
    # Convert to grayscale
    gray_image = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)

    # Resize image based on scale factor
    new_width = int(gray_image.shape[1] // reduction_factor)
    new_height = int(gray_image.shape[0] // reduction_factor)
    resized_image = cv2.resize(gray_image, (new_width, new_height), interpolation=cv2.INTER_AREA)

    ascii_output = ''
    for y_row in resized_image:
        for pixel_value in y_row:
            index = min(int(pixel_value // (256 / len(symbols))), len(symbols) - 1)
            ascii_output += symbols[index]
        ascii_output += '\n'

    return ascii_output

