# Scrapy spider to extract size availability from Koovs product page using Selenium

import scrapy
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.common.exceptions import TimeoutException


class KoovsSpider(scrapy.Spider):
    name = 'koovs_spider'
    start_urls = ['http://www.koovs.com/only-onlall-stripe-ls-shirt-59554.html?from=category-651&skuid=236376']

    def __init__(self, *args, **kwargs):
        super(KoovsSpider, self).__init__(*args, **kwargs)

        # Configure Chrome options for headless execution
        chrome_options = webdriver.ChromeOptions()
        chrome_options.add_argument('--headless')
        chrome_options.add_argument('--no-sandbox')
        chrome_options.add_argument('--disable-dev-shm-usage')

        self.browser = webdriver.Chrome(options=chrome_options)

    def start_requests(self):
        for target_url in self.start_urls:
            yield scrapy.Request(url=target_url, callback=self.parse)

    def parse(self, response):
        self.browser.get(response.url)

        try:
            # Wait up to 10 seconds for the size selector element to appear
            size_selector = WebDriverWait(self.browser, 10).until(
                EC.visibility_of_element_located((By.CLASS_NAME, 'size-dropdown'))
            )

            # Extract all size options
            size_options = size_selector.find_elements(By.TAG_NAME, 'option')

            for option in size_options:
                size_label = option.text.strip()
                is_in_stock = 'Not available' not in size_label

                yield {
                    'size': size_label,
                    'available': is_in_stock
                }

        except TimeoutException:
            self.logger.warning('Size dropdown failed to load within timeout period')

    def closed(self, reason):
        if hasattr(self, 'browser'):
            self.browser.quit()

