# Script to compute file checksums and detect duplicates using SHA-256 instead of MD5

import os
import hashlib

def compute_sha256(file_path):
    """Compute the SHA-256 hash of a given file."""
    sha256_hash = hashlib.sha256()
    with open(file_path, 'rb') as file:
        for block in iter(lambda: file.read(8192), b''):
            sha256_hash.update(block)
    return sha256_hash.hexdigest()

def scan_directory_for_files():
    """Scan current working directory and collect files with their hashes."""
    file_checksums = {}
    current_dir = os.getcwd()

    for entry in os.listdir(current_dir):
        full_path = os.path.join(current_dir, entry)
        if os.path.isfile(full_path):
            checksum = compute_sha256(full_path)
            file_checksums[entry] = checksum
            print(f"{entry}: {checksum}")

    return file_checksums

def identify_duplicate_files(checksum_data):
    """Identify files that share identical checksums."""
    checksum_groups = {}

    for filename, checksum in checksum_data.items():
        if checksum not in checksum_groups:
            checksum_groups[checksum] = [filename]
        else:
            checksum_groups[checksum].append(filename)

    # Filter only groups with more than one file (duplicates)
    duplicate_groups = {
        checksum: filenames 
        for checksum, filenames in checksum_groups.items() 
        if len(filenames) > 1
    }

    if duplicate_groups:
        print("Duplicate files detected:")
        for checksum, filenames in duplicate_groups.items():
            print(f"SHA-256: {checksum}")
            for name in filenames:
                print(f"  - {name}")
    else:
        print("No duplicate files were found.")

if __name__ == "__main__":
    collected_hashes = scan_directory_for_files()
    identify_duplicate_files(collected_hashes)

