# Storage for to-do items (list of dictionaries)
todo_items = []

def create_todo_item(task_title):
    """Creates and appends a new to-do item with auto-incremented ID."""
    new_id = len(todo_items) + 1
    new_item = {
        "id": new_id,
        "title": task_title,
        "status": False
    }
    todo_items.append(new_item)
    return new_item

def list_all_todos():
    """Returns the complete list of to-do items."""
    return todo_items

def fetch_todo_by_identifier(item_id):
    """Retrieves a specific to-do item by its ID."""
    for item in todo_items:
        if item["id"] == item_id:
            return item
    return None

def modify_todo(item_id, new_title=None, new_status=None):
    """Updates an existing to-do item's title or completion status."""
    for item in todo_items:
        if item["id"] == item_id:
            if new_title is not None:
                item["title"] = new_title
            if new_status is not None:
                item["status"] = new_status
            return item
    return None

def remove_todo(item_id):
    """Removes a to-do item from the list by ID."""
    global todo_items
    todo_items = [item for item in todo_items if item["id"] != item_id]
    return True

