    try:
        payload = request.get_json()
        operation = payload['action']
        arguments = payload.get('parameters', [])
        request_id = payload['request_id']

        # Route method calls to appropriate handlers
        if operation == 'createTask':
            output = create_todo_item(*arguments)
        elif operation == 'listTasks':
            output = list_all_todos()
        elif operation == 'getTask':
            output = fetch_todo_by_identifier(*arguments)
        elif operation == 'editTask':
            output = modify_todo(*arguments)
