import re

class Tokenizer:
    def __init__(self, text):
        self.source = text
        self.index = 0
        self.token_list = self.scan()

    def scan(self):
        patterns = [
            ('CONJ_AND', r'AND'),     # conjunction operator
            ('CONJ_OR',  r'OR'),      # disjunction operator
            ('NEGATION', r'NOT'),     # negation operator
            ('BOOL_TRUE', r'TRUE'),   # boolean true literal
            ('BOOL_FALSE', r'FALSE'), # boolean false literal
            ('OPEN_PAREN', r'\('),    # opening parenthesis
            ('CLOSE_PAREN', r'\)'),   # closing parenthesis
            ('IDENTIFIER', r'[a-zA-Z][a-zA-Z0-9]*'), # variable name
            ('WHITESPACE', r'[ \t]+'), # whitespace to ignore
        ]

        regex_pattern = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in patterns)
        result_tokens = []

        for match in re.finditer(regex_pattern, self.source):
            token_type = match.lastgroup
            matched_text = match.group(token_type)

            if token_type != 'WHITESPACE':
                result_tokens.append((token_type, matched_text))

        return result_tokens

    def advance(self):
        if self.index < len(self.token_list):
            current_token = self.token_list[self.index]
            self.index += 1
            return current_token
        else:
            return (None, None)

# Function to find differences between two dictionaries
def find_dict_differences(d1, d2):
    # Collect entries unique to d1 or with changed values
    unique_to_d1 = {}
    for key in d1:
        if key not in d2 or d1[key] != d2[key]:
            unique_to_d1[key] = d1[key]

    # Collect entries unique to d2 or with changed values
    unique_to_d2 = {}
    for key in d2:
        if key not in d1 or d2[key] != d1[key]:
            unique_to_d2[key] = d2[key]

    return unique_to_d1, unique_to_d2

