# Check for duplicates in array using sorting method

def detect_cycle(arr):
    if len(arr) < 2:
        return False

    sorted_arr = sorted(arr)
    for i in range(len(sorted_arr) - 1):
        if sorted_arr[i] == sorted_arr[i + 1]:
            return True
    return False

# Alternative implementation of a basic sentiment analyzer

class BasicEmotionDetector:
    def __init__(self):
        # Initialize sets of emotional indicators
        self.upbeat_terms = {"good", "great", "excellent", "amazing", "wonderful", "fantastic", "love", "happy", "best", "enjoy"}
        self.downbeat_terms = {"bad", "terrible", "awful", "horrible", "poor", "disappointing", "hate", "sad", "worst", "annoying"}

    def determine_sentiment(self, text):
        # Process input: convert to lowercase and split into words
        tokens = text.lower().split()

        # Count occurrences of positive and negative terms
        upbeat_score = 0
        for term in tokens:
            if term in self.upbeat_terms:
                upbeat_score += 1

        downbeat_score = 0
        for term in tokens:
            if term in self.downbeat_terms:
                downbeat_score += 1

        # Determine overall sentiment based on scores
        if upbeat_score > downbeat_score:
            return "Positive"
        elif downbeat_score > upbeat_score:
            return "Negative"
        else:
            return "Neutral"

