# Compute statistics and perform normalization/denormalization

def compute_average(values, pos=0, accum=0):
    if pos == len(values):
        return accum / len(values)
    return compute_average(values, pos + 1, accum + values[pos])

def compute_standard_deviation(values, avg, pos=0, sq_diff_total=0):
    if pos == len(values):
        return (sq_diff_total / len(values)) ** 0.5
    return compute_standard_deviation(values, avg, pos + 1, 
                                      sq_diff_total + (values[pos] - avg) ** 2)

def scale_data(values, avg=None, std=None, pos=0):
    # Validate input type
    if not isinstance(values, list) or not all(isinstance(v, (int, float)) for v in values):
        raise TypeError("Input must be a list of numeric values")

    # Calculate statistics if not provided
    if avg is None:
        avg = compute_average(values)
    if std is None:
        std = compute_standard_deviation(values, avg)

    # Base case: processed all elements
    if pos == len(values):
        return [(val - avg) / std for val in values]

    # Recursive step: process remaining elements first
    scaled_list = scale_data(values, avg, std, pos + 1)
    scaled_list[pos] = (values[pos] - avg) / std
    return scaled_list

def reverse_scale(scaled_values, original_values, avg=None, std=None, pos=0):
    # Validate input types
    if not isinstance(scaled_values, list) or not all(isinstance(v, (int, float)) for v in scaled_values):
        raise TypeError("Scaled input must be a list of numeric values")

    # Calculate original statistics if not provided
    if avg is None:
        avg = compute_average(original_values)
    if std is None:
        std = compute_standard_deviation(original_values, avg)

    # Base case: processed all elements
    if pos == len(scaled_values):
        return [val * std + avg for val in scaled_values]

    # Recursive step: process remaining elements first
    reversed_list = reverse_scale(scaled_values, original_values, avg, std, pos + 1)
    reversed_list[pos] = scaled_values[pos] * std + avg
    return reversed_list

# Example usage
data = [4, 8, 15, 23, 42]

try:
    scaled_array = scale_data(data)
    print("Scaled Array:", scaled_array)

    unscaled_array = reverse_scale(scaled_array, data)
    print("Unscaled Array:", unscaled_array)
except TypeError as e:
    print(e)

import re
from datetime import datetime, timedelta
import pytz

class DateTimeConverter:
    def __init__(self, date_input, time_input, tz_input):
        self.date_input = date_input
        self.time_input = time_input
        self.tz_input = tz_input
        self.date_obj = None
        self.time_obj = None
        self.tz_obj = None

    def extract_date(self):
        formats = [
            (r'^(\d{4})-(\d{2})-(\d{2})$', lambda m: (int(m.group(1)), int(m.group(2)), int(m.group(3)))),
            (r'^(\d{2})/(\d{2})/(\d{4})$', lambda m: (int(m.group(3)), int(m.group(1)), int(m.group(2)))),
            (r'^(\d{4})/(\d{2})/(\d{2})$', lambda m: (int(m.group(1)), int(m.group(2)), int(m.group(3))))
        ]

        for pattern, extractor in formats:
            match = re.match(pattern, self.date_input)
            if match:
                try:
                    y, m, d = extractor(match)
                    self.date_obj = datetime(y, m, d)
                    return True
                except ValueError:
                    continue
        return False

    def extract_time(self):
        patterns = [
            (r'^(\d{2}):(\d{2})$', lambda m: (int(m.group(1)), int(m.group(2)), 0)),
            (r'^(\d{2}):(\d{2}):(\d{2})$', lambda m: (int(m.group(1)), int(m.group(2)), int(m.group(3))))
        ]

        for pattern, extractor in patterns:
            match = re.match(pattern, self.time_input)
            if match:
                try:
                    h, mi, s = extractor(match)
                    self.time_obj = datetime(1900, 1, 1, h, mi, s)
                    return True
                except ValueError:
                    continue
        return False

    def set_timezone(self):
        try:
            tz_upper = self.tz_input.upper()

            # Check if it's a valid IANA timezone
            if tz_upper in pytz.all_timezones_set:
                self.tz_obj = pytz.timezone(tz_upper)
                return True

            # Handle UTC±HH:MM format
            utc_match = re.match(r'UTC([+-])(\d{2}):(\d{2})', tz_upper)
            if utc_match:
                sign = 1 if utc_match.group(1) == '+' else -1
                hours = int(utc_match.group(2))
                minutes = int(utc_match.group(3))
                offset_minutes = sign * (hours * 60 + minutes)
                self.tz_obj = pytz.FixedOffset(offset_minutes)
                return True

            raise ValueError("Timezone not recognized")
        except Exception:
            return False

    def validate_inputs(self):
        if not self.extract_date():
            return "Date format error"
        if not self.extract_time():
            return "Time format error"
        if not self.set_timezone():
            return "Timezone format error"
        return None

    def to_iso_format(self):
        combined_dt = datetime.combine(self.date_obj.date(), self.time_obj.time())
        localized_dt = self.tz_obj.localize(combined_dt)
        utc_dt = localized_dt.astimezone(pytz.utc)
        return utc_dt.isoformat().replace('+00:00', 'Z')

def transform_to_iso(date_str, time_str, tz_str):
    converter = DateTimeConverter(date_str, time_str, tz_str)
    validation_error = converter.validate_inputs()
    if validation_error:
        return validation_error
    return converter.to_iso_format()

# Example usage:
date_str = "2023-10-05"
time_str = "14:30"
tz_str = "America/New_York"
print(transform_to_iso(date_str, time_str, tz_str))  # Output: 2023-10-05T18:30:00Z

