# Course Management System - Alternative Implementation

import re

class CourseManager:
    def __init__(self):
        self.course_list = {}

    def check_course_identifier(self, identifier):
        if not re.match(r'^[a-zA-Z][a-zA-Z0-9]{0,9}$', identifier):
            raise ValueError("Invalid course ID. It should start with a letter and contain only alphanumeric characters, with a maximum length of 10 characters.")

    def verify_text_length(self, text, limit):
        if len(text) > limit:
            raise ValueError(f"Value exceeds maximum length of {limit} characters.")

    def enroll_course(self, identifier, title, details, educator, timetable):
        self.check_course_identifier(identifier)
        self.verify_text_length(title, 50)
        self.verify_text_length(details, 200)
        self.verify_text_length(educator, 50)

        for entry in timetable:
            if len(entry) != 5:
                raise ValueError("Each session must be a tuple of (date, start_time, end_time, location, max_students).")
            if not isinstance(entry[0], str) or not isinstance(entry[1], str) or not isinstance(entry[2], str) or not isinstance(entry[3], str) or not isinstance(entry[4], int):
                raise ValueError("Session format is incorrect.")

        self.course_list[identifier] = {
            'title': title,
            'details': details,
            'educator': educator,
            'timetable': timetable,
            'enrollment_counts': [0] * len(timetable)
        }

    def find_full_courses(self):
        return [course_id for course_id, course in self.course_list.items() if all(enrolled == capacity for enrolled, (_, _, _, _, capacity) in zip(course['enrollment_counts'], course['timetable']))]

    def count_open_seats(self, course_id, session_num):
        if course_id not in self.course_list:
            raise KeyError(f"Course ID {course_id} not found.")
        if session_num < 0 or session_num >= len(self.course_list[course_id]['timetable']):
            raise IndexError("Session index out of range.")

        capacity = self.course_list[course_id]['timetable'][session_num][4]
        enrolled = self.course_list[course_id]['enrollment_counts'][session_num]
        return capacity - enrolled

    def total_enrollments(self, course_id):
        if course_id not in self.course_list:
            raise KeyError(f"Course ID {course_id} not found.")

        return sum(self.course_list[course_id]['enrollment_counts'])

    def mean_enrollment_rate(self):
        total_enrolled = sum(sum(course['enrollment_counts']) for course in self.course_list.values())
        total_sessions = sum(len(course['timetable']) for course in self.course_list.values())
        if total_sessions == 0:
            return 0
        return total_enrolled / total_sessions

    def top_enrolled_course(self):
        if not self.course_list:
            return None

        highest_fill_ratio = -1
        leading_course_id = None

        for course_id, course in self.course_list.items():
            total_enrolled = sum(course['enrollment_counts'])
            total_capacity = sum(session[4] for session in course['timetable'])
            if total_capacity == 0:
                continue
            fill_ratio = total_enrolled / total_capacity
            if fill_ratio > highest_fill_ratio:
                highest_fill_ratio = fill_ratio
                leading_course_id = course_id

        return leading_course_id

    def add_participant(self, course_id, session_num):
        if course_id not in self.course_list:
            raise KeyError(f"Course ID {course_id} not found.")
        if session_num < 0 or session_num >= len(self.course_list[course_id]['timetable']):
            raise IndexError("Session index out of range.")

        capacity = self.course_list[course_id]['timetable'][session_num][4]
        if self.course_list[course_id]['enrollment_counts'][session_num] >= capacity:
            raise ValueError("Session is at capacity.")

        self.course_list[course_id]['enrollment_counts'][session_num] += 1

# Example usage
manager = CourseManager()
manager.enroll_course("CS101", "Introduction to Computer Science", "An introductory course to computer science", "Dr. Smith", [
    ("2023-10-01", "09:00", "11:00", "Room A1", 20),
