print("Available seats in CS101 session 0:", manager.count_open_seats("CS101", 0))
print("Total registered students in CS101:", manager.total_enrollments("CS101"))
print("Average registered students:", manager.mean_enrollment_rate())
print("Most popular course:", manager.top_enrolled_course())

# Calculate square roots for a range with validation and error handling

import math
import unittest

def generate_sqrt_mapping(low, high):
    # Initialize result dictionary
    sqrt_map = {}

    try:
        # Convert inputs to integers if possible
        low_val = int(low)
        high_val = int(high)

        # Validate range order
        if low_val > high_val:
            raise ValueError("Lower bound must not exceed upper bound.")

        # Build dictionary using loop instead of comprehension
        current = low_val
        while current <= high_val:
            sqrt_map[current] = math.sqrt(current)
            current += 1

        return sqrt_map

    except ValueError as e:
        print(f"Validation issue: {e}")
        return {}
    except TypeError:
        print("Error: Inputs must be numeric types.")
        return {}

# Unit test suite
class TestSqrtMapping(unittest.TestCase):
    def test_correct_range(self):
        output = generate_sqrt_mapping(1, 25)
        target = {i: math.sqrt(i) for i in range(1, 26)}
        self.assertEqual(output, target)

    def test_reversed_range(self):
        output = generate_sqrt_mapping(25, 1)
        self.assertEqual(output, {})

    def test_string_inputs(self):
        output = generate_sqrt_mapping('x', 25)
        self.assertEqual(output, {})

    def test_decimal_inputs(self):
        output = generate_sqrt_mapping(1.0, 25.0)
        target = {i: math.sqrt(i) for i in range(1, 26)}
        self.assertEqual(output, target)

if __name__ == '__main__':
    unittest.main()

# Retrieve Venmo transaction data using stored authentication

def get_credentials():
    """Load authentication details from secret file"""
    with open('secret.txt') as f:
        lines = [line.strip() for line in f.readlines() if line.strip()]
    return {'cookie': lines[0], 'token': lines[1]}

def build_request_headers(cookie_value, auth_token):
    """Construct HTTP headers for API requests"""
    return {
        'Cookie': cookie_value,
        'Authorization': 'Bearer ' + auth_token,
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36',
    }

def collect_transactions():
    """Fetch all transaction pages from Venmo API"""
    creds = get_credentials()
    base_url = 'https://api.venmo.com/v1/transaction-history'
    current_page = 1

    while True:
        try:
            response = requests.get(
                base_url, 
                params={'page': current_page}, 
                headers=build_request_headers(creds['cookie'], creds['token'])
            )

            if response.status_code == 200:
                data = response.json()
                print(data)

                # Check for next page
                if 'paging' not in data or 'next' not in data['paging']:
                    break

                current_page += 1
            else:
                print(f"API request failed: {response.status_code} {response.reason}")
                break

        except requests.exceptions.RequestException as err:
            print(f"Network error encountered: {err}")
            break

# Execute the transaction collection process
collect_transactions()

# Parse SQL query and extract components using alternative logic

import sqlparse

query = "SELECT d_year, s_nation, p_category, sum(lo_revenue - lo_supplycost) as profit FROM DATES, CUSTOMER, SUPPLIER, PART, LINEORDER WHERE lo_custkey = c_custkey AND lo_suppkey = s_suppkey AND lo_partkey = p_partkey AND lo_orderdate = d_datekey AND c_region = 'AFRICA' AND s_region = 'AFRICA' AND (d_year = 1996 OR d_year = 1997) AND (p_mfgr = 'MFGR#2' OR p_mfgr = 'MFGR#4') GROUP BY d_year, s_nation, p_category ORDER BY d_year, s_nation, p_category"

parsed_query = sqlparse.parse(query)[0]

def get_tables_from_clause(parsed_stmt):
    table_names = []
    found_from = False

    for token in parsed_stmt.tokens:
        if found_from:
            # Stop when encountering next keyword like WHERE, ORDER, etc.
            if token.ttype is sqlparse.tokens.Keyword:
                break

            # Handle comma-separated tables or JOINs
            if isinstance(token, sqlparse.sql.IdentifierList):
                for item in token.get_identifiers():
                    table_names.append(item.get_real_name())
            elif isinstance(token, sqlparse.sql.Identifier):
                table_names.append(token.get_real_name())

        # Detect FROM keyword
        if (token.ttype is sqlparse.tokens.Keyword and 
            token.value.upper() == 'FROM'):
            found_from = True

    return table_names

def retrieve_where_conditions(parsed_stmt):
    condition_parts = []
    in_where = False

    for token in parsed_stmt.tokens:
        if in_where:
            # Collect tokens until we hit another clause (GROUP BY, ORDER BY, etc.)
            if token.ttype is sqlparse.tokens.Keyword:
                break
            condition_parts.append(str(token))

        # Detect WHERE keyword
        if (token.ttype is sqlparse.tokens.Keyword and 
            token.value.upper() == 'WHERE'):
            in_where = True

    return ' '.join(condition_parts)

def collect_grouping_columns(parsed_stmt):
    group_cols = []
    after_group_by = False

    for token in parsed_stmt.tokens:
        if after_group_by:
            # Stop at next clause keyword
            if token.ttype is sqlparse.tokens.Keyword:
                break

            if isinstance(token, sqlparse.sql.IdentifierList):
                for col in token.get_identifiers():
                    group_cols.append(col.get_real_name())
            elif isinstance(token, sqlparse.sql.Identifier):
                group_cols.append(token.get_real_name())

        # Detect GROUP BY keyword
        if (token.ttype is sqlparse.tokens.Keyword and 
            token.value.upper() == 'GROUP BY'):
            after_group_by = True

    return group_cols

def collect_sorting_columns(parsed_stmt):
    sort_cols = []
    after_order_by = False

    for token in parsed_stmt.tokens:
        if after_order_by:
            # Stop at end of ORDER BY clause
            if token.ttype is sqlparse.tokens.Keyword:
                break

            if isinstance(token, sqlparse.sql.IdentifierList):
                for col in token.get_identifiers():
                    sort_cols.append(col.get_real_name())
            elif isinstance(token, sqlparse.sql.Identifier):
                sort_cols.append(token.get_real_name())

        # Detect ORDER BY keyword
        if (token.ttype is sqlparse.tokens.Keyword and 
            token.value.upper() == 'ORDER BY'):
            after_order_by = True

    return sort_cols

# Extract information using new function names
table_list = get_tables_from_clause(parsed_query)
where_clause_text = retrieve_where_conditions(parsed_query)
grouping_fields = collect_grouping_columns(parsed_query)
sorting_fields = collect_sorting_columns(parsed_query)

# Display extracted data
print("Tables:", table_list)
print("Where Conditions:", where_clause_text)
print("Group By Columns:", grouping_fields)
print("Order By Columns:", sorting_fields)

def total_numeric_value(data_structure):
    """
    Compute the aggregate sum of all numeric elements within a hierarchical tuple structure.
    Non-numeric items are disregarded, and complex numbers contribute only their real component.

    :param data_structure: A nested tuple collection potentially containing various data types
    :return: The cumulative sum of all real numeric values present
    """
    def is_number(val):
        return isinstance(val, (int, float))

    def get_real_part(val):
        if isinstance(val, complex):
            return val.real
        return val

    def traverse_and_accumulate(container):
        accumulated = 0
        for element in container:
            if isinstance(element, tuple):
                accumulated += traverse_and_accumulate(element)
            elif is_number(element) or isinstance(element, complex):
                accumulated += get_real_part(element)
        return accumulated

    return traverse_and_accumulate(data_structure)

