def signup():
    form = SignupForm()
    if form.validate_on_submit():
        # Check if email is already taken
        existing_user = next((u for u in registered_users.values() if u.email == form.email_field.data), None)
        if not existing_user:
            # Create new user account
            new_id = len(registered_users) + 1
            new_account = AppUser(new_id, form.email_field.data, form.password_field.data)
            registered_users[new_id] = new_account
            flash('Account created successfully! You can now sign in.', 'success')
            return redirect(url_for('signin'))
