def check_dict_case(dct):
    if not dct:
        return False

    # Count keys in different cases
    lower_keys = 0
    upper_keys = 0
    for key in dct.keys():
        if key.islower():
            lower_keys += 1
        elif key.isupper():
            upper_keys += 1

    # Check if all keys are lowercase and all values are lowercase
    if lower_keys == len(dct):
        for value in dct.values():
            if not isinstance(value, str) or not value.islower():
                return False
        return True

    # Check if all keys are uppercase and all values are uppercase
    elif upper_keys == len(dct):
        for value in dct.values():
            if not isinstance(value, str) or not value.isupper():
                return False
        return True

    # Mixed case keys - invalid
    else:
        return False

# Modified version with equivalent functionality but different implementation approach

def compute_lcs_length(str1, str2):
    m, n = len(str1), len(str2)
    # Create DP table initialized with zeros
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the DP table bottom-up
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if str1[i-1] == str2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    return dp

def reconstruct_lcs(str1, str2, dp):
    i, j = len(str1), len(str2)
    lcs_chars = []

    # Backtrack through the DP table to find the LCS string
    while i > 0 and j > 0:
        if str1[i-1] == str2[j-1]:
            lcs_chars.append(str1[i-1])
            i -= 1
            j -= 1
        elif dp[i-1][j] > dp[i][j-1]:
            i -= 1
        else:
            j -= 1

    return ''.join(reversed(lcs_chars))

def find_common_subsequence(strings_list):
    if not strings_list:
        return ""

    # Start with first string as base
    current_lcs = strings_list[0]

    # Iteratively compute LCS with each subsequent string
    for idx in range(1, len(strings_list)):
        dp_table = compute_lcs_length(current_lcs, strings_list[idx])
        current_lcs = reconstruct_lcs(current_lcs, strings_list[idx], dp_table)

    return current_lcs

def find_shortest_unique_subsequence(strings_collection):
    if not strings_collection:
        return ""

    shortest_unique = None

    # Check all possible substrings of each string
    for s in strings_collection:
        for start_idx in range(len(s)):
            for end_idx in range(start_idx + 1, len(s) + 1):
                candidate = s[start_idx:end_idx]

                # Check if this substring appears only in current string
                is_unique = True
                for other in strings_collection:
                    if other != s and candidate in other:
                        is_unique = False
                        break

                if is_unique:
                    if shortest_unique is None or len(candidate) < len(shortest_unique):
                        shortest_unique = candidate

    return shortest_unique if shortest_unique else ""

def main_processing(data1, data2):
    combined_data = data1 + data2

    # Find shortest unique subsequence
    sus_result = find_shortest_unique_subsequence(combined_data)

    # Find longest common subsequence across all strings
    lcs_result = find_common_subsequence(combined_data)

    return sus_result, len(lcs_result)

