# Alternative implementation using different variable names and logic structure

def transform_text(text, shift_direction):
    result = []
    for char in text:
        if 'a' <= char <= 'z':
            # Process lowercase letters with modular arithmetic
            base = ord('a')
            offset = (ord(char) - base + shift_direction) % 26
            result.append(chr(base + offset))
        elif 'A' <= char <= 'Z':
            # Process uppercase letters with modular arithmetic
            base = ord('A')
            offset = (ord(char) - base + shift_direction) % 26
            result.append(chr(base + offset))
        else:
            # Keep non-alphabetic characters as they are
            result.append(char)
    return ''.join(result)

def encode_string(text):
    return transform_text(text, 2)

def decode_string(text):
    return transform_text(text, -2)

def verify_encoding_decoding(text):
    encoded_version = encode_string(text)
    decoded_version = decode_string(encoded_version)

    if text == decoded_version:
        print(f"Original: {text}")
        print(f"Encoded: {encoded_version}")
        print(f"Decoded: {decoded_version}")
        print("Encoding and decoding are correct.")
    else:
        print("There was an error in encoding or decoding.")

