# Re-architecting the drone control system with alternative logic structures

import threading
import time
from abc import ABC, abstractmethod
from typing import List, Dict, Optional

class DroneCommandCenter:
    def __init__(self):
        self._active_units: List['Unit'] = []
        self._is_operational = False
        self._mutex = threading.Lock()

    def register_unit(self, unit: 'Unit'):
        with self._mutex:
            if unit not in self._active_units:
                self._active_units.append(unit)
                unit.attach(self)

    def deregister_unit(self, unit: 'Unit'):
        with self._mutex:
            if unit in self._active_units:
                unit.detach()
                self._active_units.remove(unit)

    def activate(self):
        with self._mutex:
            if not self._is_operational:
                self._is_operational = True
                for unit in self._active_units:
                    unit.activate()

    def deactivate(self):
        with self._mutex:
            if self._is_operational:
                self._is_operational = False
                for unit in self._active_units:
                    unit.deactivate()

    def report_issue(self, exception: Exception):
        print(f"Alert: {exception}")
        # Additional error handling procedures can be implemented here

class Unit(ABC):
    def __init__(self):
        self._command_center: Optional[DroneCommandCenter] = None
        self._state_active = False
        self._worker_thread = None

    def attach(self, center: DroneCommandCenter):
        self._command_center = center

    def detach(self):
        self._command_center = None

    def activate(self):
        if not self._state_active:
            self._state_active = True
            self._worker_thread = threading.Thread(target=self._process)
            self._worker_thread.daemon = True
            self._worker_thread.start()

    def deactivate(self):
        if self._state_active:
            self._state_active = False
            self._worker_thread.join(timeout=2.0)

    @abstractmethod
    def _process(self):
        pass

class FlightRegulator(Unit):
    def __init__(self):
        super().__init__()
        self._sensor_readings = {}

    def _process(self):
        while self._state_active:
            try:
                self._refresh_sensor_info()
                self._apply_flight_adjustments()
                time.sleep(1)  # Simulate a 1-second operational cycle
            except Exception as err:
                self._command_center.report_issue(err)

    def _refresh_sensor_info(self):
        # Simulate sensor data acquisition
        self._sensor_readings['altitude'] = 100
        self._sensor_readings['velocity'] = 50

    def _apply_flight_adjustments(self):
        # Simulate applying flight corrections
        print("Applying flight adjustments using current telemetry:", self._sensor_readings)

class PathManager(Unit):
    def __init__(self):
        super().__init__()
        self._target_points: List[Dict[str, float]] = []

    def enqueue_target(self, lat: float, lon: float):
        self._target_points.append({'latitude': lat, 'longitude': lon})

    def _process(self):
        while self._state_active:
            try:
                self._advance_to_next_target()
                time.sleep(1)  # Simulate a 1-second operational cycle
            except Exception as err:
                self._command_center.report_issue(err)

    def _advance_to_next_target(self):
        if self._target_points:
            target = self._target_points.pop(0)
            print(f"Proceeding toward target: {target}")
        else:
            print("All targets have been reached.")

class LinkHandler(Unit):
    def __init__(self):
        super().__init__()
        self._outgoing_queue: List[str] = []

    def queue_transmission(self, payload: str):
        self._outgoing_queue.append(payload)

    def _process(self):
        while self._state_active:
            try:
                self._transmit_available_messages()
                time.sleep(1)  # Simulate a 1-second operational cycle
            except Exception as err:
                self._command_center.report_issue(err)

    def _transmit_available_messages(self):
        if self._outgoing_queue:
            message = self._outgoing_queue.pop(0)
            print(f"Transmitting: {message}")
        else:
            print("No pending messages to transmit.")

