# Type III Clone: Refactored logic with equivalent functionality but different implementation approach

def is_prime_number(value):
    # Check for non-positive numbers and 1
    if value <= 1:
        return False
    # Only check up to square root, skipping even numbers after checking 2
    if value == 2:
        return True
    if value % 2 == 0:
        return False

    # Check odd divisors from 3 up to sqrt(value)
    divisor = 3
    while divisor * divisor <= value:
        if value % divisor == 0:
            return False
        divisor += 2
    return True

def get_factors(number):
    # Collect factors in pairs more efficiently
    small_factors = []
    large_factors = []

    # Iterate only up to sqrt(number)
    factor = 1
    while factor * factor <= number:
        if number % factor == 0:
            small_factors.append(factor)
            other_factor = number // factor
            if other_factor != factor:
                large_factors.append(other_factor)
        factor += 1

    # Combine and sort the factors
    return small_factors + large_factors[::-1]

def greatest_common_divisor(x, y):
    # Euclidean algorithm implementation
    while y != 0:
        x, y = y, x % y
    return abs(x)

def least_common_multiple(x, y):
    # Use GCD to compute LCM
    if x == 0 or y == 0:
        return 0
    return abs(x * y) // greatest_common_divisor(x, y)

def analyze_input(input_data):
    # Handle numeric types (int, float)
    if isinstance(input_data, (int, float)):
        # Round floats to nearest integer
        num_val = int(round(input_data))

        # Get all divisors/factors
        factors_list = get_factors(num_val)

        # Analyze properties of divisors
        is_even_count = len(factors_list) % 2 == 0
        total_sum = sum(factors_list)

        # Find largest prime factor
        prime_factors = list(filter(is_prime_number, factors_list))
        largest_prime = max(prime_factors) if prime_factors else None

        # Compute LCM and GCD of all divisors
        lcm_result = None
        gcd_result = None
        if len(factors_list) > 1:
            lcm_result = factors_list[0]
            gcd_result = factors_list[0]
            for i in range(1, len(factors_list)):
                lcm_result = least_common_multiple(lcm_result, factors_list[i])
                gcd_result = greatest_common_divisor(gcd_result, factors_list[i])

        return (is_even_count, factors_list, total_sum, largest_prime, (lcm_result, gcd_result), None, None, None, None)

    # Handle complex numbers
    elif isinstance(input_data, complex):
        real_part = input_data.real
        imag_part = input_data.imag

        # Sum rounded real and imaginary parts as integer
        combined_value = int(round(real_part)) + int(round(imag_part))

        # Process same as numeric input
        factors_list = get_factors(combined_value)

        is_even_count = len(factors_list) % 2 == 0
        total_sum = sum(factors_list)

        prime_factors = list(filter(is_prime_number, factors_list))
        largest_prime = max(prime_factors) if prime_factors else None

        lcm_result = None
        gcd_result = None
        if len(factors_list) > 1:
            lcm_result = factors_list[0]
            gcd_result = factors_list[0]
            for i in range(1, len(factors_list)):
                lcm_result = least_common_multiple(lcm_result, factors_list[i])
                gcd_result = greatest_common_divisor(gcd_result, factors_list[i])

        return (is_even_count, factors_list, total_sum, largest_prime, (lcm_result, gcd_result), real_part, imag_part, None, None)

    # Handle string inputs
    elif isinstance(input_data, str):
        try:
            # Try parsing as integer first
            parsed_int = int(input_data)
            return analyze_input(parsed_int)
        except ValueError:
            try:
                # Then try parsing as float
                parsed_float = float(input_data)
                return analyze_input(parsed_float)
            except ValueError:
                return "Input is not a valid number"

    # Handle iterable collections (list, tuple, set)
    elif isinstance(input_data, (list, tuple, set)):
        results_dict = {}
        for item in input_data:
            results_dict[item] = analyze_input(item)
        return results_dict

    # Unsupported data type
    else:
        return "Unsupported input type"

