# Health metrics calculator - computes BMI, WHR, BMR, and MHR

def compute_body_mass_index(mass, stature):
    """Determine Body Mass Index (BMI) from mass and stature."""
    index = mass / (stature ** 2)
    return round(index, 2)

def compute_waist_hip_proportion(waist_measurement, hip_measurement):
    """Determine Waist-to-Hip Ratio (WHR) from measurements."""
    proportion = waist_measurement / hip_measurement
    return round(proportion, 2)

def compute_resting_energy_expenditure(mass, lean_body_mass_percent):
    """Determine Basal Metabolic Rate (BMR) using the Katch-McArdle formula."""
    lean = mass * (1 - (lean_body_mass_percent / 100))
    rate = 370 + (21.6 * lean)
    return round(rate, 2)

def compute_heart_rate_limit(years, gender):
    """Determine Maximum Heart Rate (MHR) using the Tanaka equation."""
    if gender.lower() == 'man':
        limit = 208 - (0.7 * years)
    elif gender.lower() == 'woman':
        limit = 206 - (0.88 * years)
    else:
        raise ValueError("Gender must be 'man' or 'woman'.")
    return int(round(limit))

def main():
    # Gather user data
    mass = float(input("Enter your weight in kilograms: "))
    stature = float(input("Enter your height in meters: "))
    waist_measurement = float(input("Enter your waist circumference in centimeters: "))
    hip_measurement = float(input("Enter your hip circumference in centimeters: "))
    lean_body_mass_percent = float(input("Enter your body fat percentage: "))
    years = int(input("Enter your age: "))
    gender = input("Enter your gender (man/woman): ")

    # Perform calculations
    bmi = compute_body_mass_index(mass, stature)
    whr = compute_waist_hip_proportion(waist_measurement, hip_measurement)
    bmr = compute_resting_energy_expenditure(mass, lean_body_mass_percent)
    mhr = compute_heart_rate_limit(years, gender)

    # Display outcomes
