# Compute the factorial of a non-negative integer

def factorial(n):
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers")
    product = 1
    counter = 2
    while counter <= n:
        product *= counter
        counter += 1
    return product

# Student Management System with indexing capabilities

class Learner:
    def __init__(self, identifier, name, years, scores, extracurriculars):
        self.identifier = identifier
        self.name = name
        self.years = years
        self.scores = scores
        self.extracurriculars = extracurriculars

class LearningRegistry:
    def __init__(self):
        self.learners = []
        self.age_map = {}
        self.score_range_map = {}
        self.activity_map = {}

    def enroll(self, identifier, name, years, scores, extracurriculars):
        learner = Learner(identifier, name, years, scores, extracurriculars)
        self.learners.append(learner)
        self._reindex_learner(learner, inserting=True)

    def modify_learner(self, identifier, name=None, years=None, scores=None, extracurriculars=None):
        for learner in self.learners:
            if learner.identifier == identifier:
                if name is not None:
                    learner.name = name
                if years is not None:
                    learner.years = years
                if scores is not None:
                    learner.scores = scores
                if extracurriculars is not None:
                    learner.extracurriculars = extracurriculars
                self._reindex_learner(learner, inserting=True)
                return
        raise ValueError(f"Student with ID {identifier} does not exist")

    def find_by_age(self, years):
        return [learner for learner in self.learners if learner.identifier in self.age_map.get(years, [])]

    def find_by_score_band(self, low_score, high_score):
        score_interval = (low_score, high_score)
        return [learner for learner in self.learners if learner.identifier in self.score_range_map.get(score_interval, [])]

    def find_by_activity(self, activity):
        return [learner for learner in self.learners if learner.identifier in self.activity_map.get(activity, [])]

    def _reindex_learner(self, learner, inserting=False):
        if inserting:
            # Add to age index
            if learner.years not in self.age_map:
                self.age_map[learner.years] = []
            self.age_map[learner.years].append(learner.identifier)

            # Add to score range index
            for score_set in learner.scores:
                interval = (min(score_set), max(score_set))
                if interval not in self.score_range_map:
                    self.score_range_map[interval] = []
                self.score_range_map[interval].append(learner.identifier)

            # Add to activity index
            for club in learner.extracurriculars:
                if club not in self.activity_map:
                    self.activity_map[club] = []
                self.activity_map[club].append(learner.identifier)
        else:
            # Remove from age index
            if learner.years in self.age_map and learner.identifier in self.age_map[learner.years]:
                self.age_map[learner.years].remove(learner.identifier)

            # Remove from score range index
            for score_set in learner.scores:
                interval = (min(score_set), max(score_set))
                if interval in self.score_range_map and learner.identifier in self.score_range_map[interval]:
                    self.score_range_map[interval].remove(learner.identifier)

            # Remove from activity index
            for club in learner.extracurriculars:
                if club in self.activity_map and learner.identifier in self.activity_map[club]:
                    self.activity_map[club].remove(learner.identifier)

