import numpy as np
from scipy.integrate import quad

def check_parameters(r1, r2, a, b, h, func_f, func_g):
    # Validate non-negative constraints
    if any(val < 0 for val in [r1, r2, a, b, h]):
        raise ValueError("Invalid input: negative values are not allowed")

    # Validate function parameters
    if func_f is not None and not callable(func_f):
        raise ValueError("Invalid input: f must be a callable function")
    if func_g is not None and not callable(func_g):
        raise ValueError("Invalid input: g must be a callable function")

def calculate_conical_frustum_area_volume(r_top, r_bottom, height):
    slant_height = np.sqrt((r_top - r_bottom)**2 + height**2)
    surface_area = np.pi * (r_top + r_bottom) * slant_height
    volume = (np.pi * height / 3) * (r_top**2 + r_top*r_bottom + r_bottom**2)
    return surface_area, volume

def calculate_elliptical_conical_frustum_area_volume(a_top1, b_top1, a_bottom1, b_bottom1, height):
    # Approximate surface area using numerical integration
    def integrand(h_val):
        return 2 * np.pi * np.sqrt(a_top1**2 + b_top1**2) * np.sqrt(1 + ((a_top1 - a_bottom1)/h_val)**2)

    surface_area, _ = quad(integrand, 1e-8, height)
    volume = (np.pi * height / 3) * (a_top1*b_top1 + a_top1*b_bottom1 + a_bottom1*b_bottom1)
    return surface_area, volume

def calculate_variable_radius_cone_area_volume(radius_func, total_height):
    # Surface area calculation using numerical integration
    def surface_integrand(h_val):
        delta = 1e-6
        radius = radius_func(h_val)
        derivative_approx = (radius_func(h_val + delta) - radius) / delta
        return 2 * np.pi * radius * np.sqrt(1 + derivative_approx**2)

    surface_area, _ = quad(surface_integrand, 0, total_height)

    # Volume calculation using numerical integration
    def volume_integrand(h_val):
        return np.pi * (radius_func(h_val))**2

    volume, _ = quad(volume_integrand, 0, total_height)
    return surface_area, volume

def handle_cone_calculation(r1, r2, a, b, h, f_func, g_func, time_values=None):
    check_parameters(r1, r2, a, b, h, f_func, g_func)

    # Handle time-dependent case
    if g_func is not None:
        output_results = []
        for t in time_values:
            r1_t, r2_t, a_t, b_t, h_t = g_func(t)
            A_t, V_t = handle_cone_calculation(r1_t, r2_t, a_t, b_t, h_t, f_func, None)
            output_results.append((A_t, V_t))
        return output_results

    # Handle variable radius case
    if f_func is not None:
        return calculate_variable_radius_cone_area_volume(f_func, h)

    # Handle elliptical base case
    if a > 0 and b > 0:
        return calculate_elliptical_conical_frustum_area_volume(r1, r1, r2, r2, h)

    # Default to standard conical frustum
    return calculate_conical_frustum_area_volume(r1, r2, h)

def main_processing(cone_definitions, time_points=None):
    final_results = []
    for cone_params in cone_definitions:
        r1, r2, a, b, h, f_func, g_func = cone_params
        result = handle_cone_calculation(r1, r2, a, b, h, f_func, g_func, time_points)
        final_results.append(result)
    return final_results

# Example usage
cone_definitions = [
    (3, 2, 0, 0, 5, None, None),
    (4, 3, 5, 3, 6, None, None),
    (5, 4, 0, 0, 7, lambda h: 5 - h/2, None),
    (6, 5, 7, 4, 8, None, lambda t: (6 + t, 5 + t, 7 + t, 4 + t, 8 + t))
]

time_points = np.linspace(0, 10, 100)
calculation_results = main_processing(cone_definitions, time_points)
