# Generate all possible tilings of a 3x3 board using 1x1 and 2x1 blocks

def display_grid(grid):
    for line in grid:
        print(' '.join(str(item) for item in line))
    print('---')

def check_position(grid, r, c):
    size = len(grid)
    if r < 0 or r >= size or c < 0 or c >= size:
        return False
    if grid[r][c] != 0:
        return False
    return True

def apply_tile(grid, r, c, tile_kind):
    if tile_kind == 'single':
        grid[r][c] = 1
    elif tile_kind == 'double':
        grid[r][c] = 2
        grid[r][c + 1] = 2

def undo_tile(grid, r, c, tile_kind):
    if tile_kind == 'single':
        grid[r][c] = 0
    elif tile_kind == 'double':
        grid[r][c] = 0
        grid[r][c + 1] = 0

def explore(grid, row, col, results):
    n = len(grid)
    if row == n:
        results.append([line.copy() for line in grid])
        return

    if col == n:
        explore(grid, row + 1, 0, results)
        return

    if grid[row][col] != 0:
        explore(grid, row, col + 1, results)
        return

    # Attempt placing a 1x1 tile
    apply_tile(grid, row, col, 'single')
    explore(grid, row, col + 1, results)
    undo_tile(grid, row, col, 'single')

    # Attempt placing a 2x1 tile
    if col + 1 < n and grid[row][col + 1] == 0:
        apply_tile(grid, row, col, 'double')
        explore(grid, row, col + 2, results)
        undo_tile(grid, row, col, 'double')

def enumerate_all_arrangements():
    dimension = 3
    grid = [[0] * dimension for _ in range(dimension)]
    outcomes = []
    explore(grid, 0, 0, outcomes)
    for result in outcomes:
        display_grid(result)

enumerate_all_arrangements()

# Recursively calculate total size of a directory in gigabytes

import os

def calculate_directory_size(directory_path):
    total_bytes = 0
    try:
        with os.scandir(directory_path) as entries:
            for entry in entries:
                try:
                    if entry.is_file():
                        total_bytes += entry.stat().st_size
                    elif entry.is_dir():
                        total_bytes += calculate_directory_size(entry.path)
                except (OSError, PermissionError):
                    print(f"Access denied or error reading: {entry.path}")
    except (OSError, PermissionError):
        print(f"Cannot access directory: {directory_path}")
    return total_bytes

