# Adventure game with room navigation, item collection, and puzzle solving

class Chamber:
    def __init__(self, title, narrative, objects=None, pathways=None, challenge=None, answer=None):
        self.title = title
        self.narrative = narrative
        self.objects = objects if objects is not None else []
        self.pathways = pathways if pathways is not None else {}
        self.challenge = challenge
        self.answer = answer

    def acquire(self, obj):
        self.objects.append(obj)

    def discard(self, obj):
        if obj in self.objects:
            self.objects.remove(obj)

    def attempt_solution(self, response):
        if self.challenge and response == self.answer:
            print("Challenge resolved!")
            self.challenge = None
            self.answer = None
            return True
        else:
            print("That doesn't appear to be the correct solution.")
            return False

    def inspect(self):
        print(f"--- {self.title} ---")
        print(self.narrative)
        if self.objects:
            print("Objects present:", ", ".join(self.objects))
        if self.challenge:
            print("A riddle or task awaits here.")
        print("Available paths:", ", ".join(self.pathways.keys()))

def start_game():
    # Establish chambers
    kitchen = Chamber(
        title="Kitchen",
        narrative="You find yourself in a softly lit kitchen. A table holds various tools and a passage leads eastward.",
        objects=["knife", "spoon"],
        pathways={"east": "hallway"}
    )

    corridor = Chamber(
        title="Corridor",
        narrative="You stand in an extended hallway. Entrances lie to the north, south, and east.",
        pathways={"north": "chamber", "south": "kitchen", "east": "parlor"}
    )

    chamber = Chamber(
        title="Chamber",
        narrative="You enter a comfortable bedroom. A bed rests against one wall, while a compact desk features a secured compartment.",
        objects=["book"],
        challenge="What code opens the drawer?",
        answer="1234"
    )

    parlor = Chamber(
        title="Parlor",
        narrative="You are in a generous parlor. Furniture includes a sofa, television, and an exit leading outdoors.",
        objects=["remote", "key"],
        pathways={"west": "corridor", "east": "exterior"}
    )

    exterior = Chamber(
        title="Exterior",
        narrative="You stand beyond the home's boundaries. Escape achieved! Well done!",
        pathways={}
    )

    # Link chambers together
    kitchen.pathways["east"] = corridor
    corridor.pathways["north"] = chamber
    corridor.pathways["south"] = kitchen
    corridor.pathways["east"] = parlor
    parlor.pathways["west"] = corridor
    parlor.pathways["east"] = exterior

    # Player possessions
    bag = []

    # Initial location
    position = kitchen

    while True:
        position.inspect()
        user_input = input("What would you like to do? ").lower().split()

        if not user_input:
            continue

        verb = user_input[0]

        if verb == "move":
            if len(user_input) > 1:
                direction = user_input[1]
                if direction in position.pathways:
                    position = position.pathways[direction]
                else:
                    print("That direction is inaccessible.")
            else:
                print("Specify a direction to move.")

        elif verb == "grab":
            if len(user_input) > 1:
                object_name = user_input[1]
                if object_name in position.objects:
                    position.discard(object_name)
                    bag.append(object_name)
                    print(f"You pick up the {object_name}.")
                else:
                    print("No such object exists here.")
            else:
                print("Specify what to take.")

        elif verb == "apply":
            if len(user_input) > 1:
                object_name = user_input[1]
                if object_name in bag:
                    if position.challenge:
                        if position.attempt_solution(object_name):
                            if object_name == "key" and position.title == "Parlor":
                                print("Using the key, you unlock the door and make your escape!")
                                break
                    else:
                        print("No challenge requires resolution here.")
                else:
                    print("You do not possess that item.")
            else:
                print("Specify what to use.")

        elif verb == "possessions":
            if bag:
                print("Carrying:", ", ".join(bag))
            else:
                print("Your inventory is empty.")

        elif verb == "examine":
            position.inspect()

        elif verb == "exit":
            print("Appreciate your participation!")
            break

        else:
            print("Command unrecognized.")

