# Custom hash table implementation with separate chaining

class Dictionary:
    def __init__(self, capacity=100):
        self.capacity = capacity
        self.buckets = [None] * capacity

    def _compute_index(self, item_key):
        # Compute bucket index using Python's built-in hash function
        return hash(item_key) % self.capacity

    def add(self, key, value):
        bucket_index = self._compute_index(key)
        if self.buckets[bucket_index] is None:
            self.buckets[bucket_index] = []

        # Check if key already exists for update
        for position, (stored_key, stored_value) in enumerate(self.buckets[bucket_index]):
            if stored_key == key:
                self.buckets[bucket_index][position] = (key, value)
                return

        # Otherwise append new key-value pair
        self.buckets[bucket_index].append((key, value))

    def retrieve(self, key):
        bucket_index = self._compute_index(key)
        if self.buckets[bucket_index] is not None:
            for stored_key, stored_value in self.buckets[bucket_index]:
                if stored_key == key:
                    return stored_value
        raise KeyError(f"Key '{key}' does not exist in dictionary")

    def remove(self, key):
        bucket_index = self._compute_index(key)
        if self.buckets[bucket_index] is not None:
            for position, (stored_key, _) in enumerate(self.buckets[bucket_index]):
                if stored_key == key:
                    del self.buckets[bucket_index][position]
                    return
        raise KeyError(f"Key '{key}' does not exist in dictionary")

    def __str__(self):
        return str(self.buckets)

