# Recursive function to check if structure is entirely empty and count empty containers

def check_empty_containers(obj, seen=None):
    if seen is None:
        seen = set()

    # Avoid infinite recursion for circular references
    obj_id = id(obj)
    if obj_id in seen:
        return True, 0

    seen.add(obj_id)

    # Handle dictionary type
    if isinstance(obj, dict):
        if len(obj) == 0:
            return True, 1

        all_empty = True
        total_empty = 0

        for val in obj.values():
            is_val_empty, cnt = check_empty_containers(val, seen)
            if not is_val_empty:
                all_empty = False
            total_empty += cnt

        return all_empty, total_empty

    # Handle list, tuple, and set types
    elif isinstance(obj, (list, tuple, set)):
        all_empty = True
        total_empty = 0

        for item in obj:
            is_item_empty, cnt = check_empty_containers(item, seen)
            if not is_item_empty:
                all_empty = False
            total_empty += cnt

        return all_empty, total_empty

    # For any other data type, consider it non-empty
    else:
        return False, 0


