# Filter even numbers and values from nested structures

def check_even(val):
    """Determine if a value represents an even number."""
    # Handle string inputs
    if isinstance(val, str):
        # Check if it's a positive integer string
        if val.isdigit():
            num = int(val)
            return num % 2 == 0
        # Try converting to float for decimal strings
        try:
            fval = float(val)
            if fval.is_integer() and int(fval) % 2 == 0:
                return True
        except ValueError:
            pass
    # Handle numeric types
    elif isinstance(val, (int, float)):
        # Reject non-integer floats
        if isinstance(val, float) and not val.is_integer():
            return False
        return int(val) % 2 == 0
    return False

def transform_to_tuple(data):
    """Convert lists and dicts into tuples."""
    if isinstance(data, list):
        return tuple(data)
    elif isinstance(data, dict):
        return tuple(data.items())
    return data

def extract_even_items(container):
    """Recursively filter out non-even elements from nested containers."""
    output = ()
    for item in container:
        # Recursively process nested tuples
        if isinstance(item, tuple):
            output += (extract_even_items(item),)
        # Convert and process lists/dicts
        elif isinstance(item, (list, dict)):
            output += (extract_even_items(transform_to_tuple(item)),)
        # Skip complex numbers
        elif isinstance(item, complex):
            continue
        # Handle booleans: False is 0 (even), True is 1 (odd)
        elif isinstance(item, bool):
            if not item:  # Only keep False (0)
                output += (item,)
        # Keep only even numbers/values
        elif check_even(item):
            output += (item,)
    return output

