# Find the closest store based on customer location using geocoding and distance calculation

from flask import Flask, request, render_template
from geopy.geocoders import Nominatim
from geopy.distance import geodesic

app = Flask(__name__)

# Read store information from CSV file
def fetch_store_data():
    store_list = []
    with open('stores.csv', 'r') as data_file:
        for record in data_file:
            parts = record.strip().split(',')
            name = parts[0]
            address = parts[1]
            latitude = float(parts[2])
            longitude = float(parts[3])
            store_list.append((name, address, latitude, longitude))
    return store_list

# Convert customer address to coordinates
def get_coordinates(address):
    locator = Nominatim(user_agent="store_finder_service")
    result = locator.geocode(address)
    if result:
        return (result.latitude, result.longitude)
    return None

# Determine nearest store from customer's location
def locate_closest_store(store_database, user_position):
    closest = None
    shortest = float('inf')
    for entry in store_database:
        store_position = (entry[2], entry[3])
        separation = geodesic(user_position, store_position).kilometers
        if separation < shortest:
            shortest = separation
            closest = entry
    return closest, shortest

@app.route('/', methods=['GET', 'POST'])
def main_page():
    if request.method == 'POST':
        user_input = request.form['address']
        user_location = get_coordinates(user_input)
        if user_location:
            all_stores = fetch_store_data()
            found_store, gap = locate_closest_store(all_stores, user_location)
            return render_template('index.html', closest_store=found_store, gap=gap)
        else:
            return render_template('index.html', error="Unable to locate address")
    return render_template('index.html')

if __name__ == '__main__':
    app.run(debug=True)

import numpy as np

class TicTacToe:
    def __init__(self):
        self.grid = np.zeros((3, 3), dtype=int)
        self.turn = 1  # 1 for player X, -1 for player O
        self.game_over = False
        self.outcome = None

    def restart(self):
        self.grid.fill(0)
        self.turn = 1
        self.game_over = False
        self.outcome = None
        return self.grid.copy()

    def get_valid_moves(self):
        moves = []
        for row in range(3):
            for col in range(3):
                if self.grid[row, col] == 0:
                    moves.append((row, col))
        return moves

    def play_move(self, position):
        row, col = position

        # Check if move is valid
        if self.grid[row, col] != 0:
            return self.grid.copy(), -1, True, {"error": "invalid_position"}

        # Place current player's mark
        self.grid[row, col] = self.turn

        # Check for win condition
        if self.has_won():
            self.game_over = True
            self.outcome = self.turn
            reward = 1.0
        # Check for draw
        elif not self.get_valid_moves():
            self.game_over = True
            reward = 0.0
        else:
            # Switch turns
            self.turn *= -1
            reward = 0.0

        return self.grid.copy(), reward, self.game_over, {}

    def has_won(self):
        # Check rows and columns
        for i in range(3):
            if np.all(self.grid[i, :] == self.turn) or np.all(self.grid[:, i] == self.turn):
                return True

        # Check diagonals
        if np.all(np.diag(self.grid) == self.turn):
            return True
        if np.all(np.diag(np.flipud(self.grid)) == self.turn):
            return True

        return False

    def display(self):
        print(self.grid)

