# Define a class to manage student information and academic performance
class Learner:
    def __init__(self, full_name, years_old, current_class):
        self.full_name = full_name
        self.years_old = years_old
        self.current_class = current_class
        self.enrolled_courses = []  # List to store enrolled courses
        self.course_scores = {}     # Dictionary to store scores for each course

    def enroll_course(self, course_name):
        if course_name not in self.enrolled_courses:
            self.enrolled_courses.append(course_name)
            self.course_scores[course_name] = None  # Initialize score as None

    def drop_course(self, course_name):
        if course_name in self.enrolled_courses:
            self.enrolled_courses.remove(course_name)
            del self.course_scores[course_name]

    def list_courses(self):
        return self.enrolled_courses

    def assign_score(self, course_name, score_value):
        if course_name in self.enrolled_courses:
            if 0 <= score_value <= 100:
                self.course_scores[course_name] = score_value
            else:
                raise ValueError("Score must be between 0 and 100")
        else:
            raise ValueError(f"Course {course_name} is not enrolled")

    def calculate_mean_score(self):
        accumulated_scores = 0
        num_courses_with_scores = 0
        for course, score in self.course_scores.items():
            if score is not None:
                accumulated_scores += score
                num_courses_with_scores += 1
        if num_courses_with_scores == 0:
            return None  # No scores available yet
        return accumulated_scores / num_courses_with_scores

