# Compare two text files and analyze their content similarity

def load_file_content(file_name):
    with open(file_name, 'r', encoding='utf-8') as f:
        return [line for line in f]

def compute_text_diff(lines_a, lines_b):
    # Create a custom diff representation using line-by-line comparison
    result = []
    max_len = max(len(lines_a), len(lines_b))

    for idx in range(max_len):
        line_a = lines_a[idx] if idx < len(lines_a) else ""
        line_b = lines_b[idx] if idx < len(lines_b) else ""

        if line_a == line_b:
            result.append(f"  {line_a.rstrip()}")
        else:
            if line_a:
                result.append(f"- {line_a.rstrip()}")
            if line_b:
                result.append(f"+ {line_b.rstrip()}")

    return "\n".join(result)

def calculate_similarity(lines_x, lines_y):
    # Convert to sets of unique lines
    set_x = set(lines_x)
    set_y = set(lines_y)

    # Compute intersection and union manually
    common = set()
    all_items = set()

    for item in set_x:
        all_items.add(item)
        if item in set_y:
            common.add(item)

    for item in set_y:
        all_items.add(item)

    # Avoid division by zero
    if len(all_items) == 0:
        return 1.0

    return len(common) / len(all_items)

def process_files(path_one, path_two):
    content_one = load_file_content(path_one)
    content_two = load_file_content(path_two)

    # Show differences
    diff_output = compute_text_diff(content_one, content_two)
    print("Differences:\n", diff_output)

    # Calculate similarity
    score = calculate_similarity(content_one, content_two)
    print(f"Jaccard Similarity Score: {score:.2f}")

if __name__ == "__main__":
    file_a = 'file1.txt'
    file_b = 'file2.txt'
    process_files(file_a, file_b)

# Custom serializers for Parent and Child models with nested representation

from rest_framework import serializers
from .models import Child, Parent, PhoneNumber

class ChildSerializer(serializers.ModelSerializer):
    class Meta:
        model = Child
        fields = ['id', 'name']

class ParentSerializer(serializers.ModelSerializer):
    # Initialize child field as read-only serializer in __init__ to avoid queryset dependency
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.fields['child'] = ChildSerializer(read_only=True)

    class Meta:
        model = Parent
        fields = ['id', 'name', 'phone_number', 'child']

    # Override to_representation for explicit control (optional since field is already set)
    def to_representation(self, instance):
        # Ensure child field uses the nested serializer
        representation = super().to_representation(instance)
        if 'child' in representation:
            child_instance = instance.child
            representation['child'] = ChildSerializer(child_instance).data
        return representation

import re
from typing import List

def sorted_list_sum(lst: List[str], reverse: bool = False) -> List[str]:
    """
    Formulate a function which intakes a list of strings, eliminates strings that possess odd lengths or incorporate numerals,
    and yields a sorted list in compliance with the succeeding constraints:
    - The received list will consistently be a list string-based and never numeric.
    - Potential for duplicate elements.
    - Sequence the list according to the length of every word in an escalating order.
    - For words identical in length, organise the list alphabetically.
    - Dismiss case sensitivity and special characters when executing the sorting process.
    Further, include an element to interchange the sorting scheme between ascending and descending according to an optional boolean parameter `reverse` with a default set to False.
    """

    def is_valid_string(s: str) -> bool:
        """Check if the string has an even length and does not contain numerals."""
        # Check for digits using character iteration
        has_digit = False
        for char in s:
            if '0' <= char <= '9':
                has_digit = True
                break

        # Check if length is even
        return len(s) % 2 == 0 and not has_digit

    def normalize_string(s: str) -> str:
        """Normalize the string by removing special characters and converting to lowercase."""
        normalized = ""
        for char in s:
            if 'a' <= char <= 'z' or 'A' <= char <= 'Z':
                normalized += char.lower()
        return normalized

    # Filter out invalid strings
    valid_strings = []
    for item in lst:
        if is_valid_string(item):
            valid_strings.append(item)

    # Sort the list based on the length of the strings, and alphabetically for strings of the same length
    def sort_key(s: str):
        return (len(s), normalize_string(s))

    # Implementing custom sort using bubble sort to avoid built-in sorted
    n = len(valid_strings)
    for i in range(n):
        for j in range(0, n - i - 1):
            key_j = sort_key(valid_strings[j])
            key_j1 = sort_key(valid_strings[j + 1])

            # Determine if swap is needed based on reverse flag
            should_swap = False
            if not reverse:
                # Ascending order
                if key_j > key_j1:
                    should_swap = True
            else:
                # Descending order
                if key_j < key_j1:
                    should_swap = True

            if should_swap:
                valid_strings[j], valid_strings[j + 1] = valid_strings[j + 1], valid_strings[j]

    return valid_strings

