import re

def assess_password_strength(password):
    """
    Assesses the strength of a password based on multiple criteria.

    :param password: The password to assess.
    :return: A dictionary with assessment details including score, suggestions, and strength status.
    """
    min_len = 8
    max_len = 64

    # Check for presence of required character types using regex
    has_upper = bool(re.search(r'[A-Z]', password))
    has_lower = bool(re.search(r'[a-z]', password))
    has_number = bool(re.search(r'\d', password))
    has_special = bool(re.search(r'[!@#$%^&*(),.?":{}|<>]', password))

    evaluation_score = 0
    improvement_notes = []

    # Length validation
    if len(password) < min_len:
        improvement_notes.append(f"Extend your password to at least {min_len} characters.")
    if len(password) > max_len:
        improvement_notes.append(f"Keep your password under {max_len} characters.")

    # Character type validations
    if not has_upper:
        improvement_notes.append("Include at least one uppercase letter (A–Z).")
    if not has_lower:
        improvement_notes.append("Include at least one lowercase letter (a–z).")
    if not has_number:
        improvement_notes.append("Include at least one numeric digit (0–9).")
    if not has_special:
        improvement_notes.append("Include at least one special character (!@#$%^&*(),.?\":{}|<>).")

    # Scoring system: award points for meeting each criterion
    if len(password) >= min_len:
        evaluation_score += 1
    if has_upper:
        evaluation_score += 1
    if has_lower:
        evaluation_score += 1
    if has_number:
        evaluation_score += 1
    if has_special:
        evaluation_score += 1

    return {
        "score": evaluation_score,
        "feedback": improvement_notes,
        "is_strong": evaluation_score >= 3
    }

