# Check for numbers that equal the sum of their digits raised to the power of the number of digits

def check_digit_power_sum(value):
    digits = str(value)
    power = len(digits)
    total = 0
    for d in digits:
        total += int(d) ** power
    return value == total

def verify_narcissistic_property(value):
    return check_digit_power_sum(value)

def process_range(initial, final):
    # Validate inputs
    if not isinstance(initial, int) or not isinstance(final, int):
        raise TypeError("Both initial and final values must be integers.")
    if initial > final:
        raise ValueError("Initial value must be less than or equal to final value.")

    special_numbers = []
    equivalent_numbers = []
    remaining_numbers = []

    for current in range(initial, final + 1):
        if check_digit_power_sum(current):
            special_numbers.append(current)
            equivalent_numbers.append(current)  # Both terms refer to the same concept here
        else:
            remaining_numbers.append(current)

    count_total = final - initial + 1
    output = {
        'special_numbers': special_numbers,
        'equivalent_numbers': equivalent_numbers,
        'remaining_numbers': remaining_numbers,
        'frequencies': {
            'special': len(special_numbers),
            'equivalent': len(equivalent_numbers),
            'remaining': len(remaining_numbers),
            'total': count_total
        },
        'ratios': {
            'special': (len(special_numbers) / count_total) * 100,
            'equivalent': (len(equivalent_numbers) / count_total) * 100,
            'remaining': (len(remaining_numbers) / count_total) * 100
        }
    }

    return output

def execute():
    try:
        lower_bound = 100
        upper_bound = 1000
        analysis = process_range(lower_bound, upper_bound)

        print(f"Special Numbers: {analysis['special_numbers']}")
        print(f"Equivalent Numbers: {analysis['equivalent_numbers']}")
        print(f"Remaining Numbers: {analysis['remaining_numbers']}")

        print(f"Frequencies: {analysis['frequencies']}")
        print(f"Ratios: {analysis['ratios']['special']:.2f}%")

    except (TypeError, ValueError) as err:
        print(f"Exception: {err}")

if __name__ == "__main__":
    execute()

