import unittest

class Base58Exception(Exception):
    pass

class Base58Converter:
    SYMBOLS = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz'
    RADIX = 58

    @staticmethod
    def convert_to_base58(value: int) -> str:
        if value < 0:
            raise Base58Exception("Value must be non-negative")

        if value == 0:
            return '1'

        result = []
        current_value = value
        while current_value > 0:
            current_value, index = divmod(current_value, Base58Converter.RADIX)
            result.append(Base58Converter.SYMBOLS[index])

        # Reverse to get correct order
        encoded = ''.join(reversed(result))

        # Count leading zeros in original number representation
        zero_count = 0
        temp = value
        while temp % Base58Converter.RADIX == 0 and temp > 0:
            zero_count += 1
            temp //= Base58Converter.RADIX

        # Add leading '1' characters for each zero remainder
        return '1' * zero_count + encoded

    @staticmethod
    def convert_from_base58(text: str) -> int:
        if not text or not all(symbol in Base58Converter.SYMBOLS for symbol in text):
            raise Base58Exception("Invalid Base58 string")

        result = 0
        for symbol in text:
            result = result * Base58Converter.RADIX + Base58Converter.SYMBOLS.index(symbol)

        # Count leading '1' characters which represent zero values
        leading_ones = 0
        for char in text:
            if char == '1':
                leading_ones += 1
            else:
                break

        # Each leading '1' represents a factor of 58 in the original number
        return result // (Base58Converter.RADIX ** leading_ones)

# Unit Tests
class TestBase58Conversion(unittest.TestCase):
    def test_encoding_values(self):
        self.assertEqual(Base58Converter.convert_to_base58(0), '1')
        self.assertEqual(Base58Converter.convert_to_base58(1), '2')
        self.assertEqual(Base58Converter.convert_to_base58(57), 'y')
        self.assertEqual(Base58Converter.convert_to_base58(123456789), '15VjRaDX9zpbA8LVnbrCAFzrVzN7ixHNsC')

    def test_decoding_values(self):
        self.assertEqual(Base58Converter.convert_from_base58('1'), 0)
        self.assertEqual(Base58Converter.convert_from_base58('2'), 1)
        self.assertEqual(Base58Converter.convert_from_base58('y'), 57)
        self.assertEqual(Base58Converter.convert_from_base58('15VjRaDX9zpbA8LVnbrCAFzrVzN7ixHNsC'), 123456789)

    def test_round_trip_conversion(self):
        original_value = 123456789
        encoded_form = Base58Converter.convert_to_base58(original_value)
        decoded_form = Base58Converter.convert_from_base58(encoded_form)
        self.assertEqual(decoded_form, original_value)

    def test_error_handling(self):
        with self.assertRaises(Base58Exception):
            Base58Converter.convert_to_base58(-5)
        with self.assertRaises(Base58Exception):
            Base58Converter.convert_from_base58('invalid!@#')

