from django.core.management.base import BaseCommand
import argparse

class Command(BaseCommand):
    help = 'Computes the square of an input integer'

    def add_arguments(self, parser):
        parser.add_argument(
            'value',
            type=int,
            help='The integer to be squared'
        )

