        result = value * value
        self.stdout.write(
            self.style.SUCCESS(f'The square of {value} is {result}')
        )

# Monitor and accumulate time spent using web browsers

import psutil
import time
from datetime import datetime, timedelta

# Define browser-related process identifiers
BROWSER_IDENTIFIERS = ['chrome', 'firefox', 'safari', 'msedge', 'opera', 'brave']

def retrieve_active_window_title():
    """Retrieve the title of the currently focused window."""
    import os
    if os.name == 'nt':  # Windows platform
        try:
            import win32gui
            return win32gui.GetWindowText(win32gui.GetForegroundWindow())
        except ImportError:
            print("Required module not found: pywin32. Install via: pip install pywin32")
            return None
    elif os.name == 'posix':  # Linux/macOS platforms
        try:
            import subprocess
            result = subprocess.check_output(["xdotool", "getwindowfocus", "getwindowname"], stderr=subprocess.DEVNULL)
            return result.strip().decode()
        except (ImportError, FileNotFoundError):
            print("Missing dependency: xdotool. Install via: sudo apt-get install xdotool")
            return None
    else:
        return None

def is_web_browser_in_use():
    """Determine whether the active application is a recognized web browser."""
    current_title = retrieve_active_window_title()
    if current_title:
        for identifier in BROWSER_IDENTIFIERS:
            if identifier in current_title.lower():
                return True
    return False

def monitor_browser_usage():
    """Monitor and record cumulative time spent in web browsers."""
    session_start = None
    accumulated_duration = timedelta()

    while True:
        if is_web_browser_in_use():
            if session_start is None:
                session_start = datetime.now()
        else:
            if session_start is not None:
                session_end = datetime.now()
                accumulated_duration += session_end - session_start
                session_start = None
                print(f"Total browser usage time: {accumulated_duration}")

        time.sleep(1)  # Poll interval set to one second

if __name__ == "__main__":
    monitor_browser_usage()

# Rock-Paper-Scissors game with recursive input validation

import random

def get_player_selection():
    choice = input("Choose your move (Rock, Paper, Scissors): ").strip().title()
    if choice in ["Rock", "Paper", "Scissors"]:
        return choice
    else:
        print("Invalid selection. Please choose Rock, Paper, or Scissors.")
        return get_player_selection()

def generate_computer_move():
    options = ["Rock", "Paper", "Scissors"]
    return random.choice(options)

def decide_outcome(player_move, computer_move):
    if player_move == computer_move:
        return "Draw!"
    elif ((player_move == "Rock" and computer_move == "Scissors") or
          (player_move == "Paper" and computer_move == "Rock") or
          (player_move == "Scissors" and computer_move == "Paper")):
        return "Player wins!"
    else:
        return "Computer wins!"

def run_round():
    print("Welcome to Rock-Paper-Scissors!")
    player_move = get_player_selection()
    computer_move = generate_computer_move()
    print(f"You selected {player_move}, computer selected {computer_move}.")
    outcome = decide_outcome(player_move, computer_move)
    print(outcome)

def main():
    while True:
        run_round()
        continue_game = input("Play again? (yes/no): ").strip().lower()
        if continue_game != "yes":
            print("Goodbye! Thanks for playing!")
            break

if __name__ == "__main__":
    main()

