# Grade tracking system with GPA calculation and trend analysis

# Mapping of score ranges to letter grades and base GPA values
SCORE_TO_GRADE_MAP = {
    range(90, 101): ('A', 4.0),
    range(80, 90): ('B', 3.0),
    range(70, 80): ('C', 2.0),
    range(60, 70): ('D', 1.0),
    range(0, 60): ('F', 0.0)
}

# Additional points added for course difficulty levels
DIFFICULTY_BONUS = {
    'AP': 1.0,
    'Honors': 0.5,
    'Standard': 0.0
}

def convert_score_to_letter(score):
    """Convert numeric score to letter grade and base GPA"""
    for score_range, (letter, gpa) in SCORE_TO_GRADE_MAP.items():
        if score in score_range:
            return letter, gpa
    raise ValueError("Score must be between 0 and 100")

def compute_weighted_gpa(scores, course_difficulties):
    """Calculate weighted GPA based on scores and course difficulties"""
    if len(scores) != len(course_difficulties):
        raise ValueError("Number of scores must equal number of course difficulties")

    total_adjusted_gpa = 0
    for score, difficulty in zip(scores, course_difficulties):
        _, base_gpa = convert_score_to_letter(score)
        total_adjusted_gpa += base_gpa + DIFFICULTY_BONUS[difficulty]

    return total_adjusted_gpa / len(scores)

def analyze_performance_trend(performance_scores):
    """Analyze whether student performance is improving, declining, or stable"""
    if len(performance_scores) < 2:
        return "Insufficient data for trend analysis"

    # Simple linear regression implementation
    n = len(performance_scores)
    x_mean = (n - 1) / 2
    y_mean = sum(performance_scores) / n

    numerator = sum((i - x_mean) * (performance_scores[i] - y_mean) for i in range(n))
    denominator = sum((i - x_mean) ** 2 for i in range(n))

    slope = numerator / denominator if denominator != 0 else 0

    if slope > 0.5:
        return "Improving"
    elif slope < -0.5:
        return "Declining"
    else:
        return "Stable"

class Learner:
    def __init__(self, learner_name):
        self.name = learner_name
        self.test_scores = []
        self.class_levels = []

    def record_academic_data(self, new_scores, new_levels):
        """Record new academic data after validation"""
        if len(new_scores) != len(new_levels):
            raise ValueError("Scores and course levels must have same count")

        for score, level in zip(new_scores, new_levels):
            if not (0 <= score <= 100):
                raise ValueError(f"Invalid score {score}. Must be 0-100.")
            if level not in DIFFICULTY_BONUS:
                raise ValueError(f"Unknown course level '{level}'. Valid: {', '.join(DIFFICULTY_BONUS.keys())}")

        self.test_scores.extend(new_scores)
        self.class_levels.extend(new_levels)

    def generate_summary(self):
        """Create comprehensive academic summary"""
        if not self.test_scores:
            return f"No academic records found for {self.name}"

        # Convert scores to letter grades
        letter_grades = [convert_score_to_letter(score)[0] for score in self.test_scores]

        # Calculate metrics
        weighted_gpa = compute_weighted_gpa(self.test_scores, self.class_levels)
        trend = analyze_performance_trend(self.test_scores)

        # Format output
        summary = (f"Academic Report for {self.name}:\n"
                   f"Grades: {', '.join(letter_grades)}\n"
                   f"Weighted GPA: {weighted_gpa:.2f}\n"
                   f"Performance Trend: {trend}\n")

        return summary

def main():
    student_records = {}
    while True:
        print("\n1. Register Student\n2. Record Grades\n3. View Report\n4. Quit")
        selection = input("Select an option: ")

        if selection == '1':
            name = input("Enter student name: ")
            if name in student_records:
                print(f"Student {name} is already registered.")
            else:
                student_records[name] = Learner(name)
                print(f"Student {name} successfully registered.")

        elif selection == '2':
            name = input("Enter student name: ")
            if name not in student_records:
                print(f"Student {name} not found. Please register first.")
                continue

            try:
                scores = list(map(int, input("Enter test scores (space-separated): ").split()))
                levels = input("Enter course levels (space-separated, e.g., AP Honors Standard): ").split()

                student_records[name].record_academic_data(scores, levels)
                print("Academic data recorded successfully.")
            except ValueError as error:
                print(f"Error: {error}")

        elif selection == '3':
            name = input("Enter student name: ")
            if name not in student_records:
                print(f"Student {name} not found.")
                continue

            print(student_records[name].generate_summary())

        elif selection == '4':
            print("Thank you for using the academic tracking system.")
            break

        else:
            print("Invalid selection. Please choose 1-4.")

if __name__ == "__main__":
    main()

# Modified Go board game implementation with alternate logic

class GoGame:
    def __init__(self, grid_size=19):
        self.grid_size = grid_size
        self.board_state = [[None] * grid_size for _ in range(grid_size)]
        self.active_player = 'B'  # 'B' for black, 'W' for white

    def display_board(self):
        for line in self.board_state:
            print(' '.join('.' if spot is None else spot for spot in line))
        print()

    def add_stone(self, x, y):
        if self.board_state[x][y] is not None:
            print("Space already taken.")
            return False
        self.board_state[x][y] = self.active_player
        self.active_player = 'W' if self.active_player == 'B' else 'B'
        return True

    def check_move_validity(self, x, y):
        if x < 0 or x >= self.grid_size or y < 0 or y >= self.grid_size:
            return False
        if self.board_state[x][y] is not None:
            return False
        return True

    def end_condition(self):
        # Check if any empty positions remain
        for line in self.board_state:
            for spot in line:
                if spot is None:
                    return False
        return True

    def run_game(self):
        print("Welcome to Go!")
        self.display_board()
        while not self.end_condition():
            try:
                x = int(input(f"Player {self.active_player}, enter row: "))
                y = int(input(f"Player {self.active_player}, enter column: "))
                if self.check_move_validity(x, y):
                    self.add_stone(x, y)
                    self.display_board()
                else:
                    print("Invalid move, please try again.")
            except ValueError:
                print("Please enter valid integers for coordinates.")

        print("Game Finished! The board is completely filled.")

if __name__ == "__main__":
