# Import necessary modules for environment handling, HTTP requests, and JSON processing
import os
import requests
import json

def fetch_api_credentials():
    """Obtain the API token from environment variables or raise an exception if missing."""
    token = os.environ.get('API_KEY')
    if not token:
        raise ValueError("API key is missing. Set the 'API_KEY' environment variable.")
    return token

def send_authenticated_post(url, payload):
    """Send a POST request with Bearer token authentication and JSON payload."""
    api_token = fetch_api_credentials()
    request_headers = {
        'Authorization': f'Bearer {api_token}',
        'Content-Type': 'application/json'
    }

    try:
        # Convert payload to JSON string before sending
        response = requests.post(url, headers=request_headers, json=payload)
        response.raise_for_status()  # Ensure non-2xx responses raise exceptions
        return response.json()
    except requests.exceptions.RequestException as error:
        print(f"Request failed: {error}")
        return None

def pretty_print_response(api_response):
    """Convert the API response into a nicely formatted string for display."""
    if api_response:
        return json.dumps(api_response, indent=4)
    else:
        return "No data returned from the server."

def execute_main_workflow():
    target_url = 'https://api.example.com/v1/resource'
    request_body = {
        "key1": "value1",
        "key2": "value2"
    }

    result = send_authenticated_post(target_url, request_body)
    print(pretty_print_response(result))

if __name__ == "__main__":
