# Retrieve applicable tax regulations based on the provided date

def get_applicable_tax_regulations(report_date):
    return TaxRule.query.filter(
        (TaxRule.effective_date <= report_date) &
        (TaxRule.expiration_date.is_(None) | (TaxRule.expiration_date > report_date))
    ).all()

def assess_conditions(regulation, record):
    conditions = TaxCriterion.query.filter_by(tax_rule_id=regulation.tax_rule_id).all()
    logic = TaxCriterionCombination.query.filter_by(tax_rule_id=regulation.tax_rule_id).first()

    evaluations = []
    for condition in conditions:
        data_value = record.get(condition.criterion_field)
        if condition.criterion_type == 'boolean':
            evaluation = data_value == (condition.value == 'true')
        elif condition.criterion_type == 'numeric':
            evaluation = eval(f"{data_value} {condition.operator} {condition.value}")
        elif condition.criterion_type == 'categorical':
            evaluation = data_value == condition.value
        evaluations.append(evaluation)

    if logic.combination_type == 'AND':
        return all(evaluations)
    elif logic.combination_type == 'OR':
        return any(evaluations)

def compute_tax(record, report_date):
    regulations = get_applicable_tax_regulations(report_date)
    for regulation in regulations:
        if assess_conditions(regulation, record):
            record['tax_amount'] += record['taxable_amount'] * regulation.tax_rate
    return record

