class StudentRegistry:
    def __init__(self):
        self.student_records = {}

    def register_new_student(self, student_name, years_old):
        if student_name in self.student_records:
            raise ValueError(f"Student '{student_name}' is already registered.")
        self.student_records[student_name] = {"years_old": years_old, "enrollments": []}

    def deregister_student(self, student_name):
        if student_name not in self.student_records:
            raise ValueError(f"Student '{student_name}' is not registered.")
        del self.student_records[student_name]

    def modify_student_age(self, student_name, new_age):
        if student_name not in self.student_records:
            raise ValueError(f"Student '{student_name}' is not registered.")
        self.student_records[student_name]["years_old"] = new_age

    def add_course_to_student(self, student_name, course_name, instructor_name):
        if student_name not in self.student_records:
            raise ValueError(f"Student '{student_name}' is not registered.")

        new_course = Course(course_name, instructor_name)
        student_info = self.student_records[student_name]

        # Check if already enrolled using the custom equality method
        for existing in student_info["enrollments"]:
            if existing == new_course:
                return  # Already enrolled, do nothing

        student_info["enrollments"].append(new_course)

    def drop_course_from_student(self, student_name, course_name):
        if student_name not in self.student_records:
            raise ValueError(f"Student '{student_name}' is not registered.")

        student_info = self.student_records[student_name]
        student_info["enrollments"] = [
            course for course in student_info["enrollments"] 
            if course.course_name != course_name
        ]

    def retrieve_student_info(self, student_name):
        if student_name not in self.student_records:
            raise ValueError(f"Student '{student_name}' is not registered.")
        return self.student_records[student_name]

    def __repr__(self):
        return f"StudentRegistry(student_records={self.student_records})"

