# Alternative implementation using iterative BFS instead of DFS

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def has_prime_factor(n):
    # Check divisibility by small primes (2 through 19)
    prime_list = [2, 3, 5, 7, 11, 13, 17, 19]
    for p in prime_list:
        if n != p and n % p == 0:  # Exclude the case where n itself is prime (optional refinement)
            return True
    return False

def collect_even_level_prime_divisible_nodes(root_node):
    if not root_node:
        return [], 0

    matching_values = []
    queue = [(root_node, 0)]  # (node, level)

    while queue:
        current_node, current_level = queue.pop(0)

        # Process node if it's at even level and value divisible by prime
        if current_level % 2 == 0 and has_prime_factor(current_node.val):
            matching_values.append(current_node.val)

        # Add children to queue with incremented level
        if current_node.left:
            queue.append((current_node.left, current_level + 1))
        if current_node.right:
            queue.append((current_node.right, current_level + 1))

    return matching_values, sum(matching_values)

