def assertive_median(l: list, cmp_func: callable):
    """Return median of the list 'l' avoiding forming an array or using built-in features.
    The code should handle tuples represented by both even and odd numbers, duplicates, using cmp_func for comparison. There should be exception handling for incorrect or non-calculable input data, and it should be verified that the list contains at least one element.
    """
    # Input validation
    if not isinstance(l, list):
        raise ValueError("Input must be a list of numbers.")
    if len(l) == 0:
        raise ValueError("List must contain at least one element.")
    if not all(isinstance(item, (int, float)) for item in l):
        raise ValueError("Input must be a list of numbers.")
    if not callable(cmp_func):
        raise ValueError("cmp_func must be a callable comparator function.")

    # Helper function to partition the list
    def divide_sequence(sequence, start, end):
        pivot_val = sequence[end]
        boundary = start - 1

        for idx in range(start, end):
            if cmp_func(sequence[idx], pivot_val) < 0:
                boundary += 1
                sequence[boundary], sequence[idx] = sequence[idx], sequence[boundary]

        sequence[boundary + 1], sequence[end] = sequence[end], sequence[boundary + 1]
        return boundary + 1

    # Quickselect implementation to find k-th smallest element
    def locate_kth_element(arr, position, left, right):
        if left == right:
            return arr[left]

        split_point = divide_sequence(arr, left, right)

        if position == split_point:
            return arr[position]
        elif position < split_point:
            return locate_kth_element(arr, position, left, split_point - 1)
        else:
            return locate_kth_element(arr, position, split_point + 1, right)

    # Calculate median based on list length parity
    total_items = len(l)
    if total_items % 2 == 1:
        # Odd number of elements: return middle element
        return locate_kth_element(l, total_items // 2, 0, total_items - 1)
    else:
        # Even number of elements: average of two middle elements
        lower_mid = locate_kth_element(l, total_items // 2 - 1, 0, total_items - 1)
        upper_mid = locate_kth_element(l, total_items // 2, 0, total_items - 1)
        return (lower_mid + upper_mid) / 2

# Test cases
assert assertive_median([3, 1, 2, 4, 5], lambda a, b: a - b) == 3
assert assertive_median([-10, 4, 6, 1000, 10, 20], lambda a, b: a - b) == 15.0
assert assertive_median([1, 2, 2, 4, 5], lambda a, b: a - b) == 2

