# Alternative implementation of Quaternion class with different internal logic but same functionality

class Quaternion:
    def __init__(self, real=0.0, i_comp=0.0, j_comp=0.0, k_comp=0.0):
        """
        Creates a quaternion with components [real, i, j, k]

        Args:
            real (float): Real part
            i_comp (float): Coefficient for i component
            j_comp (float): Coefficient for j component
            k_comp (float): Coefficient for k component
        """
        self.components = [float(real), float(i_comp), float(j_comp), float(k_comp)]

    def __repr__(self):
        return f"Quaternion({self.components[0]}, {self.components[1]}, {self.components[2]}, {self.components[3]})"

    def __str__(self):
        signs = ['+', '+', '+']
        for i in range(1, 4):
            if self.components[i] < 0:
                signs[i-1] = '-'
        abs_vals = [abs(x) for x in self.components[1:]]
        return f"{self.components[0]} {signs[0]} {abs_vals[0]}i {signs[1]} {abs_vals[1]}j {signs[2]} {abs_vals[2]}k"

    def conjugate(self):
        """Returns the quaternion conjugate"""
        new_components = [self.components[0], -self.components[1], -self.components[2], -self.components[3]]
        return Quaternion(*new_components)

    def norm(self):
        """Computes the Euclidean norm of the quaternion"""
        return sum(x**2 for x in self.components) ** 0.5

    def normalize(self):
        """Returns unit quaternion in same direction"""
        magnitude = self.norm()
        if magnitude == 0:
            raise ValueError("Cannot normalize zero quaternion")
        return Quaternion(*(x/magnitude for x in self.components))

    def __add__(self, other):
        """Performs quaternion addition"""
        if isinstance(other, Quaternion):
            return Quaternion(*(a + b for a, b in zip(self.components, other.components)))
        else:
            raise TypeError("Addition requires another Quaternion")

    def __sub__(self, other):
        """Performs quaternion subtraction"""
        if isinstance(other, Quaternion):
            return Quaternion(*(a - b for a, b in zip(self.components, other.components)))
        else:
            raise TypeError("Subtraction requires another Quaternion")

    def __mul__(self, other):
        """Implements Hamilton product for quaternions"""
        if not isinstance(other, Quaternion):
            raise TypeError("Multiplication requires another Quaternion")

        r1, i1, j1, k1 = self.components
        r2, i2, j2, k2 = other.components

        # Using matrix multiplication approach for quaternion product
        result = [
            r1*r2 - i1*i2 - j1*j2 - k1*k2,
            r1*i2 + i1*r2 + j1*k2 - k1*j2,
            r1*j2 - i1*k2 + j1*r2 + k1*i2,
            r1*k2 + i1*j2 - j1*i2 + k1*r2
        ]
        return Quaternion(*result)

    def __truediv__(self, other):
        """Performs quaternion division using conjugate and norm"""
        if not isinstance(other, Quaternion):
            raise TypeError("Division requires another Quaternion")

        denominator = other.norm() ** 2
        if denominator == 0:
            raise ZeroDivisionError("Cannot divide by zero quaternion")

        return self * other.conjugate() / denominator

