# Define a class to represent a student with academic information

class Learner:
    def __init__(self, full_name, institution, year, academic_score):
        self.full_name = full_name
        self.institution = institution
        self.year = year
        self.academic_score = academic_score
        self.enrollments = []

    def change_year(self, new_year):
        if not isinstance(new_year, int):
            raise TypeError("Year must be an integer.")
        if new_year < 1 or new_year > 12:
            raise ValueError("Year must be between 1 and 12.")
        self.year = new_year

    def modify_academic_score(self, new_score):
        if not isinstance(new_score, (int, float)):
            raise TypeError("Academic score must be numeric.")
        if new_score < 0.0 or new_score > 4.0:
            raise ValueError("Academic score must be in the range [0.0, 4.0].")
        self.academic_score = new_score

    def register_course(self, course_title):
        if len(self.enrollments) >= 7:
            raise RuntimeError("Maximum of 7 courses allowed per student.")
        if course_title in self.enrollments:
            raise RuntimeError(f"Course {course_title} is already registered.")
        self.enrollments.append(course_title)

    def compute_gpa(self, course_scores):
        if not isinstance(course_scores, dict):
            raise TypeError("Course scores must be provided as a dictionary.")
        if set(course_scores.keys()) != set(self.enrollments):
            raise ValueError("All enrolled courses must have corresponding scores.")

        total_weight = 0
        weighted_sum = 0

        for course, score in course_scores.items():
            if not isinstance(score, (int, float)):
                raise TypeError(f"Score for {course} must be numeric.")
            if score < 0.0 or score > 100.0:
                raise ValueError(f"Score for {course} must be between 0.0 and 100.0.")

            # Assume uniform credit hours (e.g., 4 credits each)
            credit_hours = 4
            total_weight += credit_hours
            weighted_sum += score * credit_hours

        if total_weight == 0:
            raise ValueError("Total credit weight cannot be zero.")

        final_gpa = (weighted_sum / total_weight) / 100 * 4.0
        return final_gpa

