class AcademicSubject:
    def __init__(self, subject_name, subject_code, credit_hours, lead_instructor):
        # Validate input types
        if not isinstance(subject_name, str) or not isinstance(subject_code, str) or not isinstance(lead_instructor, str):
            raise ValueError("Subject Name, Subject Code, and Lead Instructor must be strings.")
        if not isinstance(credit_hours, int) or credit_hours <= 0:
            raise ValueError("Credit Hours must be a positive integer.")

        self.subject_name = subject_name
        self.subject_code = subject_code
        self.credit_hours = credit_hours
        self.lead_instructor = lead_instructor

    def __str__(self):
        return f"Subject: {self.subject_name}, Code: {self.subject_code}, Credits: {self.credit_hours}, Instructor: {self.lead_instructor}"

class SubjectCollection:
    def __init__(self):
        self.subjects = []

    def register_subject(self, subject_name, subject_code, credit_hours, lead_instructor):
        # Check for duplicate subject codes
        if any(sub.subject_code == subject_code for sub in self.subjects):
            raise ValueError(f"Subject with code {subject_code} already registered.")

        new_subject = AcademicSubject(subject_name, subject_code, credit_hours, lead_instructor)
        self.subjects.append(new_subject)

    def list_all_subjects(self):
        return [str(subject) for subject in self.subjects]

    def modify_subject_details(self, subject_code, **changes):
        for subject in self.subjects:
            if subject.subject_code == subject_code:
                for attr, val in changes.items():
                    if attr == 'subject_name':
                        subject.subject_name = val
                    elif attr == 'credit_hours':
                        if not isinstance(val, int) or val <= 0:
                            raise ValueError("Credit Hours must be a positive integer.")
                        subject.credit_hours = val
                    elif attr == 'lead_instructor':
                        subject.lead_instructor = val
                return
        raise ValueError(f"Subject with code {subject_code} not found.")

    def remove_subject(self, subject_code):
        for idx, subject in enumerate(self.subjects):
            if subject.subject_code == subject_code:
                del self.subjects[idx]
                return
        raise ValueError(f"Subject with code {subject_code} not found.")

    def find_by_code(self, subject_code):
        for subject in self.subjects:
            if subject.subject_code == subject_code:
                return subject
        return None

    def find_by_instructor(self, instructor_name):
        return [subject for subject in self.subjects if subject.lead_instructor == instructor_name]

    def organize_by_attribute(self, sort_field='subject_name'):
        if sort_field not in ['subject_name', 'credit_hours']:
            raise ValueError("Sort field must be 'subject_name' or 'credit_hours'.")

        return sorted(self.subjects, key=lambda sub: getattr(sub, sort_field))

# Car Control System - Refactored Implementation

from abc import ABC, abstractmethod
from enum import Enum, auto

# Re-engineered state enumerations with alternative naming and values
class PowerMode(Enum):
    INACTIVE = 0
    ACTIVE = 1

class ChargeStatus(Enum):
    CRITICAL = 1
    NORMAL = 2
    FULL = 3

class DetectionUnit(Enum):
    DISABLED = 0
    ENABLED = 1

# Singleton implementation for vehicle status tracking
class VehicleStatus:
    _single_instance = None

    @classmethod
    def acquire(cls):
        if cls._single_instance is None:
            cls._single_instance = cls()
        return cls._single_instance

    def __init__(self):
        self.power_mode = PowerMode.INACTIVE
        self.charge_status = ChargeStatus.NORMAL
        self.detection_unit = DetectionUnit.DISABLED

    def adjust_power(self, mode: PowerMode):
        self.power_mode = mode

    def adjust_charge(self, level: ChargeStatus):
        self.charge_status = level

    def adjust_detection(self, unit: DetectionUnit):
        self.detection_unit = unit

# Abstract interface for monitoring components
class Monitor(ABC):
    @abstractmethod
    def react(self, vehicle_status: VehicleStatus):
        pass

# Main vehicle control system
class AutonomousVehicle:
    def __init__(self):
        self.status = VehicleStatus.acquire()
        self.monitors = []

    def register_monitor(self, monitor: Monitor):
        self.monitors.append(monitor)

    def unregister_monitor(self, monitor: Monitor):
        self.monitors.remove(monitor)

    def broadcast_changes(self):
        for monitor in self.monitors:
            monitor.react(self.status)

    def ignite_engine(self):
        self.status.adjust_power(PowerMode.ACTIVE)
        print("Engine ignited.")
        self.broadcast_changes()

    def extinguish_engine(self):
        self.status.adjust_power(PowerMode.INACTIVE)
        print("Engine extinguished.")
        self.broadcast_changes()

    def replenish_energy(self, level: ChargeStatus):
        self.status.adjust_charge(level)
        print(f"Energy replenished to {level.name} level.")
        self.broadcast_changes()

    def enable_sensors(self):
        self.status.adjust_detection(DetectionUnit.ENABLED)
        print("Sensors enabled.")
        self.broadcast_changes()

    def disable_sensors(self):
        self.status.adjust_detection(DetectionUnit.DISABLED)
        print("Sensors disabled.")
        self.broadcast_changes()

    def autonomous_drive(self):
        if (self.status.power_mode == PowerMode.ACTIVE and 
            self.status.detection_unit == DetectionUnit.ENABLED):
            print("Autonomous driving initiated.")
        else:
            print("Autonomous driving unavailable. Verify engine and sensor conditions.")

    def automated_parking(self):
        if self.status.detection_unit == DetectionUnit.ENABLED:
            print("Automated parking sequence started.")
        else:
            print("Automated parking unavailable. Check sensor configuration.")

    def hazard_alert(self):
        if self.status.detection_unit == DetectionUnit.ENABLED:
            print("Hazard detection system operational.")
        else:
            print("Hazard detection system inactive. Verify sensor setup.")

# Concrete monitoring component
class StatusRecorder(Monitor):
    def react(self, vehicle_status: VehicleStatus):
        print(f"Status Report: Engine={vehicle_status.power_mode.name}, "
              f"Charge={vehicle_status.charge_status.name}, "
              f"Sensors={vehicle_status.detection_unit.name}")

# Demonstration section
if __name__ == "__main__":
    vehicle = AutonomousVehicle()
    recorder = StatusRecorder()
    vehicle.register_monitor(recorder)

    vehicle.ignite_engine()
    vehicle.replenish_energy(ChargeStatus.FULL)
    vehicle.enable_sensors()
    vehicle.autonomous_drive()
    vehicle.automated_parking()
    vehicle.hazard_alert()
    vehicle.extinguish_engine()
    vehicle.disable_sensors()

