# Modified logic: Uses parameterized queries safely, avoids SQL injection,
# and improves user input validation and error handling.

import sqlite3
import csv
from datetime import datetime
from collections import Counter

# Database connection (reusing same database)
conn = sqlite3.connect('sales.db')
cursor = conn.cursor()

# Ensure the sales table exists with updated schema for better data integrity
cursor.execute('''
CREATE TABLE IF NOT EXISTS sales (
    sale_id INTEGER PRIMARY KEY AUTOINCREMENT,
    product_name TEXT NOT NULL,
    quantity INTEGER NOT NULL CHECK(quantity > 0),
    sale_date DATE NOT NULL,
    price REAL NOT NULL CHECK(price >= 0)
)
''')
conn.commit()

def getSalesByProduct(product_name):
    """Calculate total sales for a given product."""
    try:
        cursor.execute(
            'SELECT COALESCE(SUM(quantity * price), 0) FROM sales WHERE product_name = ?', 
            (product_name,)
        )
        result = cursor.fetchone()
        return float(result[0])
    except Exception as e:
        print(f"Error retrieving sales: {e}")
        return 0.0

def addSale(sale_data):
    """Add a new sale record to the database."""
    try:
        # Validate inputs before insertion
        if not isinstance(sale_data['quantity'], int) or sale_data['quantity'] <= 0:
            raise ValueError("Quantity must be a positive integer")
        if not isinstance(sale_data['price'], (int, float)) or sale_data['price'] < 0:
            raise ValueError("Price must be non-negative")

        cursor.execute(
            'INSERT INTO sales (product_name, quantity, sale_date, price) VALUES (?, ?, ?, ?)',
            (sale_data['product_name'], sale_data['quantity'], sale_data['sale_date'], sale_data['price'])
        )
        conn.commit()
        print(f"✅ Sale added for '{sale_data['product_name']}' on {sale_data['sale_date']}")
    except Exception as e:
        print(f"❌ Error adding sale: {e}")

def getTopSellingProducts():
    """Retrieve top 5 products by total sales revenue."""
    try:
        cursor.execute('''
            SELECT product_name, SUM(quantity * price) AS total_sales 
            FROM sales 
            GROUP BY product_name 
            ORDER BY total_sales DESC 
            LIMIT 5
        ''')
        top_products = cursor.fetchall()

        if not top_products:
            print("No sales records found.")
            return

        print("\n🏆 Top 5 Selling Products:")
        for idx, (product, sales) in enumerate(top_products, start=1):
            print(f"{idx}. {product} - ${float(sales):.2f}")

        selection = input("\nSelect a product number (1-5) to view details: ").strip()
        if selection.isdigit() and 1 <= int(selection) <= len(top_products):
            selected_product = top_products[int(selection) - 1][0]
            print(f"\n📊 Sales for '{selected_product}': ${getSalesByProduct(selected_product):.2f}")
        else:
            print("⚠️ Invalid selection.")
    except Exception as e:
        print(f"❌ Error fetching top products: {e}")

def deleteSale(sale_id):
    """Delete a specific sale by ID after confirmation."""
    try:
        cursor.execute('SELECT * FROM sales WHERE sale_id = ?', (sale_id,))
        sale = cursor.fetchone()

        if sale:
            print(f"\n🗑️ Found sale: ID={sale[0]}, Product='{sale[1]}', Date={sale[3]}")
            confirm = input("Confirm deletion? (y/n): ").strip().lower()
            if confirm == 'y':
                cursor.execute('DELETE FROM sales WHERE sale_id = ?', (sale_id,))
                conn.commit()
                print("✅ Sale deleted successfully.")
            else:
                print("❌ Deletion cancelled.")
        else:
            print("❌ Sale not found.")
    except Exception as e:
        print(f"❌ Error deleting sale: {e}")

def displaySalesData(date_start, date_end, product_name=None):
    """Display sales within a date range, optionally filtered by product."""
    try:
        query = 'SELECT * FROM sales WHERE sale_date BETWEEN ? AND ?'
        params = [date_start, date_end]
        if product_name:
            query += ' AND product_name = ?'
            params.append(product_name)

        cursor.execute(query, params)
        sales = cursor.fetchall()

        if not sales:
            print("⚠️ No sales found for the specified criteria.")
            return

        print("\n📋 Sales Data:")
        for sale in sales:
            print(f"ID: {sale[0]}, Product: {sale[1]}, Qty: {sale[2]}, Date: {sale[3]}, Price: ${sale[4]:.2f}")
    except Exception as e:
        print(f"❌ Error displaying sales data: {e}")

def exportSalesData(date_start, date_end, product_name=None, format='csv'):
    """Export sales data to CSV file."""
    try:
        query = 'SELECT * FROM sales WHERE sale_date BETWEEN ? AND ?'
        params = [date_start, date_end]
        if product_name:
            query += ' AND product_name = ?'
            params.append(product_name)

        cursor.execute(query, params)
        sales = cursor.fetchall()

        filename = 'sales_export_' + datetime.now().strftime('%Y%m%d_%H%M%S') + '.csv'
        with open(filename, mode='w', newline='', encoding='utf-8') as file:
            writer = csv.writer(file)
            writer.writerow(['Sale ID', 'Product Name', 'Quantity', 'Sale Date', 'Price'])
            writer.writerows(sales)
        print(f"✅ Sales data exported to '{filename}'")
    except Exception as e:
        print(f"❌ Export failed: {e}")

def main():
    while True:
        print("\n" + "="*30)
        print("🛒 Sales Management System")
        print("="*30)
        print("1. View Sales by Product")
        print("2. Add New Sale")
