# Convert SQL query to Elasticsearch DSL query

import sqlparse
import json

def convert_sql_to_elasticsearch(sql_input):
    try:
        parsed_statements = sqlparse.parse(sql_input)
        if not parsed_statements:
            raise ValueError("Empty or invalid SQL input")

        main_statement = parsed_statements[0]
        es_result = {}

        # Extract selected fields
        selected_tokens = [t for t in main_statement.tokens if isinstance(t, (sqlparse.sql.IdentifierList, sqlparse.sql.Identifier))]
        field_list = []
        if selected_tokens and hasattr(selected_tokens[0], 'tokens'):
            for item in selected_tokens[0].tokens:
                if isinstance(item, sqlparse.sql.Identifier):
                    field_list.append(item.value)
        es_result['_source'] = field_list

        # Extract index name from FROM clause
        table_tokens = [t for t in main_statement.tokens if isinstance(t, sqlparse.sql.Identifier) and t.value.lower() != 'from']
        if table_tokens:
            es_result['index'] = table_tokens[0].value

        # Process WHERE conditions
        where_tokens = [t for t in main_statement.tokens if isinstance(t, sqlparse.sql.Where)]
        if where_tokens:
            es_result['query'] = {'bool': {'must': []}}
            parsed_conditions = extract_where_conditions(where_tokens[0])
            es_result['query']['bool']['must'].extend(parsed_conditions)

        # Handle GROUP BY clause
        group_by_tokens = [t for t in main_statement.tokens if isinstance(t, sqlparse.sql.Token) and t.value.lower() == 'group by']
        if group_by_tokens:
            aggregation_config = build_grouping_aggregation(main_statement)
            es_result['aggs'] = aggregation_config

        # Handle HAVING clause
        having_tokens = [t for t in main_statement.tokens if isinstance(t, sqlparse.sql.Token) and t.value.lower() == 'having']
        if having_tokens:
            filter_conditions = extract_having_conditions(main_statement)
            if 'query' not in es_result:
                es_result['query'] = {'bool': {}}
            if 'bool' not in es_result['query']:
                es_result['query']['bool'] = {}
            es_result['query']['bool']['filter'] = filter_conditions

        return json.dumps(es_result, indent=4)
    except Exception as error:
        return f"Error: {str(error)}"

def extract_where_conditions(where_part):
    condition_list = []
    for token in where_part.tokens:
        if isinstance(token, sqlparse.sql.Comparison):
            condition_list.append(analyze_comparison(token))
        elif isinstance(token, sqlparse.sql.Token) and token.value.lower() in ('and', 'or'):
            condition_list.append(token.value.lower())
    return condition_list

def analyze_comparison(expr):
    left_operand = expr.left.value
    right_operand = expr.right.value
    op_token = expr.token_next(0, skip_cm=True)
    operator = op_token.value if op_token else '='

    if operator == '=':
        return {'term': {left_operand: right_operand}}
    elif operator == '!=':
        return {'bool': {'must_not': {'term': {left_operand: right_operand}}}}
    elif operator in ('>', '<', '>=', '<='):
        return {'range': {left_operand: {operator: right_operand}}}
    elif operator.lower() == 'like':
        return {'wildcard': {left_operand: right_operand}}
    elif operator.lower() == 'in':
        identifiers = list(expr.right.get_identifiers()) if hasattr(expr.right, 'get_identifiers') else []
        values = [val.value for val in identifiers]
        return {'terms': {left_operand: values}}
    else:
        raise ValueError(f"Unsupported operator: {operator}")

def build_grouping_aggregation(statement):
    grouping_config = {}
    for idx, token in enumerate(statement.tokens):
        if isinstance(token, sqlparse.sql.Token) and token.value.lower() == 'group by':
            next_token = statement.tokens[idx + 1] if idx + 1 < len(statement.tokens) else None
            if next_token and hasattr(next_token, 'get_identifiers'):
                grouped_fields = [f.value for f in next_token.get_identifiers()]
                grouping_config = {'by_field': {}}
                for field in grouped_fields:
                    grouping_config['by_field'][field] = {'terms': {'field': field}}
            break
    return grouping_config

def extract_having_conditions(statement):
    filter_conditions = []
    for token in statement.tokens:
        if isinstance(token, sqlparse.sql.Token) and token.value.lower() == 'having':
            filter_conditions = extract_where_conditions(token)
            break
    return filter_conditions

# Example usage
sql_input = """
SELECT name, age
FROM users
WHERE age > 25 AND name LIKE 'J%'
GROUP BY name
HAVING COUNT(name) > 1
"""

es_output = convert_sql_to_elasticsearch(sql_input)
print(es_output)

import json
import os

class CostCenterController:
    def __init__(self, data_file='data/cost_centers.json'):
        self.data_file = data_file
        self.entries = self._fetch_entries()
        if not self.entries:
            self.next_identifier = 1
        else:
            self.next_identifier = max(int(entry['identifier']) for entry in self.entries) + 1

    def _fetch_entries(self):
        if os.path.isfile(self.data_file):
            try:
                with open(self.data_file, 'r') as f:
                    return json.load(f)
            except (json.JSONDecodeError, IOError):
                return []
        return []

    def _persist_entries(self):
        with open(self.data_file, 'w') as f:
            json.dump(self.entries, f, indent=4)

    def _validate_entry_fields(self, project_title, labels, current_status):
        if len(project_title) > 50 or len(labels) > 50:
            raise ValueError("Project title and labels must each be under 50 characters.")
        if current_status not in ['active', 'inactive']:
            raise ValueError("Status must be either 'active' or 'inactive'.")

    def _verify_admin_access(self, requester, label):
        if label == 'admin_only' and requester != 'admin':
            raise PermissionError("Access denied: only admin users can handle entries marked 'admin_only'.")

    def create_entry(self, requester, project_title, labels, current_status):
        self._validate_entry_fields(project_title, labels, current_status)
        self._verify_admin_access(requester, labels)

        new_entry = {
            'identifier': self.next_identifier,
            'project_title': project_title,
            'labels': labels,
            'current_status': current_status
        }
        self.entries.append(new_entry)
        self._persist_entries()
        self.next_identifier += 1
        return new_entry

    def modify_entry(self, requester, entry_id, project_title=None, labels=None, current_status=None):
        target_entry = next((entry for entry in self.entries if entry['identifier'] == entry_id), None)
        if target_entry is None:
            raise ValueError(f"No entry found with identifier {entry_id}.")

        if labels:
            self._verify_admin_access(requester, labels)

        if project_title:
            self._validate_entry_fields(project_title, target_entry['labels'], target_entry['current_status'])
            target_entry['project_title'] = project_title

        if labels:
            self._validate_entry_fields(target_entry['project_title'], labels, target_entry['current_status'])
            target_entry['labels'] = labels

        if current_status:
            self._validate_entry_fields(target_entry['project_title'], target_entry['labels'], current_status)
            target_entry['current_status'] = current_status

        self._persist_entries()
        return target_entry

    def remove_entry(self, requester, entry_id):
        target_entry = next((entry for entry in self.entries if entry['identifier'] == entry_id), None)
        if target_entry is None:
            raise ValueError(f"No entry found with identifier {entry_id}.")

        self._verify_admin_access(requester, target_entry['labels'])

        self.entries.remove(target_entry)
        self._persist_entries()
        return target_entry

# Demonstration usage:
if __name__ == "__main__":
    controller = CostCenterController()

    # Create a new cost center entry
    created = controller.create_entry('admin', 'Project Alpha', 'admin_only', 'active')
    print("Created Entry:", created)

    # Modify an existing entry
    modified = controller.modify_entry('admin', created['identifier'], project_title='Project Beta', labels='public', current_status='inactive')
    print("Modified Entry:", modified)

    # Remove an entry
    removed = controller.remove_entry('admin', created['identifier'])
    print("Removed Entry:", removed)

