# Generate a list of dictionaries with optional nested structures

import uuid

def create_dict_list(count, input_keys=None, input_values=None, use_nested=False):
    # Set default empty lists if inputs are None
    input_keys = input_keys if input_keys is not None else []
    input_values = input_values if input_values is not None else []

    # Remove duplicates while preserving order
    distinct_keys = []
    for k in input_keys:
        if k not in distinct_keys:
            distinct_keys.append(k)

    distinct_values = []
    for v in input_values:
        if v not in distinct_values:
            distinct_values.append(v)

    output = []

    # Create dictionaries using unique keys
    for key_item in distinct_keys:
        if len(output) >= count:
            break
        inner_structure = {str(uuid.uuid4()): None} if use_nested else {}
        output.append({key_item: inner_structure})

    # Create dictionaries using unique values
    for idx, val in enumerate(distinct_values):
        if len(output) >= count:
            break
        if val is not None:
            inner_structure = {idx: val}
        else:
            inner_structure = {str(uuid.uuid4()): None}

        if use_nested and not inner_structure:
            inner_structure = {str(uuid.uuid4()): None}

        output.append({str(uuid.uuid4()): inner_structure})

    # Fill remaining slots with random-key dictionaries
    while len(output) < count:
        outer_key = str(uuid.uuid4())
        inner_structure = {str(uuid.uuid4()): None} if use_nested else {}
        output.append({outer_key: inner_structure})

    return output

