import time

def validate_quadruplet(x1, x2, x3, x4):
    """
    Determine if four numbers satisfy the Pythagorean quadruplet condition.
    """
    return x1 * x1 + x2 * x2 + x3 * x3 == x4 * x4

def search_for_quadruplet(target_sum):
    """
    Search for a valid Pythagorean quadruplet that sums to target_sum.

    :param target_sum: The desired total sum of the quadruplet.
    :return: A list [x1, x2, x3, x4] if found, else None.
    """
    for x1 in range(1, target_sum):
        remaining_after_x1 = target_sum - x1
        for x2 in range(x1, remaining_after_x1):
            remaining_after_x2 = remaining_after_x1 - x2
            for x3 in range(x2, remaining_after_x2):
                x4 = remaining_after_x2 - x3
                if x4 > x3 and validate_quadruplet(x1, x2, x3, x4):
                    return [x1, x2, x3, x4]
    return None

def execute_search(target_sum):
    """
    Execute the search for a Pythagorean quadruplet with timing and output results.

    :param target_sum: The target sum for the quadruplet.
    """
    if not isinstance(target_sum, int):
        raise TypeError("Input must be an integer.")

    start = time.time()

    result = search_for_quadruplet(target_sum)

    end = time.time()
    duration = end - start

    if result:
        x1, x2, x3, x4 = result
        print(f"Discovered Pythagorean quadruplet: {result}")
        print(f"Verification: {x1}² + {x2}² + {x3}² = {x4}²")
        print(f"Total: {x1} + {x2} + {x3} + {x4} = {target_sum}")
    else:
        print("No valid Pythagorean quadruplet exists for the specified sum.")

    print(f"Processing time: {duration:.6f} seconds")

