# Alternative implementation to find mathematical expressions that evaluate to a target value

import itertools
import math
from typing import List, Tuple, Optional

def find_matching_expression(values: List[int], goal: int, permit_repeats: bool) -> Tuple[str, int]:
    def safe_eval(expression: str) -> float:
        try:
            return eval(expression)
        except ZeroDivisionError:
            return float('inf')
        except (SyntaxError, ValueError, OverflowError):
            return float('nan')

    def expression_is_valid(expr: str) -> bool:
        try:
            eval(expr)
            return True
        except:
            return False

    def construct_expressions(nums: List[int], goal: int, depth_limit: int) -> Tuple[str, int]:
        if not nums:
            return "", -1

        # Generate unique permutations if duplicates are not allowed
        all_perms = list(itertools.permutations(nums))
        if not permit_repeats:
            unique_perms = set()
            for perm in all_perms:
                unique_perms.add(perm)
            all_perms = list(unique_perms)

        # Define available operations
        ops_list = ['+', '-', '*', '/', '**', 'math.log']

        # Try different combinations of numbers and operations
        for current_perm in all_perms:
            for op_count in range(1, depth_limit + 1):
                for op_combo in itertools.product(ops_list, repeat=op_count):
                    expr_parts = [str(current_perm[0])]
                    num_consumed = 1

                    for j, operation in enumerate(op_combo):
                        if num_consumed >= len(current_perm):
                            break

                        if operation == 'math.log':
                            base_val = current_perm[num_consumed]
                            if base_val > 0 and base_val != 1:
                                expr_parts.append(f" {operation}({base_val})")
                                num_consumed += 1
                            else:
                                break
                        else:
                            expr_parts.append(f" {operation} {current_perm[num_consumed]}")
                            num_consumed += 1

                    full_expr = "".join(expr_parts)

                    if expression_is_valid(full_expr):
                        computed_value = safe_eval(full_expr)
                        if math.isclose(computed_value, goal, rel_tol=1e-9):
                            return full_expr, op_count

        return "", -1

    # Limit the search depth to prevent excessive computation
    max_depth = 5
    result_expr, op_count = construct_expressions(values, goal, max_depth)
    return result_expr, op_count

