import sys
import json
from pypdf import PdfReader

def extract_field_identifier(annotation):
    path_components = []
    current_annotation = annotation
    while current_annotation:
        name = current_annotation.get('/T')
        if name:
            path_components.append(name)
        current_annotation = current_annotation.get('/Parent')
    return ".".join(reversed(path_components)) if path_components else None

def build_field_descriptor(field, full_id):
    descriptor = {"field_id": full_id}
    field_type = field.get('/FT')

    if field_type == "/Tx":
        descriptor["type"] = "text"
    elif field_type == "/Btn":
        descriptor["type"] = "checkbox"
        states = field.get("/_States_", [])
        if len(states) == 2:
            if "/Off" in states:
                checked_state = [s for s in states if s != "/Off"][0]
                descriptor["checked_value"] = checked_state
                descriptor["unchecked_value"] = "/Off"
            else:
                print(f"Warning: unexpected checkbox states for '{full_id}'. Values may be incorrect.")
                descriptor["checked_value"] = states[0]
                descriptor["unchecked_value"] = states[1]
        else:
            descriptor["checked_value"] = states[0] if states else ""
            descriptor["unchecked_value"] = "/Off"
    elif field_type == "/Ch":
        descriptor["type"] = "choice"
        options = field.get("/_States_", [])
        descriptor["choice_options"] = [
            {"value": opt[0], "text": opt[1]} for opt in options
        ]
    else:
        descriptor["type"] = f"unknown ({field_type})"

    return descriptor

def collect_form_fields(reader: PdfReader):
    raw_fields = reader.get_fields()
    processed_fields = {}
    potential_radio_groups = set()

    # First pass: process direct fields (skip containers unless they're radio groups)
    for field_name, field_data in raw_fields.items():
        kids = field_data.get("/Kids")
        if kids:
            if field_data.get('/FT') == "/Btn":
                potential_radio_groups.add(field_name)
            continue
        processed_fields[field_name] = build_field_descriptor(field_data, field_name)

    # Second pass: locate annotations and handle radio buttons
    radio_details = {}
    for page_idx, page in enumerate(reader.pages):
        annotations = page.get('/Annots', [])
        for annot in annotations:
            field_path = extract_field_identifier(annot)

            if field_path in processed_fields:
                processed_fields[field_path]["page"] = page_idx + 1
                processed_fields[field_path]["rect"] = annot.get('/Rect')
            elif field_path in potential_radio_groups:
                try:
                    appearance = annot["/AP"]["/N"]
                    active_states = [state for state in appearance if state != "/Off"]
                except KeyError:
                    continue

                if len(active_states) == 1:
                    rect = annot.get("/Rect")
                    if field_path not in radio_details:
                        radio_details[field_path] = {
                            "field_id": field_path,
                            "type": "radio_group",
                            "page": page_idx + 1,
                            "radio_options": [],
                        }

                    radio_details[field_path]["radio_options"].append({
                        "value": active_states[0],
                        "rect": rect,
                    })

    # Filter out fields without location info
    valid_fields = []
    for field_desc in processed_fields.values():
        if "page" in field_desc:
            valid_fields.append(field_desc)
        else:
            print(f"Warning: field '{field_desc.get('field_id')}' has no position info; skipping")

    # Combine with radio button data
    all_fields = valid_fields + list(radio_details.values())

    # Sort by page number, then vertical position (inverted), then horizontal position
    def ordering_key(field):
        if "radio_options" in field:
            r = field["radio_options"][0]["rect"] or [0, 0, 0, 0]
        else:
            r = field.get("rect") or [0, 0, 0, 0]
        y_pos = -r[1]  # Invert Y for PDF coordinate system
        return [field.get("page", 0), y_pos, r[0]]

    all_fields.sort(key=ordering_key)
    return all_fields

def export_field_data(pdf_file: str, output_json: str):
    pdf_reader = PdfReader(pdf_file)
    field_list = collect_form_fields(pdf_reader)

    with open(output_json, "w") as out_file:
        json.dump(field_list, out_file, indent=2)

    print(f"Exported {len(field_list)} form fields to {output_json}")

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python extract_form_fields.py <input_pdf> <output_json>")
        sys.exit(1)

    export_field_data(sys.argv[1], sys.argv[2])

