def _convert_to_list(input_val: Any) -> List[int]:
    """Convert various input types to a list of integers."""
    if isinstance(input_val, list):
        return [int(x) for x in input_val]
    elif isinstance(input_val, range):
        return list(input_val)
    else:
        return [int(input_val)]


def _parse_bucket_line(line_content: str) -> Tuple[List[int], List[int], List[int]]:
    """Safely parse a bucket definition line using restricted eval context."""
    try:
        parsed = eval(line_content, {"__builtins__": {}}, {"range": range})
        if not isinstance(parsed, tuple) or len(parsed) != 3:
            raise ValueError("Expected a 3-element tuple")
        return tuple(_convert_to_list(part) for part in parsed)
    except Exception as err:
        logger.warning(f"Failed to parse bucket line '{line_content}': {err}")
        raise


def _categorize_buckets(prompt_buckets: List[Tuple[int, int, int]], 
                        decode_buckets: List[Tuple[int, int, int]],
                        x_val: int, y_val: int, z_val: int) -> None:
    """Append bucket to appropriate list based on y value (1 for decode, else prompt)."""
    if y_val == 1:
        decode_buckets.append((x_val, y_val, z_val))
    else:
        prompt_buckets.append((x_val, y_val, z_val))


class FileBucketingStrategy:
    def get_buckets(self, file_path: str, is_prompt: bool) -> List[Tuple[int, int, int]]:
        """Load and categorize buckets from a configuration file."""
        prompt_buckets = []
        decode_buckets = []

        with open(file_path, 'r') as config_file:
            for raw_line in config_file:
                line = raw_line.strip()

                # Skip empty lines and comments
                if not line or line.startswith('#'):
                    continue

                try:
                    x_vals, y_vals, z_vals = _parse_bucket_line(line)
                except ValueError:
                    continue

                # Generate all combinations and categorize
                for x, y, z in ((int(x), int(y), int(z)) 
                               for x in x_vals 
                               for y in y_vals 
                               for z in z_vals):
                    _categorize_buckets(prompt_buckets, decode_buckets, x, y, z)

        # Return sorted result based on requested type
        return sorted(prompt_buckets) if is_prompt else sorted(decode_buckets)

