import librosa.filters
import numpy as np
from scipy import signal
from scipy.io import wavfile
from src.utils.hparams import hparams as hp


def load_audio(filepath, target_sample_rate):
    """Load audio file and return normalized waveform."""
    return librosa.core.load(filepath, sr=target_sample_rate)[0]


def write_wav_to_file(audio_data, output_path, sample_rate):
    """Write audio data to WAV file after scaling to int16 range."""
    peak_amplitude = max(0.01, np.max(np.abs(audio_data)))
    scaled_audio = audio_data * (32767 / peak_amplitude)
    wavfile.write(output_path, sample_rate, scaled_audio.astype(np.int16))


def write_wavenet_audio(audio_signal, save_path, sampling_rate):
    """Write audio using librosa's built-in writer (for Wavenet compatibility)."""
    librosa.output.write_wav(save_path, audio_signal, sr=sampling_rate)


def apply_preemphasis(signal_wave, coefficient=0.97, enabled=True):
    """Apply pre-emphasis filter if enabled."""
    if not enabled:
        return signal_wave
    return signal.lfilter([1, -coefficient], [1], signal_wave)


def invert_preemphasis(signal_wave, coefficient=0.97, enabled=True):
    """Invert pre-emphasis filter if previously applied."""
    if not enabled:
        return signal_wave
    return signal.lfilter([1], [1, -coefficient], signal_wave)


def compute_hop_length():
    """Determine hop size either from config or derive from frame shift."""
    configured_hop = hp.hop_size
    if configured_hop is None:
        assert hp.frame_shift_ms is not None, "frame_shift_ms must be set when hop_size is None"
        configured_hop = int(hp.frame_shift_ms / 1000 * hp.sample_rate)
    return configured_hop


def compute_linear_spectrogram(waveform):
    """Generate linear spectrogram from waveform."""
    stft_output = _compute_stft(apply_preemphasis(waveform, hp.preemphasis, hp.preemphasize))
    magnitude_spectrum = np.abs(stft_output)
    db_spectrum = _amplitude_to_decibel(magnitude_spectrum) - hp.ref_level_db

    return _apply_normalization_if_enabled(db_spectrum)


def compute_mel_spectrogram(waveform):
    """Generate mel-scaled spectrogram from waveform."""
    stft_output = _compute_stft(apply_preemphasis(waveform, hp.preemphasis, hp.preemphasize))
    magnitude_spectrum = np.abs(stft_output)
    mel_matrix = _get_mel_filterbank()
    mel_spectrum = np.dot(mel_matrix, magnitude_spectrum)
    db_mel = _amplitude_to_decibel(mel_spectrum) - hp.ref_level_db

    return _apply_normalization_if_enabled(db_mel)


def _get_lws_instance():
    """Create LWS processor instance if enabled."""
    import lws
    return lws.lws(hp.n_fft, compute_hop_length(), fftsize=hp.win_size, mode="speech")


def _compute_stft(y):
    """Compute STFT using either LWS or librosa backend."""
    if hp.use_lws:
        return _get_lws_instance().stft(y).T
    else:
        return librosa.stft(y=y, n_fft=hp.n_fft, hop_length=compute_hop_length(),
                            win_length=hp.win_size)


def count_spectrogram_frames(signal_length, window_size, hop_size):
    """Estimate number of frames in spectrogram given signal length."""
    padding = window_size - hop_size
    total_effective_len = signal_length + 2 * padding
    if signal_length % hop_size == 0:
        num_frames = (total_effective_len - window_size) // hop_size + 1
    else:
        num_frames = (total_effective_len - window_size) // hop_size + 2
    return num_frames


def compute_padding_bounds(signal_array, window_size, hop_size):
    """Calculate left/right padding needed for full coverage."""
    frame_count = count_spectrogram_frames(len(signal_array), window_size, hop_size)
    pad_amount = window_size - hop_size
    extended_length = len(signal_array) + 2 * pad_amount
    right_extra = (frame_count - 1) * hop_size + window_size - extended_length
    return pad_amount, pad_amount + right_extra


def librosa_style_padding(signal_array, window_size, hop_size):
    """Return padding values matching librosa's default behavior."""
    last_frame_index = (signal_array.shape[0] // hop_size)
    required_length = (last_frame_index + 1) * hop_size
    right_pad = required_length - signal_array.shape[0]
    return 0, right_pad


# Mel conversion utilities
_mel_basis_cache = None


def _get_mel_filterbank():
    """Build or retrieve cached mel filterbank matrix."""
    global _mel_basis_cache
    if _mel_basis_cache is None:
        assert hp.fmax <= hp.sample_rate // 2, "fmax exceeds Nyquist frequency"
        _mel_basis_cache = librosa.filters.mel(
            sr=hp.sample_rate,
            n_fft=hp.n_fft,
            n_mels=hp.num_mels,
            fmin=hp.fmin,
            fmax=hp.fmax
        )
    return _mel_basis_cache


def _amplitude_to_decibel(amplitude_values):
    """Convert amplitude to decibel scale."""
    min_amp = np.exp(hp.min_level_db / 20 * np.log(10))
    clipped = np.maximum(min_amp, amplitude_values)
    return 20 * np.log10(clipped)


def _decibel_to_amplitude(decibel_values):
    """Convert decibel back to linear amplitude."""
    return np.power(10.0, decibel_values * 0.05)


def _apply_normalization_if_enabled(spectral_data):
    """Conditionally normalize spectrogram based on hyperparameters."""
    if not hp.signal_normalization:
        return spectral_data
    return _normalize_spectrogram(spectral_data)


def _normalize_spectrogram(spectrogram):
    """Normalize spectrogram to [-max_abs_value, max_abs_value] or [0, max_abs_value]."""
    if hp.allow_clipping_in_normalization:
        if hp.symmetric_mels:
            normalized = (2 * hp.max_abs_value) * ((spectrogram - hp.min_level_db) / (-hp.min_level_db)) - hp.max_abs_value
            return np.clip(normalized, -hp.max_abs_value, hp.max_abs_value)
        else:
            normalized = hp.max_abs_value * ((spectrogram - hp.min_level_db) / (-hp.min_level_db))
            return np.clip(normalized, 0, hp.max_abs_value)

    # Without clipping: verify input validity first
    assert spectrogram.max() <= 0 and spectrogram.min() - hp.min_level_db >= 0, \
        "Input spectrogram out of expected range"

    if hp.symmetric_mels:
        return (2 * hp.max_abs_value) * ((spectrogram - hp.min_level_db) / (-hp.min_level_db)) - hp.max_abs_value
    else:
        return hp.max_abs_value * ((spectrogram - hp.min_level_db) / (-hp.min_level_db))


def _denormalize_spectrogram(normalized_spectrogram):
    """Reverse normalization to recover original dB-scale spectrogram."""
    if hp.allow_clipping_in_normalization:
        clipped = np.clip(normalized_spectrogram, -hp.max_abs_value, hp.max_abs_value)
        if hp.symmetric_mels:
            denorm = (((clipped + hp.max_abs_value) * -hp.min_level_db) / (2 * hp.max_abs_value)) + hp.min_level_db
        else:
            denorm = ((np.clip(normalized_spectrogram, 0, hp.max_abs_value) * -hp.min_level_db) / hp.max_abs_value) + hp.min_level_db
        return denorm

    if hp.symmetric_mels:
        return (((normalized_spectrogram + hp.max_abs_value) * -hp.min_level_db) / (2 * hp.max_abs_value)) + hp.min_level_db
    else:
        return ((normalized_spectrogram * -hp.min_level_db) / hp.max_abs_value) + hp.min_level_db

