import sys
import re
import pathlib

# Define detection patterns for suspicious activities
exfil_patterns = [r"http[s]?://", r"webhook", r"pastebin", r"ngrok", r"tunnel", r"request\.bin", r"discordapp"]
file_access_patterns = [r"\.env", r"\.ssh", r"/etc/", r"credentials", r"token", r"apikey", r"private"]
shell_execution_patterns = [r"curl .*\| bash", r"chmod \+x", r"sudo", r"rm -rf"]

# Organize pattern categories with descriptive labels
pattern_categories = [
    ("DATA_EXFILTRATION", exfil_patterns),
    ("SENSITIVE_FILES", file_access_patterns),
    ("COMMAND_EXECUTION", shell_execution_patterns)
]

# Initialize risk assessment variables
risk_level = 0
detected_issues = []

# Validate input path
input_file_path = pathlib.Path(sys.argv[1]) if len(sys.argv) > 1 else None
if not input_file_path or not input_file_path.is_file():
    print("Usage: python audit.py path/to/skill.md", file=sys.stderr)
    sys.exit(1)

# Read and process file content
content = input_file_path.read_text(errors="ignore")
line_list = content.splitlines()

# Analyze each line for potential security issues
for line_index, current_line in enumerate(line_list, start=1):
    normalized_line = current_line.lower()

    for category_name, regex_list in pattern_categories:
        for pattern in regex_list:
            if re.search(pattern, normalized_line):
                detected_issues.append({
                    "line_number": line_index,
                    "category": category_name,
                    "context": current_line.strip()[:200]
                })

                # Assign risk points based on severity
                if category_name == "DATA_EXFILTRATION":
                    risk_level += 3
                elif category_name == "SENSITIVE_FILES":
                    risk_level += 2
                else:
                    risk_level += 1

# Determine overall risk level
if risk_level >= 6:
    threat_level = "HIGH"
elif risk_level >= 3:
    threat_level = "MEDIUM"
else:
    threat_level = "LOW"

# Output results
print(f"RISK: {threat_level}\n")

if detected_issues:
    for issue in detected_issues:
        print(f"- [{issue['category']}] line {issue['line_number']}: {issue['context']}")
else:
    print("No obvious red flags. Manual review still recommended.")

