# Custom dictionary wrapper with attribute-style access and nested support
class ConfigWrapper:
    def __init__(self, data):
        self._storage = data

    def __getattr__(self, attr_name):
        try:
            result = self._storage[attr_name]
            # Convert nested dictionaries to ConfigWrapper instances recursively
            if isinstance(result, dict):
                return ConfigWrapper(result)
            return result
        except KeyError as err:
            raise AttributeError(f"Configuration has no key '{attr_name}'") from err

    def __getitem__(self, item_key):
        return self._storage[item_key]

    def __contains__(self, item_key):
        return item_key in self._storage

    def fetch(self, item_key, fallback=None):
        """Retrieve value using key with optional default (like dict.get)."""
        return self._storage.get(item_key, fallback)

    def __repr__(self):
        return repr(self._storage)


# Manager class for storing and accessing components by name
class ComponentRegistry:
