import json

def FormatApiError(error_msg: str):
    return "API Error: " + error_msg

def ProcessVolcResponse(api_response: dict):
    if not api_response:
        return FormatApiError("Empty response")

    # Handle both dict and string representations of JSON
    parsed_data = api_response
    if isinstance(api_response, str):
        try:
            parsed_data = json.loads(api_response)
        except json.JSONDecodeError:
            return FormatApiError("Invalid JSON response")

    # Check for error information in the response
    error_info = parsed_data.get("ResponseMetadata", {}).get("Error")

    if error_info and isinstance(error_info, dict):
        error_message = error_info.get("Message", "Unknown error")
        return FormatApiError(error_message)

    return str(parsed_data)

# AutoRepaySetting class implementation - Type III clone
class RepaymentConfiguration:
    def __init__(self, repayment_status=None, config_instance=None):
        # Initialize with optional status and configuration
        if config_instance is None:
            from gate_api.configuration import Configuration
            config_instance = Configuration()

        self.configuration = config_instance
        self._repayment_state = None
        self.field_map = {}

        if repayment_status is not None:
            self.repayment_state = repayment_status

    @property
    def repayment_state(self):
        """Get the current repayment configuration state"""
        return self._repayment_state

    @repayment_state.setter
    def repayment_state(self, new_state):
        """Set the repayment configuration state with validation"""
        valid_states = ["on", "off"]

        if (hasattr(self.configuration, 'client_side_validation') and 
            self.configuration.client_side_validation and 
            new_state not in valid_states):
            raise ValueError(
                f"Invalid value for `repayment_state` ({new_state}), "
                f"must be one of {valid_states}"
            )

        self._repayment_state = new_state

    def as_dictionary(self):
        """Convert object to dictionary representation"""
        output = {}
        type_mapping = {
            'status': 'str'
        }

        for field_name, _ in type_mapping.items():
            attr_value = getattr(self, '_' + field_name, None)

            if isinstance(attr_value, list):
                output[field_name] = [
                    item.as_dictionary() if hasattr(item, 'as_dictionary') else item
                    for item in attr_value
                ]
            elif hasattr(attr_value, 'as_dictionary'):
                output[field_name] = attr_value.as_dictionary()
            elif isinstance(attr_value, dict):
                output[field_name] = {
                    k: v.as_dictionary() if hasattr(v, 'as_dictionary') else v
                    for k, v in attr_value.items()
                }
            else:
                output[field_name] = attr_value

        return output

    def __str__(self):
        """String representation using pprint formatting"""
        import pprint
        return pprint.pformat(self.as_dictionary())

    def __repr__(self):
        """Official string representation"""
        return self.__str__()

    def __eq__(self, other):
        """Check equality with another object"""
        if not isinstance(other, RepaymentConfiguration):
            return False
        return self.as_dictionary() == other.as_dictionary()

    def __ne__(self, other):
        """Check inequality with another object"""
        if not isinstance(other, RepaymentConfiguration):
            return True
        return self.as_dictionary() != other.as_dictionary()

