def upgrade(connection):
    # Check if required columns exist by attempting to query them
    try:
        connection.execute("SELECT role FROM group_members LIMIT 0")
    except:
        connection.execute("ALTER TABLE group_members ADD COLUMN role TEXT DEFAULT 'member'")

    try:
        connection.execute("SELECT joined_at FROM group_members LIMIT 0")
    except:
        connection.execute("ALTER TABLE group_members ADD COLUMN joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP")

    connection.commit()

