import torch, os

class TensorWrapper:
    def __init__(self, tensor_data):
        self.tensor_data = tensor_data

    def shape(self):
        return list(self.tensor_data.shape)

class BinaryStateLoader:
    def __init__(self, file_path, target_device):
        print("Non-safetensors format detected; loading may be slower. Consider converting to safetensors for better performance.")
        self.parameters = torch.load(file_path, weights_only=True, map_location=target_device)

    def parameter_names(self):
        return self.parameters.keys()

    def load_tensor(self, key):
        return self.parameters[key]

    def slice_tensor(self, key):
        return TensorWrapper(self.parameters[key])

class StorageManager:
    def __init__(self, source_paths, compute_device, precision_type=None, mapping_transform=None, cache_limit=10**9):
        # Normalize input paths to list
        self.source_paths = source_paths if isinstance(source_paths, list) else [source_paths]
        self.target_device = compute_device
        self.precision = precision_type

        # Allow buffer size override via environment variable
        env_buffer = os.environ.get('DIFFSYNTH_DISK_MAP_BUFFER_SIZE')
        self.cache_limit = int(env_buffer) if env_buffer is not None else cache_limit

        self.storage_containers = []
        self.reset_storage()
        self.index_mapping = {}

        # Build name-to-file mapping
        for idx, container in enumerate(self.storage_containers):
            for param_name in container.parameter_names():
                self.index_mapping[param_name] = idx

        # Prepare optional renaming logic
        self.renaming_rules = self.generate_rename_map(mapping_transform)

    def reset_storage(self):
        if len(self.storage_containers) == 0:
            # Initial load of all files
            for path in self.source_paths:
                if path.endswith(".safetensors"):
                    self.storage_containers.append(safe_open(path, framework="pt", device=str(self.target_device)))
                else:
                    self.storage_containers.append(BinaryStateLoader(path, target_device=self.target_device))
        else:
            # Reload existing containers
            for i, path in enumerate(self.source_paths):
                if path.endswith(".safetensors"):
                    self.storage_containers[i] = safe_open(path, framework="pt", device=str(self.target_device))

        self.total_elements = 0

    def __getitem__(self, key):
        # Apply renaming if present
        if self.renaming_rules is not None:
            key = self.renaming_rules[key]

        # Locate the appropriate storage container
        container_id = self.index_mapping[key]
        value = self.storage_containers[container_id].load_tensor(key)

        # Apply dtype conversion if specified
        if self.precision is not None and isinstance(value, torch.Tensor):
            value = value.to(self.precision)

        # Ensure CPU tensors are cloned (avoid shared memory issues)
        if isinstance(value, torch.Tensor) and value.device.type == "cpu":
            value = value.clone()

        # Track total parameter count for buffer management
        if isinstance(value, torch.Tensor):
            self.total_elements += value.numel()

        # Flush storage if buffer limit exceeded
        if self.total_elements > self.cache_limit:
            self.reset_storage()

        return value

    def generate_rename_map(self, transform_func):
        if transform_func is None:
            return None

        # Collect current parameter names
        temp_dict = {}
        for container in self.storage_containers:
            for name in container.parameter_names():
                temp_dict[name] = name

        # Apply transformation function
        return transform_func(temp_dict)

    def __iter__(self):
        if self.renaming_rules is not None:
            return iter(self.renaming_rules)
        else:
            return iter(self.index_mapping)

    def __contains__(self, item):
        if self.renaming_rules is not None:
            return item in self.renaming_rules
        else:
            return item in self.index_mapping

# Function to mask sensitive network location info in a URL

from urllib.parse import urlparse, urlunparse

def hide_credentials_in_url(url_string):
    if not url_string:
        return url_string

    # Parse the URL into components
    parsed = urlparse(url_string)

    # Start building the masked netloc part
    host_part = parsed.hostname or ""
    if parsed.port:
        host_part += f":{parsed.port}"

    # If credentials exist, replace them with masked version
    if parsed.username or parsed.password:
        host_part = f"***:***@{host_part}"

    # Reconstruct the URL with masked netloc
    return urlunparse(parsed._replace(netloc=host_part))

# Parse telemetry data from a JSONL file and compute statistics

import sys
import json

def read_telemetry_file(filepath):
    """Generator that yields parsed JSON objects from a JSONL file."""
    with open(filepath, 'r', encoding='utf-8') as file:
        for line in file:
            stripped_line = line.strip()
            if not stripped_line:
                continue
            try:
                yield json.loads(stripped_line)
            except json.JSONDecodeError:
                # Skip malformed lines
                continue

def analyze_telemetry_data(file_path):
    """Analyze telemetry data and print summary statistics."""
    energies = []
    step_indices = []

    for record in read_telemetry_file(file_path):
        energy_value = record.get('E')
        if isinstance(energy_value, (int, float)):
            energies.append(float(energy_value))

        step_index = record.get('step_idx')
        if isinstance(step_index, int):
            step_indices.append(step_index)

    if not energies:
        print('no energy values found')
        return

    # Compute energy differences between consecutive points
    energy_differences = []
    for i in range(1, len(energies)):
        energy_differences.append(energies[i] - energies[i-1])

    # Count negative differences (indicating non-monotonic behavior)
    negative_count = 0
    for diff in energy_differences:
        if diff < 0:
            negative_count += 1

    # Calculate ratio of negative differences
    monotonic_ratio = (negative_count / len(energy_differences)) if energy_differences else float('nan')

    # Print summary statistics
    print(f'file: {file_path}')
    print(f'num_steps: {len(energies)}  minE: {min(energies):.6f}  finalE: {energies[-1]:.6f}  meanE: {sum(energies)/len(energies):.6f}')

    if energy_differences:
        diff_mean = sum(energy_differences) / len(energy_differences)
        print(f'dE: mean={diff_mean:.6f}  <0 fraction={monotonic_ratio:.3f}  first={energy_differences[0]:.6f}  last={energy_differences[-1]:.6f}')

    if step_indices:
        print(f'last step_idx: {step_indices[-1]}')

if __name__ == '__main__':
    if len(sys.argv) < 2:
        print('usage: parse_telemetry.py <path/to/telemetry.jsonl>')
        sys.exit(1)

