class BagelPostInfer:
    def __init__(self, config, llm_config):
        self.config = config
        self.moe_enabled = "Mo" in llm_config["layer_module"]

    def assign_scheduler(self, scheduler):
        self.scheduler = scheduler

    def process_input(self, weights, input_sequence, text_indices=None, vae_indices=None, processing_mode="und"):
        if self.moe_enabled:
            if processing_mode == "und":
                processed_seq = weights.norm.apply(input_sequence)
            elif processing_mode == "gen":
                processed_seq = torch.zeros_like(input_sequence)
                processed_seq[text_indices] = weights.norm.apply(input_sequence[text_indices])
                processed_seq[vae_indices] = weights.norm_moe_gen.apply(input_sequence[vae_indices])
            else:
                processed_seq = input_sequence
        else:
            processed_seq = weights.norm.apply(input_sequence)
        return processed_seq

    def convert_llm_to_vae(self, weights, feature_tensor):
        feature_tensor = feature_tensor.to(AI_DEVICE).to(torch.bfloat16)
        converted = weights.llm2vae.apply(feature_tensor)
        return converted

