# Cancel all open orders across multiple exchange interfaces

import blankly

def cancel_open_orders():
    exchange_list = [
        blankly.Alpaca(),
        blanky.Binance(),
        blankly.CoinbasePro(),
        blankly.Kucoin(),
        blankly.Oanda()
    ]

    for exchange in exchange_list:
        try:
            active_orders = exchange.interface.get_open_orders()
            for order in active_orders:
                order_id = order['id']
                symbol = order['symbol']
                print(f"Canceling {order_id} on {symbol}")
                exchange.interface.cancel_order(symbol, order_id)
        except Exception as error:
            print(error)
            continue

if __name__ == "__main__":
    cancel_open_orders()

