import random
from dataclasses import dataclass
from typing import List, Dict, Any
from training.dataset.vos_segment_loader import LazySegments

MAX_ATTEMPTS = 1000

@dataclass
class FrameObjectBatch:
    selected_frames: List[int]
    target_objects: List[int]

class VideoSampler:
    def __init__(self, order_frames=True):
        self.order_frames = order_frames

class UniformRandomSampler(VideoSampler):
    def __init__(
        self,
        frame_count,
        object_limit,
        backward_time_chance=0.0,
    ):
        self.frame_count = frame_count
        self.object_limit = object_limit
        self.backward_time_chance = backward_time_chance

    def sample(self, video_data, segmentation_provider, current_epoch=None):
        for attempt in range(MAX_ATTEMPTS):
            if len(video_data.frames) < self.frame_count:
                raise ValueError(
                    f"Cannot extract {self.frame_count} frames from video '{video_data.video_name}' "
                    f"which contains only {len(video_data.frames)} annotated frames."
                )

            # Randomly select starting point
            start_index = random.randint(0, len(video_data.frames) - self.frame_count)
            selected_frame_list = [
                video_data.frames[start_index + offset] 
                for offset in range(self.frame_count)
            ]

            # Optionally reverse temporal order
            if random.random() < self.backward_time_chance:
                selected_frame_list.reverse()

            # Determine visible objects in the first frame
            detected_ids = []
            first_frame_segments = segmentation_provider.load(selected_frame_list[0].frame_idx)

            if isinstance(first_frame_segments, LazySegments):
                # SA1BRawDataset-specific handling
                detected_ids = list(first_frame_segments.keys())
            else:
                for obj_id, mask in first_frame_segments.items():
                    if mask.any():  # Check if segment has non-zero pixels
                        detected_ids.append(obj_id)

            # Accept sample only if at least one object is visible
            if len(detected_ids) > 0:
                break

            if attempt >= MAX_ATTEMPTS - 1:
                raise RuntimeError("Failed to find any frame with visible objects after maximum retries")

        # Select subset of objects up to limit
        chosen_objects = random.sample(
            detected_ids,
            min(len(detected_ids), self.object_limit)
        )

        return FrameObjectBatch(
            selected_frames=[f.frame_idx for f in selected_frame_list],
            target_objects=chosen_objects
        )

class EvaluationSampler(VideoSampler):
    """
    VOS Sampler for evaluation: includes all frames and all objects in a video
    """
    def __init__(self):
        super().__init__()

    def sample(self, video_data, segmentation_provider, current_epoch=None):
        """
        Retrieves complete set of frames and objects for evaluation
        """
        if self.order_frames:
            # Sort frames chronologically by index
            ordered_frames = sorted(video_data.frames, key=lambda f: f.frame_idx)
        else:
            # Preserve original sequence
            ordered_frames = video_data.frames

        # Get all object IDs from first frame
        initial_frame_objects = segmentation_provider.load(ordered_frames[0].frame_idx).keys()

        if not initial_frame_objects:
            raise ValueError("First frame of video contains no annotated objects")

        return FrameObjectBatch(
            selected_frames=[f.frame_idx for f in ordered_frames],
            target_objects=list(initial_frame_objects)
        )

