class DataHandler:
    """Handles data encoding for network transfer"""

    @staticmethod
    def convert_to_transmittable_format(input_data):
        """Transform data into a safe transmission format"""
        # OBSFUCATION: Using Base64 to obscure content
        try:
            serialized = json.dumps(input_data)
            encoded_bytes = base64.b64encode(serialized.encode('utf-8'))
