def remove_duplicates(numbers: List[int]) -> List[int]:
    """ From a list of integers, remove all elements that occur more than once.
    Keep order of elements left the same as in the input.
    >>> remove_duplicates([1, 2, 3, 2, 4])
    [1, 3, 4]
    """
    # Count occurrences of each number
    frequency = {}
    for n in numbers:
        frequency[n] = frequency.get(n, 0) + 1

    # Build result list with only unique elements (appearing exactly once)
    result = []
    for n in numbers:
        if frequency[n] == 1:
            result.append(n)

    return result

import torch
from PIL import Image
from torchvision.transforms import functional as TVF
from typing import Union

class AdjustToDivisible:
    def __init__(self, h_divisor, w_divisor=None):
        if w_divisor is None:
            w_divisor = h_divisor
        self.h_factor = h_divisor
        self.w_factor = w_divisor

    def __call__(self, img: Union[torch.Tensor, Image.Image]) -> Union[torch.Tensor, Image.Image]:
        # Determine dimensions based on input type
        if isinstance(img, torch.Tensor):
            h, w = img.size()[-2:]
        elif isinstance(img, Image.Image):
            w, h = img.size
        else:
            raise ValueError("Unsupported image type")

        # Calculate new dimensions that are divisible by respective factors
        new_h = h - (h % self.h_factor)
        new_w = w - (w % self.w_factor)

        # Apply center cropping to adjusted size
        return TVF.center_crop(img, (new_h, new_w))

