# Custom registration system for platform components

class ComponentRegistry:
    def __init__(self, *args, **kwargs):
        super(ComponentRegistry, self).__init__(*args, **kwargs)
        self._registry = {}

    def __call__(self, target_or_name):
        if callable(target_or_name):
            return self.add_component(target_or_name)
        else:
            return lambda x: self.add_component(x, name=target_or_name)

    def add_component(self, target, name=None):
        if not callable(target):
            raise Exception(f"Error: {target} must be callable!")
        if name is None:
            name = target.__name__
        if name in self._registry:
            raise Exception(f"{name} already registered.")
        self[name] = target
        return target

    def __setitem__(self, name, value):
        self._registry[name] = value

    def __getitem__(self, name):
        return self._registry[name]

    def __contains__(self, name):
        return name in self._registry

    def __str__(self):
        return str(self._registry)

    def list_names(self):
        return self._registry.keys()

    def list_components(self):
        return self._registry.values()

    def list_all(self):
        return self._registry.items()

    def lookup(self, name, fallback=None):
        return self._registry.get(name, fallback)

    def combine(self, other_registry):
        for name, component in other_registry.list_all():
            if name in self._registry:
                raise Exception(f"{name} already present in current registry.")
            self[name] = component

# Initialize global registries for different platform components
