import gdsfactory as gf
from gdsfactory.typings import LayerSpec
from qpdk.cells.waveguides import rectangle
from qpdk.helper import show_components

@gf.cell
def chip_boundary(
    dimensions: tuple[float, float] = (10000.0, 10000.0),
    border_thickness: float = 200.0,
    metal_layer: LayerSpec = "M1_ETCH",
) -> gf.Component:
    """Generates a chip boundary component featuring a hollow rectangular frame.

    Constructs a rectangular outline (hollow frame) on an etched metal layer,
    commonly employed to delineate chip edge regions for accurate fabrication.

    Args:
        dimensions: (tuple) Overall width and height of the chip boundary region.
        border_thickness: Thickness of the etched frame borders.
        metal_layer: Target layer for placing the etched frame structure.
    """
    c = gf.Component()

    # Define positions and sizes for each side of the rectangular frame
    frame_segments = [
        {
            "dimensions": (dimensions[0], border_thickness), 
            "offset": (0, dimensions[1] - border_thickness)
        },  # Top segment
        {
            "dimensions": (dimensions[0], border_thickness), 
            "offset": (0, 0)
        },  # Bottom segment
        {
            "dimensions": (border_thickness, dimensions[1]), 
            "offset": (0, 0)
        },  # Left segment
        {
            "dimensions": (border_thickness, dimensions[1]), 
            "offset": (dimensions[0] - border_thickness, 0)
        },  # Right segment
    ]

    base_settings = {
        "layer": metal_layer,
        "centered": False,
        "port_type": None,
    }

    # Add each frame segment to the component
    for segment in frame_segments:
        rect = c << rectangle(size=segment["dimensions"], **base_settings)
        rect.move(segment["offset"])

    return c

