# A lightweight key-value storage system with automatic eviction of old entries
from collections import OrderedDict
from cosmos_rl.utils.logging import logger

class LRUStyleCache:
    """
    A memory-efficient dictionary-like structure that retains only the most recent
    entries up to a specified limit. Older entries are automatically discarded when
    the capacity is exceeded, mimicking an LRU (Least Recently Used) behavior.
    """
    def __init__(self, capacity=100000):
        self.capacity = capacity
        self.cache = OrderedDict()

    def _update_access(self, key):
        # Move accessed item to end to mark it as recently used
        value = self.cache.pop(key)
        self.cache[key] = value

    def put(self, key, value):
        # Remove existing entry if present before adding new one
        if key in self.cache:
            self.cache.pop(key)

        # Insert new entry at the end (most recent)
        self.cache[key] = value

        # Trim oldest entries if exceeding capacity
        while len(self.cache) > self.capacity:
            self.cache.popitem(last=False)  # Remove least recently used item

    def fetch(self, key, fallback=None):
        if key not in self.cache:
            return fallback

        self._update_access(key)
        return self.cache[key]

    def remove(self, key):
        del self.cache[key]

    def size(self):
        return len(self.cache)

    def has(self, key):
        return key in self.cache

    def retrieve(self, key, default=None):
        return self.fetch(key, default)

    def list_keys(self):
        return list(self.cache.keys())

    def list_values(self):
        return list(self.cache.values())

    def list_pairs(self):
        return list(self.cache.items())

    def __str__(self):
        return f"LRUStyleCache({list(self.cache.items())})"

class LightweightKVStore:
    """
    A minimalistic key-value store implementation using LRU-style caching.
    Designed for scenarios where Redis isn't available or needed — suitable for
    development, testing, or low-resource environments.
    """
    def __init__(self):
        self.backend = LRUStyleCache()

    async def assign(self, key: str, value: str):
        self.backend.put(key, value)
        logger.info(f"[LightweightKVStore] Assigned key '{key}' with value '{value}'")

    async def query(self, key: str):
        return self.backend.fetch(key)

