# Decorator to ensure only one instance of a class is created

def singleton(cls):
    _instances = {}
    def wrapper(*args, **kwargs):
        if cls not in _instances:
            _instances[cls] = cls(*args, **kwargs)
        return _instances[cls]
    return wrapper

import ctypes
import gc
import sys
import torch

def clone_tensor_if_shared(obj):
    # Clone tensor if it's shared memory, otherwise return as-is
    if isinstance(obj, torch.Tensor):
        return obj.clone() if obj.is_shared() else obj
    # Recursively process lists
    elif isinstance(obj, list):
        return [clone_tensor_if_shared(item) for item in obj]
    # Recursively process tuples
    elif isinstance(obj, tuple):
        return tuple(clone_tensor_if_shared(item) for item in obj)
    # Recursively process dictionaries
    elif isinstance(obj, dict):
        return {key: clone_tensor_if_shared(value) for key, value in obj.items()}
    # Return other objects unchanged
    else:
        return obj

def force_decrement_ref(tensor_obj):
    # Safely decrement reference count for a tensor object
    if not torch.is_tensor(tensor_obj):
        return

    try:
        ref_count = sys.getrefcount(tensor_obj)
        # Decrement references multiple times to ensure cleanup
        for _ in range(ref_count + 10):
            ctypes.pythonapi.Py_DecRef(ctypes.py_object(tensor_obj))
    except Exception as error:
        print(f"Reference decrement failed: {error}")

def clear_cuda_resources():
    # Find and clean up CUDA tensors
    for resource in gc.get_objects():
        if torch.is_tensor(resource) and resource.is_cuda:
            force_decrement_ref(resource)

    # Force garbage collection and clear CUDA cache
    gc.collect()
    torch.cuda.empty_cache()

