        device_context = torch.xpu.device
else:
    from contextlib import nullcontext
    def device_context(device):
        return nullcontext()

def configure_kernel_params(
    element_count: int,
) -> (
    int,
    int,
):
    # Determine optimal block size as next power of two
    BLOCK_SIZE: int = get_next_pow2(element_count)

    # Validate against maximum allowed size
    if BLOCK_SIZE > MAX_BLOCK_SIZE:
        raise RuntimeError(
            f"Triton kernel launch failed: input size {element_count} exceeds "
            f"maximum supported block size {MAX_BLOCK_SIZE}."
        )

    # Configure warp count based on block size
    warps_per_block: int = 4
    if BLOCK_SIZE >= 32768:
        warps_per_block = 32
    elif BLOCK_SIZE >= 8192:
        warps_per_block = 16
    elif BLOCK_SIZE >= 2048:
        warps_per_block = 8

    return BLOCK_SIZE, warps_per_block

# Handle CRUD operations for items using DynamoDB
import json
import boto3
from stlv_resources import Resources

def handler(event, context):
    # Initialize DynamoDB table resource
    dynamodb = boto3.resource("dynamodb")
    items_table = dynamodb.Table(Resources.items.table_name)

    # Extract request details
    request_method = event.get("httpMethod", "")
    path_params = event.get("pathParameters", {}) or {}
    item_key = path_params.get("id")

    # Process based on HTTP method
    if request_method == "POST":
        payload = json.loads(event["body"])
        items_table.put_item(Item=payload)
        return {
            "statusCode": 201,
            "body": json.dumps(payload)
        }

    elif request_method == "GET" and item_key:
        response = items_table.get_item(Key={"pk": item_key})
        record = response.get("Item")
        if record is None:
            return {
                "statusCode": 404,
                "body": "not found"
            }
        return {
            "statusCode": 200,
            "body": json.dumps(record)
        }

    elif request_method == "DELETE" and item_key:
        items_table.delete_item(Key={"pk": item_key})
        return {
            "statusCode": 200,
            "body": "deleted"
        }

    else:
        return {
            "statusCode": 400,
            "body": "bad request"
        }

import numpy as np
from transformers import Pipeline

def softmax_function(output_values):
    # Numerical stability improvement using max subtraction
    maximum_value = np.max(output_values, axis=-1, keepdims=True)
    adjusted_exponentials = np.exp(output_values - maximum_value)
    return adjusted_exponentials / adjusted_exponentials.sum(axis=-1, keepdims=True)

class BinaryClassificationPipeline(Pipeline):
    def _sanitize_parameters(self, **parameters):
        preprocessing_args = {}
        if "pair_text" in parameters:
            preprocessing_args["pair_text"] = parameters["pair_text"]
        return preprocessing_args, {}, {}

    def preprocess(self, first_text, pair_text=None):
        return self.tokenizer(first_text, text_pair=pair_text, return_tensors=self.framework)

    def _forward(self, input_data):
        return self.model(**input_data)

    def postprocess(self, model_results):
        raw_scores = model_results.logits[0].numpy()
        probabilities = softmax_function(raw_scores)
        top_class_index = np.argmax(probabilities)
        predicted_label = self.model.config.id2label[top_class_index]
        confidence_score = probabilities[top_class_index].item()
        raw_scores_list = raw_scores.tolist()
        return {"label": predicted_label, "score": confidence_score, "logits": raw_scores_list}

