from auth import authenticate

def _extract_body(payload):
    # Try to find plain text content in parts first
    if "parts" in payload:
        for part in payload["parts"]:
            if part.get("mimeType") == "text/plain":
                encoded_data = part.get("body", {}).get("data", "")
                if encoded_data:
                    decoded_bytes = base64.urlsafe_b64decode(encoded_data)
                    return decoded_bytes.decode("utf-8", errors="ignore")

    # Fallback to direct body data
    raw_data = payload.get("body", {}).get("data", "")
    if raw_data:
        decoded_bytes = base64.urlsafe_b64decode(raw_data)
        return decoded_bytes.decode("utf-8", errors="ignore").strip()
    return ""

