import numpy as np
import torch
import torch.nn as nn

def initialize_layer(layer, std_value=np.sqrt(2), bias_value=0.0):
    """Initialize layer weights with orthogonal initialization and biases with constant value."""
    torch.nn.init.orthogonal_(layer.weight, gain=std_value)
    torch.nn.init.constant_(layer.bias, bias_value)
    return layer

def select_activation(activation_type):
    """Select activation function based on string input."""
    activation_map = {
        "relu": nn.ReLU,
        "gelu": nn.GELU,
        "tanh": nn.Tanh
    }

    if activation_type.lower() in activation_map:
        return activation_map[activation_type.lower()]
    else:
        raise ValueError(f"Unsupported activation: {activation_type}")

def build_mlp(
    input_dim, hidden_dims, activation_class=nn.ReLU, apply_final_activation=True, 
    normalize_output=False
):
    """Build a multi-layer perceptron (MLP) as a list of layers."""
    layers = []
    current_dim = input_dim

    for i, next_dim in enumerate(hidden_dims):
        # Add linear transformation
        layers.append(nn.Linear(current_dim, next_dim))

        # Add normalization and activation (except possibly after last layer)
        if apply_final_activation or i < len(hidden_dims) - 1:
            if normalize_output:
                layers.append(nn.LayerNorm(next_dim))
            layers.append(activation_class())

        current_dim = next_dim

    return layers

def apply_weight_initialization(mlp_layers, activation_name):
    """Apply appropriate weight initialization to MLP layers."""
    for layer in mlp_layers:
        if isinstance(layer, nn.Linear):
            # Special handling for the final layer
            if layer is mlp_layers[-1]:
                torch.nn.init.normal_(layer.weight, mean=0.0, std=0.02)
                if layer.bias is not None:
                    torch.nn.init.zeros_(layer.bias)
            else:
                # Use Kaiming initialization for other layers
                torch.nn.init.kaiming_normal_(
                    layer.weight, mode='fan_out', nonlinearity=activation_name.lower()
                )
                if layer.bias is not None:
                    torch.nn.init.zeros_(layer.bias)

