def create_data_iterators(train_loader=None, val_loader=None, test_loader=None, mode="cyclic"):
    def _infinite_loop(loader):
        while True:
            for batch in loader:
                yield batch

    def _create_iterator(data_loader, strategy=mode):
        """Generate appropriate iterator based on strategy."""
        if strategy == "once":
            return iter(data_loader)
        elif strategy == "cyclic":
            return iter(_infinite_loop(data_loader))
        else:
            raise ValueError(f"Unsupported iterator mode: {strategy}")

    # Build iterators for each dataset if provided
    train_iter = _create_iterator(train_loader) if train_loader is not None else None
    val_iter   = _create_iterator(val_loader)   if val_loader is not None else None
    test_iter  = _create_iterator(test_loader)  if test_loader is not None else None

    return train_iter, val_iter, test_iter

