import numpy as np
import torch

class DiagonalGaussianDistribution:
    def __init__(self, params, is_deterministic=False, axis=1):
        self.params = params
        self.mean, self.logvar = torch.chunk(params, 2, dim=axis)
        self.logvar = torch.clamp(self.logvar, -30.0, 20.0)
        self.is_deterministic = is_deterministic
        self.std_dev = torch.exp(0.5 * self.logvar)
        self.variance = torch.exp(self.logvar)
        if self.is_deterministic:
            self.variance = self.std_dev = torch.zeros_like(self.mean, device=params.device, dtype=params.dtype)

    def generate_sample(self, rng=None):
        noise = torch.randn(self.mean.shape, device=self.params.device,
                           dtype=self.params.dtype, generator=rng)
        sample = self.mean + self.std_dev * noise
        return sample

    def kl_divergence(self, reference_dist=None):
        if self.is_deterministic:
            return torch.tensor([0.0])
        else:
            if reference_dist is None:
                return 0.5 * torch.sum(
                    torch.pow(self.mean, 2) +
                    self.variance - 1.0 - self.logvar,
                    dim=[1, 2, 3]
                )
            else:
                return 0.5 * torch.sum(
                    torch.pow(self.mean - reference_dist.mean, 2) / reference_dist.variance +
                    self.variance / reference_dist.variance -
                    1.0 - self.logvar + reference_dist.logvar,
                    dim=[1, 2, 3]
                )

    def negative_log_likelihood(self, observed_data, axes=(1, 2, 3)):
        if self.is_deterministic:
            return torch.tensor([0.0])
        log_two_pi = np.log(2.0 * np.pi)
        return 0.5 * torch.sum(
            log_two_pi + self.logvar +
            torch.pow(observed_data - self.mean, 2) / self.variance,
            dim=axes
        )

    def most_likely_value(self):
        return self.mean

