from agents import Agent, ItemHelpers, Runner, function_tool

@function_tool
def generate_joke_count() -> int:
    """Generate a random number of jokes to share, between 1 and 10 inclusive."""
    return random.randint(1, 10)

async def execute_joke_session():
    # Create an agent designed to tell jokes
    joke_agent = Agent(
        name="ComedianBot",
        instructions="First invoke the `generate_joke_count` tool to determine how many jokes to deliver, then proceed with telling exactly that many jokes.",
        tools=[generate_joke_count],
    )

    print("=== Session beginning ===")

    # Run the agent with streaming enabled
    stream_result = Runner.run_streamed(
        joke_agent,
        input="Please tell me some jokes!",
    )

    async for event in stream_result.stream_events():
        # Skip raw response events
        if event.type == "raw_response_event":
            continue
        elif event.type == "agent_updated_stream_event":
            print(f"Agent updated: {event.new_agent.name}")
        elif event.type == "run_item_stream_event":
            if event.item.type == "tool_call_item":
                tool_name = getattr(event.item.raw_item, 'name', 'Unknown Tool')
                print(f"-- Tool invoked: {tool_name}")
            elif event.item.type == "tool_call_output_item":
                print(f"-- Tool result: {event.item.output}")
            elif event.item.type == "message_output_item":
                text_content = ItemHelpers.text_message_output(event.item)
                print(f"-- Message delivered:\n{text_content}")
            else:
                pass  # Other event types are not processed
    print("=== Session ended ===")

if __name__ == "__main__":
    asyncio.run(execute_joke_session())

