class AGFSConnectionFailure(AGFSClientError):
    """Raised when connection establishment or maintenance fails"""
    pass

class AGFSServerTimeout(AGFSClientError):
    """Raised when a server response exceeds the allowed time limit"""
    pass

class AGFSHTTPStatusCodeError(AGFSClientError):
