# Import necessary components from the wrapping module
from wrapping_module import (
    apply_wrapper,
    get_wrapped_method,
    get_wrapped_method_name,
    strip_metadata,
    mark_wrapable,
)

class BaseArithmetic:
    def __init__(self):
        self.offset = 2

    @mark_wrapable()
    def perform_addition(self, first, second):
        return first + second + self.offset

    @mark_wrapable(name="perform_multiplication")
    def perform_multiplication(self, val1, val2):
        return val1 * val2 * self.offset

class DecoratedCalculator:
    def __init__(self, base_instance: BaseArithmetic):
        super().__init__()
        self.label = "Output:"
        self.base = base_instance
        apply_wrapper(self, base_instance, self._handle_invocation)

    def _handle_invocation(self, *arguments, **options):
        # Extract metadata from options
        method_identifier = get_wrapped_method_name(options)
        target_function = get_wrapped_method(options)

        # Clean up the options dictionary
        cleaned_options = strip_metadata(options)

        # Log the intercepted call
        print("intercepted method:", method_identifier)
        print("intercepted method:", target_function)

        # Execute the original method with cleaned arguments
        return target_function(*arguments, **cleaned_options)

def verify_wrapping():
    arithmetic = BaseArithmetic()
    decorated = DecoratedCalculator(arithmetic)

    # Test addition with offset
    assert decorated.perform_addition(2, 3) == 7

    # Test multiplication with offset
    assert decorated.perform_multiplication(4, 5) == 40

if __name__ == "__main__":
    verify_wrapping()

