import re
import string
from collections import Counter

def preprocess_text(text):
    def strip_articles(input_text):
        return re.sub(r"\b(a|an|the)\b", " ", input_text)

    def standardize_whitespace(input_text):
        return " ".join(input_text.split())

    def filter_punctuation(input_text):
        punctuation_set = set(string.punctuation)
        return "".join(char for char in input_text if char not in punctuation_set)

    def to_lowercase(input_text):
        return input_text.lower()

    processed = to_lowercase(text)
    processed = filter_punctuation(processed)
    processed = strip_articles(processed)
    processed = standardize_whitespace(processed)
    return processed

def compute_f1(predicted, target):
    INITIAL_METRIC = (0.0, 0.0, 0.0)

    if predicted is None:
        return INITIAL_METRIC

    clean_prediction = preprocess_text(predicted)
    clean_ground_truth = preprocess_text(target)

    # Handle special cases for binary/no-answer scenarios
    if clean_prediction in {"yes", "no", "noanswer"} and clean_prediction != clean_ground_truth:
        return INITIAL_METRIC

    if clean_ground_truth in {"yes", "no", "noanswer"} and clean_prediction != clean_ground_truth:
        return INITIAL_METRIC

    pred_tokens = clean_prediction.split()
    truth_tokens = clean_ground_truth.split()

    overlapping_terms = Counter(pred_tokens) & Counter(truth_tokens)
    overlap_count = sum(overlapping_terms.values())

    if overlap_count == 0:
        return INITIAL_METRIC

    precision_val = overlap_count / len(pred_tokens) if pred_tokens else 0.0
    recall_val = overlap_count / len(truth_tokens) if truth_tokens else 0.0

    if precision_val + recall_val == 0:
        f1_val = 0.0
    else:
        f1_val = 2 * (precision_val * recall_val) / (precision_val + recall_val)

    return f1_val, precision_val, recall_val

