# Generate search queries for academic research papers

research_topic = "{{ research_topic }}"
n_queries = {{ n_queries }}

# Parse and extract key concepts from the research topic
keywords = [word.strip().lower() for word in research_topic.replace(',', ' ').split() if len(word) > 2]
# Remove duplicates while preserving order
seen = set()
unique_keywords = []
for kw in keywords:
    if kw not in seen:
        seen.add(kw)
        unique_keywords.append(kw)

# Construct concise queries (1-4 keywords each)
queries = []
if len(unique_keywords) >= 2:
    # Combine top 2-3 keywords in various ways
    for i in range(min(n_queries, len(unique_keywords))):
        if i == 0:
            queries.append(" ".join(unique_keywords[:2]))
        elif i == 1 and len(unique_keywords) >= 3:
            queries.append(" ".join(unique_keywords[1:3]))
        elif i < n_queries:
            queries.append(unique_keywords[i % len(unique_keywords)])
else:
    # Fallback: use single keyword repeated with variations
    base_kw = unique_keywords[0] if unique_keywords else "research"
    queries = [base_kw + " review", base_kw + " survey", base_kw + " approach"]

# Ensure exactly n_queries entries
while len(queries) < n_queries:
    queries.append(base_kw + " method")
queries = queries[:n_queries]

print(queries)

from rest_framework.fields import empty
from apps.core.utils.serializers import UsernameSerializer
from apps.opspilot.models import KnowledgeDocument, WebPageKnowledge
import serializers

class KnowledgeDocumentSerializer(UsernameSerializer):
    train_status_display = serializers.SerializerMethodField()
    sync_enabled = serializers.SerializerMethodField()
    sync_time = serializers.SerializerMethodField()
    last_run_time = serializers.SerializerMethodField()

    class Meta:
        model = KnowledgeDocument
        fields = '__all__'

    def __init__(self, instance=None, data=empty, **kwargs):
        super().__init__(instance=instance, data=data, **kwargs)

        # Determine document IDs based on instance type
        if isinstance(instance, KnowledgeDocument):
            doc_ids = [instance.id]
        elif instance is None:
            doc_ids = []
        else:
            # Filter only web_page type documents from the list
            doc_ids = [doc.id for doc in instance if getattr(doc, 'knowledge_source_type', '') == 'web_page']

        # Fetch related web page knowledge data in bulk
        web_page_data = WebPageKnowledge.objects.filter(
            knowledge_document_id__in=doc_ids
        ).values(
            'knowledge_document_id',
            'sync_enabled',
            'sync_time',
            'last_run_time'
        )

        # Build lookup dictionary for quick access
        self.web_page_lookup = {
            item['knowledge_document_id']: item 
            for item in web_page_data
        }

    @staticmethod
    def get_train_status_display(obj):
        return obj.get_train_status_display()

    def get_sync_enabled(self, obj):
        if getattr(obj, 'knowledge_source_type', '') == 'web_page':
            record = self.web_page_lookup.get(obj.id, {})
            return record.get('sync_enabled', False)
        return False

    def get_last_run_time(self, obj):
        if getattr(obj, 'knowledge_source_type', '') == 'web_page':
            record = self.web_page_lookup.get(obj.id, {})
            return record.get('last_run_time', '')
        return ''

    def get_sync_time(self, obj):
        if getattr(obj, 'knowledge_source_type', '') == 'web_page':
            record = self.web_page_lookup.get(obj.id, {})
            return record.get('sync_time', '')
        return ''

