import pandas as pd
import string
from mindspeed_mm.tasks.evaluation.eval_datasets.datasets_base import BaseEvalDataset
from mindspeed_mm.tasks.evaluation.utils.string_utils import string_to_list

class AI2DEvalDataset(BaseEvalDataset):
    def __init__(self, dataset_path, dataset_name):
        super().__init__(dataset_path, dataset_name)

    def build_prompt(self, line):
        # Handle integer index input by retrieving corresponding row
        if isinstance(line, int):
            line = self.data.iloc[line]

        # Determine image path based on meta_only flag
        if self.meta_only:
            image_paths = string_to_list(line['image_path'])
        else:
            image_paths = self.dump_image(line)

        # Extract question and valid options
        question_text = line['question']
        choices = {}
        for letter in string.ascii_uppercase:
            if letter in line and not pd.isna(line[letter]):
                choices[letter] = line[letter]

        # Build options section of prompt
        options_section = ''
        if choices:
            options_section = 'Options:\n'
            for option_key, option_value in choices.items():
                options_section += f'{option_key}. {option_value}\n'

        # Add hint if available
        hint_text = line.get('hint')
        if hint_text is None or pd.isna(hint_text):
            hint_text = None

        # Construct final prompt
        full_prompt = ''
        if hint_text is not None:
            full_prompt += f'Hint: {hint_text}\n'
        full_prompt += f'Question: {question_text}\n'
        if choices:
            full_prompt += options_section
            full_prompt += 'Please select the correct answer from the options above. \n'

        # Prepare message list with image(s) and text
        message_list = []
        if isinstance(image_paths, list):
            message_list.extend([dict(type='image', value=path) for path in image_paths])
        else:
