# Validate date in MM-DD-YYYY format

def is_valid_date(date_str):
    if not date_str:
        return False

    try:
        components = date_str.split('-')
        if len(components) != 3:
            return False

        month_str, day_str, year_str = components

        # Check length requirements for each component
        if len(month_str) != 2 or len(day_str) != 2 or len(year_str) != 4:
            return False

        # Convert to integers
        month = int(month_str)
        day = int(day_str)
        year = int(year_str)

        # Validate month range
        if month < 1 or month > 12:
            return False

        # Validate day is positive
        if day < 1:
            return False

        # Days per month validation
        if month in [1, 3, 5, 7, 8, 10, 12]:
            if day > 31:
                return False
        elif month in [4, 6, 9, 11]:
            if day > 30:
                return False
        elif month == 2:
            # February can have at most 29 days (leap year consideration)
            if day > 29:
                return False

        return True
    except Exception:
        return False

