# Speech-to-text transcription using ElevenLabs Scribe API
import os
import json
from dotenv import load_dotenv

load_dotenv()

class AudioTranscriber:
    """Convert speech in audio files to text via ElevenLabs Scribe"""

    def __init__(self, api_token=None):
        self.api_token = api_token or os.getenv('ELEVENLABS_API_KEY')
        self.endpoint_base = "https://api.elevenlabs.io/v1"

    def convert_speech_to_text(self, audio_path, lang=None, include_speaker_tags=True,
                               speaker_count=None, word_timing="word"):
        """
        Process audio file and extract transcribed text

        Supported formats: mp3, mp4, mpeg, mpga, m4a, wav, webm
        Maximum file size: 100 MB
        """
        endpoint_url = f"{self.endpoint_base}/speech-to-text"

        request_headers = {
            "xi-api-key": self.api_token
        }

        payload = {
            "model_id": "scribe_v1",
            "tag_audio_events": str(include_speaker_tags).lower(),
            "timestamps_granularity": word_timing
        }

        if lang:
            payload["language_code"] = lang
        if speaker_count:
            payload["num_speakers"] = speaker_count

        try:
            with open(audio_path, 'rb') as audio_data:
                upload_files = {
                    'file': (os.path.basename(audio_path), audio_data)
                }

                api_response = requests.post(endpoint_url, 
                                            headers=request_headers, 
                                            data=payload, 
                                            files=upload_files, 
                                            timeout=120)
                api_response.raise_for_status()

                response_data = api_response.json()
                return {
                    "status": True,
                    "transcript": response_data.get('text', ''),
                    "detected_language": response_data.get('language_code', 'unknown'),
                    "word_details": response_data.get('words', []),
                    "speaker_info": response_data.get('speakers', [])
                }

        except requests.exceptions.RequestException as error:
            return {"status": False, "message": f"API call failed: {str(error)}"}
        except Exception as error:
            return {"status": False, "message": str(error)}

def execute():
    import argparse

    parser = argparse.ArgumentParser(description='ElevenLabs Scribe STT Tool')
    parser.add_argument('audio_file', help='Path to input audio file')
    parser.add_argument('--lang', '-l', help='Specify language code (e.g., ar, en)')
    parser.add_argument('--speakers', '-s', type=int, help='Expected number of speakers')

    arguments = parser.parse_args()

    transcriber = AudioTranscriber()
    output = transcriber.convert_speech_to_text(
        arguments.audio_file, 
        lang=arguments.lang, 
        speaker_count=arguments.speakers
    )
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    execute()

