# Custom HTTP request handler with routing capabilities
import json
import logging
from http.server import BaseHTTPRequestHandler

logger = logging.getLogger(__name__)

class RouteManager:
    def __init__(self):
        # Store routes organized by HTTP method and path
        self.endpoints = {
            "GET": {},
            "POST": {}
        }

    def register(self, method: str, route: str, callback):
        method = method.upper()
        if method not in self.endpoints:
            self.endpoints[method] = {}
        self.endpoints[method][route] = callback

    def get_endpoint(self, path: str):
        def wrapper(func):
            self.register("GET", path, func)
            return func
        return wrapper

    def post_endpoint(self, path: str):
        def wrapper(func):
            self.register("POST", path, func)
            return func
        return wrapper

    def resolve(self, request_handler: BaseHTTPRequestHandler):
        # Extract base path without query parameters
        base_path = request_handler.path.split('?')[0]
        http_method = request_handler.command.upper()

        if http_method in self.endpoints and base_path in self.endpoints[http_method]:
            try:
                self.endpoints[http_method][base_path](request_handler)
            except Exception as ex:
                logger.error(f"Exception during {http_method} {base_path}: {ex}")
                self._respond_error(request_handler, 500, str(ex))
        else:
            self._respond_error(request_handler, 404, "Resource not found")

    def _respond_error(self, request_handler: BaseHTTPRequestHandler, status_code: int, error_msg: str):
        request_handler.send_response(status_code)
        request_handler.send_header('Content-Type', 'application/json')
        request_handler.end_headers()
        response_body = json.dumps({"error": error_msg})
        request_handler.wfile.write(response_body.encode('utf-8'))

# Singleton router instance
_router_instance = RouteManager()

def get_route_manager():
    return _router_instance

import json
import sys

def process_fields(fields_data):
    output_lines = []
    form_fields = fields_data.get("form_fields", [])
    output_lines.append(f"Read {len(form_fields)} fields")

    def boxes_overlap(box_a, box_b):
        # Check if two axis-aligned rectangles do NOT overlap
        no_horizontal_overlap = box_a[0] >= box_b[2] or box_a[2] <= box_b[0]
        no_vertical_overlap = box_a[1] >= box_b[3] or box_a[3] <= box_b[1]
        return not (no_horizontal_overlap or no_vertical_overlap)

    # Prepare list of all bounding boxes with metadata
    box_list = []
    for field in form_fields:
        box_list.append({
            "box": field["label_bounding_box"],
            "type": "label",
            "field": field
        })
        box_list.append({
            "box": field["entry_bounding_box"],
            "type": "entry",
            "field": field
        })

    issues_found = False

    # Check for overlaps between boxes on the same page
    for idx, item1 in enumerate(box_list):
        for jdx in range(idx + 1, len(box_list)):
            item2 = box_list[jdx]

            # Only compare boxes on the same page
            if item1["field"]["page_number"] == item2["field"]["page_number"]:
                if boxes_overlap(item1["box"], item2["box"]):
                    issues_found = True

                    # Distinguish same-field vs different-field intersections
                    if item1["field"] is item2["field"]:
                        output_lines.append(
                            f"FAILURE: intersection between label and entry bounding boxes for `{item1['field']['description']}` "
                            f"({item1['box']}, {item2['box']})"
                        )
                    else:
                        output_lines.append(
                            f"FAILURE: intersection between {item1['type']} bounding box for `{item1['field']['description']}` "
                            f"({item1['box']}) and {item2['type']} bounding box for `{item2['field']['description']}` ({item2['box']})"
                        )

                    # Limit number of messages to avoid overwhelming output
                    if len(output_lines) >= 20:
                        output_lines.append("Aborting further checks; fix bounding boxes and try again")
                        return output_lines

    # Additional validation: check entry box height against font size
    for item in box_list:
        if item["type"] == "entry":
            field_data = item["field"]
            if "entry_text" in field_data:
                font_size = field_data["entry_text"].get("font_size", 14)
                box_height = item["box"][3] - item["box"][1]

                if box_height < font_size:
                    issues_found = True
                    output_lines.append(
                        f"FAILURE: entry bounding box height ({box_height}) for `{field_data['description']}` "
                        f"is too short for the text content (font size: {font_size}). "
                        f"Increase the box height or decrease the font size."
                    )

                    if len(output_lines) >= 20:
                        output_lines.append("Aborting further checks; fix bounding boxes and try again")
                        return output_lines

    if not issues_found:
        output_lines.append("SUCCESS: All bounding boxes are valid")

    return output_lines

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: check_bounding_boxes.py [fields.json]")
        sys.exit(1)

    with open(sys.argv[1]) as file:
        data = json.load(file)

    results = process_fields(data)
    for line in results:
        print(line)

