from whimbox.common.cvars import *
from whimbox.ui.template.posi_manager import Area

class TextTemplate(AssetBase):
    def __init__(self, content: str, detection_zone: Area, identifier=None, 
                 comparison_strategy=CONTAIN_MATCHING, logging_flag=LOG_WHEN_TRUE):
        # Initialize parent class with name
        if identifier is None:
            super().__init__(get_name_from_caller(depth=2))
        else:
            super().__init__(identifier)

        # Store configuration attributes
        self.content = content
        self.detection_zone = detection_zone
        self.comparison_strategy = comparison_strategy
        self.logging_flag = logging_flag

    def get_content(self):
        return self.content

    def evaluate_results(self, candidates: list):
        # Normalize input to list if string
        if isinstance(candidates, str):
            candidates = [candidates]

        for candidate in candidates:
            # Skip empty strings
            if not candidate.strip():
                continue

            # Apply matching logic based on strategy
            if self.comparison_strategy == CONTAIN_MATCHING:
                if self.content in candidate:
                    return True
                continue
            elif self.comparison_strategy == ACCURATE_MATCHING:
                if self.content == candidate:
                    return True
                continue

        return False

class Text(TextTemplate):
    def __init__(self, text, cap_area, identifier=None, logging_flag=LOG_WHEN_TRUE) -> None:
        # Auto-generate name if not provided
        if identifier is None:
            identifier = get_name_from_caller(depth=2)

        # Call parent constructor with updated parameters
        super().__init__(
            text=text, 
