import os

def is_single_model_directory(model_path):
    # Check if both required files exist in the given directory
    graph_file = os.path.join(model_path, "graph_net.json")
    model_file = os.path.join(model_path, "model.py")
    return os.path.isfile(graph_file) and os.path.isfile(model_file)

def find_model_paths_recursively(base_dir):
    # Traverse directories recursively to find model directories
    for item in os.listdir(base_dir):
        full_path = os.path.join(base_dir, item)
        if os.path.isdir(full_path):
            if is_single_model_directory(full_path):
                yield full_path
            else:
                # Recursively search in subdirectories
                yield from find_model_paths_recursively(full_path)

def get_direct_subdirectories(parent_folder):
    # Return list of immediate subdirectory paths
    subdirs = []
    for entry in os.listdir(parent_folder):
        full_entry_path = os.path.join(parent_folder, entry)
        if os.path.isdir(full_entry_path):
            subdirs.append(full_entry_path)
    return subdirs

