# Process text to replace spaces based on consecutive count
processed_chars = []
index = 0
while index < len(text):
    if text[index] == ' ':
        # Count how many consecutive spaces there are
        consecutive_spaces = 0
        while index < len(text) and text[index] == ' ':
            consecutive_spaces += 1
            index += 1

        # Replace with dash if more than 2 spaces, otherwise underscores
        if consecutive_spaces > 2:
            processed_chars.append('-')
        else:
            processed_chars.append('_' * consecutive_spaces)
    else:
        processed_chars.append(text[index])
        index += 1

return ''.join(processed_chars)

from datetime import datetime
from langchain_core.messages import BaseMessage
from langgraph.graph.message import add_messages
from typing import Sequence, TypedDict, Annotated

def append_messages_with_time(left: Sequence[BaseMessage], right: Sequence[BaseMessage]):
    """Processes and appends messages with timestamps before merging."""
    # Normalize input to list format
    incoming = right if isinstance(right, list) else [right]

    # Generate current timestamp in ISO format
    timestamp = datetime.now().isoformat()

    # Process each message to ensure timestamp is attached
    for item in incoming:
        # Handle LangChain message objects
        if hasattr(item, 'additional_kwargs'):
            if "timestamp" not in item.additional_kwargs:
                item.additional_kwargs["timestamp"] = timestamp
        # Handle dictionary-style messages
        elif isinstance(item, dict):
            if "additional_kwargs" not in item:
                item["additional_kwargs"] = {}
            if "timestamp" not in item["additional_kwargs"]:
                item["additional_kwargs"]["timestamp"] = timestamp

    # Merge using the original add_messages function
    return add_messages(left, incoming)

class AgentSelection(TypedDict):
    """Details about the chosen agent."""
    identifier: str
    control_mode: str  # auto/manual

class ConversationSummary(TypedDict):
    """Summary metadata for the conversation."""
    content: str
    interaction_count: int

class AgentContext(TypedDict):
    """Current state of the agent system."""
    selected_agent: AgentSelection
    messages: Annotated[Sequence[BaseMessage], append_messages_with_time]
    summary: ConversationSummary

