# LIFO queue implementation using deque for efficient stack operations

import collections
from ..packages import six
from ..packages.six.moves import queue

class LifoQueue(queue.Queue):
    def _init(self, _):
        # Initialize with a deque to support LIFO behavior
        self.queue = collections.deque()

    def _qsize(self, len=len):
        # Return current number of items in the queue
        return len(self.queue)

    def _put(self, item):
        # Add item to the end of the deque (top of stack)
        self.queue.append(item)

    def _get(self):
        # Remove and return the last item added (LIFO order)
        return self.queue.pop()

