    return is_local_version() or is_production_version()

def is_sandbox_mode():
    """Checks whether the app is operating in the initial-generation sandbox environment.

    Note: The second-generation runtimes do operate within a sandbox, but it's 
    significantly less restrictive; thus, such checks are typically unnecessary.
    Reference: https://cloud.google.com/appengine/docs/standard/runtimes
    """
    return is_in_appengine() and os.environ.get("APPENGINE_RUNTIME") == "python27"

