import json
import sys

class RectAndField:
    def __init__(self, rect_coords, box_type, field_data):
        self.rect = rect_coords
        self.rect_type = box_type
        self.field = field_data

def check_overlap(rect1, rect2):
    # Check if rectangles are disjoint horizontally or vertically
    horizontal_gap = rect1[0] >= rect2[2] or rect1[2] <= rect2[0]
    vertical_gap = rect1[1] >= rect2[3] or rect1[3] <= rect2[1]
    return not (horizontal_gap or vertical_gap)

def validate_bounding_boxes(json_input):
    output_lines = []
    data = json.load(json_input)

    form_fields = data.get("form_fields", [])
    output_lines.append(f"Processed {len(form_fields)} form fields")

    processed_items = []
    for field in form_fields:
        processed_items.append(RectAndField(field["label_bounding_box"], "label", field))
        processed_items.append(RectAndField(field["entry_bounding_box"], "entry", field))

    issues_found = False

    # Check all pairs of bounding boxes
    total_items = len(processed_items)
    for idx in range(total_items):
        current_item = processed_items[idx]

        for next_idx in range(idx + 1, total_items):
            next_item = processed_items[next_idx]

            # Only compare items on the same page
            if current_item.field["page_number"] == next_item.field["page_number"]:
                if check_overlap(current_item.rect, next_item.rect):
                    issues_found = True

                    # Determine message based on relationship between fields
                    if current_item.field is next_item.field:
                        desc = current_item.field["description"]
                        output_lines.append(
                            f"ERROR: Overlap between label and entry boxes for '{desc}' "
                            f"({current_item.rect}, {next_item.rect})"
                        )
                    else:
                        output_lines.append(
                            f"ERROR: Overlap between {current_item.rect_type} box for "
                            f"'{current_item.field['description']}' ({current_item.rect}) and "
                            f"{next_item.rect_type} box for '{next_item.field['description']}' "
                            f"({next_item.rect})"
                        )

                    # Limit number of messages to prevent excessive output
                    if len(output_lines) >= 20:
                        output_lines.append("Stopping validation after reaching message limit. "
                                          "Please fix detected issues and re-run.")
                        return output_lines

    # Additional validation for entry boxes
    for item in processed_items:
        if item.rect_type == "entry":
            if "entry_text" in item.field:
                font_size = item.field["entry_text"].get("font_size", 14)
                actual_height = item.rect[3] - item.rect[1]

                if actual_height < font_size:
                    issues_found = True
                    desc = item.field["description"]
                    output_lines.append(
                        f"ERROR: Entry box height ({actual_height}) for '{desc}' is insufficient "
                        f"for text content (font size: {font_size}). Consider increasing box height "
                        f"or reducing font size."
                    )

                    if len(output_lines) >= 20:
                        output_lines.append("Stopping validation after reaching message limit. "
                                          "Please fix detected issues and re-run.")
                        return output_lines

    if not issues_found:
        output_lines.append("OK: All bounding boxes passed validation")

    return output_lines

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: validate_bounding_boxes.py [fields.json]")
        sys.exit(1)

    with open(sys.argv[1]) as file:
        results = validate_bounding_boxes(file)

    for line in results:
        print(line)

# Custom data structures for handling HTTP headers and lookups

from collections import OrderedDict
from .compat import Mapping, MutableMapping

class InsensitiveKeyDict(MutableMapping):
    """A dictionary that performs case-insensitive key lookups.

    Supports all MutableMapping operations and includes dict-like copy functionality.
    The original key casing is preserved for iteration and representation purposes,
    but comparisons are performed in a case-insensitive manner.

    Example usage:
        header_dict = InsensitiveKeyDict()
        header_dict['Content-Type'] = 'text/html'
        header_dict['content-type'] == 'text/html'  # True
        list(header_dict) == ['Content-Type']  # True

    Note: Behavior is undefined when multiple keys have identical lowercase forms.
    """
    def __init__(self, initial_data=None, **kwargs):
        self._data = OrderedDict()
        if initial_data is None:
            initial_data = {}
        self.update(initial_data, **kwargs)

    def __setitem__(self, key, value):
        # Store using lowercase key for lookup, preserve original key with value
        self._data[key.lower()] = (key, value)

    def __getitem__(self, key):
        return self._data[key.lower()][1]

    def __delitem__(self, key):
        del self._data[key.lower()]

    def __iter__(self):
        return (original_key for original_key, _ in self._data.values())

    def __len__(self):
        return len(self._data)

    def case_insensitive_items(self):
        """Return items with lowercase keys."""
        return ((lower_key, value) for lower_key, (key, value) in self._data.items())

    def __eq__(self, other):
        if not isinstance(other, Mapping):
            return NotImplemented
        if not isinstance(other, InsensitiveKeyDict):
            other = InsensitiveKeyDict(other)
        return dict(self.case_insensitive_items()) == dict(other.case_insensitive_items())

    def clone(self):
        """Create a copy of the dictionary."""
        return InsensitiveKeyDict(self._data.values())

    def __repr__(self):
        return repr(dict(self.items()))

class DynamicLookup(dict):
    """Dictionary that supports attribute-style access with default values."""
    def __init__(self, identifier=None):
        self._name = identifier
        super().__init__()

    def __repr__(self):
        return f"<DynamicLookup '{self._name}'>"

    def __getattr__(self, attr):
        # Allow attribute-style access with default None
        try:
            return self[attr]
        except KeyError:
            return None

    def fetch(self, key, fallback=None):
        """Retrieve item with fallback value."""
        return self.get(key, fallback)

