import gym
import numpy as np
from gym.spaces import Box, Dict
import copy

class SinglePrecision(gym.ObservationWrapper):
    def __init__(self, env):
        super().__init__(env)

        # Handle Box observation spaces
        if isinstance(self.observation_space, Box):
            original_space = self.observation_space
            self.observation_space = Box(
                low=original_space.low,
                high=original_space.high,
                shape=original_space.shape,
                dtype=np.float32
            )
        # Handle Dict observation spaces
        elif isinstance(self.observation_space, Dict):
            updated_spaces = {}
            for key, space in self.observation_space.spaces.items():
                if isinstance(space, Box):
                    updated_spaces[key] = Box(
                        low=space.low,
                        high=space.high,
                        shape=space.shape,
                        dtype=np.float32
                    )
                else:
                    updated_spaces[key] = space
            self.observation_space = Dict(updated_spaces)
        else:
            raise NotImplementedError("Unsupported observation space type")

    def observation(self, obs):
        # Process numpy arrays
        if isinstance(obs, np.ndarray):
            return obs.astype(np.float32)
        # Process dictionaries of observations
        elif isinstance(obs, dict):
            processed_obs = {}
            for key, value in obs.items():
                if isinstance(value, np.ndarray):
                    processed_obs[key] = value.astype(np.float32)
                else:
                    processed_obs[key] = value
            return processed_obs
        # Fallback for other types
        return obs

import sys
import yaml
from copy import deepcopy

def convert_yaml_to_cli_args():
    def flatten_dict(data):
        """Flatten nested dictionaries into a single-level dictionary.
        Replace underscores in keys with hyphens."""
        result = {}

        def _process(obj, prefix=""):
            if isinstance(obj, dict):
                for key, value in obj.items():
                    new_key = f"{prefix}{key}".replace('_', '-')
                    if isinstance(value, dict):
                        _process(value, f"{new_key}-")
                    else:
                        result[new_key] = value
            # Non-dict values are ignored at top level

        _process(data)
        return result

    # Check if first argument is a YAML file
    if len(sys.argv) < 2 or not sys.argv[1].endswith('.yaml'):
        return

    yaml_path = sys.argv[1]

    # Load and parse YAML configuration
    try:
        with open(yaml_path, 'r') as file:
            raw_config = yaml.safe_load(file)
    except FileNotFoundError:
        print(f"Warning: Config file not found: {yaml_path}")
        return
    except PermissionError:
        print(f"Error: Permission denied accessing: {yaml_path}")
        return
    except yaml.YAMLError as e:
        print(f"Error: Invalid YAML syntax in {yaml_path}: {e}")
        return
    except Exception as e:
        print(f"Error: Failed to load {yaml_path}: {e}")
        return

    # Ensure required sections exist
    if 'gpt_args' not in raw_config:
        raise KeyError("Missing required 'gpt_args' section in config")
    if 'MM_TOOL_PATH' not in raw_config:
        raise KeyError("Missing required 'MM_TOOL_PATH' in config")

    # Prepare command-line arguments
    cli_args = [sys.argv[0]]  # Keep original script name
    flattened_gpt = flatten_dict(raw_config['gpt_args'])

    # Merge LoRA args if present
    if 'lora_args' in raw_config:
        flattened_lora = flatten_dict(raw_config['lora_args'])
        flattened_gpt.update(flattened_lora)

    # Convert each config entry to CLI format
    for param, val in flattened_gpt.items():
        cli_args.append(f"--{param}")
        if isinstance(val, bool) and val:
            # Boolean true flags don't need a value
            continue
        elif isinstance(val, list):
            # Add multiple values for list-type parameters
            for item in val:
                cli_args.append(str(item))
        else:
            cli_args.append(str(val))

    # Append metadata-related arguments
    cli_args.extend([
        "--mm-data", yaml_path,
        "--mm-model", yaml_path,
        "--mm-tool", raw_config['MM_TOOL_PATH']
    ])

    # Replace current sys.argv with generated CLI args
    sys.argv = cli_args

# Execute the conversion function
convert_yaml_to_cli_args()

