import logging
from app.collectors.base import Collector, CollectorResult

logger = logging.getLogger("docsis.collector.backup")

class BackupScheduler(Collector):
    """Collector responsible for managing automated backup operations."""
    identifier = "backup"

    def __init__(self, config_handler, interval=86400, **options):
        super().__init__(interval)
        self._config_handler = config_handler

    def is_active(self):
        return self._config_handler.is_backup_enabled()

    def execute(self):
        from .backup import generate_backup_file, remove_stale_backups

        storage_dir = self._config_handler.data_directory
        target_location = self._config_handler.get("backup_destination", "/backup")
        max_retention = self._config_handler.get("backup_retention_count", 5)

        try:
            backup_filename = generate_backup_file(storage_dir, target_location)
            remove_stale_backups(target_location, count=max_retention)
            logger.info("Automated backup completed: %s", backup_filename)
            return CollectorResult.success(self.identifier, {"path": backup_filename})
        except Exception as error:
            logger.warning("Backup process encountered an error: %s", error)
            return CollectorResult.error(self.identifier, str(error))
